INSERT INTO `crs_tabledata719` VALUES ('3', '{E6A0A1CD-D704-428B-9532-1FF7AF37E829}', '60', 'INHE-0088', '2016-01-13 11:09:50', '0000-00-00 00:00:00', '2016-01-19 11:32:06', 'unchecked', 'n', 'n', '', '1', 'sctz2016011322/ST20511/生产通知单', '', '外购，深圳快递出货', '0', '2016-01-13 11:09:50', 'Sudanese Chinese Meter Factory', 'ST20', 'ST20511', '28359', '2016-01-20', '国际业务一部', '余冬纯', '', '', '生产通知单', '已经收到了全额预付款', '同意', '同意', '', '同意', '', '', '同意。', '', '', '同意，生产辅料由江西工厂处理', '丁富民2016-01-19 10:15:10', '王功勇2016-01-19 11:05:47', 'sctz2016011322', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('4', '{3C647902-1233-47A6-BA55-276D55974364}', '61', 'INHE-0051', '2016-01-13 16:25:11', '0000-00-00 00:00:00', '2016-01-15 14:32:12', 'unchecked', 'n', 'n', '', '1', 'sctz2016011323/ZEC1-09/生产通知单', '', '1.技术要求和ZEC1项目一样，见附件技术规格，用公司最新的DIN三代产品供货，满足ZEC所有技术要求即可，另外，双回路计量，旁路不断电。\r\r\r\n2.客户要求1月27日交货，单相表可考虑从PY02挪用物料生产，三相表需尽快交货，需工厂建议最早交期。\r\r\r\n3.客户已提供15万美金预付款水单，但是水单上我司公司名称不正确，已让客户在修改。', '4184', '2016-01-13 16:25:11', 'Finmark Industries (Pvt) Ltd', 'ZEC1', 'ZEC1-09', '28370', '2016-01-27', '国际业务二部', '盛燕', '', '05', '生产通知单', '请领导审批', '同意', '', '', '同意', '', '', '同意。', '', '', '同意', '丁富民2016-01-15 09:58:23', '王功勇2016-01-15 13:52:39', 'sctz2016011323', '01', null, null, null, null, null, null, null, null, null, null);
