INSERT INTO `crs_tabledata719` VALUES ('7', '{092198B2-BA44-4CA6-A90F-657AB3D87D2E}', '61', 'INHE-0392', '2016-01-19 13:48:14', '0000-00-00 00:00:00', '2016-01-21 08:51:07', 'unchecked', 'n', 'n', '', '1', 'sctz2016011927/PSA7/生产通知单', '', '此订单属于PSA4项目追加订单，用来更换现场旧版集中器中的瑞斯康方案PLC模块，确保旧集中器可用来抄新表，免费为客户更换，但是\r\r因PSA4项目已结束，时间紧急，故追加为PSA7的订单。\r\r\n', '0', '2016-01-19 13:48:14', 'BLINDOMETER LA S.A.S', 'PSA', 'PSA7', '24624', '2016-01-20', '国际业务二部', '彭孜孜', '第三方检验', '06', '生产通知单', '原合同的追加订单，免费替换给客户使用', '同意', '张丽莹2016-01-19 16:26:01', '郭涛2016-01-19 16:12:04', '陶保荣2016-01-20 14:19:38', '', '', '同意。', '', '', '同意', '丁富民2016-01-20 18:01:12', '王功勇2016-01-20 18:04:15', 'sctz2016011927', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('8', '{95559986-1ADB-439C-B7F1-684A0985ACDA}', '61', 'INHE-0381', '2016-01-19 13:56:53', '0000-00-00 00:00:00', '2016-01-21 08:50:17', 'unchecked', 'n', 'n', '', '1', 'sctz2016011928/UW01/生产通知单', '', '1.最终客户是首次使用我司电表和系统，无安全模块和SGC码，需公司安排。\r\r\n2.已询问江西工厂，有库存货物，还需修改设置和铭牌。', '175', '2016-01-19 13:56:53', 'Delta Electricals Limited', 'UW', 'UW01', 'INHESC2016011844', '2016-01-22', '国际业务二部', '张柳芳(Alexie)', '', '05', '生产通知单', '合同全款已收齐，同意', '同意', '张丽莹2016-01-20 09:48:04', '郭涛2016-01-19 16:03:52', '陶保荣2016-01-20 14:19:00', '', '', '同意。', '', '', '同意', '丁富民2016-01-20 18:01:39', '王功勇2016-01-20 18:03:32', 'sctz2016011928', '01', null, null, null, null, null, null, null, null, null, null);
