INSERT INTO `crs_tabledata719` VALUES ('10', '{F4C3A585-121E-4200-AF5B-069265E18CEE}', '61', 'INHE-0507', '2016-01-27 17:21:11', '0000-00-00 00:00:00', '2016-01-27 17:21:11', 'unchecked', 'n', 'n', '', '1', 'sctz2016012732/ESA-01/生产通知单', '', '', '35000', '2016-01-27 17:21:11', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'ESA', 'ESA-01', '28299', '2016-02-29', '国际业务二部', '王晶晶', '第三方检验', '02', '生产通知单', '', '', '', '', '', '', '', '', '', '', '', '', '', 'sctz2016012732', '', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('11', '{7C0A836D-8B10-4486-A674-4929F7EEC97C}', '61', 'INHE-0228', '2016-01-28 09:11:38', '0000-00-00 00:00:00', '2016-01-29 09:01:37', 'unchecked', 'n', 'n', '', '1', 'sctz2016012834/CDN10/生产通知单', '', '由于电力公司现在缺表安装，因此电力公司希望我司协调交期，需在4月10日之前发货。\r\n合同评审的流程已经下发，由于交期紧急，请先走生产流程，安排生产。', '23400', '2016-01-28 09:11:38', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN10', 'INHESC2016012762', '2016-04-10', '国际业务二部', '谭雯', '', '04', '生产通知单', '合同评审流程还在进行中，该项目是全款LC支付', '同意', '张丽莹2016-01-28 14:32:03', '郭涛2016-01-28 14:15:17', '同意', '陶保荣2016-01-28 14:52:10', '', '同意。', '', 'CDN08项目中三款产品的翻单生产，CDN08项目表计部分的BOM表、产品生产程序、产品校调说明书等资料已经下发，请参考处理', '同意。翻单产品，由江西工厂处理。', '丁富民2016-01-28 15:23:58', '王功勇2016-01-28 16:10:49', 'sctz2016012834', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('12', '{163A1BDD-044C-4C0D-95A2-080FFEBD1834}', '60', 'INHE-0088', '2016-01-28 09:38:13', '0000-00-00 00:00:00', '2016-02-16 15:13:39', 'unchecked', 'n', 'n', '', '1', 'sctz2016012835/ST20603/生产通知单', '', '锡条为重货，要求加固外箱，小包装打包，减轻单间重量，扎带捆扎\r\r\n									\r\r\n', '0', '2016-01-28 09:38:13', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20603', 'INHESC2016011542', '2016-01-31', '国际业务一部', '余冬纯', '', '06', '生产通知单', '合同已经过评审，货款已全部收齐', '同意', '张丽莹2016-02-15 08:56:04', '王维2016-02-15 08:42:32', '同意', '陶保荣2016-02-16 11:29:54', '', '同意。', '', '', '同意。生产辅料由江西工厂处理。', '丁富民2016-02-16 11:34:27', '王功勇2016-02-16 15:04:56', 'sctz2016012835', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('13', '{22A4C621-5CBC-4EA7-9DFC-8FAEE6C4024D}', '61', 'INHE-0051', '2016-01-28 10:42:26', '0000-00-00 00:00:00', '2016-01-29 10:45:37', 'unchecked', 'n', 'n', '', '1', 'sctz2016012840/ESA-01/生产通知单', '', '1.附件.rar里面是此项目所有技术相关文档，中英对照文件是DSP34-1635标准的翻译。\r\r\n2.此项目对电表表卡，铭牌，表号文件等都有详细要求，业务将整理后稍后发出来。所有资料需和业务确认。\r\r\n3.此项目对故障率要求：电表和CIU安装后，每年故障率不超过1%。请注意质量控制。\r\r\n4.此项目对质保要求：发货后5年。', '35000', '2016-01-28 10:42:26', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'ESA', 'ESA-01', '28299', '2016-03-11', '国际业务二部', '盛燕', '第三方检验', '02', '生产通知单', '该项目每一批货物的货款的20%预付，已收到。', '同意', '张丽莹2016-01-28 17:19:33', '郭涛2016-01-28 16:57:27', '同意', '陶保荣2016-01-29 09:49:23', '', '同意。', '', 'ESA项目已经安排成品试生产，等成品试完成之后，再作成品、散件BOM表正式处理。', '同意。', '丁富民2016-01-29 10:24:58', '王功勇2016-01-29 10:44:04', 'sctz2016012840', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('14', '{9B265C39-C125-41A6-815F-839ACFAAC96B}', '61', 'INHE-0507', '2016-01-28 11:45:33', '0000-00-00 00:00:00', '2016-01-29 09:01:50', 'unchecked', 'n', 'n', '', '1', 'sctz2016012841/N4-2/生产通知单', '', '', '0', '2016-01-28 11:45:33', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'N4', 'N4-2', '28371', '2016-03-10', '国际业务二部', '王晶晶', '第三方检验', '04', '生产通知单', '合同已评审，总金额 120250美元。已收到112,750美元  还有运费7,500美元未收', '同意', '张丽莹2016-01-28 14:27:37', '郭涛2016-01-28 14:08:22', '同意', '陶保荣2016-01-28 14:49:32', '', '同意。', '', '合作工厂的电表生产/检验设备，设备规格/型号/品牌请与客户服务部沟通确认，建议使用江西工厂同类设备，方便日后维护。', '同意。', '丁富民2016-01-28 15:26:22', '王功勇2016-01-28 16:09:12', 'sctz2016012841', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('15', '{BDCBA1F1-BCF0-4718-87B2-45DBABA3EA7B}', '61', 'INHE-0392', '2016-01-28 14:30:59', '0000-00-00 00:00:00', '2016-01-29 10:42:12', 'unchecked', 'n', 'n', '', '1', 'sctz2016012842/CP05追加/生产通知单', '', '', '0', '2016-01-28 14:30:59', 'Caravan Park Electrical Services Limited', 'CP', 'CP05追加', 'INHESC2016012655', '2016-01-31', '国际业务二部', '彭孜孜', '第三方检验', '06', '生产通知单', '结算方式为全款TT预付，已收到全部货款，同意。', '同意', '张丽莹2016-01-28 17:10:06', '郭涛2016-01-28 16:54:59', '同意', '陶保荣2016-01-29 09:48:18', '', '同意。', '', '', '同意，外购产品', '丁富民2016-01-29 10:25:36', '王功勇2016-01-29 10:41:27', 'sctz2016012842', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('16', '{2E8FAB52-C4BA-47A7-BACB-FFB323C02621}', '60', 'INHE-0088', '2016-02-15 11:31:01', '0000-00-00 00:00:00', '2016-02-16 15:13:48', 'unchecked', 'n', 'n', '', '1', 'sctz2016021553/REB601/生产通知单', '', '交期要求紧急，是否到厂验货待定（4名工程师，10天内）。\r\r\r\n技术应答表、电表铭牌、尺寸、LCD等图纸、出厂设置等文件生产前需要提交给电力公司盖章确认。', '5000', '2016-02-15 11:31:01', 'Ideal Enterprise', 'REB', 'REB601', 'INHESC2016011950', '2016-03-05', '国际业务一部', '余冬纯', '', '02', '生产通知单', '合同已经过评审，货款将以全款即期信用证方式收回。', '同意，由于交期紧急，从电力公司开出信用证之日算起60天完成交货和安装，现在电力公司已经于今日将信用证开出，客户正在办理给我司开出信用证，请江西提前做物料采购和生产准备。', '张丽莹2016-02-15 17:00:06', '王维2016-02-15 16:13:55', '同意', '陶保荣2016-02-16 11:28:49', '单相代码表。但有特殊化要求，项目研发负责人：何梓劲', '请项目组、财务、跟单组密切跟踪LC，必须及时收到。', 'SC44-2A', '单相代码表，透明左右进出线端子盖（已经安排江西达实开模）；表计功能有特殊化要求。', '同意。', '丁富民2016-02-16 11:38:37', '王功勇2016-02-16 15:02:57', 'sctz2016021553', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('17', '{74D03D42-0AAD-4D84-9611-F3420BD6E0B2}', '53', 'JXINHE-2433', '2016-02-16 08:15:32', '0000-00-00 00:00:00', '2016-02-18 09:27:27', 'unchecked', 'n', 'n', '', '1', 'sctz2016021657/CZ01/生产通知单', '', '一，2个USB接口光学探头已领用\r\r\n二，产品要求：1. CIP采用矩泉方案 2. 电表有无功计量 3. 电表与集中器通信方式为G3-PLC 4. 三相表接线方式是非对称。\r\r\n三，试点订单需要的产品需要满足附件中City Power技术规范和NRS049的规范，但是稍微有些出入，是与客户讨论的结果，不存在问题。', '70', '2016-02-16 08:15:32', 'CZ ELECTRONICS MANUFACTURING (PTY) LTD.', 'CZ', 'CZ01', '28269', '2016-03-20', '工业园国际业务部', '黄倩', '', '02', '生产通知单', '合同已经过评审，货款已收到。', '同意生产通知变更，变更内容为：G3-PLC产品改为普通的FSK-PLC产品，即BS安装可更换通信模块表+FSK通信模块+CIP。', '张丽莹2016-02-19 10:37:10', '宋宁2016-02-19 10:30:39', '', '', '', '同意。', '', '建议采用CDN项目单相/三相可更换通信模块（PLC载波）分体式代码表；PLC载波方案可以选择慧联通信方案/或者钜泉方案。表计、PLC载波模块是现成设计方案，建议由江西工厂处理/客服验收。', '同意', '丁富民2016-02-19 15:11:03', '王功勇2016-02-19 15:57:47', 'sctz2016021657', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('18', '{14701D45-D6ED-4D3D-8C0E-A5121133E039}', '5', 'IM-0015', '2016-02-16 15:42:15', '0000-00-00 00:00:00', '2016-02-16 15:42:15', 'unchecked', 'n', 'n', '', '1', 'sctz2016021658/草原04/生产通知单', '', '', '17000', '2016-02-16 15:42:15', '草原', '草原之鹰', '草原04', 'xsdd2015121727', '2016-02-18', '营运总监', '龙丹', '', '', '生产通知单', '', '', '', '', '', '', '', '', '', '', '', '', '', 'sctz2016021658', '', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('19', '{E7E2F7F5-41DA-4E21-A9DF-FE6D2A9BD7FE}', '60', 'INHE-0066', '2016-02-23 14:08:02', '0000-00-00 00:00:00', '2016-02-23 15:26:40', 'unchecked', 'n', 'n', '', '1', 'sctz2016022362/PO1602/生产通知单', '', 'APC220-43-0B要求：\r\r\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\r\r\r\r\r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\r\r\r\r\r\r\r\n3、用于电表上，带自动组网功能。              \r\r\r\r\r\r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43”，主要用于区分开其他功能的无线通信模块。              \r\r\r\r\r\r\r\r\n5、电压源：3.5-5.5V              \r\r\r\r\r\r\r\r\n6、频率： 433.05-434.7 MHz           \r\r\r\r\r\r\r\r\n7、温度范围：-30-+80              \r\r\r\r\r\r\r\r\n8、外包装箱用纸贴上唛头：APC220-43\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\nAPC910M-B要求：\r\r\r\r\r\r\n\r1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。  \r\r\r\r\r\r\r\n2、安美通集抄无线射频通信模块。             \r\r\r\r\r\r\r\n3、电压：4.5-6V             \r\r\r\r\r\r\r\n4、频段：432-434MHz              \r\r\r\r\r\r\r\n5、SMA连接线必须装在电路板上。\r\r\r\r\r\r\n\r\r\r\r\r\r\r\nAPC220-43-3B要求：\r\r\r\r\r\n1、白雪项目专用安美通普通无线射频通信模块，不带嵌入式天线。（不需要把天线焊在模块上。）           \r\r2、用于电表上，带自动组网功能。           \r\r\r\r\n3、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43-3”，主要用于区分开其他功能的无线通信模块。           \r\r\r\r\n4、电压源：3.5-5.5V           \r\r\r\r\n5、频率：433.05-434.7 MHz\r\r\r\r\n6、温度范围：-30-+80           \r\r\r\r\n7、外包装箱用纸贴上唛头：APC220-43 \r\r\r\r\r\n', '0', '2016-02-23 14:08:02', 'Energomera CJSC', '白雪', 'PO1602', 'INHESC2016022373', '2016-02-29', '国际业务一部', '邱洁', '', '05', '生产通知单', '合同已评审，16975.2美元已收到', '同意', '张丽莹2016-02-29 13:50:23', '王维2016-02-29 13:46:29', '同意', '陶保荣2016-02-29 23:10:53', '', '', '', '', '同意。外购产品由江西工厂处理。', '丁富民2016-03-01 10:06:12', '王功勇2016-03-01 15:05:13', 'sctz2016022362', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('20', '{73FD7F24-39C0-4709-8AA3-9E9BDFE35903}', '61', 'INHE-0228', '2016-02-24 11:18:36', '0000-00-00 00:00:00', '2016-02-24 11:18:36', 'unchecked', 'n', 'n', '', '1', 'sctz2016022463/CDN10/生产通知单', '', '已经收到PI，并走完合同评审，LC还在开立中，请先启动生产，交期在5月2日前，视LC的装船期，可能有提前一周的可能。', '38784', '', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN10', '', '2016-05-02', '国际业务二部', '谭雯', '', '04', '生产通知单', '', '', '', '', '', '', '', '', '', '', '', '', '', 'sctz2016022463', '', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('21', '{63DF7B5D-5A05-4AED-A87D-3B98B035D37F}', '61', 'INHE-0228', '2016-02-25 14:32:24', '0000-00-00 00:00:00', '2016-02-29 08:29:55', 'unchecked', 'n', 'n', '', '1', 'sctz2016022564/CDN11/生产通知单', '', '已经收到PI，并走完合同评审，LC还在开立中，请先启动生产，交期在5月2日前，视LC的装船期，可能有提前一周的可能。										\r\n', '38784', '2016-02-25 14:32:24', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN11', 'INHESC2016021569', '2016-05-02', '国际业务二部', '谭雯', '', '04', '生产通知单', '合同已经过评审，货款支付方式为60远期信用证，无预付款', '同意先备料；生产启动以收到LC为准。', '张丽莹2016-02-26 14:04:48', '郭涛2016-02-26 13:38:42', '同意', '陶保荣2016-02-26 18:58:20', '', '同意。', '', '', '同意，翻单生产，由江西工厂处理。', '丁富民2016-02-27 12:13:34', '王功勇2016-02-28 09:01:50', 'sctz2016022564', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('22', '{FDD878C3-6695-4F8B-B48D-D85112F9124E}', '61', 'INHE-0228', '2016-02-25 15:08:58', '0000-00-00 00:00:00', '2016-02-29 08:30:20', 'unchecked', 'n', 'n', '', '1', 'sctz2016022565/CDN12/生产通知单', '', '已经收到PI，并走完合同评审，LC还在开立中，请先规划生产，启动备料。							\r\r\n										\r\r\n', '25344', '2016-02-25 15:08:58', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN12', 'INHESC2016021570', '2016-07-01', '国际业务二部', '谭雯', '', '04', '生产通知单', '合同已评审，付款方式为60天远期信用证，无预付款', '同意先备料，生产启动以收到LC为准。', '张丽莹2016-02-26 17:46:19', '郭涛2016-02-26 17:41:17', '同意', '陶保荣2016-02-26 18:57:25', '', '同意。', '', '', '同意。翻单产品由江西工厂处理。', '丁富民2016-02-27 13:49:20', '王功勇2016-02-28 09:01:08', 'sctz2016022565', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('23', '{A6B0B99D-16E7-4275-AAC2-D0F40D34EEB6}', '61', 'INHE-0228', '2016-02-25 15:16:46', '0000-00-00 00:00:00', '2016-02-29 08:30:43', 'unchecked', 'n', 'n', '', '1', 'sctz2016022566/CDN13/生产通知单', '', '已经收到PI，并走完合同评审，LC还在开立中，请先规划生产，启动备料。							\r\n										\r\n										\r\n', '25344', '2016-02-25 15:16:46', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN13', 'INHESC2016021571', '2016-09-02', '国际业务二部', '谭雯', '', '04', '生产通知单', '合同已评审，付款方式为60天远期信用证，无预付款			\r\n', '同意先备料；生产启动以收到LC为准。', '张丽莹2016-02-26 17:46:42', '郭涛2016-02-26 17:39:32', '同意', '陶保荣2016-02-26 18:53:09', '', '同意。', '', '', '同意。翻单产品由江西工厂处理。', '丁富民2016-02-27 13:50:22', '王功勇2016-02-28 08:59:06', 'sctz2016022566', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('24', '{2E3BE06F-AD1B-429E-A0D3-A417DA728796}', '60', 'INHE-0066', '2016-02-29 10:36:18', '0000-00-00 00:00:00', '2016-11-23 17:56:33', 'unchecked', 'n', 'n', '', '1', 'sctz2016022967/白雪601/生产通知单', '', '1、采用新模具结构供货。     \r\r\r\r\r\n2、做防水灌胶处理。\r\r\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。      \r\r\r\r\r\r\n4、MAC地址为该表表号（表地址）的最后六位数字，该体现激光雕刻在表外壳背部。       \r\r\r\r\r\r\n5、PLC载波显示单元的铭牌标识为：CE208。         \r\r\r\r\r\r\n6、显示单元不需要贴易碎贴。        \r\r\r\r\r\r\n7、出厂设置：           \r\r\r\r\r\r\n1）表内时间为：GMT+4           \r\r\r\r\r\r\n2）冬夏令时转换功能关闭。           \r\r\r\r\r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\r\r\r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\r\r\r\r\n5）特殊节假日没有。           \r\r\r\r\r\r\n6）电表密码：000000.           \r\r\r\r\r\r\n7）负荷门限：0.           \r\r\r\r\r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\r\r\r\r\n9）取负荷点的平均时间：30分钟。          \r\r\r\r\r\r\n8、继电器：100A，但标识采用120A。      \r\r\r\r\r\r\n9、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）       \r\r\r\r\r\r\n10、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\r\r\r\r\n11、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU的内盒中。  \r\r\r\n\r\r12、分批交货：\r\r\r\n\r\r\r\r3206套-4月22日交货\r\r\n\r\r\r\r13585套-5月6日交货\r\r\n3249套-5月9日交货 \r\r\r\r\r\r\n', '20040', '2016-02-29 10:36:18', 'Energomera CJSC', '白雪', '白雪601', 'INHESC2016022574', '2016-04-22', '国际业务一部', '邱洁', '', '04', '生产通知单', '收到了20%预付款- 215936 美金的水单，已批准同意下单生产', '同意', '张丽莹2016-02-29 18:31:27', '王维2016-02-29 18:02:03', '同意', '陶保荣2016-02-29 23:10:20', '', '同意。时间十分紧张，请商务组紧密跟踪研发项目组的研发进展，有问题及时向我提出。', '', '', '同意。', '丁富民2016-03-01 10:06:59', '王功勇2016-03-01 15:03:57', 'sctz2016022967', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('25', '{7EC9B4BF-6D3E-47C8-8120-74F188FC3BCC}', '61', 'INHE-0431', '2016-03-04 08:47:50', '0000-00-00 00:00:00', '2016-03-04 17:32:07', 'unchecked', 'n', 'n', '', '1', 'sctz2016030469/SIB01/生产通知单', '', '生产请参考之前的SIA01订单,但是请注意有以下更改:1.密钥为370017 2.后付费模式.  另外最后包装前的质检请把整套产品,包括电表和模块装在一起进行检验测试,因为之前到客户手的里的模块有5个是坏的,以免后续还要重新寄送模块', '15', '2016-03-04 08:47:50', 'BRILLIANCE TECHNOLOGIES CO., LIMITED', 'SIB', 'SIB01', 'INHESC2016030277', '2016-03-31', '国际业务二部', '刘佩(Ted)', '', '04', '生产通知单', '合同已评审，全额预付款已收到', '同意', '张丽莹2016-03-04 14:26:41', '郭涛2016-03-04 13:32:21', '同意', '陶保荣2016-03-04 14:43:27', '', '', '', '', '同意，翻单生产。', '丁富民2016-03-04 17:08:05', '王功勇2016-03-04 17:31:13', 'sctz2016030469', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('26', '{03289206-9718-41C7-BA46-5FBC2388001D}', '61', 'INHE-0432', '2016-03-15 16:49:04', '0000-00-00 00:00:00', '2016-03-17 11:15:13', 'unchecked', 'n', 'n', '', '1', 'sctz2016031570/GA03/生产通知单', '', '', '510', '2016-03-15 16:49:04', 'GVE Projects Limited', 'GA', 'GA03', 'INHESC2016031584', '2016-04-04', '国际业务二部', '谭东羊(Timon)', '', '04', '生产通知单', '合同已评审，预付款已收。', '', '张丽莹2016-03-17 09:00:41', '', '同意', '陶保荣2016-03-17 09:49:40', '', '', '', '业务已经给出要求----属翻单处理，请江西工厂安排。', '同意', '丁富民2016-03-17 11:01:57', '王功勇2016-03-17 11:14:40', 'sctz2016031570', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('27', '{C13A98E6-0EE3-499C-86EC-61893AB8D9C6}', '61', 'INHE-0432', '2016-03-15 19:04:28', '0000-00-00 00:00:00', '2016-03-17 11:14:54', 'unchecked', 'n', 'n', '', '1', 'sctz2016031571/GA03/生产通知单', '', '', '200', '2016-03-15 19:04:28', 'Arnergy Solar Ltd.', 'GA', 'GA03', 'INHESC2016031592', '2016-04-04', '国际业务二部', '谭东羊(Timon)', '', '04', '生产通知单', '合同已评审，预付款已收', '同意', '张丽莹2016-03-17 08:59:20', '郭涛2016-03-16 16:48:48', '同意', '陶保荣2016-03-17 09:49:08', '', '', '', '业务已经给出要求，请按翻译单--由江西工厂处理。', '同意', '丁富民2016-03-17 11:03:31', '王功勇2016-03-17 11:14:09', 'sctz2016031571', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('28', '{8E61900E-9E5D-4D52-996F-C58B455404D0}', '60', 'INHE-0088', '2016-03-16 18:09:41', '0000-00-00 00:00:00', '2016-03-18 10:11:16', 'unchecked', 'n', 'n', '', '1', 'sctz2016031672/WZ601/生产通知单', '', '发货安排：\r\r\n1. 第一批：5000套单相5月1日交货；\r\r\n2. 第二批：25000套单相、1000套三相5月27日交货；', '31000', '2016-03-16 18:09:41', 'Ideal Enterprise', 'WZ', 'WZ601', 'INHESC2016030380', '2016-05-01', '国际业务一部', '余冬纯', '', '02', '生产通知单', '合同已评审，即期信用证结算', '同意', '张丽莹2016-03-17 16:25:19', '王维2016-03-17 16:18:59', '同意', '陶保荣2016-03-17 21:54:37', '', '注意：交期要求5月1日，希望研发抓紧开模（透明延伸端盖），和其他设计定型工作。', '项目负责人：何梓劲', '1：单相表可以按REB601项目进行备料、安排生产（除面板、包装唛头可以需要修改）。2：三相表请按三相理可换通信模块代码表准备主要物料（继电器、MCU芯片），PCB板正在安排设计。', '同意', '丁富民2016-03-18 08:51:51', '王功勇2016-03-18 10:10:25', 'sctz2016031672', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('29', '{0B786C93-2953-4954-963A-2F0E36962CDE}', '60', 'INHE-0066', '2016-03-21 15:02:57', '0000-00-00 00:00:00', '2016-03-24 09:31:56', 'unchecked', 'n', 'n', '', '1', 'sctz2016032173/PO1603/生产通知单', '', 'APC220-43-0B要求：\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\n3、用于电表上，带自动组网功能。              \r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43”，主要用于区分开其他功能的无线通信模块。              \r\n5、电压源：3.5-5.5V              \r\n6、频率： 433.05-434.7 MHz           \r\n7、温度范围：-30-+80              \r\n8、外包装箱用纸贴上唛头：APC220-43\r\n\r\nAPC910M-B要求：\r\n1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。  \r\n2、安美通集抄无线射频通信模块。             \r\n3、电压：4.5-6V             \r\n4、频段：432-434MHz              \r\n5、SMA连接线必须装在电路板上。\r\n\r\nAPC220-43-3B要求：\r\n1、白雪项目专用安美通普通无线射频通信模块，不带嵌入式天线。（不需要把天线焊在模块上。）           2、用于电表上，带自动组网功能。           \r\n3、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43-3”，主要用于区分开其他功能的无线通信模块。           \r\n4、电压源：3.5-5.5V           \r\n5、频率：433.05-434.7 MHz\r\n6、温度范围：-30-+80           \r\n7、外包装箱用纸贴上唛头：APC220-43 \r\n										\r\n', '0', '2016-03-21 15:02:57', 'Energomera CJSC', '白雪', 'PO1603', 'INHESC2016032195', '2016-03-31', '国际业务一部', '邱洁', '', '05', '生产通知单', '合同已评审，40%预付款已收', '同意', '张丽莹2016-03-22 08:47:26', '王维2016-03-21 17:03:05', '同意', '陶保荣2016-03-23 10:26:02', '', '', '', '', '同意', '丁富民2016-03-23 10:28:45', '王功勇2016-03-23 10:52:08', 'sctz2016032173', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('30', '{1C902866-E212-41B8-A7AA-6BADB43CAD65}', '61', 'INHE-0507', '2016-03-22 09:42:08', '0000-00-00 00:00:00', '2016-03-23 09:54:32', 'unchecked', 'n', 'n', '', '1', 'sctz2016032274/N4-2/生产通知单', '', '以上工具全部按照附件 ： N4-2项目工具清单及规格 来采购。', '0', '2016-03-22 09:42:08', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'N4', 'N4-2', '28371', '2016-03-29', '国际业务二部', '王晶晶', '第三方检验', '04', '生产通知单', '合同已评审，货款已收到', '同意', '张丽莹2016-03-22 18:10:30', '郭涛2016-03-22 17:28:18', '同意', '陶保荣2016-03-23 09:34:34', '', '', '', '', '同意', '丁富民2016-03-23 09:48:40', '王功勇2016-03-23 09:52:08', 'sctz2016032274', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('31', '{C9CC90BD-6D4E-46B3-B957-0ECBD7FC2BD4}', '60', 'INHE-0088', '2016-03-24 09:19:11', '0000-00-00 00:00:00', '2016-03-25 08:47:53', 'unchecked', 'n', 'n', '', '1', 'sctz2016032475/ST20601/生产通知单', '', '深圳快递出货\r\r\r\r\n当地环境温度高，MCU不能带LCD，通过双绞线显示单元查询电表信息，带GPRS/GSM通信模块，表计功能参考样机', '10', '2016-03-24 09:19:11', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20601', 'INHESC2016011540', '2016-04-20', '国际业务一部', '余冬纯', '', '06', '生产通知单', '合同已评审，货款已收齐', '同意', '张丽莹2016-03-24 14:25:31', '王维2016-03-24 14:22:10', '同意', '陶保荣2016-03-24 15:39:31', '', '', '', '此是ST20市场一个特殊项目使用（只作过样机，与曾经出货的三相代码表功能上不一样），三相可更换通信模块表（GPRS模块），建议按CDN07/CDN08项目的三相可更换通信模块表来作。数量很少，建议由江西工厂处理，客户服务部验货出厂。', '同意', '丁富民2016-03-24 17:14:36', '王功勇2016-03-25 08:46:03', 'sctz2016032475', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('32', '{9AC43A73-CCA1-4085-8182-A22AA8EFE5AA}', '61', 'INHE-0091', '2016-03-24 15:06:01', '0000-00-00 00:00:00', '2016-03-25 10:57:25', 'unchecked', 'n', 'n', '', '1', 'sctz2016032476/M9/生产通知单', '', '1. 采购生产前需要提供相应产品技术规格给客户，客户确认后才准予下单采购。', '0', '2016-03-24 15:06:01', 'Electricity Supply Corporation of Malawi Limited', 'M9', 'M9', '23696', '2016-04-15', '国际业务二部', '林丽璇(Elle Lin)', '', '04', '生产通知单', '合同已评审，已收到20%的预付款', '', '张丽莹2016-03-24 17:49:52', '', '同意', '陶保荣2016-03-25 09:00:39', '', '', '', '建议由江西工厂处理。', '同意', '丁富民2016-03-25 09:47:05', '王功勇2016-03-25 10:54:11', 'sctz2016032476', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('33', '{5DAFD9F1-5AAA-4393-8ED6-A9658B5581C8}', '60', 'INHE-0066', '2016-03-29 17:42:30', '0000-00-00 00:00:00', '2016-04-01 18:01:36', 'unchecked', 'n', 'n', '', '1', 'sctz2016032977/白雪604/生产通知单', '', '1、采用新模具结构供货。     \r\r\n2、做防水灌胶处理。\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。      \r\r\n4、MAC地址为该表表号（表地址）的最后六位数字，该地址激光雕刻在表外壳背部。       \r\r\n5、PLC载波显示单元的铭牌标识为：CE208。         \r\r\n6、显示单元不需要贴易碎贴。        \r\r\n7、出厂设置：           \r\r\n1）表内时间为：GMT+4           \r\r\n2）冬夏令时转换功能关闭。           \r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\n5）特殊节假日没有。           \r\r\n6）电表密码：000000.           \r\r\n7）负荷门限：0.           \r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\n9）取负荷点的平均时间：30分钟。          \r\r\n8、继电器：100A，但标识采用120A。      \r\r\n9、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）       \r\r\n10、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\n11、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU的内盒中。  \r\r\n12、分批交货：\r\r\n15030套-5月18日交货\r\r\n15030套-6月1日交货\r\r\n\r\r\n										\r\r\n', '30060', '2016-03-29 17:42:30', 'Energomera CJSC', '白雪', '白雪604', 'INHESC2016032999', '2016-05-18', '国际业务一部', '邱洁', '', '04', '生产通知单', '合同已评审，预付款未收到，预计近期到款。', '同意', '张丽莹2016-04-01 10:24:21', '王维2016-03-30 14:20:19', '同意', '陶保荣2016-04-01 11:09:42', '', '', '', '塑胶件加工比较慢，需要采购提前准备', '同意', '丁富民2016-04-01 11:38:07', '王功勇2016-04-01 18:01:08', 'sctz2016032977', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('34', '{FB300798-7514-42E1-862C-410B33FEFA5A}', '61', 'INHE-0432', '2016-03-31 16:19:10', '0000-00-00 00:00:00', '2016-04-01 19:04:47', 'unchecked', 'n', 'n', '', '1', 'sctz2016033179/GR01/生产通知单', '', '请工厂直接使用NR05库存，打包直接发货，无需做任何更改。', '50', '2016-03-31 16:19:10', 'GMA Global Resources Limited', 'GR', 'GR01', 'INHESC2016033101', '2016-04-10', '国际业务二部', '谭东羊(Timon)', '', '04', '生产通知单', '合同在评审中，全部货款已收，同意', '同意', '张丽莹2016-04-01 15:25:26', '郭涛2016-04-01 15:07:24', '同意，用库存备品检验后发货。', '陶保荣2016-04-01 17:09:04', '', '', '', '', '同意', '丁富民2016-04-01 18:56:02', '王功勇2016-04-01 19:03:00', 'sctz2016033179', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('35', '{9A6BB34C-8D64-4057-B4D3-8AF5D227CB3C}', '61', 'INHE-0507', '2016-04-07 13:43:59', '0000-00-00 00:00:00', '2016-04-11 09:42:43', 'unchecked', 'n', 'n', '', '1', 'sctz2016040781/N4-2/生产通知单', '', '规格型号若有不清楚的地方请咨询杨西刚，并和业务确认。', '0', '2016-04-07 13:43:59', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'N4', 'N4-2', '28371', '2016-04-15', '国际业务二部', '王晶晶', '', '04', '生产通知单', '该合同已评审，还未收到预付款', '同意', '张丽莹2016-04-07 16:21:10', '郭涛2016-04-07 16:08:45', '同意', '陶保荣2016-04-08 08:39:01', '', '', '', '', '同意', '丁富民2016-04-08 09:37:26', '王功勇2016-04-09 21:43:45', 'sctz2016040781', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('36', '{F013C1B5-E680-45B3-B299-F10596BD764C}', '60', 'INHE-0066', '2016-04-08 09:53:46', '0000-00-00 00:00:00', '2016-04-11 09:42:55', 'unchecked', 'n', 'n', '', '1', 'sctz2016040882/白雪606/生产通知单', '', '', '0', '2016-04-08 09:53:46', 'Energomera CJSC', '白雪', '白雪606', 'INHESC2016040807', '2016-04-14', '国际业务一部', '邱洁', '', '05', '生产通知单', '合同已评审，尚未收到预付款', '同意', '张丽莹2016-04-08 13:32:36', '王维2016-04-08 11:40:11', '同意', '陶保荣2016-04-08 17:32:49', '', '', '', '', '同意，翻单生产由江西工厂处理。', '丁富民2016-04-08 19:15:26', '王功勇2016-04-09 21:40:00', 'sctz2016040882', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('37', '{D4F48A4A-AE6B-4375-BBAB-BFE6750E73C1}', '60', 'INHE-0066', '2016-04-08 11:39:57', '0000-00-00 00:00:00', '2016-04-12 10:28:45', 'unchecked', 'n', 'n', '', '1', 'sctz2016040883/白雪605/生产通知单', '', 'APC220-43-0B要求：\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\n3、用于电表上，带自动组网功能。              \r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43”，主要用于区分开其他功能的无线通信模块。              \r\n5、电压源：3.5-5.5V              \r\n6、频率： 433.05-434.7 MHz           \r\n7、温度范围：-30-+80              \r\n8、外包装箱用纸贴上唛头：APC220-43\r\n\r\nAPC910M-B要求：\r\n1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。  \r\n2、安美通集抄无线射频通信模块。             \r\n3、电压：4.5-6V             \r\n4、频段：432-434MHz              \r\n5、SMA连接线必须装在电路板上。\r\n\r\nAPC220-43-3B要求：\r\n1、白雪项目专用安美通普通无线射频通信模块，不带嵌入式天线。（不需要把天线焊在模块上。）           2、用于电表上，带自动组网功能。           \r\n3、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43-3”，主要用于区分开其他功能的无线通信模块。           \r\n4、电压源：3.5-5.5V           \r\n5、频率：433.05-434.7 MHz\r\n6、温度范围：-30-+80           \r\n7、外包装箱用纸贴上唛头：APC220-43 \r\n										\r\n										\r\n', '0', '2016-04-08 11:39:57', 'Energomera CJSC', '白雪', '白雪605', 'INHESC2016040808', '2016-04-20', '国际业务一部', '邱洁', '', '05', '生产通知单', '合同已审批，发货前收请货款，同意先生产', '同意', '张丽莹2016-04-11 15:02:45', '王维2016-04-08 11:47:46', '同意', '陶保荣2016-04-11 19:32:25', '', '', '', '', '同意', '丁富民2016-04-12 10:04:37', '王功勇2016-04-12 10:20:19', 'sctz2016040883', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('38', '{3312DEC7-545B-492E-917D-FD95C0D9FD9D}', '61', 'INHE-0432', '2016-04-14 17:39:59', '0000-00-00 00:00:00', '2016-04-15 15:33:24', 'unchecked', 'n', 'n', '', '1', 'sctz2016041484/GA03/生产通知单', '', 'GA03客户一共需要2个GSM短信猫。此前下单一个。现补上。技术规格已在OA发给工厂。请参考。', '0', '2016-04-14 17:39:59', 'GVE Projects Limited', 'GA', 'GA03', 'INHESC2016031584', '2016-04-25', '国际业务二部', '谭东羊(Timon)', '', '', '生产通知单', '合同已评审，已收60%预付款，同意', '同意', '张丽莹2016-04-15 08:35:45', '郭涛2016-04-14 23:07:10', '同意', '陶保荣2016-04-15 11:33:20', '', '', '', '外购产品。', '同意。', '丁富民2016-04-15 13:47:07', '王功勇2016-04-15 15:33:05', 'sctz2016041484', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('39', '{668A3797-D0F9-4876-9D4D-019FF75A1DB6}', '61', 'INHE-0222', '2016-04-19 14:50:39', '0000-00-00 00:00:00', '2016-04-20 17:24:24', 'unchecked', 'n', 'n', '', '1', 'sctz2016041986/PSA6/生产通知单', '', '1.单相表为PSA6单相2线分体PLC DIN表翻单，但是是新的一家电力公司ESSA订单，面板需重新设计。\r\n2.三相表为新需求，功能同PSA6已供货三相CT表一致，但此次不带CIU，面板需重新设计，同时两款三相表（CT接入和直接接入）都要求用新开模CT表的模具来做。\r\n3.面板，出厂设置，外箱都需要设计并同客户确认。\r\n', '972', '2016-04-19 14:50:39', 'STAEKKA SAS', 'PSA6', 'PSA6', 'INHESC2016040606', '2016-05-19', '国际业务二部', '张红丽', '', '04', '生产通知单', '合同已评审，预付款已收，同意', '同意。请张红丽注意IEC（IEC62053-21和IEC62055-33）标准的打标问题。', '张丽莹2016-04-20 08:48:34', '郭涛2016-04-19 21:52:00', '同意', '陶保荣2016-04-20 09:39:25', '', '', '', '翻单生产，铭牌修改/确认等由江西工厂处理。', '同意。', '丁富民2016-04-20 10:32:29', '王功勇2016-04-20 17:17:05', 'sctz2016041986', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('40', '{F33D1408-688C-4EF4-B500-436E9CC95EEA}', '61', 'INHE-0091', '2016-04-21 09:45:43', '0000-00-00 00:00:00', '2016-09-18 16:30:42', 'unchecked', 'n', 'n', '', '1', 'sctz2016042187/M9/生产通知单', '', '', '0', '2016-04-21 09:45:43', 'Electricity Supply Corporation of Malawi Limited', 'M9', 'M9', '23696', '2016-10-14', '国际业务二部', '林丽璇(Elle Lin)', '', '04', '生产通知单', '合同已在15年评审，已收20%预付款', '同意', '张丽莹2016-09-18 08:34:47', '郭涛2016-09-14 22:57:58', '同意', '陶保荣2016-09-18 08:46:17', '', '', '', '', '同意', '丁富民2016-09-18 10:31:18', '王功勇2016-09-18 11:39:16', 'sctz2016042187', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('41', '{08B5DB3A-601E-4C7C-8CFD-7CA39CB1B837}', '60', 'INHE-0088', '2016-04-22 14:45:48', '0000-00-00 00:00:00', '2016-04-25 10:09:52', 'unchecked', 'n', 'n', '', '1', 'sctz2016042288/DPM601/生产通知单', '', '产品功能请参考JES项目单三相双绞线分体通信预付费表功能处理。', '100', '2016-04-22 14:45:48', 'DELTAPRIMA METERING SDN BHD', 'DPM', 'DPM601', 'INHESC2016042116', '2016-06-05', '国际业务一部', '余冬纯', '', '06', '生产通知单', '合同已评审，预付款已收，同意', '同意，注意此批产品需要使用虚拟密钥和SGC。', '张丽莹2016-04-22 17:23:57', '王维2016-04-22 17:19:38', '同意', '陶保荣2016-04-23 22:20:31', '', '', '', '虚拟密钥：370023.01.1', '同意，翻单生产，由江西工厂处理。', '丁富民2016-04-25 08:19:14', '王功勇2016-04-25 10:09:26', 'sctz2016042288', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('42', '{5347FEE5-DEDD-422F-8FA0-A34C110A2DE6}', '61', 'INHE-0222', '2016-05-04 13:29:43', '0000-00-00 00:00:00', '2016-05-05 15:46:14', 'unchecked', 'n', 'n', '', '1', 'sctz2016050489/PSA6/生产通知单', '', '1.此为同一个项目追加生产的部分，追加生产374台。\r\r\r\n\r\r\r\n2.预付款支付过程中，预计本周内到账，先下生产通知。', '374', '2016-05-04 13:29:43', 'STAEKKA SAS', 'PSA6', 'PSA6', 'INHESC2016040606', '2016-05-19', '国际业务二部', '张红丽', '', '04', '生产通知单', '合同已评审，尚未收到预付款', '同意', '张丽莹2016-05-04 17:51:54', '郭涛2016-05-04 17:28:35', '同意', '陶保荣2016-05-05 09:41:36', '', '', '', '', '同意', '丁富民2016-05-05 09:50:38', '王功勇2016-05-05 15:45:16', 'sctz2016050489', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('43', '{87C67078-BE02-4AE4-934F-6B51A04C910F}', '61', 'INHE-0434', '2016-05-05 13:57:32', '0000-00-00 00:00:00', '2016-05-06 11:07:33', 'unchecked', 'n', 'n', '', '1', 'sctz2016050590/YL/生产通知单', '', '1) 接线方式虽然选择了“单进单出”，但请参考附件技术规格14.18项；\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\n2) 客户当前时区位于UTC+3:30, 但电表需支持夏令时功能，请参考附件技术规格7.3.2项；\r\r\r\r\r\r\n\r\r\r\r\r\n3）客户届时可能会在发货前去江西工业园验货，所以请从生产时就做好客户验货的准备；\r\n\r\n4) 客户对交期要求非常严格，请务必在40天内交货。', '550', '2016-05-05 13:57:32', 'SANA Meter Co.ltd', 'YL', 'YL', 'INHESC2016042517', '2016-06-13', '国际业务二部', '钟云林(Andy)', '', '02', '生产通知单', '合同已评审，已收到预付款，同意', '同意', '张丽莹2016-05-06 08:41:16', '郭涛2016-05-05 18:43:38', '同意', '', '', '新市场，重要。请研发和生产注意客户的技术要求。', '', '项目研发方面负责人：王顺万             要求采用OBIS编码，参考表型SIA01项目，可能会涉及到程序修改。另外LCD显示屏上没有手形符号。这些都需要澄清确认。所以交期将会是一个问题。', '同意', '丁富民2016-05-06 10:54:15', '王功勇2016-05-06 11:06:26', 'sctz2016050590', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('44', '{842DB951-3E97-4618-93AF-7B282F3DB57E}', '61', 'INHE-0228', '2016-05-18 18:48:53', '0000-00-00 00:00:00', '2016-05-25 16:28:29', 'unchecked', 'n', 'n', '', '1', 'sctz2016051891/CDN06/生产通知单', '', '1.三相四线直接介入可更换通信模块代码智能表(不带模块) :此款产品和CDN常规出货的三相表不一样，需要支付DLMS via RS485，目的是用于兼容到BOUYUES的路灯抄表系统。此前也出过样机，调试成功。见OA《CDN06样机申请》。\r\r\r\r\n另外，原来的RJ11接口换成绿色的接口，以上附件中的《接口修改》。\r\r\r\r\n2.CT表没有特殊要求，但是还需和电力公司确认最终出厂设置。\r\r\r\r\r\n3.已经收到PO正本，付款方式为赊销，公司已审批。', '400', '2016-05-18 18:48:53', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN06', 'INHESC2016051331', '2016-07-15', '国际业务二部', '谭雯', '', '04', '生产通知单', '合同已评审，交货后60天TT付款', '同意。', '张丽莹2016-05-24 08:41:04', '郭涛2016-05-24 04:15:28', '同意', '陶保荣2016-05-24 13:41:50', '', '', '', '', '同意', '丁富民2016-05-24 14:06:15', '王功勇2016-05-25 09:28:14', 'sctz2016051891', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('45', '{823120A7-B1EE-4B56-B61E-E00C38874F61}', '61', 'INHE-0381', '2016-05-24 02:32:49', '0000-00-00 00:00:00', '2016-06-20 10:10:28', 'unchecked', 'n', 'n', '', '1', 'sctz2016052492/GN03/生产通知单', '', '无', '0', '2016-05-24 02:32:49', 'TOGO ASSISTANCE SERVICES', 'GN', 'GN03', 'INHESC2016052041', '2016-06-10', '国际业务二部', '张柳芳(Alexie)', '', '05', '生产通知单', '合同已评审，已收到全部货款，同意', '同意', '张丽莹2016-05-26 09:22:11', '郭涛2016-05-26 02:46:57', '同意', '陶保荣2016-05-27 10:27:21', '', '', '', '具体型号/规格由软件事业部黄庆负责确认。', '同意', '丁富民2016-05-27 11:32:25', '王功勇2016-05-30 21:46:26', 'sctz2016052492', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('46', '{EECB661E-F682-4B6D-871C-193AB2BAA5A3}', '61', 'INHE-0432', '2016-05-24 11:48:45', '0000-00-00 00:00:00', '2016-05-25 16:56:16', 'unchecked', 'n', 'n', '', '1', 'sctz2016052493/GR01/生产通知单', '', '', '50', '2016-05-24 11:48:45', 'GMA Global Resources Limited', 'GR', 'GR01', 'INHESC2016033101', null, '国际业务二部', '谭东羊(Timon)', '', '', '生产通知单', '合同已评审，货款已收齐，同意', '同意', '张丽莹2016-05-24 17:12:50', '郭涛2016-05-24 17:07:57', '同意', '陶保荣2016-05-25 08:46:11', '', '', '', '', '同意', '丁富民2016-05-25 09:13:47', '王功勇2016-05-25 09:27:35', 'sctz2016052493', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('47', '{F329F0EC-F727-4802-A45F-52A0F7A2E90F}', '61', 'INHE-0538', '2016-05-25 10:06:52', '0000-00-00 00:00:00', '2016-05-27 15:15:05', 'unchecked', 'n', 'n', '', '1', 'sctz2016052598/HM03/生产通知单', '', '1.已付预付款。2.请查看附件技术规格所列出的条目和之前的出厂设置单： 友好时间设置：非上班时间不断电 a. 周一至周五5:00p.m至次日9:00a.m b. 周六周日整天 在此时间段里，即使没有额度，表计依然不断电，直到此日9:00a.m。 表计将所欠费用记为负值，并从所充额度中扣除。 失相和相错误： 只通过LCD显示通知用户，不断电。这两种只通过显示提醒用户。3.STS供应组代码为600518。4.度数计算 ', '672', '2016-05-25 10:06:52', 'LETECH TECHNOLOGIES SDN BHD', 'HM', 'HM03', 'INHESC2016052443', '2016-07-13', '国际业务二部', '张艳璐', '', '04', '生产通知单', '合同已评审，已收到预付款，同意', '同意', '张丽莹2016-05-26 09:01:00', '郭涛2016-05-26 02:45:15', '同意', '陶保荣2016-05-26 09:02:18', '', '', '', '翻单生产，请江西工厂安排处理', '同意', '丁富民2016-05-26 09:56:58', '王功勇2016-05-27 08:39:58', 'sctz2016052598', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('48', '{FCE9FBC5-C153-4A02-9403-CF63C3D49EE1}', '60', 'INHE-0088', '2016-05-31 19:20:33', '0000-00-00 00:00:00', '2016-11-23 17:56:05', 'unchecked', 'n', 'n', '', '1', 'sctz2016053199/ST20607/生产通知单', '', '急用外购产品，具体见附件要求，请发货深圳。\r\r\r\n2016-5-31 预付全款T/T到账。', '0', '2016-05-31 19:20:33', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20607', 'INHESC2016042925', '2016-06-10', '国际业务一部', '余冬纯', '', '06', '生产通知单', '合同已评审，货款已收到，同意', '同意', '张丽莹2016-06-02 08:41:05', '王维2016-06-01 18:25:52', '同意', '陶保荣2016-06-02 09:46:31', '', '', '', '', '同意', '丁富民2016-06-02 09:53:34', '王功勇2016-06-02 10:00:58', 'sctz2016053199', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('49', '{1D4B0846-50B7-4C7C-9EDA-CFD2844709C9}', '60', 'INHE-0088', '2016-06-03 20:30:59', '0000-00-00 00:00:00', '2016-06-20 10:10:09', 'unchecked', 'n', 'n', '', '1', 'sctz2016060301/JES07/生产通知单', '', '翻单JES-05', '106', '2016-06-03 20:30:59', 'JES Instrumentation * Controls', 'JES', 'JES07', 'INHESC2016060351', '2016-07-03', '国际业务一部', '余冬纯', '', '05', '生产通知单', '合同已评审，预付款已收', '同意', '张丽莹2016-06-08 15:11:29', '王维2016-06-06 12:43:03', '同意', '陶保荣2016-06-08 18:03:11', '', '', '', '', '同意。翻单生产请江西工厂处理。', '丁富民2016-06-08 18:04:58', '王功勇2016-06-08 18:42:43', 'sctz2016060301', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('50', '{A15E9C82-DBAA-4B9F-90B1-D25E9D4E663D}', '60', 'INHE-0066', '2016-06-07 16:34:57', '0000-00-00 00:00:00', '2016-06-12 08:36:13', 'unchecked', 'n', 'n', '', '1', 'sctz2016060701/白雪607/生产通知单', '', '\r\r\r\r\r\n\r\r\r\r\r\r\r\r\nAPC220-43-0B要求：\r\r\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\r\r\r\r\r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\r\r\r\r\r\r\r\n3、用于电表上，带自动组网功能。              \r\r\r\r\r\r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43”，主要用于区分开其他功能的无线通信模块。              \r\r\r\r\r\r\r\r\n5、电压源：3.5-5.5V              \r\r\r\r\r\r\r\r\n6、频率： 433.05-434.7 MHz           \r\r\r\r\r\r\r\r\n7、温度范围：-30-+80              \r\r\r\r\r\r\r\r\n8、外包装箱用纸贴上唛头：APC220-43\r\r\r\r\r\r\r\n9、出厂是发射功率设为10mW.\r\r\n\r\r\nAPC910M-43-B要求：\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。  \r\r\r\r\r\r\n2、安美通集抄无线射频通信模块。             \r\r\r\r\r\r\n3、电压：4.5-6V             \r\r\r\r\r\r\n4、频段：432-434MHz              \r\r\r\r\r\r\n5、SMA连接线必须装在电路板上。\r\r\r\r\n6、出厂时发射功率设为10mW.\r\r\r\n\r\r\r\n\r\r\r\r\r\r\n\r\r\n\r\r\r\r\r\r\n\r\rAPC220-43-2A要求：\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\r\r\r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（天线需要焊在模块上，天线与模块平行焊。）       \r\r\r\r\r\r\n3、用于掌上电脑，点对点抄读功能，但不相互干扰。       \r\r\r\r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43-2”，主要用于区分开其他功能的无线通信模块。       \r\r\r\r\r\r\n5、电压源：3.5-5.5V       \r\r\r\r\r\r\n6、频率：433,05 – 434,79 MHz       \r\r\r\r\r\r\n7、温度范围：-30-+80       \r\r\r\r\r\r\n8、外包装箱用纸贴上唛头：APC220-43-2\r\n9、出厂时发射功率设为10mW。     \r\r\r\r\r\r\n					\r\r\r\r\r\r\nUSB-APC220-43-2A要求：\r\r\r\r\r\r\n1、供应商为安美通。   \r\r\r\r\r\r\n2、外壳上只需贴USB-APC220-43-2，不需其它任何信息和Logo.   \r\r\r\r\r\r\n3、需升级为V3.0版本。										\r\r\r\r4、出厂时发射功率设为10mW。\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\nAPC910M-43-B要求：\r\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。  \r\r\r\r\r\r\r\n2、安美通集抄无线射频通信模块。             \r\r\r\r\r\r\r\n3、电压：4.5-6V             \r\r\r\r\r\r\r\n4、频段：432-434MHz              \r\r\r\r\r\r\r\n5、SMA连接线必须装在电路板上。\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\nAPC220-43-0B要求：\r\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\r\r\r\r\r\r\n2、白雪项目\r\r\r\r\r\r\n专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\r\r\r\r\r\r\n3、用于电表上，带自动组网功能。              \r\r\r\r\r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43”，主要用于区分开其他功能的无线通信模块。              \r\r\r\r\r\r\r\n5、电压源：3.5-5.5V              \r\r\r\r\r\r\r\n6、频率： 433.05-434.7 MHz           \r\r\r\r\r\r\r\n7、温度范围：-30-+80              \r\r\r\r\r\r\r\n8、外包装箱用纸贴上唛头：APC220-43\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\nAPC220-43-2A要\r\r\r\r\r\r\n求：\r\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\r\r\r\r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（天线需要焊在模块上，天线与模块平行焊。）       \r\r\r\r\r\r\r\n3、用于掌上电脑，点对点抄读功能，但不相互干扰。       \r\r\r\r\r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43-2”，主要用于区分开其他功能的无线通信模块。       \r\r\r\r\r\r\r\n5、电压源：3.5-5.5V       \r\r\r\r\r\r\r\n6、频率：433,05 – 434,79 MHz       \r\r\r\r\r\r\r\n7、温度范围：-30-+80       \r\r\r\r\r\r\r\n8、外包装箱用纸贴上唛头：APC220-43-2      \r\r\r\r\r\r\r\n					\r\r\r\r\r\r\r\nUSB-APC220-43-2A要求：\r\r\r\r\r\r\r\n1、供应商为安美通。   \r\r\r\r\r\r\r\n2、外壳上只需贴USB-APC220-43-2，不需其它任何信息和Logo.   \r\r\r\r\r\r\r\n3、需升级为V3.0版本。										\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\nAPC220-43-2A要求：\r\r\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\r\r\r\r\r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（天线需要焊在模块上，天线与模块平行焊。）       \r\r\r\r\r\r\r\r\n3、用于掌上电脑，点对点抄读功能，但不相互干扰。       \r\r\r\r\r\r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43-2”，主要用于区分开其他功能的无线通信模块。       \r\r\r\r\r\r\r\r\n5、电压源：3.5-5.5V       \r\r\r\r\r\r\r\r\n6、频率：433,05 – 434,79 MHz       \r\r\r\r\r\r\r\r\n7、温度范围：-30-+80       \r\r\r\r\r\r\r\r\n8、外包装箱用纸贴上唛头：APC220-43-2      \r\r\r\r\r\r\r\r\n					\r\r\r\r\r\r\r\r\nUSB-APC220-43-2A要求：\r\r\r\r\r\r\r\r\n1、供应商为安美通。   \r\r\r\r\r\r\r\r\n2、外壳上只需贴USB-APC220-43-2，不需其它任何信息和Logo.   \r\r\r\r\r\r\r\r\n3、需升级为V3.0版本。', '0', '2016-06-07 16:34:57', 'Energomera CJSC', '白雪', '白雪607', 'INHESC2016060703', '2016-06-20', '国际业务一部', '邱洁', '', '05', '生产通知单', '合同已评审，预付款已收，同意', '同意', '张丽莹2016-06-08 14:26:30', '王维2016-06-08 13:57:49', '同意', '陶保荣2016-06-08 15:12:32', '', '', '', '', '同意', '丁富民2016-06-08 16:32:17', '王功勇2016-06-08 17:08:43', 'sctz2016060701', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('51', '{472FA405-FFE4-4098-8AED-29BC2EA36A86}', '60', 'INHE-0066', '2016-06-08 11:22:07', '0000-00-00 00:00:00', '2016-06-24 11:03:10', 'unchecked', 'n', 'n', '', '1', 'sctz2016060801/白云601/生产通知单', '', '1、按2015年11月提供给客户的最近样机生产。\r\n2、电表将分机芯（PCBA）、LCD显示板、铝面板、底壳、按键、五金件几大部分出货。\r\r\n3、双回路计量。\r\r\n4、能支持复费率和阶梯电价两种结算方式。（默认设置见随后提供的出厂设置单）\r\r\n5、带远程通断电功能。\r\r\n6、负荷门限设置。\r\r\n7、能承受电压异常的瞬间波动，电压异常时，电表自动断电，电压恢复正常时，电表自动恢复供电。\r\r\n8、能编程设置为后付费功能   \r\r\n\r\r\n', '5000', '2016-06-08 11:22:07', '\"Aspan-Energy \" LTD', '白云', '白云601', 'INHESC2016060752', '2016-07-10', '国际业务一部', '邱洁', '', '04', '生产通知单', '合同已评审，合同总金额159000美元，50%预付，已到38292+6707 美元，还差34501美元，业务申请先备料，请领导审批\r\n', '同意', '张丽莹2016-06-23 13:55:27', '王维2016-06-08 13:55:27', '同意', '陶保荣2016-06-23 16:37:26', '', '', '', '', '同意', '丁富民2016-06-23 18:54:42', '王功勇2016-06-24 08:18:31', 'sctz2016060801', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('52', '{5ED58E88-9833-4211-81A7-E532F6E30CAF}', '61', 'INHE-0490', '2016-06-13 11:03:37', '0000-00-00 00:00:00', '2016-06-20 10:09:40', 'unchecked', 'n', 'n', '', '1', 'sctz2016061301/CP06/生产通知单', '', '此为CP项目，翻单产品，规格请见附件，其他请按照以往规格进行生产。 特殊要求： 1. 客户要求去掉电表里的Buzzer蜂鸣器   2. 电表负荷门限改为18.4kW ', '500', '2016-06-13 11:03:37', 'Caravan Park Electrical Services Limited', 'CP', 'CP06', 'INHESC2016060701', null, '国际业务二部', '范辉英', '', '04', '生产通知单', '合同已评审，货款已收到，同意', '同意', '张丽莹2016-06-13 13:44:53', '郭涛2016-06-13 12:17:03', '同意', '陶保荣2016-06-13 15:37:17', '', '注意有特殊要求。', '', '', '同意，翻单生产请江西工厂处理', '丁富民2016-06-13 17:52:07', '王功勇2016-06-13 18:35:27', 'sctz2016061301', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('53', '{D97E67EA-9EB0-4AF4-B1FB-AA136BBBF10A}', '60', 'INHE-0088', '2016-06-13 18:15:34', '0000-00-00 00:00:00', '2016-06-14 17:36:56', 'unchecked', 'n', 'n', '', '1', 'sctz2016061302/WZ601/生产通知单', '', '1、REB601项目备用表50台；\r\r\r\r\n2、WZ601项目备用表60台单相表和3台三相表。\r\r\r\n配套铭牌（单相表50个为REB601铭牌、60个为WZ601铭牌）无需粘贴，无需提供表号贴纸，无需说明书，内盒外箱使用WZ601图纸。', '113', '2016-03-16 18:09:41', 'Ideal Enterprise', 'WZ', 'WZ601', 'INHESC2016030380', '2016-06-30', '国际业务一部', '余冬纯', '', '06', '生产通知单', '合同已评审，已收到即期信用证，同意', '同意', '张丽莹2016-06-14 08:41:52', '王维2016-06-13 18:52:30', '同意', '陶保荣2016-06-14 08:45:27', '', '', '', '', '同意。供货产品备用，由江西工厂安排处理。', '丁富民2016-06-14 09:06:22', '王功勇2016-06-14 09:31:11', 'sctz2016061302', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('54', '{433E9FCB-3DD4-487A-8F6F-004AAE92DABD}', '61', 'INHE-0222', '2016-06-15 15:28:43', '0000-00-00 00:00:00', '2016-06-30 13:35:37', 'unchecked', 'n', 'n', '', '1', 'sctz2016061501/PSA10/生产通知单', '', '1.2000台订单为PSA6项目电力公司EPM翻单，同已交货的产品规格功能一致，计量单元不带LCD显示，铭牌显示及出厂设置单需要重新确认（同刚刚交货的900台一致），CIU的铭牌上增加“固件版本号FM02”（同刚刚交货的900台一致），避免同2015年已交货的产品的CIU混用，此2000台要求最晚7月29日完成生产交货。\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\n2.3000台订单为新研发产品，计量单元带LCD显示，要求最晚8月13日完成生产交货。\r\r\r\r\n\r\r\r\r\n3.现已收到部分预付款水单USD10400，如附件，其余预付款本周内可全部收齐，交期特别紧张，申请款未到前开始备料生产，请批准。', '5000', '2016-06-15 15:28:43', 'STAEKKA SAS', 'PSA10', 'PSA10', 'INHESC2016061503', '2016-07-29', '国际业务二部', '张红丽', '', '04', '生产通知单', '合同已评审，2000台全款已收，3000台30%预付款本周五收', '同意', '张丽莹2016-06-30 09:04:02', '郭涛2016-06-29 18:46:35', '同意', '陶保荣2016-06-30 09:54:36', '', '1、2000台翻单；2、3000台带LCD新产品正在研发，要求提前备料。', '', '1：翻单生产的请江西工厂进行安排处理；2：新研发产品正在准备之中，备料物料章春鹏已经给出OA，请江西工厂安排备料。7月20日计划完成研发工作。', '同意。', '丁富民2016-06-30 11:10:24', '王功勇2016-06-30 11:19:11', 'sctz2016061501', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('55', '{EF45A129-6343-4ED4-9F66-7E43EA870E28}', '61', 'INHE-0431', '2016-06-15 15:54:25', '0000-00-00 00:00:00', '2016-06-20 10:09:08', 'unchecked', 'n', 'n', '', '1', 'sctz2016061502/TNL01/生产通知单', '', '1. SGC 600415   2.预存50kwh电量   3.要求电表和断路器装在表箱（请注意是两表位表箱）里出货  4.符合IEC 62052-11 and IEC 62050-21 ', '500', '2016-06-15 15:54:25', 'Tinuten Nigeria Limited', 'TNL', 'TNL01', 'INHESC2016061504', '2016-06-29', '国际业务二部', '刘佩(Ted)', '', '04', '生产通知单', '合同已评审，货款已收，同意', '同意', '张丽莹2016-06-17 13:40:34', '郭涛2016-06-17 11:53:31', '同意', '陶保荣2016-06-17 16:04:06', '', '', '', '', '同意', '丁富民2016-06-17 16:19:42', '王功勇2016-06-17 16:23:59', 'sctz2016061502', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('56', '{9DA6B11E-728B-4FC4-A950-1A5A2D32099B}', '60', 'INHE-0088', '2016-06-17 16:19:51', '0000-00-00 00:00:00', '2016-06-20 14:10:29', 'unchecked', 'n', 'n', '', '1', 'sctz2016061701/ST20503/生产通知单', '', '\r\r\nST20503客诉第四批、第五批散件物料免费补料更换30000个故障插片，多退（后续订单充数）少补（新订单发货或单独快递）。请空运坚固小纸箱麻袋包装后打扎带，发货深圳空运出货。', '0', '2016-06-17 16:19:51', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD', 'ST20', 'ST20503', '23398', '2016-06-23', '国际业务一部', '余冬纯', '', '06', '生产通知单', '合同已评审，之前货已发完，此次为免费补故障物料', '同意', '张丽莹2016-06-20 08:55:02', '王维2016-06-20 08:33:49', '同意。', '陶保荣2016-06-20 09:22:15', '', '', '', '', '同意', '丁富民2016-06-20 13:40:18', '王功勇2016-06-20 14:08:34', 'sctz2016061701', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('57', '{5BB2A7DE-AA6F-4D07-97D1-439671C9EE78}', '60', 'INHE-0066', '2016-06-27 10:49:35', '0000-00-00 00:00:00', '2016-06-30 13:35:12', 'unchecked', 'n', 'n', '', '1', 'sctz2016062702/白雪608/生产通知单', '', '1、采用新模具结构供货。     \r\r\n2、做防水灌胶处理。\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。      \r\r\n4、MAC地址为该表表号（表地址）的最后六位数字，该地址激光雕刻在表外壳背部。       \r\r\n5、PLC载波显示单元的铭牌标识为：CE208。         \r\r\n6、显示单元不需要贴易碎贴。        \r\r\n7、出厂设置：           \r\r\n1）表内时间为：GMT+4           \r\r\n2）冬夏令时转换功能关闭。           \r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\n5）特殊节假日没有。           \r\r\n6）电表密码：000000.           \r\r\n7）负荷门限：0.           \r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\n9）取负荷点的平均时间：30分钟。          \r\r\n8、继电器：100A，但标识采用120A。      \r\r\n9、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）       \r\r\n10、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\n11、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU的内盒中。  \r\r\n\r\r\n\r\r\n										\r\r\n										\r\r\n', '10020', '2016-06-27 10:49:35', 'Energomera CJSC', '白雪', '白雪608', 'INHESC2016062701', '2016-08-05', '国际业务一部', '邱洁', '', '04', '生产通知单', '合同已评审，合同规定7.5前收预付款，业务申请先备料', '同意', '张丽莹2016-06-29 17:11:06', '王维2016-06-28 14:33:08', '同意', '陶保荣2016-06-30 09:53:44', '', '', '', '1：翻单生产，请江西工厂安排处理。2：结构上批准生产问题反映，研发准备更新烧录程序，目前正在测试/确认之中，希望本次能使用最新确认的程序进行生产。', '同意', '丁富民2016-06-30 11:12:35', '王功勇2016-06-30 11:17:57', 'sctz2016062702', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('62', '{09166925-CF66-4E9E-A184-B08D841C3750}', '60', 'INHE-0088', '2016-07-05 18:11:18', '0000-00-00 00:00:00', '2016-08-04 08:47:50', 'unchecked', 'n', 'n', '', '1', 'sctz2016070501/KG601/生产通知单', '', '1008台单费率表合同技术规格：DTS27三相4线10（100）A，3个计量单元，单费率，kWh, kVarh计量，一级、带锂亚电池，LCD显示峰值非峰值#FE54`\r\r\n我司自己开模的三相CT表外壳（带可拔插模块），其他功能要求不变，延伸端盖透明，\r\r\n包装要求液晶PCB和底壳一起，上盖和主PCB一起,产品图片请见附件\r\r\n500台双费率表合同（项目代号：KGT01，合同号：INHESC61150907WW）技术规格：DTS27三相4线10（100）A，3个计量单元，双费率，kWh, kVarh计量，一级、带锂亚电池，LCD显示峰值非峰值#FE54`\r\r\n我司自己开模的三相CT表外壳，其他功能要求不变，延伸端盖透明，\r\r\n包装要求液晶PCB和底壳一起，上盖和主PCB一起\r\r\n请提供设计唛头面板供客户确认。', '1508', '2016-07-05 18:11:18', 'Khawja Group', 'KG', 'KG601', 'INHESC2016062401', '2016-08-25', '国际业务一部', '余冬纯', '', '06', '生产通知单', '合同已评审，收到5000美元', '同意', '张丽莹2016-08-03 10:22:40', '王维2016-08-03 09:28:52', '同意', '陶保荣2016-08-03 10:36:12', '', '', '', '', '', '丁富民2016-08-03 11:42:07', '王功勇2016-08-04 02:03:27', 'sctz2016070501', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('63', '{19E91DEF-FF15-4A90-90DE-2E913B5A7D60}', '60', 'INHE-0088', '2016-07-05 18:25:05', '0000-00-00 00:00:00', '2016-07-07 14:17:00', 'unchecked', 'n', 'n', '', '1', 'sctz2016070502/JES08/生产通知单', '', '翻单JES07,同时出货', '306', '2016-07-05 18:25:05', 'JES Instrumentation * Controls', 'JES', 'JES08', 'INHESC2016062001', null, '国际业务一部', '余冬纯', '', '06', '生产通知单', '合同已评审，预付款已收', '同意', '张丽莹2016-07-07 11:01:39', '王维2016-07-07 09:57:23', '同意', '陶保荣2016-07-07 11:37:30', '', '', '', '', '同意', '丁富民2016-07-07 11:47:58', '王功勇2016-07-07 14:08:14', 'sctz2016070502', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('64', '{186286B6-3EAF-41DF-B40B-7E2303265010}', '60', 'INHE-0549', '2016-07-18 13:44:46', '0000-00-00 00:00:00', '2016-07-19 13:25:48', 'unchecked', 'n', 'n', '', '1', 'sctz2016071801/NF2-01/生产通知单', '', '', '140000', '2016-07-18 13:44:46', 'AB consulting', 'NF2', 'NF2-01', 'INHESC2016053148', '2016-11-30', '国际业务一部', '王秀明', '第三方检验', '02', '生产通知单', '合同已评审，结算方式为即期信用证', '同意，部分技术细节正在于客户确认中，将在确认后提供，请生产提前安排长周期物料采购与备货。', '张丽莹2016-07-19 08:44:04', '王维2016-07-19 08:27:06', '同意', '陶保荣2016-07-19 10:23:46', '', '希望尽快将确定的物料下单采购，在结束PY02订单生产后，立即启动NF2的生产。', '', '单相可更换通信模块代码表，为降低成本继电器/接线铜排正在安排设计/打样/确认。MCU主控芯片采购周期长可以先安排备货，其他等正式BOM表。', '同意', '丁富民2016-07-19 10:44:55', '王功勇2016-07-19 11:25:09', 'sctz2016071801', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('65', '{C70D375D-4D75-45BA-B61D-A6595E1CEF4C}', '60', 'INHE-0066', '2016-07-21 16:14:50', '0000-00-00 00:00:00', '2016-07-22 13:50:05', 'unchecked', 'n', 'n', '', '1', 'sctz2016072101/白雪609/生产通知单', '', '\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\nAPC220-43-0B要求：\r\r\r\r\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\r\r\r\r\r\r\r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\r\r\r\r\r\r\r\r\r\n3、用于电表上，带自动组网功能。              \r\r\r\r\r\r\r\r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43”，主要用于区分开其他功能的无线通信模块。              \r\r\r\r\r\r\r\r\r\r\n5、电压源：3.5-5.5V              \r\r\r\r\r\r\r\r\r\r\n6、频率： 433.05-434.7 MHz           \r\r\r\r\r\r\r\r\r\r\n7、温度范围：-30-+80              \r\r\r\r\r\r\r\r\r\r\n8、外包装箱用纸贴上唛头：APC220-43\r\r\r\r\r\r\r\r\r\r\n9、出厂是发射功率设为10mW.\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\nAPC910M-43-B要求：\r\r\r\r\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。  \r\r\r\r\r\r\r\r\r\r\n2、安美通集抄无线射频通信模块。             \r\r\r\r\r\r\r\r\r\r\n3、电压：4.5-6V             \r\r\r\r\r\r\r\r\r\r\n4、频段：432-434MHz              \r\r\r\r\r\r\r\r\r\r\n5、SMA连接线必须装在电路板上。\r\r\r\r\r\r\r\r\r\r\n6、出厂时发射功率设为10mW.\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\n\r\rAPC220-43-2A要求：\r\r\r\r\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\r\r\r\r\r\r\r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（天线需要焊在模块上，天线与模块平行焊。） 3、用于掌上电脑，点对点抄读功能，但不相互干扰。       \r\r\r\r\r\r\r\r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43-2”，主要用于区分开其他功能的无线通信模块。       \r\r\r\r\r\r\r\r\r\r\n5、电压源：3.5-5.5V       \r\r\r\r\r\r\r\r\r\r\n6、频率：433,05 – 434,79 MHz       \r\r\r\r\r\r\r\r\r\r\n7、温度范围：-30-+80       \r\r\r\r\r\r\r\r\r\r\n8、外包装箱用纸贴上唛头：APC220-43-2\r\r\r\r\r\r\r\r\r\r\n9、出厂时发射功率设为10mW。     \r\r\r\r\r\r\r\r\r\r\n       \r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\rAPC220-43-3B要求：\r\r\r\r\r\r\r\r\r\r\r\r\n1、白雪项目专用安美通普通无线射频通信模块，不带嵌入式天线。（不需要把天线焊在模块上。）           2、用于电表上，带自动组网功能。           \r\r\r\r\r\r\r\r\r\r\r\r\n3、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43-3”，主要用于区分开其他功能的无线通信模块。\r\n 4、出厂时发射功率设为10mW.          \r\r\r\r\r\r\r\r\r\r\r\r\n4、电压源：3.5-5.5V           \r\r\r\r\r\r\r\r\r\r\r\r\n5、频率：433.05-434.7 MHz\r\r\r\r\r\r\r\r\r\r\r\r\n6、温度范围：-30-+80           \r\r\r\r\r\r\r\r\r\r\r\r\n7、外包装箱用纸贴上唛头：APC220-43\r\r\r\r\r\r\r\r\r\r\r\n8、', '0', '2016-07-21 16:14:50', 'Energomera CJSC', '白雪', '白雪609', 'INHESC2016072101', '2016-08-01', '国际业务一部', '邱洁', '', '05', '生产通知单', '合同已评审，预付款已收，同意', '同意', '张丽莹2016-07-22 09:03:53', '王维2016-07-21 16:38:33', '同意', '陶保荣2016-07-22 09:10:52', '', '', '', '', '同意', '丁富民2016-07-22 13:30:54', '王功勇2016-07-22 13:41:07', 'sctz2016072101', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('66', '{71B698EC-31C0-4A61-8869-1E38D29E451E}', '60', 'INHE-0066', '2016-08-09 10:39:51', '0000-00-00 00:00:00', '2016-08-10 10:43:20', 'unchecked', 'n', 'n', '', '1', 'sctz2016080901/白雪611/生产通知单', '', '\r\r\r\n\r\r\r\nAPC220-43-0B要求：\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\r\r\n3、用于电表上，带自动组网功能。              \r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43”，主要用于区分开其他功能的无线通信模块。              \r\r\r\n5、电压源：3.5-5.5V              \r\r\r\n6、频率： 433.05-434.7 MHz           \r\r\r\n7、温度范围：-30-+80              \r\r\r\n8、外包装箱用纸贴上唛头：APC220-43\r\r\r\n9、出厂是发射功率设为10mW.\r\r\r\n\r\r\r\nAPC910M-43-B要求：\r\r\r\n1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。  \r\r\r\n2、安美通集抄无线射频通信模块。             \r\r\r\n3、电压：4.5-6V             \r\r\r\n4、频段：432-434MHz              \r\r\r\n5、SMA连接线必须装在电路板上。\r\r\r\n6、出厂时发射功率设为10mW.\r\r\r\n\r\r\r\n\r\r\r\n\r\r\r\n\r\r\r\nAPC220-43-2A要求：\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（天线需要焊在模块上，天线与模块平行焊。）       \r\r\r\n3、用于掌上电脑，点对点抄读功能，但不相互干扰。       \r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43-2”，主要用于区分开其他功能的无线通信模块。       \r\r\r\n5、电压源：3.5-5.5V       \r\r\r\n6、频率：433,05 – 434,79 MHz       \r\r\r\n7、温度范围：-30-+80       \r\r\r\n8、外包装箱用纸贴上唛头：APC220-43-2\r\r\r\n9、出厂时发射功率设为10mW。     \r', '0', '2016-08-09 10:39:51', 'Energomera CJSC', '白雪', '白雪611', 'INHESC2016080302', '2016-08-22', '国际业务一部', '邱洁', '', '05', '生产通知单', '合同已评审，预付款已收', '同意', '张丽莹2016-08-09 18:13:45', '王维2016-08-09 13:40:36', '同意', '陶保荣2016-08-10 08:37:11', '', '', '', '', '同意', '丁富民2016-08-10 08:58:39', '王功勇2016-08-10 09:00:01', 'sctz2016080901', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('67', '{CE7E7F7C-4A98-4DA8-94C2-5C2D6352D136}', '60', 'INHE-0066', '2016-08-10 18:06:48', '0000-00-00 00:00:00', '2016-08-12 09:27:23', 'unchecked', 'n', 'n', '', '1', 'sctz2016081001/白雪610/生产通知单', '', '1、采用双方验证过的程序版本TMF2-1B-16032201 2、修改过脉冲输出的阻抗。						\r\n3. 铭牌、MAC地址等需要镭雕在电表外壳上； 4. MAC地址铭牌的6位数字为该表表号的最后六位数字； 5. 表内时间为GMT+3#FE54` 6. 冬夏令时转换功能关闭； 7. 客户其他相关要求在OA上反应给研发； 7. 其他未尽要求请按照客户技术规格要求来做。', '1042', '2016-08-10 18:06:48', 'Energomera CJSC', '白雪', '白雪610', 'INHESC2016080301', '2016-09-12', '国际业务一部', '邱洁', '', '04', '生产通知单', '合同已评审，预付款已收，同意', '同意', '张丽莹2016-08-11 09:50:55', '王维2016-08-11 09:37:14', '同意', '陶保荣2016-08-11 14:40:31', '', '', '', '', '同意', '丁富民2016-08-11 15:04:06', '王功勇2016-08-12 08:46:33', 'sctz2016081001', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('68', '{9FD49CDB-2D8D-4DEA-ACC1-336BDF57A7A3}', '60', 'INHE-0066', '2016-08-12 15:29:30', '0000-00-00 00:00:00', '2016-08-15 14:18:17', 'unchecked', 'n', 'n', '', '1', 'sctz2016081201/白雪611/生产通知单', '', '\r\r\r\r\rAPC910M-43-B要求：\r\n1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。\r\n2、安美通集抄无线通信模块。\r\n3、电压：4.5-6V\r\n4、频段：432-434MHZ\r\n5、SmA连接线必须装在电路板上。\r\n6、出厂时发射功率设为10mW。\r\r\n\r\r\nUSB-APC220-43-0要求：\r\r\r\r\r\r\r\n1、供应商为安美通。   \r\r\r\r\r\r\r\n2、外壳上只需贴USB-APC220-43-0，不需其它任何信息及Logo。 \r\r\r\r\r\r\r\n3、升级为V3.0版。\r\r\r\r\r\r\r\n4、出厂时发射功率设为10mW。\r\r\r\r\n\r\r\r\r\nUSB-APC220-43-2要求：\r\r\r\r\n1、供应商为安美通。   \r\r\r\r\n2、外壳上只需贴USB-APC220-43-2，不需其它任何信息和Logo.   \r\r\r\r\n3、需升级为V3.0版本。\r\r\r\r\n4、出厂时发射功率设为10mW。\r\r\r\r\n\r\r\r\r\n\r\r\r\r\n', '0', '2016-08-12 15:29:30', 'Energomera CJSC', '白雪', '白雪611', 'INHESC2016080302', '2016-08-22', '国际业务一部', '邱洁', '', '05', '生产通知单', '合同已评审，预付款已收', '同意', '张丽莹2016-08-15 08:38:57', '王维2016-08-13 12:52:37', '同意', '陶保荣2016-08-15 08:43:20', '', '', '', '', '同意', '丁富民2016-08-15 11:08:52', '王功勇2016-08-15 13:43:17', 'sctz2016081201', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('69', '{EC580027-BC81-48D6-9730-6C7AC0DB4645}', '60', 'INHE-0088', '2016-08-12 17:54:51', '0000-00-00 00:00:00', '2016-11-23 17:55:49', 'unchecked', 'n', 'n', '', '1', 'sctz2016081202/BPD601/生产通知单', '', '电力公司有表号要求；\r\n除订单1575个IC卡，根据电力公司要求，需额外配套1575个空白IC卡\r\r\n同时，避免现场安装问题，申请配套0.2%备用表即32台表（不贴铭牌，铭牌单独包装，不粘胶）一起出货', '15750', '2016-08-12 17:54:51', 'Ideal Enterprise', 'BPD', 'BPD601', 'INHESC2016040809', '2016-09-25', '国际业务一部', '余冬纯', '', '06', '生产通知单', '合同已评审，尚未收到信用证', '同意，此订单信用证开立中，预计10天内收到，由于交期较紧，生产通知单先下先启动物料采购。', '张丽莹2016-08-17 14:35:08', '王维2016-08-17 09:53:46', '同意', '陶保荣2016-08-17 16:29:56', '', '注意：希望尽快收到LC，否则存在风险。', '', '产品还没有研发完成，项目技术负责人何梓劲。', '同意', '丁富民2016-08-17 17:21:59', '王功勇2016-08-17 18:00:40', 'sctz2016081202', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('70', '{7BEC41A8-EB01-4DEF-AF50-3AB55ABEE0BB}', '61', 'INHE-0534', '2016-08-14 18:37:31', '0000-00-00 00:00:00', '2016-08-22 08:32:48', 'unchecked', 'n', 'n', '', '1', 'sctz2016081401/MCA01/生产通知单', '', '1.产品数量可能变更，预计8月19日确定数量，会再发变更。', '295', '2016-08-14 18:37:31', 'Millennium Challenge Account - Malawi', 'MCA', 'MCA01', 'INHESC2016070807', '2016-09-10', '国际业务二部', '徐聪', '', '02', '生产通知单', '未收到货款', '同意', '黄兰兰2017-03-17 17:04:03', '郭涛2017-03-17 15:45:22', '同意', '陶保荣2017-03-17 17:24:43', '', '', '', '三相多功能表（CT表）以及GPRS模块已经生产完成，其他外协采购。', '同意。', '丁富民2017-03-17 17:33:56', '王功勇2017-03-17 18:00:28', 'sctz2016081401', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('71', '{56E5A289-9158-4ADF-8588-3C1DEA32A8DB}', '60', 'INHE-0066', '2016-08-18 17:17:23', '0000-00-00 00:00:00', '2016-08-26 15:12:00', 'unchecked', 'n', 'n', '', '1', 'sctz2016081801/白雪612/生产通知单', '', 'APC910M-43-B要求：\r\n1、采用安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\n2、安美通集抄无线射频通信模块。\r\n3、电压：4.5V-6V\r\n4、频段：432-434Mhz\r\n5、SMA连接线必须装在电路板上。\r\n6、出厂时发射功率设为10mW。', '0', '2016-08-18 17:17:23', 'Energomera CJSC', '白雪', '白雪612', 'INHESC2016081801', '2016-08-31', '国际业务一部', '邱洁', '', '05', '生产通知单', '合同已评审，预付款已收', '同意', '张丽莹2016-08-26 10:31:42', '王维2016-08-24 10:55:27', '同意', '陶保荣2016-08-26 14:46:03', '', '', '', '', '同意', '丁富民2016-08-26 15:08:02', '王功勇2016-08-26 15:10:54', 'sctz2016081801', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('72', '{CC27E53A-ADBC-4E32-B464-C08C6A3006D3}', '61', 'INHE-0588', '2016-08-18 17:12:22', '0000-00-00 00:00:00', '2016-08-22 15:51:25', 'unchecked', 'n', 'n', '', '1', 'sctz2016081802/TNL02/生产通知单', '', '1. SGC 600415   2.预存50kwh电量   3.要求电表和断路器装在表箱里出货  4.符合IEC 62052-11 and IEC 62050-21 5.客户40%货款已到账，请工厂先开始更改标识，尾款到账再安排发货 6.客户答应自己贴标识 7.其他要求同TNL01。', '900', '2016-08-18 17:12:22', '		Tinuten Nigeria Limited', 'TNL02', 'TNL02', 'INHESC2016080502', '2016-09-02', '国际业务二部', '胡林', '', '04', '生产通知单', '合同已评审，已收到客户部分预付款', '同意', '张丽莹2016-08-22 09:35:21', '郭涛2016-08-19 20:27:58', '同意', '陶保荣2016-08-22 10:18:48', '', '', '', '', '同意', '丁富民2016-08-22 11:05:58', '王功勇2016-08-22 14:10:02', 'sctz2016081802', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('73', '{91135147-1277-4DDC-AC37-2562E231B8F7}', '61', 'INHE-0228', '2016-08-19 10:01:15', '0000-00-00 00:00:00', '2016-10-24 09:15:57', 'unchecked', 'n', 'n', '', '1', 'sctz2016081901/CDN14/生产通知单', '', '已经收到PO，合同评审还在流程中，LC草稿已经收到，请先采购物料、启动生产。							\r', '12672', '2016-08-19 10:01:15', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN14', 'INHESC2016081901', '2016-10-08', '国际业务二部', '谭雯', '', '04', '生产通知单', '合同已评审，信用证未收，发货期紧迫先下单', '同意先备料；请谭雯抓紧收正本LC，及时反馈LC状态。', '张丽莹2016-08-19 17:46:11', '郭涛2016-08-19 17:11:39', '同意', '陶保荣2016-08-22 08:32:42', '', '1、请业务尽快拿到LC；                                                              2、采用慧联RF模块，请研发做BOM变更。', '', '业务没有明确RF要求，仍按照原生产BOM表、程序进行翻单生产。---安美通RF无线模块按最新版程序确认资料核对版本号。', '同意', '丁富民2016-08-22 10:05:39', '王功勇2016-08-22 10:40:26', 'sctz2016081901', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('74', '{633B114D-8313-4393-BFBB-5AA46D7255A2}', '61', 'INHE-0222', '2016-08-19 15:10:10', '0000-00-00 00:00:00', '2016-08-23 10:36:07', 'unchecked', 'n', 'n', '', '1', 'sctz2016081902/PSA10602/生产通知单', '', '1.此项目编号为PSA10602，为PSA10项目中带LCD显示的DIN表翻单，部分翻单资料如附件，已收到15%预付款，请安排生产。\r\r\n\r\r\n2. 请研发提供带LCD显示的表更新版操作手册，客户培训使用。', '5375', '2016-08-19 15:10:10', 'STAEKKA SAS', 'PSA10', 'PSA10602', 'INHESC2016071301', '2016-09-30', '国际业务二部', '张红丽', '', '04', '生产通知单', '合同已评审，已收15%预付款', '同意', '张丽莹2016-08-22 15:33:29', '郭涛2016-08-19 16:53:32', '同意', '陶保荣2016-08-23 08:55:33', '', '请尽快将MCU模具LCD显示窗口修改到位，确保超声焊面镜可靠、美观。', '', 'PSA10项目产品翻单，请江西工厂处理。（LCD显示屏部分作模具修改，方案已经给江西达实，时间预计二周）。PSA10的操作手册已经给客户服务部。', '同意。', '丁富民2016-08-23 09:06:18', '王功勇2016-08-23 10:24:17', 'sctz2016081902', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('75', '{57F9564C-FEFE-43A1-A790-224A69F15128}', '61', 'INHE-0222', '2016-08-19 15:28:09', '0000-00-00 00:00:00', '2016-08-23 10:35:46', 'unchecked', 'n', 'n', '', '1', 'sctz2016081904/PSA6602/生产通知单', '', '1.此项目编号PSA6602，为PSA6项目中BS两相3线分体双绞线通信的表翻单，翻单资料待确认。\r\n\r\n2.已收到15%预付款，请安排生产。 ', '309', '2016-08-19 15:28:09', 'STAEKKA SAS', 'PSA6', 'PSA6602', 'INHESC2016072004', '2016-09-30', '国际业务二部', '张红丽', '', '04', '生产通知单', '合同已评审，已预收部分款', '同意', '张丽莹2016-08-22 15:31:49', '郭涛2016-08-19 16:50:44', '同意', '陶保荣2016-08-23 08:53:49', '', '', '', 'PSA6翻单，请江西工厂处理。', '同意', '丁富民2016-08-23 09:03:27', '王功勇2016-08-23 10:20:29', 'sctz2016081904', '01', null, null, null, null, null, null, null, null, null, null);
