INSERT INTO `crs_tabledata719` VALUES ('84', '{0215CCA6-5EA4-45F3-B5BA-1BAFE61C93D4}', '61', 'INHE-0228', '2016-09-14 11:06:33', '0000-00-00 00:00:00', '2016-09-20 10:48:13', 'unchecked', 'n', 'n', '', '1', 'sctz2016091401/CDN17/生产通知单', '', '已经收到PO，合同评审还在流程中。LC预计9月底收到，由于交期紧张，请先采购物料、启动生产。							\r\r\r\n', '50529', '2016-09-14 11:06:33', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN17', 'INHESC2016091302', '2016-12-01', '国际业务二部', '谭雯', '', '04', '生产通知单', '合同已评审，60天远期信用证预计10月底会收到', '同意先备料；具体生产启动请谭雯通知。', '张丽莹2016-09-19 17:55:06', '郭涛2016-09-19 17:41:55', '同意', '陶保荣2016-09-19 20:23:22', '', '', '', '', '同意', '丁富民2016-09-20 08:41:17', '王功勇2016-09-20 09:34:28', 'sctz2016091401', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('85', '{EDE6D22D-EC55-4FBE-A13F-8DF9E243B6C1}', '61', 'INHE-0228', '2016-09-14 11:25:44', '0000-00-00 00:00:00', '2016-09-20 10:13:25', 'unchecked', 'n', 'n', '', '1', 'sctz2016091402/CDN18/生产通知单', '', '已经收到PO，合同评审还在流程中。LC预计11月份收到，1月底是春节，因此请规划好生产安排，确保在客户要求、交期之内交货。							', '45236', '2016-09-14 11:25:44', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN18', 'INHESC2016091303', '2017-02-01', '国际业务二部', '谭雯', '', '04', '生产通知单', '合同已评审，60天远期信用证预计11月底收到', '同意先备料；具体生产请谭雯根据LC进度通知。', '张丽莹2016-09-19 17:56:02', '郭涛2016-09-19 17:34:49', '同意', '陶保荣2016-09-19 20:22:45', '', '', '', '', '', '丁富民2016-09-20 08:41:43', '王功勇2016-09-20 09:34:00', 'sctz2016091402', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('86', '{2F57AE63-2B3E-4D1F-BC02-D3F59F479B02}', '60', 'INHE-0066', '2016-09-14 14:16:49', '0000-00-00 00:00:00', '2016-09-14 17:00:06', 'unchecked', 'n', 'n', '', '1', 'sctz2016091403/白雪613/生产通知单', '', '\r\r\nAPC220-43-2A要求：\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（天线需要焊在模块上，天线与模块平行焊。） 3、用于掌上电脑，点对点抄读功能，但不相互干扰。       \r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签“APC220-43-2”，主要用于区分开其他功能的无线通信模块。       \r\r\n5、电压源：3.5-5.5V       \r\r\n6、频率：433,05 – 434,79 MHz       \r\r\n7、温度范围：-30-+80       \r\r\n8、外包装箱用纸贴上唛头：APC220-43-2\r\r\n9、出厂时发射功率设为10mW。     										\r\r\n\r\r\r\n\r\r\r\nUSB-APC220-43-0要求：\r\r\r\n1、供应商为安美通。   \r\r\r\n2、外壳上只需贴USB-APC220-43-0，不需其它任何信息及Logo。 \r\r\r\n3、升级为V3.0版。\r\r\r\n4、出厂时发射功率设为10mW。\r\r\r\n\r\r\r\nUSB-APC220-43-2要求：\r\r\r\n1、供应商为安美通。   \r\r\r\n2、外壳上只需贴USB-APC220-43-2，不需其它任何信息和Logo.   \r\r\r\n3、需升级为V3.0版本。\r\r\r\n4、出厂时发射功率设为10mW。\r\r\r\n\r\r\r\n\r\r\r\n										\r\r\r\n', '0', '2016-09-14 14:16:49', 'Energomera CJSC', '白雪', '白雪613', 'PO#E1613', '2016-09-26', '国际业务一部', '邱洁', '', '05', '生产通知单', '合同已评审，全款已收', '同意', '张丽莹2016-09-14 15:05:57', '王维2016-09-14 14:43:03', '同意', '陶保荣2016-09-14 16:01:20', '', '', '', '', '同意', '丁富民2016-09-14 16:04:09', '王功勇2016-09-14 16:34:38', 'sctz2016091403', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('87', '{39F992B4-7BD3-4A30-A8A5-0751283209A7}', '60', 'INHE-0406', '2016-09-21 09:43:12', '0000-00-00 00:00:00', '2016-09-22 14:16:59', 'unchecked', 'n', 'n', '', '1', 'sctz2016092101/BY06/生产通知单', '', 'BY项目翻单，生产、配置同上批次电表相同', '672', '2016-09-21 09:43:12', 'OsOO ASMAN SERVIS', 'BY', 'BY06', 'INHESC2016091401', '2016-11-04', '国际业务一部', '王毅', '', '04', '生产通知单', '合同已评审，已收到8763美元', '同意', '张丽莹2016-09-21 15:21:31', '王维2016-09-21 15:14:08', '同意', '陶保荣2016-09-21 17:27:21', '', '', '', 'BY市场，曾经供过货，使用的是安美通RF无线通信方案。本次客户有要求，使用外加天线。需要慧联配合。项目技术负责人王顺万。', '同意', '丁富民2016-09-22 11:35:54', '王功勇2016-09-22 14:07:35', 'sctz2016092101', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('88', '{3B10B529-D3F9-4CC4-9C91-055E124E1F24}', '61', 'INHE-0222', '2016-09-28 11:22:10', '0000-00-00 00:00:00', '2016-10-09 09:29:46', 'unchecked', 'n', 'n', '', '1', 'sctz2016092801/PSA10603/生产通知单', '', '1.此为PSA10项目带LCD显示DIN单相表翻单，电力公司CENS3000套，ESSA3000套，铭牌需要重新设计，出厂设置需要同客户确认。\r\r\n2.本周可收到预付款，交期紧张所以申请款到前先采购备料。\r\r\n3.请PMC安排国庆节前将物料采购安排出去，确保10月底可以交货。', '6000', '2016-09-28 11:22:10', 'STAEKKA SAS', 'PSA10', 'PSA10603', 'INHESC2016092701', '2016-10-31', '国际业务二部', '张红丽', '', '04', '生产通知单', '合同已评审，货款客户已付出，待收款确认，交期紧急先备货', '同意', '张丽莹2016-10-08 10:04:08', '郭涛2016-09-29 21:15:03', '同意', '陶保荣2016-10-08 10:40:42', '', '', '', '', '同意。翻单生产由江西工厂处理。', '丁富民2016-10-09 02:18:50', '王功勇2016-10-09 09:26:59', 'sctz2016092801', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('89', '{B8EA9A46-1C8C-4741-9FBC-98450E54E733}', '60', 'INHE-0066', '2016-09-29 14:42:19', '0000-00-00 00:00:00', '2016-10-24 09:15:41', 'unchecked', 'n', 'n', '', '1', 'sctz2016092901/白云602/生产通知单', '', '1、按2015年11月提供给客户的最近样机生产。\r\n2、电表将分机芯（PCBA）、LCD显示板、铝面板、底壳、按键、五金件几大部分出货。\r\n3、双回路计量。\r\n4、能支持复费率和阶梯电价两种结算方式。（默认设置见随后提供的出厂设置单）\r\n5、带远程通断电功能。\r\n6、负荷门限设置。\r\n7、能承受电压异常的瞬间波动，电压异常时，电表自动断电，电压恢复正常时，电表自动恢复供电。\r\n8、能编程设置为后付费功能   \r\n\r\n										\r\n', '3000', '2016-09-29 14:42:19', '\"Aspan-Energy \" LTD', '白云', '白云602', '№INHE SC2016082301', '2016-10-31', '国际业务一部', '邱洁', '', '04', '生产通知单', '合同已评审，50%预付款已收', '同意', '张丽莹2016-09-29 15:23:22', '王维2016-09-29 14:59:13', '同意', '陶保荣2016-09-30 10:50:53', '', '', '', '翻单生产，由江西工厂处理。', '同意。', '丁富民2016-09-30 17:45:03', '王功勇2016-09-30 18:00:25', 'sctz2016092901', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('90', '{BD81BAB9-FFED-459A-A20D-1EBC7196EBD8}', '60', 'INHE-0088', '2016-10-08 11:31:49', '0000-00-00 00:00:00', '2016-10-09 17:22:31', 'unchecked', 'n', 'n', '', '1', 'sctz2016100801/ST20604/生产通知单', '', '客户功放板故障急需更换，单独付款，单独发货，要求12号前到深圳由客户带走。', '0', '2016-10-08 11:31:49', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20604', 'INHESC2016022575', '2016-10-12', '国际业务一部', '余冬纯', '', '', '生产通知单', '客户功放板故障急需更换', '同意', '张丽莹2016-10-08 18:06:24', '王维2016-10-08 17:56:02', '同意', '陶保荣2016-10-09 09:25:48', '', '', '', '', '同意', '丁富民2016-10-09 15:32:41', '王功勇2016-10-09 17:16:26', 'sctz2016100801', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('91', '{F8D40B6E-7956-4CC8-9F13-B59B5B9A821E}', '60', 'INHE-0066', '2016-10-09 18:14:14', '0000-00-00 00:00:00', '2016-10-11 11:39:49', 'unchecked', 'n', 'n', '', '1', 'sctz2016100902/白雪614/生产通知单', '', 'APC220-43-0B要求：\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\r\n3、用于电表上，带自动组网功能。              \r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43\"，主要用于区分开其他功能的无线通信模块。              \r\r\n5、电压源：3.5-5.5V              \r\r\n6、频率： 433.05-434.7 MHz           \r\r\n7、温度范围：-30-+80              \r\r\n8、外包装箱用纸贴上唛头：APC220-43\r\r\n9、出厂是发射功率设为10mW.\r\r\n\r\nAPC220-43-2A要求：\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（天线需要焊在模块上，天线与模块平行焊。） 3、用于掌上电脑，点对点抄读功能，但不相互干扰。       \r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43-2\"，主要用于区分开其他功能的无线通信模块。       \r\n5、电压源：3.5-5.5V       \r\n6、频率：433,05 - 434,79 MHz       \r\n7、温度范围：-30-+80       \r\n8、外包装箱用纸贴上唛头：APC220-43-2\r\n9、出厂时发射功率设为10mW。\r\n\r\n', '0', '2016-10-09 18:14:14', 'Energomera CJSC', '白雪', '白雪614', 'PO#E1614', '2016-10-21', '国际业务一部', '邱洁', '', '05', '生产通知单', '合同已评审，货款已收齐', '同意', '张丽莹2016-10-11 08:53:39', '王维2016-10-10 08:23:34', '同意', '陶保荣2016-10-11 11:27:46', '', '', '', '', '同意', '丁富民2016-10-11 11:36:58', '王功勇2016-10-11 11:38:05', 'sctz2016100902', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('92', '{698E9311-639A-43D8-A4E3-E5FD490EE8B8}', '61', 'INHE-0534', '2016-10-09 18:04:45', '0000-00-00 00:00:00', '2016-10-11 11:41:41', 'unchecked', 'n', 'n', '', '1', 'sctz2016100903/MCA01/生产通知单', '', '由于产品资料还在审核中，具体的产品型号还需客户反馈后确定', '0', '2016-10-09 18:04:45', 'Millennium Challenge Account - Malawi', 'MCA', 'MCA01', 'INHESC2016070807', '2016-10-25', '国际业务二部', '徐聪', '', '03', '生产通知单', '合同已评审，预付款已收', '同意', '张丽莹2016-10-11 09:11:11', '郭涛2016-10-09 20:39:10', '同意', '陶保荣2016-10-11 11:28:34', '', '', '', '', '同意', '丁富民2016-10-11 11:36:33', '王功勇2016-10-11 11:38:42', 'sctz2016100903', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('93', '{67A9258B-B278-4622-A4C8-FCC5204641F5}', '61', 'INHE-0381', '2016-10-13 14:11:02', '0000-00-00 00:00:00', '2016-10-24 08:27:27', 'unchecked', 'n', 'n', '', '1', 'sctz2016101301/UW02/生产通知单', '', '客户已付全款。UW01项目翻单，该项目还有15台表未发货，需与此次一起生产发货。所以本次生产一共200台DIN II。', '185', '2016-10-13 14:11:02', 'Delta Electricals Limited', 'UW', 'UW02', 'INHESC2016101001', '2016-12-09', '国际业务二部', '张柳芳(Alexie)', '', '05', '生产通知单', '合同已评审，已收预付款', '同意', '张丽莹2016-10-17 11:14:05', '郭涛2016-10-14 03:26:56', '同意', '陶保荣2016-10-17 15:13:38', '', '', '', '', '同意，翻单产品由江西工厂处理', '丁富民2016-10-18 11:50:43', '王功勇2016-10-21 22:55:20', 'sctz2016101301', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('94', '{24BCA711-DBF0-467C-920C-84D4334D8A24}', '61', 'INHE-0434', '2016-10-13 16:49:24', '0000-00-00 00:00:00', '2016-10-14 09:41:27', 'unchecked', 'n', 'n', '', '1', 'sctz2016101302/AZL0301/生产通知单', '', '1）已和客户确认，此产品将在22kV电压等级下工作，该市场没有11kV电压等级网；\r\r\r\r\r\n2）此产品包含电表需求(多功能CT/PT表，带GPRS通讯)，客户对通讯没有指明具体要求；', '0', '2016-10-13 16:49:24', 'JEDIG GROUP', 'AZL03', 'AZL0301', 'INHESC2016092801', '2016-11-15', '国际业务二部', '钟云林(Andy)', '', '04', '生产通知单', '合同已评审，预付款全款已收', '同意', '张丽莹2016-10-14 08:33:51', '郭涛2016-10-14 03:25:10', '同意', '陶保荣2016-10-14 09:01:06', '', '', '', '一台产品，建议由深圳实验室负责制作、交付。（黄俊杰、结构部、采购资源部配合；带组合互感器；）', '同意。', '丁富民2016-10-14 09:15:34', '王功勇2016-10-14 09:18:37', 'sctz2016101302', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('95', '{15507BE8-C9F2-4071-A305-A7F1F2E180DA}', '61', 'INHE-0440', '2016-10-13 17:39:47', '0000-00-00 00:00:00', '2016-10-24 08:26:10', 'unchecked', 'n', 'n', '', '1', 'sctz2016101303/TZP01/生产通知单', '', 'BS安装一体式预付费智能电表（带键盘，不带模块，保留PLC/RF/GPRS模块通讯功能），KWH结算，SGC:901037, 预存5度电，铭牌上必须是上方为INHEMETER的品牌和LOGO，铭牌下部为LETECH Technologies Sdn Bhd，详细技术规格请参考附件KKIP技术规格（中英对照版）和UET TOKEN（详细说明）。					\r\r\n', '100', '2016-10-13 17:39:47', 'LEE JONG ELECTRICAL CO. SDN BHD', 'TZP', 'TZP01', 'INHESC2016092802', '2016-11-28', '国际业务二部', '汤伟(Will)', '', '05', '生产通知单', '全部货款已收', '同意', '张丽莹2016-10-17 10:23:46', '郭涛2016-10-14 03:17:16', '同意', '陶保荣2016-10-17 10:28:11', '', '', '', '', '同意', '丁富民2016-10-18 11:52:04', '王功勇2016-10-21 22:55:45', 'sctz2016101303', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('96', '{7FDB37C1-5B8E-4B2C-A19B-C44A7B73F5C1}', '60', 'INHE-0088', '2016-10-15 15:57:46', '0000-00-00 00:00:00', '2016-11-23 17:55:32', 'unchecked', 'n', 'n', '', '1', 'sctz2016101501/DPDC601/生产通知单', '', '电力公司有指定表号\r\r\r\r\n备用表0.2%，单相表199台，三相表及GPRS模块26套。\r\r\r\n标配IC卡112500张（包装在每台表内盒），赠送11250张，收费11250张，共有135000张。', '112500', '2016-10-15 15:57:46', 'Ideal Enterprise', 'DPDC', 'DPDC601', 'INHESC2016083001', '2016-12-20', '国际业务一部', '余冬纯', '第三方检验', '02', '生产通知单', '收到信用证通知书\r\nLC号码:100517010037\r\nDPDC601项目 USD 4,327,735.00元\r\n', '', '黄兰兰2017-03-08 17:36:20', '', '同意。', '陶保荣2017-03-09 14:06:00', '', '', '', '', '同意', '丁富民2017-03-09 14:38:59', '王功勇2017-03-10 14:44:12', 'sctz2016101501', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('97', '{AEB5963A-5AE2-4F17-8DED-A37040F0C3CD}', '61', 'INHE-0222', '2016-10-19 10:50:26', '0000-00-00 00:00:00', '2016-10-24 14:37:15', 'unchecked', 'n', 'n', '', '1', 'sctz2016101901/PSA10604/生产通知单', '', '1.此为PSA10第4次翻单，9800套为EPM公司订单，铭牌，出厂设置，箱唛等所有资料同已交货的5375套保持一致。\r\r\r\r\n\r\r\r\r\n2.30套为备品，铭牌及贴纸需要重新设计，不带电力公司LOGO。\r\r\r\n\r\r\r\n3.此单要求3000-5000套同PSA10603一起交货。\r\n\r\n4.此单已收到15%预付款水单，请安排备料生产。', '9830', '2016-10-19 10:50:26', 'STAEKKA SAS', 'PSA10', 'PSA10604', 'INHESC201610150', '2016-11-18', '国际业务二部', '张红丽', '', '04', '生产通知单', '合同已评审，预付款已收。', '同意', '张丽莹2016-10-24 09:03:18', '郭涛2016-10-21 12:37:57', '同意', '陶保荣2016-10-24 09:07:45', '', '', '', '翻单产品，请江西工厂处理。', '同意', '丁富民2016-10-24 10:21:29', '王功勇2016-10-24 14:18:17', 'sctz2016101901', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('98', '{743B069E-050F-49E9-891E-EDBDDB017C8F}', '61', 'INHE-0222', '2016-10-25 12:44:31', '0000-00-00 00:00:00', '2016-10-26 14:00:24', 'unchecked', 'n', 'n', '', '1', 'sctz2016102501/PSA12601/生产通知单', '', '1. 此为电力公司ESSA订单，研发新品，铭牌，出厂设置，外箱等资料需要重新设计。\r\r\n\r\r\n2. 除单相3线特性外，其余功能同PSA10供货产品一致。\r\n\r\n3. 预付款本周到账，申请先采购备料。', '640', '2016-10-25 12:44:31', 'MESSEN S.A.S', 'PSA12', 'PSA12601', 'INHESC2016102402', '2016-11-25', '国际业务二部', '张红丽', '', '04', '生产通知单', '尚未评审，根据往期经验客户会预付货款', '同意', '张丽莹2016-10-25 14:44:17', '郭涛2016-10-25 14:33:38', '同意', '陶保荣2016-10-25 20:22:33', '', '', '', '11月25日交货存在问题，单相三线的设计方案、程序没有进行测试确认，研发预计在11月15日左右能完成研发工作。项目负责人章春鹏。', '同意', '丁富民2016-10-26 08:52:57', '王功勇2016-10-26 13:58:23', 'sctz2016102501', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('99', '{68F5A8F7-D5E9-4D2B-800E-66CA21DC4A4B}', '60', 'INHE-0088', '2016-10-26 17:04:51', '0000-00-00 00:00:00', '2016-11-03 17:36:40', 'unchecked', 'n', 'n', '', '1', 'sctz2016102601/ST20613/生产通知单', '', '翻单订单，注意要求请见附件，客户全款预付，交期要求紧急，烦请各部门协调配合，请审批！', '8000', '2016-10-26 17:04:51', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20613', 'INHESC2016103102', '2016-11-10', '国际业务一部', '余冬纯', '', '06', '生产通知单', '合同已评审，已收到付款水单', '同意，此订单货款付款水单客户已经提供。', '张丽莹2016-11-02 08:59:29', '王维2016-11-02 08:45:24', '同意', '陶保荣2016-11-03 09:05:59', '', '', '', '翻单生产，由江西工厂处理。', '同意', '丁富民2016-11-03 17:08:52', '王功勇2016-11-03 17:24:54', 'sctz2016102601', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('100', '{CFC71154-137C-4BD8-B360-E6F7882211F6}', '60', 'INHE-0088', '2016-10-26 18:59:08', '0000-00-00 00:00:00', '2016-10-28 09:37:54', 'unchecked', 'n', 'n', '', '1', 'sctz2016102602/ST20611/生产通知单', '', '翻单订单，注意要求请见附件，客户全款预付，交期要求紧急，烦请各部门协调配合，请审批！										\r\n', '15000', '2016-10-26 18:59:08', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20611', 'IHESC2016090201', '2016-11-10', '国际业务一部', '余冬纯', '', '04', '生产通知单', '已收到预付款水单', '同意', '张丽莹2016-10-27 10:42:43', '王维2016-10-27 10:20:55', '同意', '陶保荣2016-10-27 14:29:58', '', '', '', '翻单生产，只是铭牌、外箱唛头有修改一，建议由江西工工厂处理。', '同意', '丁富民2016-10-28 08:26:44', '王功勇2016-10-28 08:50:22', 'sctz2016102602', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('101', '{65A9C663-D3E2-4BAE-8944-10410F80DAD5}', '60', 'INHE-0066', '2016-10-28 11:52:38', '0000-00-00 00:00:00', '2016-11-16 13:22:24', 'unchecked', 'n', 'n', '', '1', 'sctz2016102801/白雪615/生产通知单', '', 'APC220-43-0B要求：\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\r\r\n3、用于电表上，带自动组网功能。              \r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43\"，主要用于区分开其他功能的无线通信模块。              \r\r\r\n5、电压源：3.5-5.5V              \r\r\r\n6、频率： 433.05-434.7 MHz           \r\r\r\n7、温度范围：-30-+80              \r\r\r\n8、外包装箱用纸贴上唛头：APC220-43\r\r\r\n9、出厂是发射功率设为10mW.\r\r\r\n\r\r\r\nAPC220-43-2A要求：\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（天线需要焊在模块上，天线与模块平行焊。） 3、用于掌上电脑，点对点抄读功能，但不相互干扰。       \r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43-2\"，主要用于区分开其他功能的无线通信模块。       \r\r\r\n5、电压源：3.5-5.5V       \r\r\r\n6、频率：433,05 - 434,79 MHz       \r\r\r\n7、温度范围：-30-+80       \r\r\r\n8、外包装箱用纸贴上唛头：APC220-43-2\r\r\r\n9、出厂时发射功率设为10mW。\r\r\r\n\r\r\r\nAPC220-43-3B要求：\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\r\n2、白雪项目专用安美通普通无线射频通信模块，不需要把天线焊在模块上。           \r\r\n3、用于电表上，带自动组网功能。              \r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43-3\"，主要用于区分开其他功能的无线通信模块。              \r\r\n5、电压源：3.5-5.5V              \r\r\n6、频率： 433.05-434.7 MHz           \r\r\n7、温度范围：-30-+80              \r\r\n8、外包装箱用纸贴上唛头：APC220-43\r\r\n9、出厂是发射功率设为10mW.\r\r\n\r\r\nAPC220-43-2A要求：\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（天线需要焊在模块上，天线与模块平行焊。） 3、用于掌上电脑，点对点抄读功能，但不相互干扰。       \r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43-2\"，主要用于区分开其他功能的无线通信模块。       \r\r\n5、电压源：3.5-5.5V       \r\r\n6、频率：433,05 - 434,79 MHz       \r\r\n7、温度范围：-30-+80       \r\r\n8、外包装箱用纸贴上唛头：APC220-43-2\r\r\n9、出厂时发射功率设为10mW。\r\r\nAPC220-43-0B要求：\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\r\n3、用于电表上，带自动组网功能。              \r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43\"，主要用于区分开其他功能的无线通信模块。              \r\r\n5、电压源：3.5-5.5V              \r\r\n6、频率： 433.05-434.7 MHz           \r\r\n7、温度范围：-30-+80              \r\r\n8、外包装箱用纸贴上唛头：APC220-43\r\r\n9、出厂是发射功率设为10mW.\r\r\n\r\r\nAPC220-43-2A要求：\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（天线需要焊在模块上，天线与模块平行焊。） 3、用于掌上电脑，点对点抄读功能，但不相互干扰。       \r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43-2\"，主要用于区分开其他功能的无线通信模块。       \r\r\n5、电压源：3.5-5.5V       \r\r\n6、频率：433,05 - 434,79 MHz       \r\r\n7、温度范围：-30-+80       \r\r\n8、外包装箱用纸贴上唛头：APC220-43-2\r\r\n9、出厂时发射功率设为10mW。\r\r\n\r\r\n										\r\r\n\r\r\n										\r\r\n										\r\r\n\r\r\r\n										\r\r\r\n\r\r\r\n										\r\r\r\n', '0', '2016-10-28 11:52:38', 'Energomera CJSC', '白雪', '白雪615', 'PO#E1615', '2016-11-28', '国际业务一部', '邱洁', '', '05', '生产通知单', '合同已评审，已收40%预付款', '同意', '张丽莹2016-10-31 10:40:52', '王维2016-10-29 16:07:52', '同意', '陶保荣2016-10-31 14:19:44', '', '', '', '', '同意', '丁富民2016-10-31 14:32:02', '王功勇2016-10-31 16:06:55', 'sctz2016102801', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('102', '{0C7F2EC1-62E1-412A-8138-1F94679A14A1}', '60', 'INHE-0066', '2016-10-31 11:17:37', '0000-00-00 00:00:00', '2016-11-03 17:35:29', 'unchecked', 'n', 'n', '', '1', 'sctz2016103101/白雪616/生产通知单', '', '1、采用新模具结构供货。     \r\r\r\r\n2、PCB板不需灌胶和喷三防漆！\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。      \r\r\r\r\n4、MAC地址为该表表号（表地址）的最后六位数字，该地址激光雕刻在表外壳背部。       \r\r\r\r\n5、PLC载波显示单元的铭牌标识为：CE208。         \r\r\r\r\n6、显示单元不需要贴易碎贴。        \r\r\r\r\n7、出厂设置：           \r\r\r\r\n1）表内时间为：GMT+4           \r\r\r\r\n2）冬夏令时转换功能关闭。           \r\r\r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\r\r\n5）特殊节假日没有。           \r\r\r\r\n6）电表密码：000000.           \r\r\r\r\n7）负荷门限：0.           \r\r\r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\r\r\n9）取负荷点的平均时间：30分钟。          \r\r\r\r\n8、继电器：100A，但标识采用120A。      \r\r\r\r\n9、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）       \r\r\r\r\n10、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\r\r\n11、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU的内盒中。  \r\r\r\r\n\r\r\r\r\n\r\r\r\r\n										\r\r\r\r\n										\r\r\r\r\n										\r\r\r\r\n', '51500', '2016-10-31 11:17:37', 'Energomera CJSC', '白雪', '白雪616', 'PO#E1616', '2016-12-30', '国际业务一部', '邱洁', '', '04', '生产通知单', '合同已评审，尚未收到预付款，业务反应交货较为紧急', '同意，此订单请江西务必确保开箱合格率。', '张丽莹2016-11-01 17:46:47', '王维2016-10-31 13:44:06', '同意', '陶保荣2016-11-03 09:05:01', '', '本订单需要发3%的成品作为备品，与现场抽检合格率比较，＜3%的部分由客户购买，＞3%的部分需要再补充备品。请工厂注意质量控制。', '', '', '同意', '丁富民2016-11-03 17:07:50', '王功勇2016-11-03 17:23:56', 'sctz2016103101', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('103', '{73BCFFD2-8759-4F98-986A-47C93ECAFD10}', '61', 'INHE-0051', '2016-11-01 10:56:01', '0000-00-00 00:00:00', '2016-11-08 13:49:21', 'unchecked', 'n', 'n', '', '1', 'sctz2016110105/ESA-01/生产通知单', '', '1.此项目代号为ESA-02，为ESA-01翻单。在ESA-01基础上需修改事项:\r\n1）出厂前输入激活码激活电表 \r\n2）端子孔由弧形改成平的，这点正在沟通中，我们争取解决客户问题而不作修改。具体将OA单独通知。\r\r\r\n2.已收到预付款133，529.50USD。', '20000', '2016-11-01 10:56:01', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'ESA', 'ESA-01', '28299', '2016-12-07', '国际业务二部', '盛燕', '第三方检验', '04', '生产通知单', '合同已评审，预付款已收', '同意', '张丽莹2016-11-07 16:46:46', '郭涛2016-11-07 14:38:17', '同意', '陶保荣2016-11-08 08:49:27', '', '', '', '翻单生产，由江西工厂负责处理。', '同意。', '丁富民2016-11-08 12:09:45', '王功勇2016-11-08 13:47:11', 'sctz2016110105', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('104', '{8BBF9372-2320-45FC-A69A-E824B89639F0}', '60', 'INHE-0088', '2016-11-02 14:34:21', '0000-00-00 00:00:00', '2016-11-03 17:35:03', 'unchecked', 'n', 'n', '', '1', 'sctz2016110201/ST20614/生产通知单', '', '与ST20613订单合并发货，货款全款T/T支付中，请安排备料。', '1000', '2016-11-02 14:34:21', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20614', 'INHESC2016102502', '2016-11-10', '国际业务一部', '余冬纯', '', '04', '生产通知单', '合同已评审，货款已收齐', '同意', '张丽莹2016-11-02 15:11:08', '王维2016-11-02 15:05:07', '同意', '陶保荣2016-11-03 09:03:04', '', '', '', '', '同意', '丁富民2016-11-03 17:07:28', '王功勇2016-11-03 17:18:17', 'sctz2016110201', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('105', '{BD01E3FD-82EB-41BE-8796-303790EC1136}', '60', 'INHE-0088', '2016-11-10 09:08:19', '0000-00-00 00:00:00', '2016-11-10 14:09:27', 'unchecked', 'n', 'n', '', '1', 'sctz2016111001/FU03/生产通知单', '', '更换FU01、FU02订单故障载波通信用户显示单元，空运订单，交期急请审批！', '0', '2016-11-10 09:08:19', 'UTILA POWER COMPANY LTD.', 'FU', 'FU03', 'INHESC2016072901', '2016-12-06', '国际业务一部', '余冬纯', '', '06', '生产通知单', '合同已评审，交期紧张，业务申请先备料', '同意', '张丽莹2016-11-10 10:16:02', '王维2016-11-10 09:58:00', '同意', '陶保荣2016-11-10 11:01:59', '', '', '', '老项目，使用的是瑞斯康的PLC载波方案。', '同意。', '丁富民2016-11-10 13:43:20', '王功勇2016-11-10 13:58:30', 'sctz2016111001', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('106', '{59813349-3466-4F9C-AAF8-632A6FC9B5C3}', '61', 'INHE-0222', '2016-11-10 10:52:46', '0000-00-00 00:00:00', '2016-11-11 13:54:50', 'unchecked', 'n', 'n', '', '1', 'sctz2016111002/PSA10605/生产通知单', '', '1.此为PSA10项目翻单，为EPM公司订单，项目编号PSA10605。\r\r\r\r\n\r\r\r\r\n2.其中12000套铭牌，出厂设置等同PSA10604中9800套产品保持一致，12套铭牌出厂设置同PSA10604中30套产品保持一致。\r\r\r\n\r\r\r\n3.请务必确保最晚12月10日从工厂发货。\r\r\n\r\r\n4.预付款预计最晚下周一收到，申请款未到先下单备料。', '12012', '2016-11-10 10:52:46', 'STAEKKA SAS', 'PSA10', 'PSA10605', 'INHESC2016110701', '2016-12-10', '国际业务二部', '张红丽', '', '04', '生产通知单', '合同已评审，预付款未收，业务申请先备料', '同意', '张丽莹2016-11-11 10:32:37', '郭涛2016-11-11 09:04:12', '同意', '陶保荣2016-11-11 11:46:20', '', '', '', '翻单生产，请江西工厂处理。', '同意', '丁富民2016-11-11 13:26:10', '王功勇2016-11-11 13:50:35', 'sctz2016111002', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('107', '{982B4D91-4A21-4D0D-AB6A-D2A49496C574}', '66', 'JXINHE-2559', '2016-11-14 13:42:51', '0000-00-00 00:00:00', '2016-11-15 10:43:28', 'unchecked', 'n', 'n', '', '1', 'sctz2016111401/FT01/生产通知单', '', '客户已付款，项目执行期为2017年1月3日，恳请尽快安排生产。', '20', '2016-11-14 13:42:51', 'Inaris Asia Pacific Sdn Bhd', 'FT', 'FT01', 'INHESC2016101701', '2016-12-20', '国际业务三部', '淦永妍', '', '04', '生产通知单', '合同已评审 ，预付款已收', '此项目为该区试点项目，将在安装电力公司MD家中安装1台，客户支付了除产品外的服务费用。该区域潜在的需求量为60万台，望能够成功执行试点本项目。考虑到运输时间，发货时间：2016年12月15日之前。', '张丽莹2016-11-14 18:16:16', '宋宁2016-11-14 15:28:21', '同意', '陶保荣2016-11-15 09:33:11', '', '请注意：是否确定用CDN项目现成的产品生产、供货？作为试点，可以先用现成的产品。', '', '为此21台产品（三款)，研发近期没有时间安排进行开发，建议使用公司现成产品交货，由客户服务组织现场试点。所以建议由江西工厂和客户服务部处理此订单。', '同意。', '丁富民2016-11-15 09:52:58', '王功勇2016-11-15 10:08:50', 'sctz2016111401', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('108', '{68DC7DF5-D874-4D05-88D3-E514C6CF7E0D}', '60', 'INHE-0535', '2016-11-18 15:09:10', '0000-00-00 00:00:00', '2016-11-21 08:44:00', 'unchecked', 'n', 'n', '', '1', 'sctz2016111801/ST20615/生产通知单', '', '交货按照5批交货，每批数量相同。第一批（51200单相表+12800三相表）50%在2016.12.10日前备好并待验货，2016.12.15日前开船；剩余50%在2016.12.20日前备好并待验货，2016.12.25日前开船；其余批次货物在前批货物发出之日起60天内备好并发出。', '320000', '2016-11-18 15:09:10', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20615', 'INHESC2016111601', '2016-12-10', '国际业务一部', '左亚楠', '第三方检验', '02', '生产通知单', '合同已评审，信用证尚未收到', '同意，注意此次备货数量为单相51200，三相12800套，通知单数量为总合同数量。', '张丽莹2016-11-18 16:45:39', '王维2016-11-18 16:18:27', '同意', '陶保荣2016-11-18 17:46:23', '', '注意：此订单分5批，每批51200套单相+12800套三相，首批发货多发1%，作为备品。现在立即备货第1批。后面的4批等待通知（基本没两个月一批）。', '', '翻单生产，请江西工厂安排处理。', '同意。', '丁富民2016-11-18 17:54:35', '王功勇2016-11-18 18:00:38', 'sctz2016111801', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('109', '{E947CF2A-71FC-407F-84EA-DD2C844778A5}', '61', 'INHE-0576', '2016-11-23 09:51:29', '0000-00-00 00:00:00', '2016-11-25 10:59:00', 'unchecked', 'n', 'n', '', '1', 'sctz2016112301/IMF02/生产通知单', '', '', '0', '2016-11-23 09:51:29', 'INHEMETER AFRICA CO., LTD.', 'IMF', 'IMF02', 'INHESC2016110402', '2016-10-30', '国际业务二部', '戴萍(Eileen)', '', '06', '生产通知单', '合同变更单已审核，DDP结算方式，款项未收', '同意', '张丽莹2016-12-19 08:52:13', '郭涛2016-12-18 12:46:38', '同意', '陶保荣2016-12-19 09:23:38', '', '', '', '', '', '丁富民2016-12-19 10:29:08', '王功勇2016-12-19 10:31:56', 'sctz2016112301', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('110', '{8F8CBAF9-BEAD-4B1F-BBC6-510BA007C330}', '61', 'INHE-0051', '2016-12-01 14:44:36', '0000-00-00 00:00:00', '2016-12-02 09:54:31', 'unchecked', 'n', 'n', '', '1', 'sctz2016120101/PY03/生产通知单', '', '1.项目代号PY03\r\r\r\n2.交期要求严格，将单独OA提出要求\r\r\n', '180600', '2016-12-01 14:44:36', 'The Kenya Power * Lighting Company Limited', 'PY03', 'PY03', 'INHESC2016111001', '2017-01-10', '国际业务二部', '盛燕', '第三方检验', '02', '生产通知单', '合同已评审', '交期时间较短，需要生产给出最快交期。', '张丽莹2016-12-01 18:02:20', '郭涛2016-12-01 15:52:30', '同意', '陶保荣2016-12-02 09:04:21', '', '请研发加快速度开模和G3-PLC转换。', '', '交货时间将是一个问题。1：产品模具设计没有完成，开模时间预计比较长。2：产品的技术方案还在确认之中。所以2017年01月交货不可能实现。', '同意', '丁富民2016-12-02 09:12:10', '王功勇2016-12-02 09:39:27', 'sctz2016120101', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('111', '{8CC7E680-33D3-46BF-8375-0F5F2A2BCDC1}', '61', 'INHE-0381', '2016-12-29 10:56:09', '0000-00-00 00:00:00', '2017-01-03 08:15:09', 'unchecked', 'n', 'n', '', '1', 'sctz2016122901/CDN20/生产通知单', '', '客户目前正在放假，下周将发来PO，由于交期紧急，请先采购物料。', '25344', '2016-12-29 10:56:09', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN20', 'INHESC2016122901', '2017-03-15', '国际业务二部', '张柳芳(Alexie)', '', '04', '生产通知单', '合同已评审，无预付款', '同意', '张丽莹2017-01-11 10:14:41', '郭涛2017-01-10 19:59:33', '同意', '陶保荣2017-01-11 11:46:38', '', '', '', '翻单生产，由江西工厂处理。', '同意', '丁富民2017-01-11 13:52:02', '王功勇2017-01-11 14:15:40', 'sctz2016122901', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('112', '{29349BA8-E45E-4D60-8033-5A59D131023F}', '61', 'INHE-0051', '2016-12-29 17:54:15', '0000-00-00 00:00:00', '2017-01-03 08:14:45', 'unchecked', 'n', 'n', '', '1', 'sctz2016122904/ESA03/生产通知单', '', '1.此项目代号为ESA03，为ESA02翻单，请注意：出厂前需输入激活码激活电表，端子孔由弧形改成平的。\r\n2.在ESA02基础上更改：1）出厂设置单上，负荷门限按照20A电流计算，出厂设置单需由业务确认   2）增加QC贴纸，业务将单独发OA说明。\r\n3.正在走合同评审流程。\r\n4.交期要求紧张。', '40000', '2016-12-29 17:54:15', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'ESA', 'ESA03', 'INHESC2016122801', '2017-01-20', '国际业务二部', '盛燕', '第三方检验', '02', '生产通知单', '合同已评审，货款未收', '同意', '张丽莹2016-12-29 18:32:34', '郭涛2016-12-29 18:19:44', '同意', '陶保荣2016-12-29 23:42:51', '', '同意。', '', '翻单生产，请由江西工厂安排处理，注意出厂设置参数的变化确认（出厂文件也由江西工厂编制修改确认)。', '同意', '丁富民2016-12-30 08:58:03', '王功勇2016-12-30 15:10:25', 'sctz2016122904', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('113', '{7D462954-8C0D-4ECF-B4AE-94AA48A6E609}', '61', 'INHE-0434', '2017-01-06 17:41:02', '0000-00-00 00:00:00', '2017-01-09 11:49:42', 'unchecked', 'n', 'n', '', '1', 'sctz2017010601/AZA01/生产通知单', '', '1. AZA项目50%预付款于1月3号到账，正在走合同评审；\r\r\r\r\r\n2. AZA项目产品依据研发部建议可以采用PY02产品，技术规格客户无特殊要求，电能表基本技术规格和要求请参考附件“AZA项目基本技术规格和要求”；\r\r\r\r\r\n3. AZA项目交期赶，要求1月15号前交付，赶年前船班发货；\r\r\r\r\r\r\n4. AZA项目产品铭牌需要重新设计，新增要求请参考附件“AZA项目产品铭牌新增要求”', '2340', '2017-01-06 17:41:02', 'JEDIG GROUP', 'AZA', 'AZA01', 'INHESC2017010403', '2017-01-15', '国际业务二部', '钟云林(Andy)', '', '06', '生产通知单', '合同已评审，50%预付款已收', '同意', '张丽莹2017-01-06 19:01:00', '郭涛2017-01-06 18:49:43', '同意', '陶保荣2017-01-09 08:43:44', '', '', '', '由于是PY02产品翻单生产（铭牌面板不同），建议由江西工厂自行处理安排。', '同意。', '丁富民2017-01-09 08:47:46', '王功勇2017-01-09 10:46:41', 'sctz2017010601', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('114', '{EAC9A342-9CD5-4A02-9E23-BAB3F7E4D5E6}', '61', 'INHE-0381', '2017-01-09 18:50:28', '0000-00-00 00:00:00', '2017-01-11 14:31:29', 'unchecked', 'n', 'n', '', '1', 'sctz2017010901/CDN21/生产通知单', '', '发货3个大柜+1个小柜', '43296', '2017-01-09 18:50:28', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN21', 'INHESC2017010902', '2017-04-10', '国际业务二部', '张柳芳(Alexie)', '', '04', '生产通知单', '合同已评审，无预付款', '同意', '张丽莹2017-01-11 10:19:10', '郭涛2017-01-10 04:39:27', '同意', '陶保荣2017-01-11 11:46:08', '', 'CDN项目都是LC结算，目前尚未收到LC，请紧密跟踪。', '', '翻单产品，由江西工厂处理。', '同意', '丁富民2017-01-11 13:39:20', '王功勇2017-01-11 14:16:43', 'sctz2017010901', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('115', '{DE952823-7C63-4507-B113-3D1D039E4D74}', '60', 'INHE-0066', '2017-01-10 16:08:17', '0000-00-00 00:00:00', '2017-01-11 14:17:36', 'unchecked', 'n', 'n', '', '1', 'sctz2017011001/白雪701/生产通知单', '', 'APC910M-43-B要求：\r\r\n1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。  \r\r\n2、安美通集抄无线射频通信模块。             \r\r\n3、电压：4.5-6V             \r\r\n4、频段：432-434MHz              \r\r\n5、SMA连接线必须装在电路板上。\r\r\n6、出厂时发射功率设为10mW.\r\r\n\r\r\r\n', '0', '2017-01-10 16:08:17', 'Energomera CJSC', '白雪', '白雪701', 'PO#E1701', '2017-01-20', '国际业务一部', '邱洁', '', '05', '生产通知单', '合同已评审，预付款未收', '同意', '张丽莹2017-01-11 10:13:45', '王维2017-01-11 09:12:01', '同意', '陶保荣2017-01-11 11:45:42', '', '', '', '', '同意', '丁富民2017-01-11 13:37:37', '王功勇2017-01-11 14:15:04', 'sctz2017011001', '01', null, null, null, null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('116', '{9002C068-714E-43B2-BCF0-6432010817C6}', '60', 'INHE-0088', '2017-01-13 09:29:37', '0000-00-00 00:00:00', '2017-01-16 13:49:37', 'unchecked', 'n', 'n', '', '1', 'sctz2017011301/ST20701/生产通知单', '', '客户已提供预付款电文，预计下周到账，特申请备货以完成发货。', '0', '2017-01-13 09:29:37', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20701', 'INHESC2017011101', null, '国际业务一部', '余冬纯', '', '06', '生产通知单', '合同已评审，货款已到银行还未到我司账户', '同意', '张丽莹2017-01-16 09:06:18', '王维2017-01-16 08:55:07', '同意', '陶保荣2017-01-16 09:09:24', '', '', '', '', '同意', '丁富民2017-01-16 10:19:04', '王功勇2017-01-16 13:40:02', 'sctz2017011301', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('117', '{AE0AD653-2226-4573-8827-184902ACBB63}', '15', 'INHE-0450', '2017-01-17 09:07:19', '0000-00-00 00:00:00', '2017-01-17 09:07:19', 'unchecked', 'n', 'n', '', '1', 'test1/生产通知单', '', '', '0', '2017-01-17 09:07:19', '荷花', '荷叶', 'test1', 'INHESC2016012761', null, '行政人力资源部', '郭林鹏', '', '', '生产通知单', '', '', '', '', '', '', '', '', '', '', '', '', '', 'sctz2017011703', '', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('118', '{14228D00-3806-4254-A4D4-A8C824CEB304}', '60', 'INHE-0066', '2017-01-17 09:38:32', '0000-00-00 00:00:00', '2017-01-18 09:48:10', 'unchecked', 'n', 'n', '', '1', 'sctz2017011705/白雪702/生产通知单', '', '白雪单相表要求：\r\r\n1、采用新模具结构供货。     \r\r\n2、PCB板不需灌胶和喷三防漆！\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。      \r\r\n4、MAC地址为该表表号（表地址）的最后六位数字，该地址激光雕刻在表外壳背部。       \r\r\n5、PLC载波显示单元的铭牌标识为：CE208。         \r\r\n6、显示单元不需要贴易碎贴。        \r\r\n7、出厂设置：           \r\r\n1）表内时间为：GMT+4           \r\r\n2）冬夏令时转换功能关闭。           \r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\n5）特殊节假日没有。           \r\r\n6）电表密码：000000.           \r\r\n7）负荷门限：0.           \r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\n9）取负荷点的平均时间：30分钟。          \r\r\n8、继电器：100A，但标识采用120A。      \r\r\n9、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）       \r\r\n10、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\n11、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU的内盒中。  \r\r\n\r\r\n白雪三相表要求：\r\r\n1、采用双方验证过的程序版本TMF2-1B-16032201 2、修改过脉冲输出的阻抗。						\r\n3. 铭牌、MAC地址等需要镭雕在电表外壳上； 4. MAC地址铭牌的6位数字为该表表号的最后六位数字； 5. 表内时间为GMT+3#FE54` 6. 冬夏令时转换功能关闭； 7. 客户其他相关要求在OA上反应给研发； 8. 其他未尽要求请按照客户技术规格要求来做。										\r\n\r\n										\r\r\n										\r\r\n										\r\r\n										\r\r\n', '13427', '2017-01-17 09:38:32', 'Energomera CJSC', '白雪', '白雪702', 'PO#E1702', '2017-02-22', '国际业务一部', '邱洁', '', '04', '生产通知单', '合同已评审，预付款已收', '同意', '张丽莹2017-01-17 10:54:56', '王维2017-01-17 10:48:52', '同意', '陶保荣2017-01-17 14:32:59', '', '', '', '', '同意', '丁富民2017-01-17 14:36:43', '王功勇2017-01-18 08:40:21', 'sctz2017011705', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('119', '{B5725BFB-D102-49B5-8B19-C8E32B3FA021}', '60', 'INHE-0066', '2017-01-18 15:26:48', '0000-00-00 00:00:00', '2017-01-19 09:22:41', 'unchecked', 'n', 'n', '', '1', 'sctz2017011801/白雪703/生产通知单', '', '白雪单相表要求：\r\r\r\n1、此单相表订单为客户用于测试三防漆和灌胶工艺的测试订单，其中100套-不灌胶，但PCB板需喷三防漆；100套-灌胶，但PCB板不需喷三防漆；100套-灌胶，且PCB板喷三防漆。\r\r\r\n2、采用新模具结构供货。     \r\r\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。      \r\r\r\r\n4、MAC地址为该表表号（表地址）的最后六位数字，该地址激光雕刻在表外壳背部。       \r\r\r\r\n5、PLC载波显示单元的铭牌标识为：CE208。         \r\r\r\r\n6、显示单元不需要贴易碎贴。        \r\r\r\r\n7、出厂设置：           \r\r\r\r\n1）表内时间为：GMT+4           \r\r\r\r\n2）冬夏令时转换功能关闭。           \r\r\r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\r\r\n5）特殊节假日没有。           \r\r\r\r\n6）电表密码：000000.           \r\r\r\r\n7）负荷门限：0.           \r\r\r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\r\r\n9）取负荷点的平均时间：30分钟。          \r\r\r\r\n8、继电器：100A，但标识采用120A。      \r\r\r\r\n9、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）       \r\r\r\r\n10、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\r\r\n11、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU的内盒中。  \r\r\r\r\n\r\r\r\r\n										\r\r\r\r\n\r\r\r\r\n										\r\r\r\r\n										\r\r\r\r\n										\r\r\r\r\n										\r\r\r\r\n										\r\r\r\r\n', '300', '2017-01-18 15:26:48', 'Energomera CJSC', '白雪', '白雪703', 'PO#E1703', '2017-02-22', '国际业务一部', '邱洁', '', '04', '生产通知单', '合同已评审，预付款未收', '同意', '张丽莹2017-01-18 18:00:10', '王维2017-01-18 17:45:17', '同意', '陶保荣2017-01-19 08:51:18', '', '', '', '翻单产品，请江西工厂处理。', '同意', '丁富民2017-01-19 08:52:56', '王功勇2017-01-19 09:12:30', 'sctz2017011801', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('120', '{7275DAEA-8268-4ED7-B681-23054C395F78}', '60', 'INHE-0088', '2017-02-14 09:53:44', '0000-00-00 00:00:00', '2017-02-16 14:36:33', 'unchecked', 'n', 'n', '', '1', 'sctz2017021401/BPDB601-1/生产通知单', '同意。', '单相指定Johnson继电器\r\r\r\r\n三相指定Grunner继电器\r\r\r\nBPDB601-1指定表号：\r\r\r\n144500台单相表：10210574174-10210718673\r\r\r\n5500台三相表：10230017328-10230022827', '150000', '2017-02-14 09:53:44', 'Ideal Enterprise', 'BPD', 'BPDB601-1', 'INHESC2O170l160l', '2017-03-31', '国际业务一部', '余冬纯', '', '02', '生产通知单', '合同已评审，未收到预付款', '同意', '张丽莹2017-02-15 08:51:07', '王维2017-02-14 19:22:59', '', '陶保荣2017-02-16 10:21:34', '', '请研发务必抓紧时间出BOM,并紧跟和协调模具交期，工业园采购部抓紧时间到料，确保生产不间断。', '', '项目经理：何梓劲                        产品正在设计开模之中，预计2017年03月中下旬投入批量生产', '同意', '丁富民2017-02-16 10:27:52', '王功勇2017-02-16 14:11:59', 'sctz2017021401', '01', '', '', '', null, null, null, null, null, null, null);
