INSERT INTO `crs_tabledata719` VALUES ('122', '{2019E8EA-8D7E-42E2-AA3F-4A2CE365A2A2}', '60', 'INHE-0088', '2017-02-14 19:44:47', '0000-00-00 00:00:00', '2017-02-23 10:47:16', 'unchecked', 'n', 'n', '', '1', 'sctz2017021403/BPDB601-2/生产通知单', '', '单相表指定Johnson继电器\r\r\n三相表指定Grunner继电器\r\r\nBPDB601-2指定表号：\r\r\n145662台单相表：10210718674-10210864335\r\r\n4338台三相表：10230022828-10230027165\r\r\n电力公司到厂验货，分批发货需分批验货\r\r\nBPDB601出厂设置要求一致需为：\r\r\n1. 预报警门限:30 tk.(现在是0）   \r\r\n2. 单次最高充值额度改为200\r\r\n00 tk. (目前10000)  \r\r\n3. 节假日默认出场设置7个固定日期的假期（详细日期待提供）  \r\r\n4. 紧急用电额度默认100 tk. （目前是0）', '150000', '2017-02-14 19:44:47', 'Ideal Enterprise', 'BPD', 'BPDB601-2', 'INHESC2017011602', '2017-04-30', '国际业务一部', '余冬纯', '', '02', '生产通知单', '合同已评审，尚未收到货款（信用证结算）', '同意', '张丽莹2017-02-16 13:55:21', '王维2017-02-16 13:51:44', '同意。', '陶保荣2017-02-16 14:23:48', '', '', '', '产品研发负责人：何梓劲', '同意', '丁富民2017-02-16 14:27:42', '王功勇2017-02-16 16:18:53', 'sctz2017021403', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('123', '{663C5565-237C-4D34-BE3A-D8FBDC417A9D}', '61', 'INHE-0222', '2017-02-17 14:03:00', '0000-00-00 00:00:00', '2017-02-20 15:58:17', 'unchecked', 'n', 'n', '', '1', 'sctz2017021701/PSA10701/生产通知单', '', '1.单相表为PSA10项目EPM公司翻单，项目编号PSA10701，翻单资料同PSA10605项目中EPM公司产品资料一致；\r\r\r\r\r\r\r\r\r\n2.三相表为PSA6项目EPM公司翻单，项目编号PSA6701，翻单资料同PSA6项目（2015年订单）中EPM公司产品资料一致。\r\r\r\r\r\r\n\r\r\r\r\r\r\n3.此单交期很紧两款产品要求30天内同时交货，即2017年3月20日同时从工厂交货；\r\r\r\r\n\r\r\r\r\r\n4.订单预付款预计下周一收到，申请款未到先安排采，请批准。\r\r\r\r\r\r\n', '5366', '2017-02-17 14:03:00', 'STAEKKA SAS', 'PSA10', 'PSA10701', 'INHESC2017021201', '2017-03-20', '国际业务二部', '张红丽', '', '04', '生产通知单', '合同已评审，尚未收到预付款', '同意', '张丽莹2017-02-20 08:54:57', '郭涛2017-02-19 00:20:52', '同意', '陶保荣2017-02-20 11:55:30', '', '', '', '翻单生产，请江西工厂工程部安排处理，研发不再参与。', '同意。', '丁富民2017-02-20 13:32:10', '王功勇2017-02-20 14:49:38', 'sctz2017021701', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('124', '{DC3ED268-F959-4835-98E4-BC0F438A0D30}', '61', 'INHE-0587', '2017-03-01 16:10:22', '0000-00-00 00:00:00', '2017-03-03 11:20:49', 'unchecked', 'n', 'n', '', '1', 'sctz2017030103/TNL03/生产通知单', '', '1.计划将NR05剩余的138套单相表及表箱出给TNL03；2.需另外设计客户公司和电力公司logo的贴纸，随大货寄出，请生产时发OA同业务确认；3.SGC 600415；预存50kwh电量；要求电表和断路器装在表箱里出货；符合IEC 62052-11 and IEC 62050-21 ', '138', '2017-03-01 16:10:22', 'Tinuten Nigeria Limited', 'TNL', 'TNL03', 'INHESC2017030101', '2017-04-09', '国际业务二部', '陆飞雨', '第三方检验', '04', '生产通知单', '货款已收，同意', '同意', '黄兰兰2017-03-02 12:50:43', '郭涛2017-03-02 03:04:24', '同意', '陶保荣2017-03-03 09:02:16', '', '', '', '使用库存产品，只作客户公司和电力公司LOGO的贴纸处理。建议由江西工厂安排处理。', '同意。', '丁富民2017-03-03 10:59:28', '王功勇2017-03-03 11:11:56', 'sctz2017030103', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('125', '{4D0E9E31-E2B5-4264-96CE-BB01FF1DCB73}', '61', 'INHE-0608', '2017-03-06 16:12:22', '0000-00-00 00:00:00', '2017-03-07 16:02:12', 'unchecked', 'n', 'n', '', '1', 'sctz2017030602/PSA15701/生产通知单', '', '1.该款表交期较紧，客户要求付款后30天内发货，现客户已经付全款', '200', '2017-03-06 16:12:22', 'MESSEN S.A.S', 'PSA15', 'PSA15701', 'INHESC2017030102', '2017-04-14', '国际业务二部', '周雅利', '', '04', '生产通知单', '收到18000美元，同意', '同意', '黄兰兰2017-03-07 10:01:16', '郭涛2017-03-06 21:16:32', '同意', '陶保荣2017-03-07 15:03:49', '', '', '', '', '同意', '丁富民2017-03-07 15:22:13', '王功勇2017-03-07 15:48:07', 'sctz2017030602', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('126', '{0A2362EC-8FBD-452D-BFBE-0E057F48751D}', '60', 'INHE-0066', '2017-03-08 17:28:37', '0000-00-00 00:00:00', '2017-03-13 14:25:42', 'unchecked', 'n', 'n', '', '1', 'sctz2017030801/白雪704/生产通知单', '', 'APC220-43-0B要求：\r\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\r\r\r\n3、用于电表上，带自动组网功能。              \r\r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43\"，主要用于区分开其他功能的无线通信模块。              \r\r\r\r\n5、电压源：3.5-5.5V              \r\r\r\r\n6、频率： 433.05-434.7 MHz           \r\r\r\r\n7、温度范围：-30-+80              \r\r\r\r\n8、外包装箱用纸贴上唛头：APC220-43\r\r\r\r\n9、出厂是发射功率设为10mW.\r\r\r\r\n\r\r\r\r\nAPC910M-43-B要求：\r\r\r\r\n1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。  \r\r\r\r\n2、安美通集抄无线射频通信模块。             \r\r\r\r\n3、电压：4.5-6V             \r\r\r\r\n4、频段：432-434MHz              \r\r\r\r\n5、SMA连接线必须装在电路板上。\r\r\r\r\n6、出厂时发射功率设为10mW.\r\r\r\r\n\r\r\r\r\n\r\r\r\r\nAPC220-43-2A要求：\r\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（天线需要焊在模块上，天线与模块平行焊。） 3、用于掌上电脑，点对点抄读功能，但不相互干扰。       \r\r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43-2\"，主要用于区分开其他功能的无线通信模块。       \r\r\r\r\n5、电压源：3.5-5.5V       \r\r\r\r\n6、频率：433,05 - 434,79 MHz       \r\r\r\r\n7、温度范围：-30-+80       \r\r\r\r\n8、外包装箱用纸贴上唛头：APC220-43-2\r\r\r\r\n9、出厂时发射功率设为10mW。   \r\r\r\r\n\r\nUSB-APC220-43-0\r\n 1、供应商为安美通。  \r\n 2、外壳上只需贴USB-APC220-43-0，不需其它任何信息及Logo。\r\n 3、升级为V3.0版。\r\n\r\nUSB-APC220-43-2\r\n 1、供应商为安美通。   \r\n 2、外壳上只需贴USB-APC220-43-2，不需其它任何信息和Logo.  \r\n 3、需升级为V3.0版本。\r\n', '0', '2017-03-08 17:28:37', 'Energomera CJSC', '白雪', '白雪704', 'PO#E1704', '2017-03-18', '国际业务一部', '邱洁', '', '05', '生产通知单', '该项目已收款70550欧元，此次产品数量增加', '', '黄兰兰2017-03-30 08:51:37', '王维2017-03-30 08:45:35', '同意', '陶保荣2017-03-30 09:39:37', '', '黄兰兰：白雪客户从来都是付美元，何来欧元？', '', '', '同意', '丁富民2017-03-30 09:46:54', '王功勇2017-03-30 10:17:00', 'sctz2017030801', '01', '', '', '', null, null, null, null, null, null, null);
