INSERT INTO `crs_tabledata719` VALUES ('130', '{1CF66C03-1778-40FE-ABAE-5FF41C2E1210}', '60', 'INHE-0088', '2017-03-17 13:24:57', '0000-00-00 00:00:00', '2017-09-11 15:11:42', 'unchecked', 'n', 'n', '', '1', 'sctz2017031702/ST20702/生产通知单', 'ST20702', '', '0', '2017-03-17 13:24:57', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20702', 'INHESC2017021801', '2017-04-08', '国际业务一部', '余冬纯', '', '06', '生产通知单', '2017.03.14收到货款', '同意', '黄兰兰2017-03-18 15:53:18', '王维2017-03-18 10:08:28', '同意', '陶保荣2017-03-20 09:08:27', '', '', '', '', '同意', '丁富民2017-03-20 10:06:41', '王功勇2017-03-21 15:29:28', 'sctz2017031702', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('131', '{05816561-01CA-4408-8ACB-7884CEAD3E63}', '60', 'INHE-0088', '2017-03-21 17:50:32', '0000-00-00 00:00:00', '2017-03-22 16:44:19', 'unchecked', 'n', 'n', '', '1', 'sctz2017032101/ST20704/生产通知单', 'ST20704', '', '0', '2017-03-21 17:50:32', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20704', 'INHESC2017031601', '2017-04-19', '国际业务一部', '余冬纯', '第三方检验', '02', '生产通知单', '客户已付款，与出纳确认银行已收款，银行暂未处理入到企业账户。', '同意', '黄兰兰2017-03-22 08:51:23', '王维2017-03-21 18:22:45', '同意', '陶保荣2017-03-22 09:22:34', '', '', '', '', '同意。', '丁富民2017-03-22 13:49:07', '王功勇2017-03-22 14:00:17', 'sctz2017032101', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('132', '{3B86B2F7-60ED-43AA-A4C9-ED8D49FBC61F}', '61', 'INHE-0578', '2017-03-22 23:12:38', '0000-00-00 00:00:00', '2017-03-24 15:58:11', 'unchecked', 'n', 'n', '', '1', 'sctz2017032201/ESA04/生产通知单', '', '1.此项目代号为ESA04，为ESA03翻单，请注意：出厂前是否输入激活码激活电表，需与业务OA确认。\r\r\n2.在ESA03基础上更改：1）出厂设置单上，负荷门限按照20A电流计算，出厂设置单需由业务确认   2）QC贴纸设计有所改动，需与业务OA确认。\r\r\n3.交期要求紧张，目前只收到合同金额16.5%的预付款（17万美金），建议启动生产，原因见OA “ ESA02和ESA03发货、收款跟踪”.', '30000', '2017-03-22 23:12:38', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'ESA', 'ESA04', 'INHESC2017032101', '2017-04-22', '国际业务二部', '覃湘君(June)', '第三方检验', '02', '生产通知单', '收到esa-04预付170000美元，预付16.5%', '同意', '黄兰兰2017-03-23 17:10:29', '郭涛2017-03-23 16:28:17', '同意', '陶保荣2017-03-24 11:28:29', '', '', '', '', '同意翻单生产，请江西工厂处理。', '丁富民2017-03-24 11:33:55', '王功勇2017-03-24 15:12:50', 'sctz2017032201', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('133', '{D969D77F-AF47-4BE8-B5A1-48CBE4549C32}', '61', 'INHE-0580', '2017-03-29 15:43:27', '0000-00-00 00:00:00', '2017-03-30 15:38:25', 'unchecked', 'n', 'n', '', '1', 'sctz2017032901/TTI01/生产通知单', '', 'smartvend和smartview软件的要求：\r\r （确保电表支持以下功能）\r\r\n1.无论何时，用户想充值，客户都能利用该软件进行充值。如果可以，请将软件设置为远程充值时，仅适用现金充值。\r\r\r\n2. 客户能够拥有完整的软件平台，来监控每个电表的使用情况，如平均消费和使用历史查询。而且软件能将所有电表划分为几个群组，并能显示每个电表群的总消费情况。\r\r\r\n3.客户能够自己设置电价，可选择阶梯电价模式，且价格固定。\r\r\r\n4.客户能够追踪每个月电表使用情况和其他数据。\r\r\r\n5.客户能够抄读电表剩余额度。电表设置低电量报警，报警额度为30度。\r\r\n6.客户能够远程切断电表和连接电表。\r\n7.提供第三方接口API，连接第三方销售。', '550', '2017-03-29 15:43:27', 'Africarriers Ltd', 'TTI', 'TTI01', 'INHESC2017031401 ', '2017-05-10', '国际业务二部', '刘前', '', '04', '生产通知单', '收该项目34960美元,结算方式为T/T,发货条件为电表50%尾款收到后发货	，合同变更后总金额增至84450美元		\r\n', '同意', '黄兰兰2017-04-19 13:51:38', '郭涛2017-04-18 16:29:17', '同意', '陶保荣2017-04-19 14:01:43', '', '', '', '', '同意', '丁富民2017-04-19 16:50:55', '王功勇2017-04-19 17:06:43', 'sctz2017032901', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('134', '{46118DB1-933A-4452-9370-4CE8A8E36FB1}', '61', 'INHE-0381', '2017-03-30 08:56:41', '0000-00-00 00:00:00', '2017-04-01 08:23:43', 'unchecked', 'n', 'n', '', '1', 'sctz2017033001/CDN22/生产通知单', '', '发货一个大柜。已收到PO，LC预计4月初收到。由于交期紧张，请先采购物料，启动生产。', '8820', '2017-03-30 08:56:41', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN22', 'INHESC2017032801', '2017-05-05', '国际业务二部', '张柳芳(Alexie)', '', '04', '生产通知单', '未收到货款', '同意', '黄兰兰2017-03-30 17:14:53', '郭涛2017-03-30 16:13:09', '同意', '陶保荣2017-03-30 17:35:49', '', '', '', '翻单生产，请江西工厂处理。', '同意', '丁富民2017-03-30 17:55:38', '王功勇2017-03-31 10:31:41', 'sctz2017033001', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('135', '{F2B4F3E4-A321-45E0-AB6E-C4E2A089D05C}', '61', 'INHE-0381', '2017-04-10 13:39:06', '0000-00-00 00:00:00', '2017-04-11 10:19:07', 'unchecked', 'n', 'n', '', '1', 'sctz2017041001/CDN19-Y/生产通知单', '', '无。', '0', '2017-04-10 13:39:06', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN19-Y', 'INHESC2017022201', '2017-04-21', '国际业务二部', '张柳芳(Alexie)', '', '05', '生产通知单', '结算方式为100%后TT，在试点运行30个工作日内付款', '同意。', '黄兰兰2017-04-11 09:12:52', '郭涛2017-04-10 21:58:55', '同意', '陶保荣2017-04-11 10:00:20', '', '', '', '属软件事业部处理。', '同意。', '丁富民2017-04-11 10:01:51', '王功勇2017-04-11 10:09:12', 'sctz2017041001', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('136', '{D3E7F50B-CF14-4239-843F-E0EE74374BF7}', '60', 'INHE-0088', '2017-04-12 17:18:23', '0000-00-00 00:00:00', '2017-04-18 08:04:29', 'unchecked', 'n', 'n', '', '1', 'sctz2017041201/ST20615/生产通知单', '', 'ST20615项目第二批ST20615-2\r\r\r\r\r\r\r\r\r\r\n生产要求及注意事项：\r\r\r\r\r\r\r\r\r\r\n1. PCB,LCD重要物料单独打托盘；\r\r\r\r\r\r\r\r\r\r\n2. 移动端子不良问题多ST20615第一批已有不良约1500PCS，要求加强来料检验，申请多配至少2000个；\r\r\r\r\r\r\r\r\r\n3. \r物料翻单ST20615-1生产，注意制造年份都为2017；\r\r\r\r\r\r\r\r\n4. \r出厂设置负荷门限修改为5kW,其余设置翻单；\r\r\r\r\r\r\r\r\n\r\r5. 其他\r任何BOM修改请提前通知业务；\r\r\r\r\r\r\n6. 如有多配物料请单独在装箱明细列明；\r\r\r\r\r\r\r\n\r\r\r7. \r\r发货前请提供详细装箱明细，附件是第一批供货明细供参考；\r\n8. ST20615-1图纸文件可翻单生产。\r\n以上请审批。', '64000', '2017-04-12 17:18:23', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20615', 'INHESC2016111601', '2017-05-27', '国际业务一部', '余冬纯', '', '04', '生产通知单', '该批与第一次数量一致，暂未收到第二次的信用证', '同意', '黄兰兰2017-04-13 08:59:47', '王维2017-04-12 17:57:01', '同意', '陶保荣2017-04-13 11:46:28', '', '', '', '翻单生产，请江西工厂处理。', '同意', '丁富民2017-04-13 18:24:06', '王功勇2017-04-13 20:10:51', 'sctz2017041201', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('137', '{63D1E13E-F7DF-431B-85D7-BC8C8CED8607}', '60', 'INHE-0066', '2017-04-13 18:17:25', '0000-00-00 00:00:00', '2017-04-14 17:49:12', 'unchecked', 'n', 'n', '', '1', 'sctz2017041302/白雪705/生产通知单', '', 'APC220-43-0B要求：\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\n3、用于电表上，带自动组网功能。              \r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43\"，主要用于区分开其他功能的无线通信模块。              \r\n5、电压源：3.5-5.5V              \r\n6、频率： 433.05-434.7 MHz           \r\n7、温度范围：-30-+80              \r\n8、外包装箱用纸贴上唛头：APC220-43\r\n9、出厂是发射功率设为10mW.\r\n\r\nAPC910M-43-B要求：\r\n1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。  \r\n2、安美通集抄无线射频通信模块。             \r\n3、电压：4.5-6V             \r\n4、频段：432-434MHz              \r\n5、SMA连接线必须装在电路板上。\r\n6、出厂时发射功率设为10mW.\r\n\r\n\r\nAPC220-43-2A要求：\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（天线需要焊在模块上，天线与模块平行焊。） 3、用于掌上电脑，点对点抄读功能，但不相互干扰。       \r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43-2\"，主要用于区分开其他功能的无线通信模块。       \r\n5、电压源：3.5-5.5V       \r\n6、频率：433,05 - 434,79 MHz       \r\n7、温度范围：-30-+80       \r\n8、外包装箱用纸贴上唛头：APC220-43-2\r\n9、出厂时发射功率设为10mW。 \r\n', '0', '2017-04-13 18:17:25', 'Energomera CJSC', '白雪', '白雪705', 'PO#E1705', '2017-04-25', '国际业务一部', '邱洁', '', '05', '生产通知单', '已经收到原合同（61962.70）的40%的预付款24785.08，现合同追加产品数量合同总金额增至（63314.70），与业务确认追加金额客户将在尾款中全部支付', '同意', '黄兰兰2017-04-18 09:13:08', '王维2017-04-18 08:19:48', '同意', '陶保荣2017-04-18 09:16:56', '', '', '', '', '同意', '丁富民2017-04-18 10:19:32', '王功勇2017-04-18 10:55:30', 'sctz2017041302', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('138', '{358C4B88-DF1E-47B8-9790-BF49D68FA448}', '61', 'INHE-0051', '2017-04-14 16:10:42', '0000-00-00 00:00:00', '2017-04-18 16:35:10', 'unchecked', 'n', 'n', '', '1', 'sctz2017041401/KF02/生产通知单', '', '1.已附上招标技术规格，及技术相关澄清函，需按照规格制作。\r\n2.铭牌需业务确认，将OA单独发出要求。\r\n3.SKD散件生产方式，需对IAC熟悉的技术人员给出。', '120000', '2017-04-14 16:10:42', 'The Kenya Power * Lighting Company Limited', 'KF02', 'KF02', 'INHESC2017033101', '2017-04-14', '国际业务二部', '盛燕', '第三方检验', '02', '生产通知单', '结算方式为每批发货的货值在提单日后120天采用T/T支付，未收到预付款，符合合同结算方式', '同意', '黄兰兰2017-04-18 10:05:20', '郭涛2017-04-14 21:19:03', '同意', '陶保荣2017-04-18 14:11:35', '', '', '', '研发项目负责人：章春鹏', '同意', '丁富民2017-04-18 16:11:12', '王功勇2017-04-18 16:16:51', 'sctz2017041401', '01', '01', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('139', '{D4181391-5E7F-4D34-895B-D30771574E73}', '61', 'INHE-0381', '2017-04-20 10:59:52', '0000-00-00 00:00:00', '2017-04-21 17:15:26', 'unchecked', 'n', 'n', '', '1', 'sctz2017042001/CDN23/生产通知单', '', '发货2个大柜。LC预计下周收到。', '25344', '2017-04-20 10:59:52', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN23', 'INHESC2017041901', '2017-05-31', '国际业务二部', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式为100%LC，60天远期，与出纳确认暂未收到信用证。', '同意', '黄兰兰2017-04-21 10:39:07', '郭涛2017-04-21 10:14:05', '同意', '陶保荣2017-04-21 14:21:56', '', '', '', '翻单产品，请江西工厂处理', '同意', '丁富民2017-04-21 14:24:22', '王功勇2017-04-21 17:13:42', 'sctz2017042001', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('140', '{AFDC34D3-0748-4990-A860-3D9D22A7743D}', '61', 'INHE-0434', '2017-04-24 16:34:02', '0000-00-00 00:00:00', '2017-04-26 17:50:20', 'unchecked', 'n', 'n', '', '1', 'sctz2017042401/AZA02/生产通知单', '', '1. 接线方式无特殊要求，按银河标准\r\r\r\r\r\n2. 产品铭牌信息需发客户确认\r\r\r\n3. 需要完整的产品而不是单单只有表计部分，据悉ST20项目出过完整的产品，孙主管有在OA上提供过产品的完整图片。\r\r\r\n\r\r\r\n', '5', '2017-04-24 16:34:02', 'JEDIG GROUP', 'AZA', 'AZA02', 'INHESC2017041902', '2017-05-25', '国际业务二部', '钟云林(Andy)', '第三方检验', '02', '生产通知单', '该项目合同的结算方式100%T/T预付，货款已收齐，同意生产。		\r\n', '同意', '黄兰兰2017-04-26 09:11:49', '郭涛2017-04-24 22:26:41', '同意', '陶保荣2017-04-26 11:27:48', '', '', '', '', '同意', '丁富民2017-04-26 13:55:39', '王功勇2017-04-26 17:04:06', 'sctz2017042401', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('141', '{E3C2169F-B813-475F-B030-497BA6DFAD93}', '61', 'INHE-0051', '2017-04-25 10:33:15', '0000-00-00 00:00:00', '2017-04-26 17:06:13', 'unchecked', 'n', 'n', '', '1', 'sctz2017042503/A40-F1/生产通知单', '', '1.DIN 3代电表，双绞线通讯分体表，A40翻单.\r\r\r\n2.交期要求很紧，希望5月中旬能发第一批，所有电表5月底能发货。', '200000', '2017-04-25 10:33:15', 'The Kenya Power * Lighting Company Limited', 'A40', 'A40-F1', 'INHESC2017041903', null, '国际业务二部', '盛燕', '第三方检验', '04', '生产通知单', '合同的结算方式为交货后30天T/T付款,此次生产为A40-FI合同全部数量，暂未收到预付款，根据合同签订的结算方式，同意。', '同意。此为紧急采购，请抓紧交付。', '黄兰兰2017-04-25 11:00:23', '郭涛2017-04-25 10:49:39', '同意', '陶保荣2017-04-25 14:17:50', '', '', '', '翻单生产，请江西工厂处理。', '同意', '丁富民2017-04-25 18:05:44', '王功勇2017-04-26 17:02:40', 'sctz2017042503', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('142', '{84B7DBA0-BACB-4F09-8D1A-B7E6D4376DAD}', '60', 'INHE-0066', '2017-04-26 15:44:07', '0000-00-00 00:00:00', '2017-04-27 14:45:46', 'unchecked', 'n', 'n', '', '1', 'sctz2017042601/白雪706/生产通知单', '', '白雪三相表要求：\r\r\r\r\r\n1、采用双方验证过的程序版本TMF2-1B-16032201 2、修改过脉冲输出的阻抗。						\r\r\r\r\r\n3. 铭牌、MAC地址等需要镭雕在电表外壳上； 4. MAC地址铭牌的6位数字为该表表号的最后六位数字； 5. 表内时间为GMT+3#FE54` 6. 冬夏令时转换功能关闭； 7. 需要把面板上的表号设到电表内 8. 计量单元左边不需要铅封，只需右边打一个铅封。9、计量单元、显示单元都不需要贴合格证 10、三相表默认密码为777777。 11：内盒不需要贴条形码', '2233', '2017-04-26 15:44:07', 'Energomera CJSC', '白雪', '白雪706', 'PO#E1706', '2017-05-28', '国际业务一部', '邱洁', '', '04', '生产通知单', '该项目的结算方式为20%T/T-预付款，80%T/T-尾款发货前付清	，已收到28160美元，合同总金额为140800美元，已收总金额的20%，符合合同结算方式，同意。', '同意', '黄兰兰2017-04-27 08:52:19', '王维2017-04-26 21:57:09', '同意', '陶保荣2017-04-27 09:06:41', '', '', '', '研发项目负责人：王占颍', '同意', '丁富民2017-04-27 09:18:52', '王功勇2017-04-27 14:25:46', 'sctz2017042601', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('143', '{31F7CD73-488B-44E0-B1CC-7FF3DB0AD145}', '80', 'INHE-0576', '2017-05-17 19:16:42', '0000-00-00 00:00:00', '2017-05-24 15:23:30', 'unchecked', 'n', 'n', '', '1', 'sctz2017051704/KF02/生产通知单', '', '1.此100台散件是作为之前KF02项目下的生产通知单中24000台散件的备品。                               2.IAC的散件备品技术要求已附上技术规格及技术相关澄清函，按照技术规格提供。                       ', '100', '2017-05-17 19:16:42', 'INHEMETER AFRICA COMPANY LIMITED', 'KF02', 'KF02', 'INHESC2017033101KF02', '2017-06-01', 'Financial DPT.', '戴萍(Eileen)', '第三方检验', '06', '生产通知单', '与业务确认，该备品为深圳银河给IAC的，该项目的结算方式为每批发货的货值在提单日后120天采用T/T支付。同意生产', '同意', '黄兰兰2017-05-23 11:13:55', '郭涛2017-05-22 14:44:12', '同意', '陶保荣2017-05-23 11:24:57', '', '', '', '', '同意', '丁富民2017-05-23 15:28:21', '王功勇2017-05-24 15:12:19', 'sctz2017051704', '01', '01', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('144', '{5ED454B1-30D2-4DA4-838E-D44DE1E8CB38}', '60', 'INHE-0088', '2017-05-20 11:34:12', '0000-00-00 00:00:00', '2017-05-27 08:50:09', 'unchecked', 'n', 'n', '', '1', 'sctz2017052001/ST20615/生产通知单', '', 'EVA泡棉修改为5mm,其他翻单', '64000', '2017-05-20 11:34:12', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20615', 'INHESC2016111601', '2017-06-20', '国际业务一部', '余冬纯', '', '02', '生产通知单', '未收到10%的预付，与业务员确认王总在2017.05.26日OA中有特批同意下单。OA标题为：ST20615生产、发货、收款跟踪。同意', '同意', '黄兰兰2017-05-26 14:40:05', '王维2017-05-21 17:03:11', '同意', '陶保荣2017-05-26 15:29:10', '', '请密切跟踪LC10%议付到账。', '', '', '同意', '丁富民2017-05-26 20:59:25', '王功勇2017-05-27 08:46:54', 'sctz2017052001', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('145', '{4DBE08BD-0D2D-4474-BE6E-222F2F46ED4F}', '60', 'INHE-0066', '2017-05-22 08:38:39', '0000-00-00 00:00:00', '2017-05-24 15:13:17', 'unchecked', 'n', 'n', '', '1', 'sctz2017052201/白雪707/生产通知单', '', 'APC220-43-0B要求：\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\n3、用于电表上，带自动组网功能。              \r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43\"，主要用于区分开其他功能的无线通信模块。              \r\n5、电压源：3.5-5.5V              \r\n6、频率： 433.05-434.7 MHz           \r\n7、温度范围：-30-+80              \r\n8、外包装箱用纸贴上唛头：APC220-43\r\n9、出厂是发射功率设为10mW.\r\n\r\nAPC220-43-2A要求：\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（天线需要焊在模块上，天线与模块平行焊。） \r\n3、用于掌上电脑，点对点抄读功能，但不相互干扰。       \r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43-2\"，主要用于区分开其他功能的无线通信模块。       \r\n5、电压源：3.5-5.5V       \r\n6、频率：433,05 - 434,79 MHz       \r\n7、温度范围：-30-+80       \r\n8、外包装箱用纸贴上唛头：APC220-43-2\r\n9、出厂时发射功率设为10mW。     \r\n       \r\nAPC220-43-3B要求：\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\n2白雪项目专用安美通普通无线射频通信模块，不带嵌入式天线。（不需要把天线焊在模块上。）           \r\n3、用于电表上，带自动组网功能。           \r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43-3\"，主要用于区分开其他功能的无线通信模块。\r\n5、出厂时发射功率设为10mW.          \r\n6、电压源：3.5-5.5V           \r\n7、频率：433.05-434.7 MHz\r\n8、温度范围：-30-+80           \r\n9、外包装箱用纸贴上唛头：APC220-43									\r\n\r\nUSB-APC220-43-0\r\n 1、供应商为安美通。  \r\n 2、外壳上只需贴USB-APC220-43-0，不需其它任何信息及Logo。\r\n 3、升级为V3.0版。\r\n\r\nUSB-APC220-43-2\r\n 1、供应商为安美通。   \r\n2、外壳上只需贴USB-APC220-43-2，不需其它任何信息和Logo.  \r\n 3、需升级为V3.0版本。\r\n', '0', '2017-05-22 08:38:39', 'Energomera CJSC', '白雪', '白雪707', 'PO#E1707', '2017-06-02', '国际业务一部', '邱洁', '', '05', '生产通知单', '该项目的结算方式为40%预付款TT-下单时支付，60%尾款TT-发货前支付。40%的预付款已收，同意。		\r\r\n', '同意', '黄兰兰2017-05-23 10:50:24', '王维2017-05-22 15:49:41', '同意', '陶保荣2017-05-23 11:00:12', '', '', '', '', '同意', '丁富民2017-05-23 15:26:58', '王功勇2017-05-24 15:11:42', 'sctz2017052201', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('146', '{276EF46B-C609-4C8B-9D86-5CCC15A968EC}', '60', 'INHE-0066', '2017-05-22 09:36:15', '0000-00-00 00:00:00', '2017-05-24 15:12:42', 'unchecked', 'n', 'n', '', '1', 'sctz2017052202/白雪708/生产通知单', '', '白雪三相表要求：\r\n1、采用双方验证过的程序版本TMF2-1B-16032201 2、修改过脉冲输出的阻抗。						\r\n3. 铭牌、MAC地址等需要镭雕在电表外壳上； 4. MAC地址铭牌的6位数字为该表表号的最后六位数字； 5. 表内时间为GMT+3#FE54` 6. 冬夏令时转换功能关闭； 7. 需要把面板上的表号设到电表内 8. 计量单元左边不需要铅封，只需右边打一个铅封。9、计量单元、显示单元都不需要贴合格证 10、三相表默认密码为777777。 11：内盒不需要贴条形码										\r\n', '687', '2017-05-22 09:36:15', 'Energomera CJSC', '白雪', '白雪708', 'PO#E1708', '2017-06-30', '国际业务一部', '邱洁', '', '04', '生产通知单', '该项目的结算方式为20%预付款TT-下单时支付，80%尾款TT-发货前付清。20%的预付款已收，同意', '同意', '黄兰兰2017-05-23 10:52:25', '王维2017-05-22 15:48:51', '同意', '陶保荣2017-05-23 10:59:40', '', '', '', '', '同意', '丁富民2017-05-23 15:25:37', '王功勇2017-05-24 15:10:14', 'sctz2017052202', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('147', '{AB9394C3-562C-4E77-9CEC-232F5EF8AA84}', '60', 'INHE-0066', '2017-05-24 10:18:58', '0000-00-00 00:00:00', '2017-05-26 14:38:04', 'unchecked', 'n', 'n', '', '1', 'sctz2017052401/白云603/生产通知单', '', '1、按2015年11月提供给客户的最近样机生产。（和602批次一样的出货，只是此次生产通知单没有按之前的整机下单，而是按散件下单。机芯和之前一样需要修调。）\r\r\n2、电表将分机芯（PCBA）、LCD显示板、铝面板、底壳、按键、五金件几大部分出货。\r\r\n3、双回路计量。\r\r\n4、能支持复费率和阶梯电价两种结算方式。（默认设置见随后提供的出厂设置单）\r\r\n5、带远程通断电功能。\r\r\n6、负荷门限设置。\r\r\n7、能承受电压异常的瞬间波动，电压异常时，电表自动断电，电压恢复正常时，电表自动恢复供电。\r\r\n8、能编程设置为后付费功能   \r\r\n\r\r\n										\r\r\n										\r\r\n', '0', '2017-05-24 10:18:58', '\"Aspan-Energy \" LTD', '白云', '白云603', 'INHESC2016110805', '2017-06-15', '国际业务一部', '邱洁', '', '05', '生产通知单', '结算方式为50%T/T-下单前支付，50%T/T尾款-发货前支付，50%的预付款已收，同意生产。', '同意', '黄兰兰2017-05-26 08:44:41', '王维2017-05-25 12:18:36', '同意', '陶保荣2017-05-26 08:50:14', '', '', '', '', '同意', '丁富民2017-05-26 12:05:19', '王功勇2017-05-26 14:30:05', 'sctz2017052401', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('148', '{C827625A-EA64-41D5-BB34-8E899ED88010}', '60', 'INHE-0088', '2017-05-25 18:12:06', '0000-00-00 00:00:00', '2017-06-01 15:45:16', 'unchecked', 'n', 'n', '', '1', 'sctz2017052501/ST20605/生产通知单', '', '紧急需求，翻单ST20704，请尽快安排生产。', '1000', '2017-05-25 18:12:06', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20605', 'INHESC2016030378', '2017-06-20', '国际业务一部', '余冬纯', '', '06', '生产通知单', '该项目的结算方式为全款即期不保兑信用证，信用证下，10%预付，90%提供发货单据扫描件后即期支付.10%信用证已收，符合合同结算方式。同意生产', '同意', '黄兰兰2017-06-01 11:42:21', '王维2017-05-27 09:50:11', '同意', '陶保荣2017-06-01 14:17:01', '', '注意跟踪10%议付进展，必须及时议付到账。', '', '', '同意', '丁富民2017-06-01 14:48:50', '王功勇2017-06-01 15:40:17', 'sctz2017052501', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('149', '{ACE2D69F-6533-41E4-B579-09247A20B98F}', '60', 'INHE-0066', '2017-05-31 16:00:44', '0000-00-00 00:00:00', '2017-06-06 14:02:44', 'unchecked', 'n', 'n', '', '1', 'sctz2017053101/白雪709/生产通知单', '', '白雪单相表要求：\r\r\n1、采用新模具结构供货。     \r\r\n2、PCB板不需灌胶和喷三防漆！\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。      \r\r\n4、MAC地址为该表表号（表地址）的最后六位数字，该地址激光雕刻在表外壳背部。       \r\r\n5、PLC载波显示单元的铭牌标识为：CE208。         \r\r\n6、显示单元不需要贴易碎贴。        \r\r\n7、出厂设置：           \r\r\n1）表内时间为：GMT+4           \r\r\n2）冬夏令时转换功能关闭。           \r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\n5）特殊节假日没有。           \r\r\n6）电表密码：000000.           \r\r\n7）负荷门限：0.           \r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\n9）取负荷点的平均时间：30分钟。          \r\r\n8、继电器：100A，但标识采用120A。      \r\r\n9、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）       \r\r\n10、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\n11、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU的内盒中。  \r\r\n										\r\r\n										\r\r\n										\r\r\n										\r\r\n										\r\r\n', '150300', '2017-05-31 16:00:44', 'Energomera CJSC', '白雪', '白雪709', 'PO#E1709', '2017-06-30', '国际业务一部', '邱洁', '', '05', '生产通知单', '该项目的结算方式为15%T/T -下单时支付，85%每一批-LC 在每批货发货前7个工作日开出，并于每批货提单之日起75天内支付。已收15%的预付款，同意生产', '同意', '黄兰兰2017-06-01 14:54:59', '王维2017-06-01 08:26:00', '同意', '陶保荣2017-06-01 15:59:02', '', '请江西工程部重点解决超声焊的一致性（密封性）问题。', '', '产品研发负责人：王占颍   生产时要注意超声波焊接的可靠性，目前超声波焊接且不能作到100%的密封性，存在一定比率的问题，需要工程生产方面去解决。', '同意', '丁富民2017-06-01 16:04:11', '王功勇2017-06-01 21:40:04', 'sctz2017053101', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('150', '{3FE7DA9C-8557-492B-93EA-F72B9060CAB7}', '61', 'INHE-0587', '2017-06-07 11:13:50', '0000-00-00 00:00:00', '2017-06-09 08:26:27', 'unchecked', 'n', 'n', '', '1', 'sctz2017060701/PN04/生产通知单', '', '1.请确认是否可使用TAN项目库存。2.LOGO需定制，请届时与业务确认。', '400', '2017-06-07 11:13:50', 'B.N.S.R. Sela', 'PN', 'PN04', 'INHESC2017052403', '2017-07-20', '国际二部 INTL.Business Dept.2', '陆飞雨', '', '04', '生产通知单', '该项目全款已收齐，同意生产。', '同意', '黄兰兰2017-06-20 09:11:00', '郭涛2017-06-19 15:59:43', '同意', '陶保荣2017-06-20 09:13:21', '', '', '', '', '同意', '丁富民2017-06-20 09:32:35', '王功勇2017-06-20 13:46:03', 'sctz2017060701', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('151', '{C5A5BB78-941F-4B42-9995-C875279369AD}', '80', 'INHE-0576', '2017-06-09 15:32:32', '0000-00-00 00:00:00', '2017-06-19 10:42:49', 'unchecked', 'n', 'n', '', '1', 'sctz2017060901/IMF03/生产通知单', '', '需要和KF02项目的表一起发货到IAC', '0', '2017-06-09 15:32:32', 'INHEMETER AFRICA CO., LTD.', 'IMF', 'IMF03', 'INHESC2017052402', '2017-07-30', 'Financial DPT.', '戴萍(Eileen)', '', '06', '生产通知单', '结算方式为提单日后120天采用T/T支付，同意生产。		\r\n', '同意', '朱君宜2017-12-26 18:31:05', '盛燕2017-12-26 14:42:50', '同意', '陶保荣2017-12-26 20:55:54', '', '', '', '', '同意', '丁富民2017-12-27 08:44:20', '王功勇2017-12-27 09:03:02', 'sctz2017060901', '01', '01', 'KF02生产所需工装夹具及辅料。', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('152', '{E0E8DA0F-50EE-4D63-ABE7-EEA8F0A617E9}', '66', 'INHE-0579', '2017-06-14 10:48:00', '0000-00-00 00:00:00', '2017-06-22 16:59:46', 'unchecked', 'n', 'n', '', '1', 'sctz2017061403/CG04/生产通知单', '', '所有电表适用于双电源方案。“双电源方案”指即可计量发电机用电、又可计量市电的PLC通信方案。						\r\n', '217', '2017-06-14 10:48:00', 'DREXEL INTERNATIONAL LTD', 'CG', 'CG04', 'INHESC2017052202', '2017-08-01', '国际三部 INTL.Business Dept.3', '孙娜', '', '05', '生产通知单', '货款已收。', '同意。', '黄兰兰2017-06-15 08:24:38', '宋宁2017-06-14 14:50:57', '同意', '陶保荣2017-06-15 08:44:16', '', '', '', '技术要求不明确，并需要研发进行产品开发，订单数量少，不具备代表性。', '暂不同意', '丁富民2017-06-22 10:41:03', '王功勇2017-06-22 14:58:47', 'sctz2017061403', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('153', '{2FE6172A-4D62-40DE-9B31-6241412A2DDC}', '60', 'INHE-0088', '2017-06-14 17:49:43', '0000-00-00 00:00:00', '2017-06-22 20:45:12', 'unchecked', 'n', 'n', '', '1', 'sctz2017061404/ST20706/生产通知单', '', '翻单，客户生产急需物料，请协助尽快采购。', '0', '2017-06-14 17:49:43', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20706', 'INHESC2017060701', '2017-06-23', '国际一部 INTL.Business Dept.1', '余冬纯', '', '06', '生产通知单', '该项目目前只收60欧元，剩余EUR31954未收到，据业务员反馈款在北京中行未下发分行，不符合合同结算方式。王总在OA标题为“ST20706收款问题”中批示同意发货，请领导指示。', '同意', '黄兰兰2017-06-22 17:13:34', '王维2017-06-15 08:40:21', '同意', '陶保荣2017-06-22 17:15:08', '', '', '', '', '同意', '丁富民2017-06-22 17:25:42', '王功勇2017-06-22 18:44:45', 'sctz2017061404', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('154', '{48A2D73E-9DC1-41CB-87B6-2B4A55AF487F}', '61', 'INHE-0578', '2017-06-15 22:55:39', '0000-00-00 00:00:00', '2017-06-19 10:33:25', 'unchecked', 'n', 'n', '', '1', 'sctz2017061501/ESA05/生产通知单', '', '1. 此项目代号为ESA05，为ESA04翻单；出厂前激活电表，具体要求与业务OA确认；\r\r\n\r\r\n\r\r\n2. 交期要求紧张。', '30000', '2017-06-15 22:55:39', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'ESA', 'ESA05', 'INHESC2017061201', '2017-07-10', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '第三方检验', '02', '生产通知单', '同意。（合同约定结算方式无预付款）', '同意', '黄兰兰2017-06-16 08:54:51', '郭涛2017-06-16 03:05:54', '同意', '陶保荣2017-06-16 11:14:55', '', '特别注意：丁总提到的，电池保护和测试。（客户工厂电池问题比较突出！）', '', '已经批量生产产品，请江西工厂安排处理。注意电池保护和测试，客户工厂电池问题比较突出，占坏机比例非常大。', '同意。', '丁富民2017-06-19 09:59:23', '王功勇2017-06-19 10:16:30', 'sctz2017061501', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('155', '{DA44FE89-2E27-4B90-85E3-952E17B9FCF2}', '61', 'INHE-0608', '2017-06-20 13:56:11', '0000-00-00 00:00:00', '2017-06-21 11:30:01', 'unchecked', 'n', 'n', '', '1', 'sctz2017062001/PSA10702/生产通知单', '', '1.PSA10702为PSA10701项目翻单，翻单资料同PSA10701的产品资料一致，但请注意此次电力公司为CENS，不是EPM.                                                                                         2.此单交期很紧，要求30天内交货，即8月1日从工厂交货', '3000', '2017-06-20 13:56:11', 'MESSEN S.A.S', 'PSA10', 'PSA10702', 'INHESC2017061302', null, '国际二部 INTL.Business Dept.2', '周雅利', '', '06', '生产通知单', '该项目结算方式为30%预付款合同签订后T/T支付，70%尾款发货前两周支付。30%的预付款已经收到，同意生产。', '同意。请工厂协助交期，客户已经付预付款。', '黄兰兰2017-06-20 17:54:51', '郭涛2017-06-20 15:33:29', '同意', '陶保荣2017-06-20 20:24:43', '', '', '', '翻单生产，请江西工厂安排处理。注意LCD显示质量问题。', '同意', '丁富民2017-06-21 10:10:54', '王功勇2017-06-21 10:54:32', 'sctz2017062001', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('156', '{1660B06A-16E8-47E0-AE40-BA1FA1E685D7}', '61', 'INHE-0608', '2017-06-20 15:58:31', '0000-00-00 00:00:00', '2017-06-22 16:59:40', 'unchecked', 'n', 'n', '', '1', 'sctz2017062002/PSA16701/生产通知单', '', '1.此单两款表均为PSA6项目翻单，但请注意此次要求使用透明端盖                                      2.该项目交期要求30天，即8月1日从工厂发货，请抓紧时间安排生产', '150', '2017-06-20 15:58:31', 'MESSEN S.A.S', 'PSA16', 'PSA16701', 'INHESC2017060801', '2017-08-01', '国际二部 INTL.Business Dept.2', '周雅利', '', '06', '生产通知单', '该项目结算方式为50%预付款合同签订后T/T支付，50%尾款发货前两周支付。50%的预付款已收齐，同意生产。', '同意。', '黄兰兰2017-06-21 16:55:28', '郭涛2017-06-21 16:20:13', '同意', '陶保荣2017-06-22 08:44:06', '', '', '', '研发项目负责人王占颍', '同意', '丁富民2017-06-22 08:54:49', '王功勇2017-06-22 14:58:19', 'sctz2017062002', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('157', '{2339CA8A-9ABE-4870-98B6-8907254CC68E}', '60', 'INHE-0549', '2017-06-21 15:55:14', '0000-00-00 00:00:00', '2017-06-23 13:22:38', 'unchecked', 'n', 'n', '', '1', 'sctz2017062101/KM01/生产通知单', '', '出厂时单三相表箱内部装好表及断路器熔断器熔芯等产品并接好线。单相断路器，安装板和CIP可单独包装。如附件与生产通知单所填内容有冲突请以生产通知单填写内容为准，如有任何其他问题请微信联系王秀明：15705276012.谢谢！', '6600', '2017-06-21 15:55:14', 'KAMA.SA', 'KM', 'KM01', 'INHESC2017022202', '2017-08-30', '国际一部 INTL.Business Dept.1', '王秀明', '', '05', '生产通知单', '该批次信用证已收382042.41美元，产品的金额为364781.15美元，运保费17261.26美元。其中非表类的第8项比合同的单价低1美元，经与业务确认品名未变，用四表位代替六表位导致。由于信用证结算交期紧张，业务今晚做合同变更评审。以上请领导审批', '同意', '黄兰兰2017-06-22 17:57:18', '', '同意', '陶保荣2017-06-23 08:35:45', '', '', '', '单相表---DIN-III(单回路计量）章春鹏     三相表---第二代三相代码表 王顺万负责     安装板需要安排开模制作', '同意', '丁富民2017-06-23 09:05:41', '王功勇2017-06-23 09:54:12', 'sctz2017062101', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('158', '{D2228B54-2E4E-4AF6-BECF-D4828B9FFA3D}', '61', 'INHE-0381', '2017-06-28 16:21:41', '0000-00-00 00:00:00', '2017-07-07 08:42:45', 'unchecked', 'n', 'n', '', '1', 'sctz2017062801/CDN25/生产通知单', '', '发货1个大柜，LC预计下周收到。', '12672', '2017-06-28 16:21:41', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN25', 'INHESC2017050802', '2017-08-04', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式为100%LC，60天远期。LC正本已收,同意生产			\r\n', '同意', '黄兰兰2017-07-06 17:10:52', '郭涛2017-06-29 14:10:02', '同意', '陶保荣2017-07-06 17:15:58', '', '与CDN24一起交货，不能分批。', '', '翻单生产，请江西工厂安排处理。', '同意', '丁富民2017-07-06 18:25:43', '王功勇2017-07-06 18:30:28', 'sctz2017062801', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('159', '{12F9FFFD-6E74-4F89-9854-C45F25F1625D}', '61', 'INHE-0381', '2017-06-29 17:56:12', '0000-00-00 00:00:00', '2017-07-07 08:34:05', 'unchecked', 'n', 'n', '', '1', 'sctz2017062901/CDN24/生产通知单', '', '发货2个大柜。LC预计下周收到。', '25344', '2017-06-29 17:56:12', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN24', 'INHESC2017050801', '2017-08-04', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式为100%LC，60天远期。LC正本已收,同意生产', '同意备料；请张柳芳抓紧跟催LC，通知启动生产。', '黄兰兰2017-07-06 17:10:21', '郭涛2017-07-04 16:45:38', '同意', '陶保荣2017-07-06 17:15:35', '', '与CDN25一起交货，不能分批。', '', '翻单生产，请江西工厂安排处理', '同意', '丁富民2017-07-06 18:24:55', '王功勇2017-07-06 18:29:48', 'sctz2017062901', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('160', '{8E80C0EE-0983-4793-B01B-19A0EF7454C5}', '61', 'INHE-0091', '2017-07-03 12:29:57', '0000-00-00 00:00:00', '2017-07-07 08:35:57', 'unchecked', 'n', 'n', '', '1', 'sctz2017070303/M12-1/生产通知单', '', '1. 分三批发货：\r\r\r\r\r\r\n第一批空运：电表30000+二表位表箱6000+四表位表箱4500；电表装进表箱中发货；交货时间：2017年8月11日\r\r\r\r\r\r\n第二批海运：电表20000+二表位表箱12000+四表位表箱5500；电表与表箱单独包装，电表不装进表箱；交货时间：2017年8月18日\r\r\r\r\r\r\n第三批海运：二表位表箱12000+六表位表箱3000；交货时间：2017年8月25日\r\r\r\n\r\r\n2.外箱唛头内容有要求\r\n\r\n3.客户FAT时间：生产第一批货进行中时。请工厂提前告知FAT时间。', '50000', '2017-07-03 12:29:57', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'M12', 'M12-1', 'ESC 469/ICB/RT/G/FY2016-17', '2017-08-11', '国际二部 INTL.Business Dept.2', '林丽璇(Elle Lin)', '第三方检验', '02', '生产通知单', '1.第一批结算方式为50%签订合同后14天TT，50%发货前TT，第二、三批结算方式为LC。2.交货时间为8.11日，本合同涉及到违约金条款项：违约金（延迟交货）应为:每周0.2%，最高可达合同价格的10%。暂未收到任何款项（预付款和LC）,无特批，不符合生产条件，但交期紧张且延期有违约金，以上请领导指示。\r\r\r\r\r\n', '同意。请林丽璇跟紧项目组催预付款，尾款和LC。', '黄兰兰2017-07-04 22:10:28', '郭涛2017-07-03 14:59:47', '同意', '陶保荣2017-07-05 08:34:25', '', '请业务紧密跟踪第一批50%预付款和第二、三批的L/C', '', '单相表研发负责人：章春鹏   表箱结构负责人：曾年贵     产品BOM表除包装外已经放发', '同意。', '丁富民2017-07-05 09:47:16', '王功勇2017-07-05 15:40:41', 'sctz2017070303', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('161', '{02F66006-8A88-4CE9-BF60-4C32B044E6DC}', '61', 'INHE-0578', '2017-07-03 15:49:37', '0000-00-00 00:00:00', '2017-07-06 13:53:28', 'unchecked', 'n', 'n', '', '1', 'sctz2017070304/ESA06/生产通知单', '', '1. 此项目代号ESA06， 为ESA05翻单，所有要求与ESA05保持一致。\r\n\r\n\r\n2. 交期要求十分紧张。', '25000', '2017-07-03 15:49:37', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'ESA', 'ESA06', 'INHESC2017061301', '2017-07-25', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '第三方检验', '02', '生产通知单', '结算方式为生产前20%T/T，发货前80% T/T。20%预付款已收，同意生产。', '同意', '黄兰兰2017-07-03 20:00:45', '郭涛2017-07-03 16:33:22', '同意', '陶保荣2017-07-04 08:44:00', '', '', '', '翻单生产，请江西工厂自行安排处理。', '同意', '丁富民2017-07-04 09:34:33', '王功勇2017-07-04 18:40:12', 'sctz2017070304', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('162', '{4AECD1B5-4BF1-460C-B1B0-7E83382677CB}', '61', 'INHE-0381', '2017-07-04 06:44:47', '0000-00-00 00:00:00', '2017-07-19 08:39:29', 'unchecked', 'n', 'n', '', '1', 'sctz2017070401/CDN26/生产通知单', '', 'CDN24至CDN29的产品都是单相RF模块表的翻单产品，但每一批发货的外箱唛头的reference都不一样需要修改。LC正在跟催开立中。', '12672', '2017-07-04 06:44:47', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN26', '17000836CA', '2017-08-31', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式为100%LC，60天远期，未收到LC.王总在OA标题为“CDN24-29物料采购审批”中特批CDN26的备料，在启动生产之前必须督促客户开出LC，在启动生产之前请孙永珍务必跟财务部或跟单组确认LC是否收到。同意先行备料', '同意备料。请张柳芳跟催LC，通知启动生产。', '黄兰兰2017-07-15 08:55:56', '郭涛2017-07-04 16:56:21', '同意', '陶保荣2017-07-17 08:32:12', '', '', '', '翻单生产，请江西工厂安排处理。', '同意', '丁富民2017-07-17 10:09:35', '王功勇2017-07-17 11:27:24', 'sctz2017070401', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('163', '{1B9FA451-0DD2-4CAE-8A63-4F7E950FC7D8}', '61', 'INHE-0500', '2017-07-05 13:38:54', '0000-00-00 00:00:00', '2017-07-26 15:08:17', 'unchecked', 'n', 'n', '', '1', 'sctz2017070501/BAP02/生产通知单', '', '电表供电来源为电力公司和发电机，电表支持电力公司和发电机两种费率，支持外部信号输入由电力公司费率自动切换至发电机费率。此功能之前客户服评审建议：PLC电表通过集中器发指令到电表切换，即由外部单独的通讯线路给指令到集中器，集中器再发给电表切换，GPRS电表直接通过外部单独的通讯线路给指令到电表切换；\r\r\n', '39', '2017-07-05 13:38:54', 'FactorFast (PTY) Ltd', 'BAP', 'BAP02', 'INHESC2017063001', '2017-07-25', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '06', '生产通知单', '结算方式为生产前合同金额的50%通过T/T支付，发货前合同金额的50%通过T/T支付，货款已全部收齐，同意生产。', '同意。南非的插头标准很特殊，已经通知李忠鹏注意核实，另外发OA确认。网速慢，打开报表太过艰难，因而不再退回。', '黄兰兰2017-07-25 13:35:10', '郭涛2017-07-18 16:26:41', '同意，', '陶保荣2017-07-25 14:35:55', '', '1、合同经过评审吗？2、技术上技术支持总监是否评审过？', '', '单相、三相、集中器都需要安排进行研发、测试。而订单不具有代表性、数量又少，研发不计划安排处理。', '不同意。没有现成产品，需要安排开发。', '丁富民2017-07-25 15:04:22', '王功勇2017-07-26 14:57:31', 'sctz2017070501', '02', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('164', '{E28DDB0C-46CA-479D-B99B-C0FB851AED6D}', '61', 'INHE-0593', '2017-07-25 15:09:25', '0000-00-00 00:00:00', '2017-08-11 08:46:48', 'unchecked', 'n', 'n', '', '1', 'sctz2017070702/MLB03/生产通知单', '', '投标时电力公司提出要求，收到预付款后45天交期，为了赢标答应了这个要求，希望公司理解支持。', '10000', '2017-07-25 15:09:25', 'ENTREPRISE MALIENNE DE TRAVAUX ET D’INGENIERIE', 'MLB03', 'MLB03', 'INHESC2017052601', '2017-09-01', '国际二部 INTL.Business Dept.2', '胡蝶', '第三方检验', '06', '生产通知单', '结算方式为50%TT生产前付款+50%TT发货前付款	，已收到该项目的50%预付款。经与业务确认，交期为本次收款后（07.26日收款）的45天交期。同意生产。', '同意（丢掉的20000台TN11订单和此订单规格类似；客户不同）。', '黄兰兰2017-07-26 14:44:36', '郭涛2017-07-26 11:50:12', '同意', '陶保荣2017-07-26 15:06:08', '', '', '', '章春鹏负责，使用BS安装一体式代码表。', '同意。', '丁富民2017-07-26 17:26:54', '王功勇2017-07-27 09:54:00', 'sctz2017070702', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('165', '{17ADB9D1-864F-4217-A771-35601992D838}', '60', 'INHE-0066', '2017-07-11 08:50:30', '0000-00-00 00:00:00', '2017-07-13 17:37:57', 'unchecked', 'n', 'n', '', '1', 'sctz2017071101/白雪710/生产通知单', '', '白雪三相表要求：\r\r\r\r\r\r\n\r\r\r\r\n1、采用双方验证过的程序版本TMF2-1B-16032201 2、修改过脉冲输出的阻抗。						\r\r\r\r\r\r\r\n3. 铭牌、MAC地址等需要镭雕在电表外壳上； 4. MAC地址铭牌的6位数字为该表表号的最后六位数字； 5. 表内时间为GMT+3#FE54` 6. 冬夏令时转换功能关闭； 7. 需要把面板上的表号设到电表内 8. 计量单元左边不需要铅封，只需右边打一个铅封。9、计量单元、显示单元都不需要贴合格证 10、三相表默认密码为777777。 11：内盒不需要贴条形码										\r\r\r\r\r\r\r\n										\r\r\r\r\r\r\r\n', '1242', '2017-07-11 08:50:30', 'Energomera CJSC', '白雪', '白雪710', 'PO#E1710', '2017-08-10', '国际一部 INTL.Business Dept.1', '邱洁', '', '04', '生产通知单', '结算方式为20%TT-预付款，80%TT尾款发货前付清，20%预付款已收齐，同意生产', '同意', '黄兰兰2017-07-12 13:33:17', '王维2017-07-12 11:58:52', '同意', '陶保荣2017-07-13 08:27:03', '', '', '', '研发项目负责人：王占颍', '同意', '丁富民2017-07-13 08:34:30', '王功勇2017-07-13 09:44:15', 'sctz2017071101', '01', '', '', '', null, null, null, null, null, null, null);
