INSERT INTO `crs_tabledata719` VALUES ('167', '{5399F747-1CAB-4E01-9309-60EA706A1FD8}', '61', 'INHE-0578', '2017-07-12 17:47:20', '0000-00-00 00:00:00', '2017-07-14 18:30:06', 'unchecked', 'n', 'n', '', '1', 'sctz2017071202/ESA08/生产通知单', '', '1. 此项目代号为ESA08， 为ESA05翻单，所有要求同ESA05，若有变更业务将OA提出。', '30000', '2017-07-12 17:47:20', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'ESA', 'ESA08', 'INHESC2017070401', '2017-08-10', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '第三方检验', '02', '生产通知单', '结算方式为生产前T/T支付19万美元，发货前T/T支付84万美元。19万美元已收，同意生产', '同意', '黄兰兰2017-07-14 10:24:56', '郭涛2017-07-13 18:16:10', '同意', '陶保荣2017-07-14 11:44:50', '', '', '', '翻单产品，请江西工厂安排处理。', '同意', '丁富民2017-07-14 13:20:00', '王功勇2017-07-14 14:03:12', 'sctz2017071202', '01', '', '', '', null, null, null, null, null, null, null);
