INSERT INTO `crs_tabledata719` VALUES ('172', '{A7A89A9B-F83C-4B9A-AFE7-27632B62B8EA}', '61', 'INHE-0381', '2017-07-17 15:22:43', '0000-00-00 00:00:00', '2017-07-19 08:39:46', 'unchecked', 'n', 'n', '', '1', 'sctz2017071702/CDN27/生产通知单', '', '外箱Oder number：17000837 CA；consignee number:17000100 YS.', '25344', '2017-07-17 15:22:43', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN27', '17000837CA', '2017-08-30', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式为100%LC，60天远期，未收到LC.王总在OA标题为“CDN24-29物料采购审批”中特批CDN27的备料，在启动生产之前必须督促客户开出LC，在启动生产之前请孙永珍务必跟财务部或跟单组确认LC是否收到。同意先行备料			\r\r\n', '', '黄兰兰2017-07-18 08:53:18', '', '同意', '陶保荣2017-07-18 14:25:22', '', '', '', '翻单生产，请江西工厂安排处理。', '同意', '丁富民2017-07-18 15:33:54', '王功勇2017-07-18 17:46:15', 'sctz2017071702', '01', '', '', '', null, null, null, null, null, null, null);
