INSERT INTO `crs_tabledata719` VALUES ('174', '{A70D4E56-DC43-47BD-ACE2-8FA554CFE576}', '61', 'INHE-0500', '2017-07-24 14:21:26', '0000-00-00 00:00:00', '2017-07-25 07:58:54', 'unchecked', 'n', 'n', '', '1', 'sctz2017072401/SERD01/生产通知单', '', '1.要求走DL/T645协议，和银河RS485采集器组成集抄；\r\r\n2,。支持30分钟负荷曲线功能；\r\n3.支持正向和反向分别计量。\r\n', '300', '2017-07-24 14:21:26', 'One Smart Power SA (pty) Ltd', 'SERD', 'SERD01', 'INHESC2017071801', '2017-09-08', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式为生产前全T/T支付	，货款已全部收齐，同意生产', '同意', '黄兰兰2017-07-24 15:38:13', '郭涛2017-07-24 15:17:13', '同意', '陶保荣2017-07-24 15:39:28', '', '', '', '建议使用单相可更换通信模块表，不带键盘、不带通信接口，产品负责人：王顺万。---建议使用库存表处理。', '同意', '丁富民2017-07-24 16:46:56', '王功勇2017-07-24 16:48:10', 'sctz2017072401', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('175', '{CEBB7DD3-95A2-4343-9C87-7411CA26B281}', '61', 'INHE-0500', '2017-07-27 13:25:25', '0000-00-00 00:00:00', '2017-07-31 09:32:11', 'unchecked', 'n', 'n', '', '1', 'sctz2017072702/SEGS01/生产通知单', '', '', '200', '2017-07-27 13:25:25', 'Meter Mate Prepaid Electric Meters cc', 'SEGS', 'SEGS01', 'INHESC2017072501', '2017-09-08', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '货款已收齐，同意生产', '同意', '黄兰兰2017-07-27 17:52:28', '郭涛2017-07-27 17:42:14', '同意', '陶保荣2017-07-28 09:00:03', '', '', '', '', '同意', '丁富民2017-07-28 11:05:20', '王功勇2017-07-28 11:32:27', 'sctz2017072702', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('176', '{18295BDA-9B2D-4A54-B3B9-A377B2E68465}', '61', 'INHE-0593', '2017-07-31 15:17:18', '0000-00-00 00:00:00', '2017-08-02 13:20:03', 'unchecked', 'n', 'n', '', '1', 'sctz2017073101/TN11/生产通知单', '', 'TN11将分3次发货，交期要求和数量如下：\r\n- 本周六（8月5日）之前，发【500台单相表】（BY06项目改表）\r\n- 剩下的交期将在9月5日前尽快发货，其中：\r\n  【2000台单相+1000台三相】发空运\r\n  【12500台单相+6500台三相】发海运\r\n\r\n注：项目总数量为15000单相+7500三相。', '22500', '2017-07-31 15:17:18', 'TOGO ASSISTANCE SERVICES', 'TN11', 'TN11', 'INHESC2017071201', '2017-09-05', '国际二部 INTL.Business Dept.2', '胡蝶', '第三方检验', '06', '生产通知单', '1.已收该项目14600美元，剩余LC未收；2.该项目的客户实际为SOCIETE GENERALE D ELECTRONIQUE，且合同金额可能有变动，已催促但业务员未及时做合同的及时变更，该生产通知单已历史客户名称下生产通知单。3.王总在OA标题“TN11合同款项相关”中同意先备料。以上请领导审批。', '同意。', '黄兰兰2017-08-02 09:34:56', '郭涛2017-07-31 16:14:07', '同意', '陶保荣2017-08-02 09:37:43', '', '请业务注意跟踪付款和LC，控制风险。', '', '章春鹏负责安排、处理', '同意', '丁富民2017-08-02 09:50:37', '王功勇2017-08-02 09:54:51', 'sctz2017073101', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('177', '{4A4EB323-7642-4DD1-A446-9D774BE71A96}', '61', 'INHE-0381', '2017-07-31 20:35:56', '0000-00-00 00:00:00', '2017-08-01 17:57:03', 'unchecked', 'n', 'n', '', '1', 'sctz2017073102/GN06/生产通知单', '', '已收到信用证。', '0', '2017-07-31 20:35:56', 'TOGO ASSISTANCE SERVICES', 'GN06', 'GN06', 'INHESC2017072601', '2017-09-29', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式为100%远期60天信用证，已收到LC通知书:CDI17000024，金额为USD190,200.00，符合结算方式，同意生产\r\r\r\r\r\n', '同意', '黄兰兰2017-08-01 10:14:28', '郭涛2017-08-01 09:22:25', '同意', '陶保荣2017-08-01 11:13:19', '', '', '', '研发需要进行表箱选择、布置设计，争取用已有表箱模具。', '同意', '丁富民2017-08-01 11:29:45', '王功勇2017-08-01 17:42:39', 'sctz2017073102', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('178', '{BA27B9DF-448F-4924-B433-C4BB61462896}', '61', 'INHE-0500', '2017-08-02 11:42:52', '0000-00-00 00:00:00', '2017-08-02 15:29:08', 'unchecked', 'n', 'n', '', '1', 'sctz2017080202/BAP02/生产通知单', '', '1.支持电网供电、发电机供电转换。\r\r\r\r\n丁总建议：PLC载波方案建议仍采用PLC+RF双模方案，类似于林丽璇GG项目处理\r\r\r\r\r\r\r\n', '39', '2017-08-02 11:42:52', 'FactorFast (PTY) Ltd', 'BAP', 'BAP02', 'INHESC2017063001', '2017-08-31', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '第二次做该项目的生产通知单，7月的生产通知单王总未同意。本次王总在OA标题为“BAP02订单情况说明和申请”中同意生产。本项目的货款已全部收齐，符合结算方式，同意生产。			\r\r\r\r\n', '同意', '黄兰兰2017-08-02 14:34:47', '郭涛2017-08-02 13:41:07', '同意', '陶保荣2017-08-02 14:53:13', '', '希望国际业务二部能继续扩大需求，避免研发投入后只执行这个小订单。', '产品最后由客户服务部根据市场需求负责测试验收。', '项目技术总负责人：王顺万。三相直通表按CDN项目制作。三相CT表建议按最新给出的BOM表执行（王占颍确认）。二款表计请江西工厂负责生产，二台集中器由研发负责处理。', '同意。', '丁富民2017-08-02 15:14:46', '王功勇2017-08-02 15:21:44', 'sctz2017080202', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('179', '{6ACF020B-A9CC-45AA-8B0B-516312B39E91}', '61', 'INHE-0500', '2017-08-07 14:57:03', '0000-00-00 00:00:00', '2017-08-08 10:42:56', 'unchecked', 'n', 'n', '', '1', 'sctz2017080701/BAP03/生产通知单', '', '', '360', '2017-08-07 14:57:03', 'FactorFast (PTY) Ltd', 'BAP', 'BAP03', 'INHESC2017080201', '2017-09-05', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式为生产前20%T/T预付款，发货前80%T/T余款支付。合同总金额为38600美元，已收7500美元，已预收19.43%，未达到合同结算方式的20%，不符合结算方式，请领导指示。', '同意', '黄兰兰2017-08-08 09:41:52', '郭涛2017-08-07 16:29:43', '同意', '', '', '请客服部与业务部落实：三相四线CT表的接线方式“双进双出”问题，只能按公司现有接线方式供货。', '', '三相四线CT接入式电表没有“双进双出”接线端子，也没有相应的定型产品。', '不同意', '丁富民2017-08-08 10:01:48', '王功勇2017-08-08 10:14:27', 'sctz2017080701', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('180', '{319F7E1E-CD56-4FD6-A552-B6E204FAB952}', '61', 'INHE-0593', '2017-08-13 20:27:46', '0000-00-00 00:00:00', '2017-08-17 08:16:11', 'unchecked', 'n', 'n', '', '1', 'sctz2017081301/BFN03/生产通知单', '', '', '18828', '2017-08-13 20:27:46', 'TOGO ASSISTANCE SERVICES', 'BFN', 'BFN03', 'INHESC2016070701', '2017-09-25', '国际二部 INTL.Business Dept.2', '胡蝶', '', '02', '生产通知单', '该项目的结算方式为：1,937,860.93欧元为不可撤销的，由一级银行保兑的远期信用证；145,151.60欧元为不可撤销的，由一级银行保兑的即期信用证。合同总金额全款LC通知书已收，金额为2,083,012.53。同意生产', 'BFN03已经收到LC。请胡蝶抓紧跟进落实LC修改项。', '黄兰兰2017-08-16 08:59:09', '郭涛2017-08-14 13:45:02', '同意', '陶保荣2017-08-16 09:15:03', '', '', '', '', '同意', '丁富民2017-08-16 09:27:50', '王功勇2017-08-16 10:24:19', 'sctz2017081301', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('181', '{45B6CD90-3021-4305-87E8-D6F1FC8D45DD}', '60', 'INHE-0066', '2017-08-14 08:44:58', '0000-00-00 00:00:00', '2017-08-14 16:29:05', 'unchecked', 'n', 'n', '', '1', 'sctz2017081401/白雪712/生产通知单', '', '白雪三相表要求：\r\n\r\n1、采用双方验证过的程序版本TMF2-1B-16032201 2、修改过脉冲输出的阻抗。						\r\n3. 铭牌、MAC地址等需要镭雕在电表外壳上； 4. MAC地址铭牌的6位数字为该表表号的最后六位数字； 5. 表内时间为GMT+3#FE54` 6. 冬夏令时转换功能关闭； 7. 需要把面板上的表号设到电表内 8. 计量单元左边不需要铅封，只需右边打一个铅封。9、计量单元、显示单元都不需要贴合格证 10、三相表默认密码为777777。 11：内盒不需要贴条形码										\r\n										\r\n										\r\n', '2304', '2017-08-14 08:44:58', 'Energomera CJSC', '白雪', '白雪712', 'PO#E1712', '2017-09-15', '国际一部 INTL.Business Dept.1', '邱洁', '', '04', '生产通知单', '该项目结算方式为20%T/T-预付款，80%尾款将于发货前支付，20%预付款已收齐，同意生产。', '同意', '黄兰兰2017-08-14 14:17:02', '王维2017-08-14 12:52:34', '同意', '陶保荣2017-08-14 14:25:18', '', '', '', '', '同意', '丁富民2017-08-14 14:34:05', '王功勇2017-08-14 16:26:01', 'sctz2017081401', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('182', '{532F4540-84F9-4291-A97E-C8E91AB8CB9A}', '60', 'INHE-0066', '2017-08-14 09:33:38', '0000-00-00 00:00:00', '2017-08-17 08:13:46', 'unchecked', 'n', 'n', '', '1', 'sctz2017081402/白雪713/生产通知单', '', 'APC220-43-0B要求：\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\r\n3、用于电表上，带自动组网功能。              \r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43\"，主要用于区分开其他功能的无线通信模块。              \r\r\n5、电压源：3.5-5.5V              \r\r\n6、频率： 433.05-434.7 MHz           \r\r\n7、温度范围：-30-+80              \r\r\n8、外包装箱用纸贴上唛头：APC220-43\r\r\n9、出厂是发射功率设为10mW.\r\r\n\r\r\nAPC910M-43-B要求：\r\r\n1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。  \r\r\n2、安美通集抄无线射频通信模块。             \r\r\n3、电压：4.5-6V             \r\r\n4、频段：432-434MHz              \r\r\n5、SMA连接线必须装在电路板上。\r\r\n6、出厂时发射功率设为10mW.\r\r\n\r\r\n\r\r\nAPC220-43-2A要求：\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（天线需要焊在模块上，天线与模块平行焊。） 3、用于掌上电脑，点对点抄读功能，但不相互干扰。       \r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43-2\"，主要用于区分开其他功能的无线通信模块。       \r\r\n5、电压源：3.5-5.5V       \r\r\n6、频率：433,05 - 434,79 MHz       \r\r\n7、温度范围：-30-+80       \r\r\n8、外包装箱用纸贴上唛头：APC220-43-2\r\r\n9、出厂时发射功率设为10mW。 \r\r\n										\r\r\nUSB-APC220-43-0\r\n 1、供应商为安美通。  \r\n 2、外壳上只需贴USB-APC220-43-0，不需其它任何信息及Logo。\r\n 3、升级为V3.0版。\r\n\r\nUSB-APC220-43-2\r\n 1、供应商为安美通。   \r\n 2、外壳上只需贴USB-APC220-43-2，不需其它任何信息和Logo.  \r\n 3、需升级为V3.0版本。\r\n', '0', '2017-08-14 09:33:38', 'Energomera CJSC', '白雪', '白雪713', 'PO#E1713', '2017-08-31', '国际一部 INTL.Business Dept.1', '邱洁', '', '01', '生产通知单', '结算方式为20%T/T预付款，80%尾款将于发货前支付，已预收25%预付款，符合结算方式。', '同意', '黄兰兰2017-08-16 08:53:01', '王维2017-08-14 12:50:50', '同意', '陶保荣2017-08-16 09:13:03', '', '', '', '专用模块翻单，请江西工厂安排处理。', '同意', '丁富民2017-08-16 09:26:29', '王功勇2017-08-16 10:24:41', 'sctz2017081402', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('183', '{DCE9166C-E4EF-49D8-9F59-AEE631F91CB1}', '60', 'INHE-0088', '2017-08-16 08:45:59', '0000-00-00 00:00:00', '2017-08-17 16:19:39', 'unchecked', 'n', 'n', '', '1', 'sctz2017081601/ST20707/生产通知单', '', '产品图片请见附件，翻单，深圳快递出货', '0', '2017-08-16 08:45:59', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20707', 'INHESC2017071701', '2017-08-25', '国际一部 INTL.Business Dept.1', '余冬纯', '', '06', '生产通知单', '结算方式为全款TT，货款已全部收齐，同意生产。', '同意', '黄兰兰2017-08-17 08:48:40', '王维2017-08-17 08:46:09', '同意', '陶保荣2017-08-17 09:53:33', '', '', '', '', '同意', '丁富民2017-08-17 14:22:51', '王功勇2017-08-17 14:28:24', 'sctz2017081601', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('184', '{5869DDFD-1A10-43A6-B13F-B1606B37074A}', '60', 'INHE-0088', '2017-08-16 17:44:16', '0000-00-00 00:00:00', '2017-08-17 16:20:08', 'unchecked', 'n', 'n', '', '1', 'sctz2017081602/ST20615/生产通知单', '', 'ST20615-4,翻单ST20615-3', '64000', '2017-08-16 17:44:16', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20615', 'INHESC2016111601', '2017-09-22', '国际一部 INTL.Business Dept.1', '余冬纯', '', '02', '生产通知单', '该批次的信用证已收，10%的预付款已到账公司已收款，同意生产。', '同意', '黄兰兰2017-08-29 09:28:55', '王维2017-08-18 10:33:17', '同意', '陶保荣2017-08-29 10:25:37', '', '', '', '翻单生产，由江西工厂安排处理。', '同意', '丁富民2017-08-29 10:44:03', '王功勇2017-08-29 10:55:59', 'sctz2017081602', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('185', '{CC11A08B-0B9D-4054-9453-09569172353C}', '61', 'INHE-0381', '2017-08-17 22:54:03', '0000-00-00 00:00:00', '2017-08-21 07:44:36', 'unchecked', 'n', 'n', '', '1', 'sctz2017081701/CDN30/生产通知单', '', '', '7200', '2017-08-17 22:54:03', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN30', '17000980CA', '2017-09-24', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', 'lc未收到，王总在OA特批，标题——“CDN26、CDN27订单生产、发货、议付跟踪”中同意收到PO立即下单。', '同意。', '黄兰兰2017-08-18 14:40:13', '郭涛2017-08-18 10:40:49', '同意', '陶保荣2017-08-18 14:52:56', '', '', '', '', '同意', '丁富民2017-08-18 20:40:15', '王功勇2017-08-19 22:44:16', 'sctz2017081701', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('186', '{3BC462EE-26DE-4383-BA0A-E75E0F755089}', '61', 'INHE-0381', '2017-08-25 00:28:58', '0000-00-00 00:00:00', '2017-10-13 12:32:22', 'unchecked', 'n', 'n', '', '1', 'sctz2017082501/CDN31/生产通知单', '', '三相表为以前的翻单产品。', '8388', '2017-08-25 00:28:58', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN31', '17001118 CA', '2017-09-23', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '信用证已收，补流程，同意。', '同意\r\nCDN31已生产，此单为补单。', '黄兰兰2017-10-13 10:07:25', '盛燕2017-10-13 10:06:39', '同意', '陶保荣2017-10-13 10:28:44', '', '', '', '', '同意', '丁富民2017-10-13 11:14:00', '王功勇2017-10-13 12:20:49', 'sctz2017082501', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('187', '{647422B7-0B33-4729-978D-75886631FB2A}', '61', 'INHE-0434', '2017-08-28 13:23:42', '0000-00-00 00:00:00', '2017-08-29 10:43:40', 'unchecked', 'n', 'n', '', '1', 'sctz2017082801/JAL01/生产通知单', '', '1. JAL项目为AZL04项目翻单(IHM4000集中器)，但集中器的铭牌需要再次和客户确认，届时需公司提供铭牌设计文件；\r\r\r\n\r\r\r\n2. JAL项目全款已收到，请公司务必争取在9月10日前完成交付；\r\r\n\r\r\n3. JAL项目所需的集中器出货需要与AZL04项目集中器出货一致即银河提供集中器表箱、断路器等；', '0', '2017-08-28 13:23:42', 'LIBANGO HOLDINGS, INC.', 'JAL', 'JAL01', 'INHESC2017081301', '2017-09-10', '国际二部 INTL.Business Dept.2', '钟云林(Andy)', '', '06', '生产通知单', '货款已收齐，同意生产。交期紧张，需在9.10前完成交付', '集中器铭牌不做特殊设计，参照AZL04执行。', '黄兰兰2017-08-29 08:56:34', '郭涛2017-08-28 21:28:07', '同意', '陶保荣2017-08-29 09:04:52', '', '', '', '已经安排实验室余祥林请购，由采购资源部外部购买。', '同意', '丁富民2017-08-29 10:08:55', '王功勇2017-08-29 10:30:05', 'sctz2017082801', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('188', '{2C516E79-0D51-4F1B-982F-B73977BD351C}', '60', 'INHE-0088', '2017-08-28 15:15:31', '0000-00-00 00:00:00', '2017-09-11 09:37:35', 'unchecked', 'n', 'n', '', '1', 'sctz2017082802/ST20708/生产通知单', '', '翻单ST20605', '1000', '2017-08-28 15:15:31', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20708', 'INHESC2017082101', '2017-10-19', '国际一部 INTL.Business Dept.1', '余冬纯', '', '02', '生产通知单', '10%预付款已收齐到账，LC通知书已收，同意生产。', '同意', '黄兰兰2017-09-08 17:02:32', '王维2017-09-08 16:59:49', '同意', '陶保荣2017-09-11 08:42:22', '', '', '', '', '同意', '丁富民2017-09-11 08:47:13', '王功勇2017-09-11 09:05:20', 'sctz2017082802', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('190', '{A307EE8D-0857-4371-9A3C-A7EB14E255B8}', '60', 'INHE-0088', '2017-09-01 13:50:22', '0000-00-00 00:00:00', '2017-09-04 15:20:01', 'unchecked', 'n', 'n', '', '1', 'sctz2017090101/BPD701/生产通知单', '', '现场急需工具，申请从深圳实验室领出，一个包放5个红外头，节省包装节省运费，快递出货。', '0', '2017-09-01 13:50:22', 'Ideal Enterprise', 'BPD', 'BPD701', 'INHESC2017082801', '2017-09-04', '国际一部 INTL.Business Dept.1', '余冬纯', '', '06', '生产通知单', '结算方式为全款T/T预付，货款已收齐，同意生产', '同意', '黄兰兰2017-09-04 09:02:54', '王维2017-09-01 17:27:03', '同意', '陶保荣2017-09-04 09:14:39', '', '', '', '', '同意', '丁富民2017-09-04 10:32:57', '王功勇2017-09-04 10:54:46', 'sctz2017090101', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('191', '{1AFC016A-6129-4BD9-A7AD-26BC261CE9D0}', '61', 'INHE-0587', '2017-09-06 15:20:26', '0000-00-00 00:00:00', '2017-09-08 08:53:26', 'unchecked', 'n', 'n', '', '1', 'sctz2017090601/GA05/生产通知单', '', '两种规格表箱均带25A断路器，商标请见附件', '0', '2017-09-06 15:20:26', 'GVE Projects Limited', 'GA', 'GA05', 'INHESC2017083001', '2017-09-26', '国际二部 INTL.Business Dept.2', '陆飞雨', '', '05', '生产通知单', '货款已收齐，同意生产。', '同意。\r\n交期很紧张，需注意。', '黄兰兰2017-09-07 10:40:13', '盛燕2017-09-07 09:49:53', '同意', '陶保荣2017-09-07 11:27:00', '', '', '', '', '同意', '丁富民2017-09-07 11:38:41', '王功勇2017-09-08 08:50:42', 'sctz2017090601', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('192', '{0DA1EBB1-59E3-45FD-8918-7146D74413C1}', '61', 'INHE-0381', '2017-09-08 01:00:57', '0000-00-00 00:00:00', '2017-09-15 10:33:00', 'unchecked', 'n', 'n', '', '1', 'sctz2017090801/MD01/生产通知单', '', '1.发货前需要SGS验货。完成生产前10天需告知完成日期，以准备通知客户验货。\r\r\n2. 产品均为模块表不带模块。\r\r\n3. 欧洲客户对交期严谨，希望按时交货。\r\r\n4. FOB九江，交货到九江码头。\r\r\n5. 客户把预付款美金转到欧元账户被拒，目前在准备重新付款，预计9月11号收到款。', '33850', '2017-09-08 01:00:57', 'BCCT', 'MD01', 'MD01', 'INHE2017062201', '2017-10-31', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '第三方检验', '06', '生产通知单', '结算方式为30%合同金额生产前TT付款，70%尾款发货前TT付款	。30%的预付款已收，同意生产。', '1.预付款预计9月11日到账，合同已完成评审流程，待客户签字回传。已收到客户通过官方公司邮箱发送的未签字的PO，PO内容准确完整。已收到客户签字盖章确认的PI。\r\r\r\n2.此项目交期要求严格，为满足交期，建议收到预付款后马上启动生产，业务将跟催尽快签订合同。', '黄兰兰2017-09-13 15:32:02', '盛燕2017-09-08 09:31:17', '', '陶保荣2017-09-13 15:56:42', '', '', '', '项目研发负责人：王顺万', '同意', '丁富民2017-09-13 16:28:09', '王功勇2017-09-13 19:58:23', 'sctz2017090801', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('193', '{CC6F5175-13E2-4FA0-AA1A-BD20EACBF091}', '61', 'INHE-0625', '2017-09-08 09:06:04', '0000-00-00 00:00:00', '2017-09-14 22:07:02', 'unchecked', 'n', 'n', '', '1', 'sctz2017090803/ITL01/生产通知单', '', '1.工装夹具是和具体生产的表型对应的，但由于此次订单工装夹具及生产辅料待定，因此工装夹具及生产辅料此批暂不生产；\r\r\r\n2.包装以打托盘形式进行。具体唛头信息待客户确定后尽快给出#FE54`\r\r\n3.ITL01的工厂设备和工具清单均由客服杨总提供。', '0', '2017-09-08 09:06:04', 'Africarriers Ltd', 'ITL', 'ITL01', 'INHESC2017080601', '2017-10-18', '国际二部 INTL.Business Dept.2', '古丽', '', '04', '生产通知单', '同意变更，合同金额不影响。', '同意', '朱君宜2018-08-16 17:09:45', '郭涛2018-08-16 16:16:25', '同意', '陶保荣2018-08-16 17:18:15', '', '', '', '', '同意', '丁富民2018-08-16 18:37:19', '王功勇2018-08-17 10:12:00', 'sctz2017090803', '01', '', '', '', 'OK', '鲁慧珍2018-08-16 14:40:52', null, null, null, null, null);
