INSERT INTO `crs_tabledata719` VALUES ('195', '{94F9E4B9-02A2-4F97-9B7B-DC629122BB9B}', '61', 'INHE-0381', '2017-09-15 04:36:20', '0000-00-00 00:00:00', '2017-09-29 13:33:36', 'unchecked', 'n', 'n', '', '1', 'sctz2017091501/CDN32/生产通知单', '', '翻单产品。外箱嘪头需修改信息，order number：17001119CA ， ref : 17000193YS', '25344', '2017-09-15 04:36:20', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN32', '17001119 CA', '2017-10-31', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '王总OA特批同意该项目立即下单,OA标题为“CDN32备料”', '同意。\r\n已通过OA批准此项目立即下单。', '黄兰兰2017-09-26 15:13:32', '盛燕2017-09-26 15:02:03', '同意', '陶保荣2017-09-26 15:19:24', '', '', '', '', '同意', '丁富民2017-09-27 12:52:10', '王功勇2017-09-27 14:01:25', 'sctz2017091501', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('196', '{D526C9D5-73DD-4E03-B953-DB6B7D269748}', '60', 'INHE-0088', '2017-09-15 08:45:00', '0000-00-00 00:00:00', '2017-09-22 14:02:03', 'unchecked', 'n', 'n', '', '1', 'sctz2017091502/ST20705/生产通知单', '', '用于ST20维修中心电表维修物料及剥线机设备维修,已入账', '0', '2017-09-15 08:45:00', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20705', 'INHESC2017032802', '2017-10-14', '国际一部 INTL.Business Dept.1', '余冬纯', '', '06', '生产通知单', '该项目全款已收齐，同意生产。', '同意', '黄兰兰2017-09-22 09:20:38', '王维2017-09-22 08:45:38', '同意', '陶保荣2017-09-22 11:48:03', '', '', '', '', '同意', '丁富民2017-09-22 13:26:16', '王功勇2017-09-22 13:56:41', 'sctz2017091502', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('197', '{B06CFA26-2892-4BA1-A078-6E7FAA35C783}', '61', 'INHE-0654', '2017-09-20 17:42:53', '0000-00-00 00:00:00', '2017-09-22 14:01:43', 'unchecked', 'n', 'n', '', '1', 'sctz2017092003/PAS17-01/生产通知单', '', '1.附件为产品的基本参数规格，要求产品使用透明长端盖.                                             2.该交期要求45天，即11月03日从工厂发货，请抓紧时间安排生产.                                      3.此订单中1435台CT表，带有1435个GPRS通讯模块，根据客户需求请先采购100个GPRS通讯模块，先安排测试，单独包装100个模块，需先单独发货，其余1335台电表和模块安装在一起.                                 4.已收到客户的预付款，请批准生产.', '1435', '2017-09-20 17:42:53', 'MESSEN S.A.S', 'PSA17', 'PAS17-01', 'INHESC2017081601', '2017-11-03', '国际二部 INTL.Business Dept.2', '李明(Ming)', '', '04', '生产通知单', '结算方式为：50%生产前T/T预付款，50%发货前尾款。经与出纳确认：目前该客户预付70000美元。预付款未达到总金额的50%（合同总金额157850美元），不符合结算方式，业务员反馈本次少付的8925美元在下一次支付，本项目交期紧张，请领导审批。', '同意', '黄兰兰2017-09-21 16:25:59', '盛燕2017-09-21 14:10:39', '同意', '陶保荣2017-09-22 08:04:34', '', '', '', '三相四线多功能表（CT表）---王占颍', '同意。', '丁富民2017-09-22 08:46:10', '王功勇2017-09-22 13:56:05', 'sctz2017092003', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('198', '{7FD44944-4405-407B-B159-63B5D4BC5CD7}', '61', 'INHE-0587', '2017-09-21 15:28:13', '0000-00-00 00:00:00', '2017-09-22 14:05:43', 'unchecked', 'n', 'n', '', '1', 'sctz2017092101/KAM01/生产通知单', '', '1.已有3台样机走了样机申请流程，故生产通知单产品数量有变；\r\r\r\n2.交期紧急，请评估是否可用PY02/CDN和TAN产品修改。\r\n3.技术规格请见附件样机申请单。', '25', '2017-09-21 15:28:13', 'VBC Lda.', 'KAM', 'KAM01', 'INHESC2017091501', '2017-10-12', '国际二部 INTL.Business Dept.2', '陆飞雨', '', '06', '生产通知单', '货款已收齐，同意生产', '同意', '黄兰兰2017-09-22 10:04:44', '盛燕2017-09-21 17:58:37', '同意', '陶保荣2017-09-22 11:48:41', '', '', '', '', '同意。', '丁富民2017-09-22 13:25:50', '王功勇2017-09-22 13:55:41', 'sctz2017092101', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('199', '{75DE5527-1076-4306-B763-5759B6F118F9}', '60', 'INHE-0088', '2017-09-28 15:04:15', '0000-00-00 00:00:00', '2017-09-29 13:46:26', 'unchecked', 'n', 'n', '', '1', 'sctz2017092801/ST20615/生产通知单', '', '预计国庆期间内收到信用证，特批提前下单，保证交期。\r\r\r\n产品翻单ST20615-4批次生产，重要物料打托，电池五金等重物打木箱。', '64000', '2017-09-28 15:04:15', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20615', 'INHESC2016111601', '2017-10-18', '国际一部 INTL.Business Dept.1', '余冬纯', '', '04', '生产通知单', '信用证未收，王总特批下单，OA标题“ST20615-5生产物料备料申请”', '同意', '黄兰兰2017-09-29 08:54:32', '王维2017-09-28 17:29:14', '同意', '陶保荣2017-09-29 09:19:27', '', '', '', '', '同意', '丁富民2017-09-29 13:35:36', '王功勇2017-09-29 13:40:16', 'sctz2017092801', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('200', '{3ED78CE3-33BD-4D8A-8CBE-84C46F038C71}', '61', 'INHE-0625', '2017-10-10 13:44:06', '0000-00-00 00:00:00', '2017-10-11 13:27:57', 'unchecked', 'n', 'n', '', '1', 'sctz2017101001/ITL01/生产通知单', '', '', '0', '2017-10-10 13:44:06', 'Africarriers Ltd', 'ITL', 'ITL01', 'INHESC2017080601', '2017-10-31', '国际二部 INTL.Business Dept.2', '古丽', '', '04', '生产通知单', '结算方式：合同金额的45%在签订合同10天之内作为预付费T/T支付，55%通过不可撤销的保兑的远期60天信用证支付。预付款已收，同意。', '同意', '黄兰兰2017-10-10 17:13:56', '盛燕2017-10-10 15:09:15', '同意', '陶保荣2017-10-11 08:23:50', '', '同意。', '', '', '同意', '丁富民2017-10-11 08:54:37', '王功勇2017-10-11 13:16:31', 'sctz2017101001', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('201', '{69DEF4AD-ABBA-4950-BB9B-6A276F575720}', '61', 'INHE-0578', '2017-10-11 15:34:56', '0000-00-00 00:00:00', '2017-10-12 07:57:56', 'unchecked', 'n', 'n', '', '1', 'sctz2017101101/ESA09/生产通知单', '', '1. 此项目代号为ESA09；\r\n\r\n\r\n2. 此次订单在此前产品基础上增加了端盖，同时秘钥更改后SGC显示也要更改；具体生产要求与业务OA确认。', '40000', '2017-10-11 15:34:56', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'ESA', 'ESA09', 'INHESC2017092001', '2017-11-10', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '第三方检验', '02', '生产通知单', '该项目付款方式：生产前TT支付 USD275,500，发货前TT支付  USD142,000，提单日后90天内TT支付USD960,000。当前预付款USD275,500.00已收到，同意生产。', '同意', '黄兰兰2017-10-11 17:41:29', '郭涛2017-10-11 15:57:32', '同意', '陶保荣2017-10-11 17:44:54', '', '', '', '项目由章春鹏负责。需要增加端盖BOM表结构件有变动；功能上作修改，程序需要作变动。', '同意。', '丁富民2017-10-11 18:06:48', '王功勇2017-10-11 22:36:41', 'sctz2017101101', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('202', '{F9885F6A-8546-4DBE-9376-9A2F3ECA1327}', '60', 'INHE-0066', '2017-10-13 14:01:08', '0000-00-00 00:00:00', '2017-10-17 15:11:20', 'unchecked', 'n', 'n', '', '1', 'sctz2017101301/白云703/生产通知单', '', '白云客户在现场的三相测试台坏了，经客服、实验室及供应商验证，需要更换单相测试台的信号源主板和信号源通信板。', '0', '2017-10-13 14:01:08', '\"Aspan-Energy \" LTD', '白云', '白云703', 'INHESC2017062301', '2017-10-30', '国际一部 INTL.Business Dept.1', '邱洁', '', '04', '生产通知单', '结算方式为50%T/T-下单时支付，50%T/T-发货前付清，货款已收齐，同意生产。', '同意', '黄兰兰2017-10-17 08:55:54', '王维2017-10-16 18:52:58', '同意', '陶保荣2017-10-17 09:13:32', '', '', '', '', '同意', '丁富民2017-10-17 09:35:25', '王功勇2017-10-17 12:40:39', 'sctz2017101301', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('203', '{C316F6DE-42B1-46E9-923B-D6119C38033A}', '60', 'INHE-0066', '2017-10-17 16:00:19', '0000-00-00 00:00:00', '2017-10-19 14:34:14', 'unchecked', 'n', 'n', '', '1', 'sctz2017101701/白云702/生产通知单', '', '1、按2015年11月提供给客户的最近样机生产。（和602批次一样的出货，只是此次生产通知单没有按之前的整机下单，而是按散件下单。机芯和之前一样需要修调。）\r\r\n2、电表将分机芯（PCBA）、LCD显示板、铝面板、底壳、按键、五金件几大部分出货。\r\r\n3、双回路计量。\r\r\n4、能支持复费率和阶梯电价两种结算方式。（默认设置见随后提供的出厂设置单）\r\r\n5、带远程通断电功能。\r\r\n6、负荷门限设置。\r\r\n7、能承受电压异常的瞬间波动，电压异常时，电表自动断电，电压恢复正常时，电表自动恢复供电。\r\r\n8、能编程设置为后付费功能   \r\r\n\r\r\n										\r\r\n										\r\r\n										\r\r\n', '0', '2017-10-17 16:00:19', '\"Aspan-Energy \" LTD', '白云', '白云702', 'INHESC2017062001', '2017-11-10', '国际一部 INTL.Business Dept.1', '邱洁', '', '04', '生产通知单', '结算方式为：50%T/T-下单前支付，50%T/T尾款-发货前支付，该项目已收95300美元，超过合同总金额（159000美元）的50%，符合合同的结算方式，同意生产。', '同意', '黄兰兰2017-10-18 11:01:52', '王维2017-10-17 17:50:00', '同意', '陶保荣2017-10-18 11:04:30', '', '', '', '', '', '丁富民2017-10-18 20:36:37', '王功勇2017-10-19 10:04:44', 'sctz2017101701', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('204', '{CE0EA75D-39CF-4D69-A5C0-5B195E51B78B}', '60', 'INHE-0066', '2017-10-18 13:56:40', '0000-00-00 00:00:00', '2017-10-20 11:55:56', 'unchecked', 'n', 'n', '', '1', 'sctz2017101801/白云701/生产通知单', '', '其他特殊要求或者补充说明：\r\r\n\r\r\n1、低压载波集中器，上行GPRS通信，下行载波通信。   \r\r\n2、必须具备三相表计量功能。   \r\r\n3、出货时包装上不要显示集中器等字样，客户那边把集中器当三相表来进口，以减少海关不必要的麻烦。  \r\r\n4、面板上需显示型号为：  DJZ22-INHE10  \r\r\n', '0', '2017-10-18 13:56:40', '\"Aspan-Energy \" LTD', '白云', '白云701', 'INHESC2017052401', '2017-11-10', '国际一部 INTL.Business Dept.1', '邱洁', '第三方检验', '04', '生产通知单', '结算方式为50%T/T-于下单前支付，50%T/T于发货前支付，50%的预付款已收，同意生产。', '同意', '黄兰兰2017-10-19 08:39:18', '王维2017-10-19 08:17:50', '同意', '陶保荣2017-10-19 09:28:55', '', '', '', '', '同意，', '丁富民2017-10-20 07:17:52', '王功勇2017-10-20 09:47:37', 'sctz2017101801', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('205', '{FE89C49A-A118-48EF-BFBF-71398902C919}', '60', 'INHE-0066', '2017-10-23 11:38:02', '0000-00-00 00:00:00', '2017-10-24 16:46:18', 'unchecked', 'n', 'n', '', '1', 'sctz2017102301/白雪714/生产通知单', '', 'APC220-43-0B要求：\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\r\r\n3、用于电表上，带自动组网功能。              \r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43\"，主要用于区分开其他功能的无线通信模块。              \r\r\r\n5、电压源：3.5-5.5V              \r\r\r\n6、频率： 433.05-434.7 MHz           \r\r\r\n7、温度范围：-30-+80              \r\r\r\n8、外包装箱用纸贴上唛头：APC220-43\r\r\r\n9、出厂是发射功率设为10mW.\r\r\r\n\r\r\r\nAPC910M-43-B要求：\r\r\r\n1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。  \r\r\r\n2、安美通集抄无线射频通信模块。             \r\r\r\n3、电压：4.5-6V             \r\r\r\n4、频段：432-434MHz              \r\r\r\n5、SMA连接线必须装在电路板上。\r\r\r\n6、出厂时发射功率设为10mW.\r\r\r\n\r\r\r\n\r\r\r\nUSB-APC220-43-2\r\r\r\n 1、供应商为安美通。   \r\r\r\n 2、外壳上只需贴USB-APC220-43-2，不需其它任何信息和Logo.  \r\r\r\n 3、需升级为V3.0版本。\r\r\r\n										\r\r\r\n', '0', '2017-10-23 11:38:02', 'Energomera CJSC', '白雪', '白雪714', 'PO#E1714', '2017-10-31', '国际一部 INTL.Business Dept.1', '邱洁', '', '05', '生产通知单', '\r\r\r\n结算方式为：20%T/T-预付款，80%尾款-将于发货前支付。20%预付款已收，同意生产。		\r\r\r\n', '同意', '朱君宜2017-10-24 11:57:07', '王维2017-10-23 17:30:29', '同意', '陶保荣2017-10-24 13:53:36', '', '', '', '', '同意', '丁富民2017-10-24 13:59:07', '王功勇2017-10-24 16:10:04', 'sctz2017102301', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('206', '{E251BBD3-B5EF-4187-ADBA-D36707ECDC75}', '60', 'INHE-0066', '2017-10-23 17:09:38', '0000-00-00 00:00:00', '2017-10-24 16:43:51', 'unchecked', 'n', 'n', '', '1', 'sctz2017102302/白雪715/生产通知单', '', '1、采用双方验证过的程序版本TMF2-1B-16032201\r\n2、修改过脉冲输出的阻抗。						\r\n3. 铭牌、MAC地址等需要镭雕在电表外壳上； \r\n4. MAC地址铭牌的6位数字为该表表号的最后六位数字；\r\n5. 表内时间为GMT+3#FE54` \r\n6. 冬夏令时转换功能关闭； \r\n7. 需要把面板上的表号设到电表内 \r\n8. 计量单元不需要打铅封。\r\n9、计量单元、显示单元都不需要贴合格证 \r\n10、三相表默认密码为777777。 \r\n11：内盒不需要贴条形码\r\n12：计量单元和显示单元都取消易碎贴纸	\r\n', '6012', '2017-10-23 17:09:38', 'Energomera CJSC', '白雪', '白雪715', 'PO#E1715', '2017-10-11', '国际一部 INTL.Business Dept.1', '邱洁', '', '04', '生产通知单', '结算方式为15%T/T预付款，85%尾款将于发货前支付，已预收15%预付款，符合结算方式。			\r\r\n', '同意', '朱君宜2017-10-24 11:43:51', '王维2017-10-23 17:31:47', '同意', '陶保荣2017-10-24 13:54:33', '', '', '', '', '同意', '丁富民2017-10-24 13:58:45', '王功勇2017-10-24 16:06:18', 'sctz2017102302', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('207', '{37ABA0AC-A23C-4E2C-AF9A-938CF6E1A7F6}', '60', 'INHE-0066', '2017-10-25 16:13:09', '0000-00-00 00:00:00', '2017-10-27 14:30:34', 'unchecked', 'n', 'n', '', '1', 'sctz2017102501/白雪716/生产通知单', '', '注：526套采用一体包装（计量单元和显示单元包装在一起），9018套采用分开包装（计量单元和显示单元分开包装）。\r\n\r\n\r\n1、采用双方验证过的程序版本TMF2-1B-16032201\r\r\r\r\r\r\n2、修改过脉冲输出的阻抗。						\r\r\r\r\r\r\n3. 铭牌、MAC地址等需要镭雕在电表外壳上； \r\r\r\r\r\r\n4. MAC地址铭牌的6位数字为该表表号的最后六位数字；\r\r\r\r\r\r\n5. 表内时间为GMT+3#FE54` \r\r\r\r\r\r\n6. 冬夏令时转换功能关闭； \r\r\r\r\r\r\n7. 需要把面板上的表号设到电表内 \r\r\r\r\r\r\n8. 计量单元不需要打铅封。\r\r\r\r\r\r\n9、计量单元、显示单元都不需要贴合格证 \r\r\r\r\r\r\n10、三相表默认密码为777777。 \r\r\r\r\r\r\n11：内盒不需要贴条形码\r\r\r\r\r\r\n12：计量单元和显示单元都取消易碎贴纸	\r\r\r\r\r\r\n										\r\r\r\r\r\r\n', '19088', '2017-10-25 16:13:09', 'Energomera CJSC', '白雪', '白雪716', 'PO#E1716', '2017-10-20', '国际一部 INTL.Business Dept.1', '邱洁', '', '04', '生产通知单', '结算方式为15%T/T-预付款，85%尾款将于发货前收到。当前已收到15%预付款，符合结算方式，同意生产。		\r\r\n', '同意', '朱君宜2017-10-26 15:58:03', '王维2017-10-25 18:08:10', '同意', '陶保荣2017-10-27 08:36:35', '', '', '', '', '同意', '丁富民2017-10-27 08:38:43', '王功勇2017-10-27 14:18:03', 'sctz2017102501', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('208', '{C0E7B6C8-1C54-4F96-8D48-E605CC65C520}', '61', 'INHE-0578', '2017-10-27 10:20:26', '0000-00-00 00:00:00', '2017-10-27 14:30:24', 'unchecked', 'n', 'n', '', '1', 'sctz2017102701/ESA10/生产通知单', '', '1. 部分预付款目前有银行水单，预计下周一到账，申请凭水单下单生产（已发OA申请）；\r\r\r\r\r\n\r\r\r\r\r\n\r\r\r\r\r\n2. 交期十分紧急，需全面争取在11月23日从工厂发货；\r\r\r\n\r\r\r\n\r\r\r\n3. 具体生产要求在生产OA中确认。', '30000', '2017-10-27 10:20:26', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'ESA', 'ESA10', 'INHESC2017101701', '2017-11-23', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '第三方检验', '02', '生产通知单', '结算方式为：生产前20%T/T，发货前80%T/T。当前已收到20%预付款206900美元，同意生产。', '同意。预付款已全额到帐，可以下单。', '朱君宜2017-10-27 11:48:14', '盛燕2017-10-27 11:06:38', '同意', '陶保荣2017-10-27 13:37:42', '', '', '', '翻单生产。', '同意。', '丁富民2017-10-27 13:41:19', '王功勇2017-10-27 14:13:43', 'sctz2017102701', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('209', '{DBCDF5AF-70A6-4197-A226-8826F300B56C}', '61', 'INHE-0675', '2017-10-27 14:35:32', '0000-00-00 00:00:00', '2017-10-27 16:34:35', 'unchecked', 'n', 'n', '', '1', 'sctz2017102702/BFN07/生产通知单', '', '', '300', '2017-10-27 14:35:32', 'TOGO ASSISTANCE SERVICES', 'BFN', 'BFN07', 'INHESC2017102603', '2017-10-31', '国际二部 INTL.Business Dept.2', '李佳嘉', '', '04', '生产通知单', '付款方式为提单日后的30天内T/T支付100%的合同款项。发货后再收款，同意生产。', '同意\r\n请研发提供出厂设置单给业务确认', '朱君宜2017-10-27 15:54:15', '盛燕2017-10-27 15:34:15', '同意', '陶保荣2017-10-27 16:16:52', '', '', '', '', '同意。', '丁富民2017-10-27 16:18:30', '王功勇2017-10-27 16:31:07', 'sctz2017102702', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('210', '{DD159272-C86C-483A-BAC3-5EEFF1EAD333}', '61', 'INHE-0381', '2017-10-30 18:24:34', '0000-00-00 00:00:00', '2017-11-01 08:22:23', 'unchecked', 'n', 'n', '', '1', 'sctz2017103001/CDN33/生产通知单', '', '1. 出货2个大柜。\r\r\n2. 外箱唛头需要修改：order number:  17001120CA ref: 17000193YS', '25344', '2017-10-30 18:24:34', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN33', '17001120 CA', '2017-11-22', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '未收到预付款。王总已特批，同意生产。详见OA邮件“CDN33备料申请”。', '同意', '朱君宜2017-10-31 09:10:42', '盛燕2017-10-31 08:54:06', '同意', '陶保荣2017-10-31 09:26:44', '', '请紧密跟踪LC，希望尽早收到。', '', '翻单生产，建议由江西工厂安排处理。', '同意', '丁富民2017-10-31 15:40:33', '王功勇2017-11-01 00:20:36', 'sctz2017103001', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('211', '{51716B47-EC21-44B4-980E-0FC10D4E5463}', '60', 'INHE-0088', '2017-11-06 09:32:38', '0000-00-00 00:00:00', '2017-11-06 17:17:47', 'unchecked', 'n', 'n', '', '1', 'sctz2017110602/FU04/生产通知单', '', '参考FU02程序；MCU可无LCD。', '1000', '2017-11-06 09:32:38', 'UTILA POWER COMPANY LTD.', 'FU', 'FU04', 'INHESC2017103101', '2017-12-08', '国际一部 INTL.Business Dept.1', '余冬纯', '', '06', '生产通知单', '结算方式为全款TT预付。 当100%预付款已收到，符合合同规定，同意生产。', '同意', '朱君宜2017-11-06 15:51:34', '王维2017-11-06 15:38:55', '同意', '陶保荣2017-11-06 16:09:31', '', '', '', '', '同意。研发项目负责人章春鹏。', '丁富民2017-11-06 17:07:56', '王功勇2017-11-06 17:16:16', 'sctz2017110602', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('212', '{28F359D1-A1E9-4BDB-9137-41F24CC04CFC}', '66', 'INHE-0634', '2017-11-08 20:59:25', '0000-00-00 00:00:00', '2017-11-09 09:32:11', 'unchecked', 'n', 'n', '', '1', 'sctz2017110802/MOC01/生产通知单', '', '', '20', '2017-11-08 20:59:25', '达明（澳门）有限公司Dynamax (Macau) Limited', 'MOC', 'MOC01', 'PO-1711-1204R1', '2017-11-22', '国际三部 INTL.Business Dept.3', '陈雁', '', '05', '生产通知单', '结算方式：发货前100%T/T预付。目前100%TT预付款已收到，符合合同规定，同意生产。', '同意。\r\n请注意这款表箱能否装下这款电表。', '朱君宜2017-11-09 08:47:25', '宋宁2017-11-09 08:22:25', '同意', '陶保荣2017-11-09 08:51:59', '', '', '', '', '同意。按公司现有产品生产，请江西工厂安排。', '丁富民2017-11-09 09:28:08', '王功勇2017-11-09 09:30:05', 'sctz2017110802', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('213', '{599A4018-A1DD-4B4A-929E-3EF4DED35637}', '60', 'INHE-0066', '2017-11-14 13:34:46', '0000-00-00 00:00:00', '2017-11-14 15:21:09', 'unchecked', 'n', 'n', '', '1', 'sctz2017111401/白云704/生产通知单', '', '1、按2015年11月提供给客户的最近样机生产。（和602批次一样的出货，只是此次生产通知单没有按之前的整机下单，而是按散件下单。机芯和之前一样需要修调。）\r\r\r\r\n2、根据最新的报关要求，电表将分机芯（PCBA）、LCD显示板、铝面板、底壳、按键、五金件、磁卡、纸箱等几大部分出货。\r\r\r\r\n3、双回路计量。\r\r\r\r\n4、能支持复费率和阶梯电价两种结算方式。（默认设置见随后提供的出厂设置单）\r\r\r\r\n5、带远程通断电功能。\r\r\r\r\n6、负荷门限设置。\r\r\r\r\n7、能承受电压异常的瞬间波动，电压异常时，电表自动断电，电压恢复正常时，电表自动恢复供电。\r\r\r\r\n8、能编程设置为后付费功能   \r\r\r\r\n\r\r\r\r\n										\r\r\r\r\n										\r\r\r\r\n										\r\r\r\r\n										\r\r\r\r\n', '0', '2017-11-14 13:34:46', '\"Aspan-Energy \" LTD', '白云', '白云704', 'INHESC2017103002', '2017-11-30', '国际一部 INTL.Business Dept.1', '邱洁', '', '04', '生产通知单', '结算方式为：50%T/T-下单前支付，50%T/T尾款-发货前支付。    当前已收到 50% TT预付款，符合合同规定，同意生产。		\r\r\n', '同意', '朱君宜2017-11-14 13:54:51', '王维2017-11-14 13:47:54', '同意', '陶保荣2017-11-14 14:08:02', '', '', '', '翻单生产，请江西工厂安排处理。', '同意', '丁富民2017-11-14 14:30:35', '王功勇2017-11-14 15:15:53', 'sctz2017111401', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('214', '{762A58D0-4FBD-4DDA-B57F-4DE34A7876DB}', '60', 'INHE-0066', '2017-11-14 16:14:57', '0000-00-00 00:00:00', '2017-11-16 08:03:55', 'unchecked', 'n', 'n', '', '1', 'sctz2017111402/白雪718/生产通知单', '', 'APC220-43-0B要求：\r\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\r\r\r\r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\r\r\r\r\r\r\n3、用于电表上，带自动组网功能。              \r\r\r\r\r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43\"，主要用于区分开其他功能的无线通信模块。              \r\r\r\r\r\r\r\n5、电压源：3.5-5.5V              \r\r\r\r\r\r\r\n6、频率： 433.05-434.7 MHz           \r\r\r\r\r\r\r\n7、温度范围：-30-+80              \r\r\r\r\r\r\r\n8、外包装箱用纸贴上唛头：APC220-43\r\r\r\r\r\r\r\n9、出厂是发射功率设为10mW.\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\nAPC220-43-3B要求：\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\r\r\n2白雪项目专用安美通普通无线射频通信模块，不带嵌入式天线。（不需要把天线焊在模块上。）           \r\r\r\n3、用于电表上，带自动组网功能。           \r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43-3\"，主要用于区分开其他功能的无线通信模块。\r\r\r\n5、出厂时发射功率设为10mW.          \r\r\r\n6、电压源：3.5-5.5V           \r\r\r\n7、频率：433.05-434.7 MHz\r\r\r\n8、温度范围：-30-+80           \r\r\r\n9、外包装箱用纸贴上唛头：APC220-43\r\r\r\n\r\r\r\n\r\r\r\nAPC910M-43-B要求：\r\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。  \r\r\r\r\r\r\r\n2、安美通集抄无线射频通信模块。             \r\r\r\r\r\r\r\n3、电压：4.5-6V             \r\r\r\r\r\r\r\n4、频段：432-434MHz              \r\r\r\r\r\r\r\n5、SMA连接线必须装在电路板上。\r\r\r\r\r\r\r\n6、出厂时发射功率设为10mW.\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\nUSB-APC220-43-0\r\r\n 1、供应商为安美通。  \r\r\n 2、外壳上只需贴USB-APC220-43-0，不需其它任何信息及Logo。\r\r\n 3、升级为V3.0版。\r\r\n\r\r\n\r\r\r\r\r\nUSB-APC220-43-2\r\r\r\r\r\r\r\n 1、供应商为安美通。   \r\r\r\r\r\r\r\n 2、外壳上只需贴USB-APC220-43-2，不需其它任何信息和Logo.  \r\r\r\r\r\r\r\n 3、需升级为V3.0版本。\r\r\r\r\r\r\r\n										\r\r\r\r\r\r\r\n										\r\r\r\r\r\r\r\n', '0', '2017-11-14 16:14:57', 'Energomera CJSC', '白雪', '白雪718', 'PO#E1718', '2017-11-29', '国际一部 INTL.Business Dept.1', '邱洁', '', '05', '生产通知单', '结算方式为20%TT预付款，80%TT尾款支付。目前已收到20%TT预付款，符合合同规定，同意生产。		\r\n', '同意', '朱君宜2017-11-14 19:06:15', '王维2017-11-14 16:58:41', '同意', '陶保荣2017-11-14 20:40:14', '', '', '', '', '同意', '丁富民2017-11-15 10:22:23', '王功勇2017-11-15 10:32:21', 'sctz2017111402', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('215', '{EECB239C-7E6E-4586-8944-E4B25C7C5954}', '60', 'INHE-0066', '2017-11-14 16:19:35', '0000-00-00 00:00:00', '2017-11-16 08:03:32', 'unchecked', 'n', 'n', '', '1', 'sctz2017111403/白雪717/生产通知单', '', '铭牌具体设计见附件图纸红色圈注。', '0', '2017-11-14 16:19:35', 'Energomera CJSC', '白雪', '白雪717', 'PO#E1717', '2017-11-20', '国际一部 INTL.Business Dept.1', '邱洁', '', '05', '生产通知单', '结算方式为100%TT下单前支付。当前100%TT预付款已收，符合合同规定，同意生产。', '同意', '朱君宜2017-11-14 19:00:56', '王维2017-11-14 16:59:34', '同意', '陶保荣2017-11-14 20:38:52', '', '', '', '翻单生产，请江西工厂安排处理。', '同意', '丁富民2017-11-15 10:21:50', '王功勇2017-11-15 10:31:58', 'sctz2017111403', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('217', '{BB35E7F5-B118-4F23-AB67-275FD5EFEE9F}', '66', 'INHE-0604', '2017-11-22 15:17:04', '0000-00-00 00:00:00', '2017-11-23 17:31:25', 'unchecked', 'n', 'n', '', '1', 'sctz2017112211/PAZ01/生产通知单', '', '1.包装应该符合空运运输环境 2.中标项目，遵循交期', '34', '2017-11-22 15:17:04', 'INSERTEC LTDA', 'PAZ', 'PAZ01', 'INHESC2017112001', '2017-12-10', '国际三部 INTL.Business Dept.3', '王晓娜', '', '05', '生产通知单', '付款方式：4880USD （货款） T/T 预付，700USD(快递费）到账发货。当前已收到货款4880美元，同意生产。', '同意。', '朱君宜2017-11-23 14:54:25', '宋宁2017-11-23 14:38:29', '同意', '陶保荣2017-11-23 15:27:45', '', '', '', '', '同意', '丁富民2017-11-23 15:44:00', '王功勇2017-11-23 16:01:52', 'sctz2017112211', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('218', '{D7628BF0-D7B3-46C1-ABD2-DB1D7C1CD626}', '61', 'INHE-0662', '2017-11-23 10:52:18', '0000-00-00 00:00:00', '2017-11-23 17:31:32', 'unchecked', 'n', 'n', '', '1', 'sctz2017112301/IOT02/生产通知单', 'IOT02', '1. 单三相直通表为IOT01翻单产品，DIN表和采集器为银河标准规格产品。\r\n2. DIN表为RS485通信，采集器为RS485通信，上行3G通信。型号为DIN3.', '105', '2017-11-23 10:52:18', 'IOTSEG Pte Ltd', 'IOT', 'IOT02', 'INHESC2017111701', '2018-01-16', '国际二部 INTL.Business Dept.2', '陈丽', '', '04', '生产通知单', '结算方式为：生产前T/T全款。当前已收到T/T全款，同意生产。', '同意', '朱君宜2017-11-23 13:54:51', '盛燕2017-11-23 13:35:11', '同意', '陶保荣2017-11-23 15:28:05', '', '', '', '', '同意', '丁富民2017-11-23 15:42:46', '王功勇2017-11-23 16:01:33', 'sctz2017112301', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('219', '{EA37B541-46DF-42C6-9B13-5E800F2114DA}', '61', 'INHE-0578', '2017-11-28 09:29:10', '0000-00-00 00:00:00', '2017-12-08 14:29:42', 'unchecked', 'n', 'n', '', '1', 'sctz2017112801/ESA11/生产通知单', '', '1. 此项目代号ESA11#FE54`\r\r\n\r\r\n\r\r\n2. 预付款在11月27日已到建行，但因公司名称错误，待收到修改函后入账，申请先下单生产。\r\n\r\n\r\n3. 4万套成品中，要求1万套出厂设置负荷门限13.8kW,余下3万套设置为4.6kW。', '50000', '2017-11-28 09:29:10', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'ESA', 'ESA11', 'INHESC2017111302', '2017-12-27', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '第三方检验', '02', '生产通知单', '结算方式：生产前TT支付340,892.28 USD，发货前TT支付1,379,107.72 USD，当前预付款	340,892.28 USD已到账，同意生产，谢谢！	\r\n		\r\n', '同意', '朱君宜2017-12-08 11:03:07', '盛燕2017-11-28 09:59:43', '同意', '陶保荣2017-12-08 11:54:34', '', '', '', '翻单生产，请江西工厂安排。', '同意', '丁富民2017-12-08 14:24:06', '王功勇2017-12-08 14:26:30', 'sctz2017112801', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('220', '{9F3BC911-BE91-43EC-8BDB-15F81BD2A12A}', '61', 'INHE-0587', '2017-11-30 14:05:26', '0000-00-00 00:00:00', '2017-12-01 14:20:38', 'unchecked', 'n', 'n', '', '1', 'sctz2017113001/KAM02/生产通知单', '', '', '20000', '2017-11-30 14:05:26', 'VBC Lda.', 'KAM', 'KAM02', 'INHESC2017111501', null, '国际二部 INTL.Business Dept.2', '陆飞雨', '', '05', '生产通知单', 'KAM02结算方式为：50%全款TT预付，发货前TT付剩下50%；目前已收到50%预付款，同意生产。		\r\n', '同意。50%预付款已到帐，请财务查实。一旦收到另一个50%款项，则需立即发货，否则每日0.1%罚款。合同规定交货时间较紧：收预付款后23天发货（余款50%收款日期不确定，所以需要马上启动生产。）', '朱君宜2017-11-30 17:14:37', '宋宁2017-11-30 16:28:36', '同意', '陶保荣2017-11-30 20:02:31', '', '请研发、生产优先处理KMA02订单，保证交期。', '', 'PLC载波测通信表计（类似PY02项目）---章春鹏项目组；RF无线通信表计（类似CDN16项目）---王顺万项目组', '同意。', '丁富民2017-12-01 09:30:39', '王功勇2017-12-01 13:59:43', 'sctz2017113001', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('221', '{E619717C-0D55-4057-A893-4F713C753DCB}', '60', 'INHE-0088', '2017-12-12 17:01:46', '0000-00-00 00:00:00', '2017-12-13 13:53:59', 'unchecked', 'n', 'n', '', '1', 'sctz2017121201/ST20710/生产通知单', '', '\rST20项目新产品方案试生产免费试点订单：\r\r\r\r\r\r\r\r\r\r\n其中14台表请安装在DIN表箱内\r\r\r\r\r\r\r\r\r\r\n1. 2个单表位表箱 (2台DIN MCU)\r\r\r\r\r\r\r\r\r\r\r\r\n2. 2个两表位表箱 (4台DIN MCU)\r\r\r\r\r\r\r\r\r\r\r\r\n3. 2个四表位表箱（8台DIN MCU）\r\r\r\r\r\r\r\r\r\r\n整表产品出货，请审批。', '100', '2017-12-12 17:01:46', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20710', 'INHESC2017092801', '2018-01-12', '国际一部 INTL.Business Dept.1', '余冬纯', '', '06', '生产通知单', '同意。 此次生产的100台电表为ST20项目新产品方案试生产免费试点订单，无预付款。详见OA邮件“ST20项目新方案样机申请”。', '同意', '朱君宜2017-12-13 09:16:54', '王维2017-12-12 18:10:12', '同意', '陶保荣2017-12-13 09:33:37', '', '', '', '新产品，研发负责人章春鹏。', '同意', '丁富民2017-12-13 09:55:12', '王功勇2017-12-13 13:49:43', 'sctz2017121201', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('222', '{383BDFAD-0226-4D63-AC09-5A6D7DCC7D2B}', '61', 'INHE-0645', '2017-12-14 02:40:53', '0000-00-00 00:00:00', '2017-12-18 09:06:44', 'unchecked', 'n', 'n', '', '1', 'sctz2017121402/BN11/生产通知单', '', '1.这批货使用TN11的单相表库存返工，更改SGC码和铭牌，需要重新制作磁卡，以及更改一些设置参数（额定电压，\r\r负荷门限、过压门限、欠压门限，秘钥 等等），具体请见附件中的BN11BS安装单相二线一体式代码智能电表生产设置文件。\r\r\r\r\n2.接受外箱唛头贴纸修改，以节约时间，降低成本。\r\r\r\n3.该批货物的运输方式为空运。\r\r\n', '5000', '2017-12-14 02:40:53', 'Société Générale d\'Electronique', 'BN11', 'BN11', 'INHESC2017110601', '2017-12-20', '国际二部 INTL.Business Dept.2', '朱偲赵燚', '', '04', '生产通知单', '结算方式为：20%预付款-生产前，80%尾款-LC信用证发货前。目前已收到20%预付款，同意生产。', '同意\r\r\r\r\r\n1.BN11合同为5000台单相表空运+9500台单相表海运。使用TN11的14500台单相表返工修改后发货，TN11订单取消，请单独OA说明此事。\r\r\r\n2.此次下单仅为5000台需空运的电表，客户需求紧急，已安排付款，交期要求为收到全款后14天发货。9500台待收到20%预付款后再下单，正在跟催预付款，收到预付款后再下单。', '朱君宜2017-12-15 16:02:44', '盛燕2017-12-14 09:52:47', '同意', '陶保荣2017-12-15 16:56:36', '', 'TN11为何取消？是否造成损失？请单独OA说明。', '', '', '同意。', '丁富民2017-12-15 17:50:56', '王功勇2017-12-15 20:12:29', 'sctz2017121402', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('223', '{130765C9-5ADA-49E5-8DF0-6289490B29C4}', '61', 'INHE-0642', '2017-12-15 02:45:13', '0000-00-00 00:00:00', '2017-12-18 09:13:24', 'unchecked', 'n', 'n', '', '1', 'sctz2017121501/JAC01/生产通知单', '', '', '1000', '2017-12-15 02:45:13', 'Dovetail Energy, Inc.', 'JAC', 'JAC01', 'INHESC2017110901 ', '2018-01-12', '国际二部 INTL.Business Dept.2', '潘正豪(James)', '', '04', '生产通知单', '结算方式：签订合同10天内T/T支付100%的合同款项	。当前已收100%预付款，同意生产。	\r\n', '同意。', '朱君宜2017-12-15 10:06:07', '盛燕2017-12-15 09:36:15', '同意', '陶保荣2017-12-15 10:34:18', '', '', '', '要求实现集中抄表。', '同意。', '丁富民2017-12-15 13:30:03', '王功勇2017-12-15 20:08:03', 'sctz2017121501', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('224', '{3C6DD944-9296-4A59-BA8A-101C6D246388}', '61', 'INHE-0612', '2017-12-15 11:27:51', '0000-00-00 00:00:00', '2017-12-18 15:39:26', 'unchecked', 'n', 'n', '', '1', 'sctz2017121502/ADC01/生产通知单', '', '1. 电表铭牌的生产需等客户确认后在生产通知的OA中发出。\r\r\r\r\r\n2. 电表的软件版本号17052603\r\r\r，配短端子盖，继电器为120A，内置一个PLC通讯模块。\r\r\n3. 预付费：密钥为999937\r\r\r\r\r\n4. CIP插头为IRAM认证的H03VVH2-F插头，且为ADC项目安规版本的可更换电池CIU。', '500', '2017-12-15 11:27:51', 'Cashpower Sudamericana S.A.', 'ADC', 'ADC01', 'INHESC2017112702', '2018-01-20', '国际二部 INTL.Business Dept.2', '陈晨', '', '', '生产通知单', '结算方式：预付款100%TT，当前已收到预付款，同意生产。', '同意', '朱君宜2018-04-17 10:47:08', '郭涛2018-04-17 10:07:03', '同意', '陶保荣2018-04-19 16:34:57', '', '', '', '', '同意', '丁富民2018-04-19 17:05:53', '王功勇2018-04-19 18:52:22', 'sctz2017121502', '01', '', '', '', 'OK', '鲁慧珍2018-04-16 17:28:30', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('225', '{153D432C-3EAC-4CF6-8EA7-50562D8DF90A}', '61', 'INHE-0381', '2017-12-19 01:06:39', '0000-00-00 00:00:00', '2017-12-21 13:45:54', 'unchecked', 'n', 'n', '', '1', 'sctz2017121901/ING01/生产通知单', '', '\"1. 出货2个大柜。\r\r\n2. 外箱唛头需要修改：order number:  17001655CA ref: 17000370YS\"				', '25344', '2017-12-19 01:06:39', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING01', '17001655 CA', '2018-01-04', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式：100%LC,60天远期，收到LC正本才发货。同意生产，暂未收到信用证。', '同意', '朱君宜2017-12-21 09:04:26', '盛燕2017-12-19 09:03:06', '同意', '陶保荣2017-12-21 09:15:48', '', '交期紧张，同意先下单，请业务紧跟LC。', '', '翻单生产，请江西工厂安排处理。', '同意', '丁富民2017-12-21 10:12:59', '王功勇2017-12-21 10:29:20', 'sctz2017121901', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('226', '{27BE14FD-EFDC-467C-87A0-0FAD8F1DE430}', '61', 'INHE-0381', '2017-12-25 06:18:35', '0000-00-00 00:00:00', '2017-12-25 16:17:02', 'unchecked', 'n', 'n', '', '1', 'sctz2017122501/ING02/生产通知单', '', '1. 出货2个大柜。\r\r\n2. 外箱唛头需要修改：order number:  17001657CA ref: 17000370YS', '25344', '2017-12-25 06:18:35', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING02', '17001657 CA', '2018-02-02', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '同意。结算方式为100%LC，60天远期，当前已收到信用证。同意生产。	\r\n', '同意', '朱君宜2017-12-25 09:42:25', '盛燕2017-12-25 09:09:23', '同意', '陶保荣2017-12-25 10:22:51', '', '', '', '翻单生产，请江西工厂安排。', '同意', '丁富民2017-12-25 13:29:26', '王功勇2017-12-25 14:03:16', 'sctz2017122501', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('227', '{027BC00A-2D94-46A0-8CBF-84A833C066F8}', '61', 'INHE-0636', '2017-12-26 19:18:04', '0000-00-00 00:00:00', '2017-12-27 11:14:19', 'unchecked', 'n', 'n', '', '1', 'sctz2017122601/UW04/生产通知单', '', '1.UW04已经完成合同评审流程，客户已经签回附件1（技术规格-同UW02现有库存）。', '20', '2017-12-26 19:18:04', 'Delta Electricals Limited', 'UW', 'UW04', 'INHESC2017121301', '2018-01-15', '国际二部 INTL.Business Dept.2', '倪明杰', '', '06', '生产通知单', '结算方式为合同签订10天内，T/T支付100%合同款项。当前已收到全款，同意生产。		\r\n', '同意', '朱君宜2017-12-27 09:05:19', '盛燕2017-12-27 08:51:58', '同意，如有库存直接出货，如没有库存样机20台生产无法安排。', '陶保荣2017-12-27 09:18:21', '', '没有同意立项！', '', '翻单生产，请江西工厂处理。但数量太少，不值得安排专门生产处理。', '同意', '丁富民2017-12-27 09:38:05', '王功勇2017-12-27 09:53:44', 'sctz2017122601', '02', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('228', '{52032333-F0ED-4629-BF79-4CFD277DA72E}', '60', 'INHE-0066', '2017-12-28 09:16:08', '0000-00-00 00:00:00', '2017-12-28 13:50:37', 'unchecked', 'n', 'n', '', '1', 'sctz2017122801/白雪719/生产通知单', '', 'APC220-43-0B要求：\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。  \r\r\r\r\r\r\n2、白雪项目专用安美通普通无线射频通信模块，带嵌入式天线。（需要把天线焊在模块上，天线与模块平行焊。）              \r\r\r\r\r\r\n3、用于电表上，带自动组网功能。              \r\r\r\r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43\"，主要用于区分开其他功能的无线通信模块。              \r\r\r\r\r\r\n5、电压源：3.5-5.5V              \r\r\r\r\r\r\n6、频率： 433.05-434.7 MHz           \r\r\r\r\r\r\n7、温度范围：-30-+80              \r\r\r\r\r\r\n8、外包装箱用纸贴上唛头：APC220-43\r\r\r\r\r\r\n9、出厂是发射功率设为10mW.\r\r\r\r\r\r\n\r\r\r\r\r\r\nAPC220-43-3B要求：\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户三方确认的V3.0版程序。\r\r\r\r\r\r\n2白雪项目专用安美通普通无线射频通信模块，不带嵌入式天线。（不需要把天线焊在模块上。）           \r\r\r\r\r\r\n3、用于电表上，带自动组网功能。           \r\r\r\r\r\r\n4、电路板上的型号印APC220，但每一个模块上需贴上标签\"APC220-43-3\"，主要用于区分开其他功能的无线通信模块。\r\r\r\r\r\r\n5、出厂时发射功率设为10mW.          \r\r\r\r\r\r\n6、电压源：3.5-5.5V           \r\r\r\r\r\r\n7、频率：433.05-434.7 MHz\r\r\r\r\r\r\n8、温度范围：-30-+80           \r\r\r\r\r\r\n9、外包装箱用纸贴上唛头：APC220-43\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\nAPC910M-43-B要求：\r\r\r\r\r\r\n1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。  \r\r\r\r\r\r\n2、安美通集抄无线射频通信模块。             \r\r\r\r\r\r\n3、电压：4.5-6V             \r\r\r\r\r\r\n4、频段：432-434MHz              \r\r\r\r\r\r\n5、SMA连接线必须装在电路板上。\r\r\r\r\r\r\n6、出厂时发射功率设为10mW.\r\r\r\r\r\r\n7、不带天线', '0', '2017-12-28 09:16:08', 'Energomera CJSC', '白雪', '白雪719', 'PO#E1719', '2018-01-10', '国际一部 INTL.Business Dept.1', '邱洁', '', '05', '生产通知单', '同意。\r\r\n结算方式为14482.6USD-下单时支付85994.7USD，1月10日发第一批货前支付，2971.7USD-第二批货发货前10天支付。当前已收到预付款USD14482.6美元，同意生产。			\r\r\n		\r\r\n', '同意', '朱君宜2017-12-28 11:07:53', '王维2017-12-28 10:58:07', '同意', '陶保荣2017-12-28 11:14:18', '', '', '', '', '同意', '丁富民2017-12-28 11:23:56', '王功勇2017-12-28 13:46:59', 'sctz2017122801', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('229', '{BC4420F8-ABFA-4112-8165-66B755992390}', '60', 'INHE-0066', '2018-01-08 10:09:31', '0000-00-00 00:00:00', '2018-03-29 14:59:24', 'unchecked', 'n', 'n', '', '1', 'sctz2018010801/白云705/生产通知单', '', '1、按2015年11月提供给客户的最近样机生产。（和602批次一样的出货，只是此次生产通知单没有按之前的整机下单，而是按散件下单。机芯和之前一样需要修调。）\r\r\n2、根据最新的报关要求，电表将分机芯（PCBA）、LCD显示板、铝面板、底壳、按键、五金件、磁卡、纸箱等几大部分出货。\r\r\n3、双回路计量。\r\r\n4、能支持复费率和阶梯电价两种结算方式。（默认设置见随后提供的出厂设置单）\r\r\n5、带远程通断电功能。\r\r\n6、负荷门限设置。\r\r\n7、能承受电压异常的瞬间波动，电压异常时，电表自动断电，电压恢复正常时，电表自动恢复供电。\r\r\n8、工厂出厂时直接编程设置为后付费模式，并激活继电器。 \r\r\n\r\r\n										\r\r\n										\r\r\n										\r\r\n										\r\r\n										\r\r\n', '0', '2018-01-08 10:09:31', '\"Aspan-Energy \" LTD', '白云', '白云705', 'INHESC2017110301', '2018-04-27', '国际一部 INTL.Business Dept.1', '邱洁', '', '04', '生产通知单', '结算方式为：50%T/T-下单前支付，50%T/T尾款-发货前支付。		\r\n当前已收到50%TT预付款，同意生产。', '同意', '朱君宜2018-03-28 14:23:59', '王维2018-03-28 12:28:18', '同意', '陶保荣2018-03-28 14:52:05', '', '', '', '翻单生产，请江西工厂安排处理。', '同意。', '丁富民2018-03-28 15:16:01', '王功勇2018-03-29 09:22:17', 'sctz2018010801', '01', '', '', '', '50%预付款已收齐，可以下单。', '鲁慧珍2018-03-27 13:45:01', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('230', '{B0092CAB-B1B0-4F26-9ED1-5E4F79241670}', '61', 'INHE-0500', '2018-01-09 08:39:59', '0000-00-00 00:00:00', '2018-01-10 16:58:38', 'unchecked', 'n', 'n', '', '1', 'sctz2018010901/BAP04/生产通知单', '', '1.BAP04的技术规格请参照BAP03的对应表型出厂设置文件', '250', '2018-01-09 08:39:59', 'FactorFast (PTY) Ltd', 'BAP', 'BAP04', 'INHESC2017122801', '2018-02-06', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '06', '生产通知单', '结算方式为：20% T/T预付款，80%余款发货前T/T。 20%TT预付款已收，同意生产。		\r\n', '同意', '朱君宜2018-01-09 13:46:17', '郭涛2018-01-09 13:38:14', '同意', '陶保荣2018-01-09 17:36:19', '', '', '', '翻单生产，请江西工厂安排处理。若有不确认问题请找项目负责人王顺万。', '同意', '丁富民2018-01-09 17:51:09', '王功勇2018-01-10 14:53:52', 'sctz2018010901', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('231', '{B20EBE61-B060-4AB4-82F6-849EFAE75F39}', '61', 'INHE-0578', '2018-01-10 09:55:11', '0000-00-00 00:00:00', '2018-01-11 08:33:38', 'unchecked', 'n', 'n', '', '1', 'sctz2018011001/ESA12/生产通知单', '', '1. 项目代号ESA12。1万套散件需配备足够数量的打包带（另行OA申请）\r\r。\r\r\n\r\r\r\r\n\r\r\r\r\n2. 预付款已全部收齐（12.5万+21.9万）\r\r。\r\r\n\r\r\r\r\n\r\r\r\r\n3. 需注意交期，春节前需安排发货。', '50000', '2018-01-10 09:55:11', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'ESA', 'ESA12', 'INHESC2017121201', '2018-01-30', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '第三方检验', '02', '生产通知单', '结算方式为：生产前TT支付344,000.00 USD；发货前TT支付416,000.00 USD；提单日后90天内，TT支付960,000.00 USD.	当前已收到预付款344000美元，同意生产。	\r\n', '同意；请工厂评估，注意交期（备料已经提前申请）。', '朱君宜2018-01-10 13:53:18', '郭涛2018-01-10 11:01:01', '同意', '陶保荣2018-01-10 14:56:22', '', '', '', '翻单生产，请江西工厂处理。', '同意。', '丁富民2018-01-10 16:55:10', '王功勇2018-01-10 19:06:07', 'sctz2018011001', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('232', '{638CFF90-B3EF-47B8-A0F0-F3D5D4953E31}', '61', 'INHE-0645', '2018-01-16 04:27:36', '0000-00-00 00:00:00', '2018-01-16 17:54:26', 'unchecked', 'n', 'n', '', '1', 'sctz2018011601/BN11/生产通知单', '', '1.电表技术要求和其它要求跟第一批5000台一致。\r\r\n2.客户已经将此批9500台50%预付款支付，附件为swift。\r\r\n3.该批货物的运输方式为海运。', '9500', '2018-01-16 04:27:36', 'Société Générale d\"Electronique', 'BN', 'BN11', 'INHESC2017110601', '2018-01-27', '国际二部 INTL.Business Dept.2', '朱偲赵燚', '', '04', '生产通知单', '结算方式：20%预付款-生产前，80%尾款-发货前。             当前收到付款水单上金额=9500台50%预付款 + 第一批5000台追加的空运费的一半 （另一半和9500台余款一起支付），同意生产9500台电表。 					\r\r\n', '同意。\r\r\r\n付款水单上金额=9500台50%预付款 + 第一批5000台追加的空运费的一半 （另一半和9500台余款一起支付） ', '朱君宜2018-01-16 10:05:32', '盛燕2018-01-16 09:46:59', '同意，', '陶保荣2018-01-16 10:49:16', '', '', '', '翻单生产（2017年12月曾经生产过），请江西工厂处理。', '同意', '丁富民2018-01-16 16:35:06', '王功勇2018-01-16 17:48:15', 'sctz2018011601', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('233', '{A05B9F26-0147-40D5-A87A-9CFF5A8ACE6D}', '61', 'INHE-0587', '2018-01-16 09:05:08', '0000-00-00 00:00:00', '2018-01-17 10:06:50', 'unchecked', 'n', 'n', '', '1', 'sctz2018011604/EAR01/生产通知单', '', '需安排工程部到供应商处验货；', '0', '2018-01-16 09:05:08', 'RAYMAN PLC', 'EAR', 'EAR01', 'INHESC2017121202', '2018-02-24', '国际二部 INTL.Business Dept.2', '陆飞雨', '第三方检验', '06', '生产通知单', '当前收到合同抵押金，暂未收到LC正本。但王总已特批，详见OA邮件“EAR01项目合作抵押金情况说明-20180116”，同意生产。', '同意', '朱君宜2018-01-30 09:37:17', '郭涛2018-01-29 23:24:33', '同意', '陶保荣2018-01-30 13:53:22', '', '', '', '生产设备，请客户服务部与江西工厂工程部安排处理。', '同意', '丁富民2018-01-30 13:55:40', '王功勇2018-01-30 13:58:12', 'sctz2018011604', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('234', '{88C3A8E2-5FC1-4D24-A568-C15FD8A47B15}', '60', 'INHE-0088', '2018-01-16 20:57:12', '0000-00-00 00:00:00', '2018-01-22 14:33:29', 'unchecked', 'n', 'n', '', '1', 'sctz2018011605/JES09/生产通知单', '', '参考订单JES07,JES08，交客户指定深圳空运货代出货，须提供测试报告给客户，请知悉。', '256', '2018-01-16 20:57:12', 'JES Instrumentation * Controls', 'JES', 'JES09', 'INHESC2017122401', '2018-02-06', '国际一部 INTL.Business Dept.1', '余冬纯', '', '06', '生产通知单', '结算方式：100%的合同款项在产品生产之前T/T支付。当前已收到100%预付款，同意生产。', '同意', '朱君宜2018-01-20 17:56:08', '王维2018-01-20 12:57:37', '同意', '陶保荣2018-01-22 09:10:52', '', '', '', 'JES项目曾经生产供货，请江西工厂根据过去生产供货产品安排处理。', '同意', '丁富民2018-01-22 13:46:01', '王功勇2018-01-22 14:12:18', 'sctz2018011605', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('235', '{75233C70-D06E-4461-8700-83FD6A12E245}', '61', 'INHE-0381', '2018-01-17 04:21:00', '0000-00-00 00:00:00', '2018-01-18 09:53:42', 'unchecked', 'n', 'n', '', '1', 'sctz2018011701/ING03/生产通知单', '', '1. 出货2个大柜。\r\r\r\n2. 外箱唛头需要修改：order number:17001658CA ref: 17000370YS', '25344', '2018-01-17 04:21:00', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING03', '17001658 CA', '2018-03-06', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式：100%LC，60天远期。当前已收到LC正本，	同意生产。	\r\r\n', '同意', '朱君宜2018-01-17 14:42:31', '郭涛2018-01-17 14:17:27', '同意', '陶保荣2018-01-17 15:04:51', '', '', '', '翻单生产，请江西工厂安排处理。', '同意', '丁富民2018-01-18 08:57:30', '王功勇2018-01-18 09:29:38', 'sctz2018011701', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('236', '{EE6C76CD-6CF7-4068-80DC-7CA2671B91BE}', '60', 'INHE-0088', '2018-01-19 01:53:00', '0000-00-00 00:00:00', '2018-01-19 17:05:52', 'unchecked', 'n', 'n', '', '1', 'sctz2018011901/ST20710/生产通知单', '', '参考ST20615-5#FE54`\r\r修改出厂设置时区及年份\r\r\nST20710-1 第一批散件\r\r\n26250套 单相2线DIN导轨安装PLC载波通信分体式预付费代码表散件（240V, 5(80)A） \r\r\n7100套 三相4线BS安装PLC载波通信分体式预付费代码表散件（3×240V, 5(100)A\r\r\nPCBA,LCD重要物料打托，金属件/电池物料打木箱，生产后提供该批次表号数据及密钥文件，交期较赶，年前发货交单议付，谢谢配合。', '33350', '2018-01-19 01:53:00', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20710', 'INHESC2017092801', '2018-02-01', '国际一部 INTL.Business Dept.1', '余冬纯', '', '02', '生产通知单', '结算方式为不可撤销非保兑即期信用证，信用证下10%预付，90%交发货单据扫描件议付。当前未收到预付款，但王总已特批，这本来是一批，现在只下一半。详见OA邮件“ST20710订单生产、发货、议付跟踪”。	\r\r\n', '同意', '朱君宜2018-01-19 09:37:21', '王维2018-01-19 08:33:41', '同意', '陶保荣2018-01-19 11:04:45', '', '', '', '翻单生产，请江西工厂安排处理。', '同意。', '丁富民2018-01-19 13:26:19', '王功勇2018-01-19 13:52:10', 'sctz2018011901', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('237', '{4D3CE83C-AEC2-4137-9FC8-E5AC9E53EEC5}', '60', 'INHE-0549', '2018-01-23 17:40:21', '0000-00-00 00:00:00', '2018-01-25 17:14:30', 'unchecked', 'n', 'n', '', '1', 'sctz2018012301/KM01/生产通知单', '', '出厂时单三相表箱内部装好表和熔断器熔芯和零线柱并接好线。单三相断路器，安装板，双绞线和CIP可单独包装。如有任何问题请微信或电话联系王秀明：15705276012。', '22947', '2018-01-23 17:40:21', 'KAMA.SA', 'KM', 'KM01', 'INHESC2017022202', '2018-03-31', '国际一部 INTL.Business Dept.1', '王秀明', '第三方检验', '06', '生产通知单', 'KMO1发往几内亚结算方式为买方将支付50万美元作为预付款，其余将在缴获日前15天TT或LC付款。当前预付款只收到30万，但王总已特批，同意生产。', '同意', '朱君宜2018-01-24 11:18:21', '王维2018-01-24 10:54:24', '同意', '陶保荣2018-01-25 11:30:53', '', '', '', '单相表负责人章春鹏；三相表负责人王顺万。涉及到表箱、安装板模具修改，请采购跟进进度。', '同意。', '丁富民2018-01-25 11:51:55', '王功勇2018-01-25 14:46:38', 'sctz2018012301', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('239', '{F26675A4-A78F-46AC-B632-32A0F05728B8}', '61', 'INHE-0500', '2018-02-01 09:19:26', '0000-00-00 00:00:00', '2018-02-05 08:26:40', 'unchecked', 'n', 'n', '', '1', 'sctz2018020101/SEGS01/生产通知单', '', '1.SEGS01销售合同变更流程已完成，变更内容为：增加170台双绞线用户显示单元（CIU）和SEGS01的BS单相可更换通讯模块（G3 PLC通讯）智能电表配套使用，增加10台双绞线用户显示单元（CIU）和SEGS01的BS三相可更换通讯模块（G3 PLC通讯）智能电表配套使用；\r\n2.变更合同的货款已全部收到。交期要求在3月15日。', '0', '2018-02-01 09:19:26', 'Meter Mate Prepaid Electric Meters cc', 'SEGS', 'SEGS01', 'INHESC2017072501', '2018-03-15', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '05', '生产通知单', '结算方式：生产前T/T全支付	，当前款已收齐，同意生产。	\r\r\r\n \r\r\r\n	\r\r\r\n', '同意', '朱君宜2018-02-02 08:56:35', '郭涛2018-02-02 03:53:16', '同意', '陶保荣2018-02-02 08:57:46', '', '', '', '', '同意', '丁富民2018-02-02 09:09:22', '王功勇2018-02-03 09:30:41', 'sctz2018020101', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('240', '{D71AE643-9E2B-4819-9D00-13100FD3A5AB}', '60', 'INHE-0549', '2018-02-02 18:55:44', '0000-00-00 00:00:00', '2018-02-05 12:06:12', 'unchecked', 'n', 'n', '', '1', 'sctz2018020201/NF7-01/生产通知单', '', '电力公司已于1月31日传真发来发货通知，按照合同规定，我司必须于收到通知后两个月内发货，否则会罚款。十套软件套装由我二月底出差带过去。有任何问题请微信联系王秀明：15705276012.谢谢！', '1974', '2018-02-02 18:55:44', 'Office National de l`électricité et de l`Eau Potable - Branche électricité', 'NF7', 'NF7-01', 'SM95507PU', '2018-03-31', '国际一部 INTL.Business Dept.1', '王秀明', '', '05', '生产通知单', '结算方式为：收到信用证以及发货通知。当前收到146,608.59美元信用证通知单，还有7%质保金和培训费暂未收到款，同意生产。		\r\r\n', '同意', '朱君宜2018-02-05 09:57:56', '王维2018-02-03 09:53:41', '同意', '陶保荣2018-02-05 10:01:56', '', '', '', '研发项目负责人：王占颍   争取2月10日前给出采购周期长的物料单，请采购提前作准备。正式BOM表预计要在3月初左右；程序预计3月上旬左右；希望能在3月底完成生产。', '同意。', '丁富民2018-02-05 10:59:06', '王功勇2018-02-05 11:34:55', 'sctz2018020201', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('241', '{64F707CE-7299-46BA-B90C-D99B9A5B586C}', '60', 'INHE-0560', '2018-02-05 16:50:57', '0000-00-00 00:00:00', '2018-02-06 16:07:44', 'unchecked', 'n', 'n', '', '1', 'sctz2018020504/白雪802/生产通知单', '', 'APC910M-43-B要求：\r\r\r\n1、采用经安美通、银河表计及白雪客户确认的V3.0版程序。  \r\r\r\n2、安美通集抄无线射频通信模块。             \r\r\r\n3、电压：4.5-6V             \r\r\r\n4、频段：432-434MHz              \r\r\r\n5、SMA连接线必须装在电路板上。\r\r\r\n6、出厂时发射功率设为10mW.\r\r\r\n7、不带天线', '0', '2018-02-05 16:50:57', 'Energomera CJSC', '白雪', '白雪802', 'PO#E18_3001_2', '2018-02-08', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式为：下单时支付20%，发货前支付剩余80%。当前未收到预付款，但王总已特批，详见OA邮件“白雪802订单下单发货申请”，同意生产。	\r\n			\r\n', '同意', '朱君宜2018-02-06 13:44:41', '王维2018-02-06 13:20:13', '同意', '陶保荣2018-02-06 14:08:47', '', '', '', '', '同意', '丁富民2018-02-06 15:11:57', '王功勇2018-02-06 15:26:16', 'sctz2018020504', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('242', '{F4DF297E-8A5D-4DCC-93AF-231C5DABA888}', '60', 'INHE-0680', '2018-02-07 13:56:07', '0000-00-00 00:00:00', '2018-02-08 14:29:18', 'unchecked', 'n', 'n', '', '1', 'sctz2018020701/BY08/生产通知单', '请协助预先确认交货期，谢谢', '1:根据客户与招标方确认的交货期，要求我方交货时间： 2018.3.14，请协助满足#FE54` \r\n2:避免遇到与BY06情况一样, 如果我们无法满足交货期，请提前告知，客户可能会取消订单#FE54`\r\n3:请调用BY06剩余产品用于生产#FE54`		\r\n4:用BY06预付款支付BY08订单；								\r\n', '42', '2018-02-07 13:56:07', 'OsOO ASMAN SERVIS', 'BY', 'BY08', 'INHESC2018012401', '2018-03-14', '国际一部 INTL.Business Dept.1', '陈嘉豪', '', '04', '生产通知单', '结算方式：生产前30%TT，发货前70%TT。因为此项目是BY06预付款支付BY08订单，相当于BY08的预付款已收，同意生产。', '同意', '朱君宜2018-02-08 09:22:03', '王维2018-02-07 21:45:16', '同意，（3个品种一共几十台样机生产很难做安排，从BY01到BY08，这个客户没有一次上过1000台的订单。）', '陶保荣2018-02-08 09:43:04', '', '', '', '数量很小，翻单生产，请工程部安排', '同意', '丁富民2018-02-08 09:57:09', '王功勇2018-02-08 11:21:00', 'sctz2018020701', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('243', '{99D9FEF7-FC84-4423-9D25-660B755E5462}', '61', 'INHE-0381', '2018-02-08 11:50:46', '0000-00-00 00:00:00', '2018-02-09 10:14:59', 'unchecked', 'n', 'n', '', '1', 'sctz2018020801/ING04/生产通知单', '', '1.客户提出后付费预付费模式转换状态后，屏幕需自动切换成有功总用电量或者剩余电量。之前发货产品切换成后付费状态，屏幕显示为00. 2. 外箱唛头文件需修改：oer number：17001659 CA，REF 号码：17000370 YS。', '25344', '2018-02-08 11:50:46', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING04', '17001659 CA', '2018-04-02', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式为：100%LC，60天远期。当前已收到ING04 LC信用证通知单，同意生产。', '同意', '朱君宜2018-02-09 09:02:31', '郭涛2018-02-08 20:05:26', '同意', '陶保荣2018-02-09 09:09:09', '', '', '', '只作嵌入式软件修改---王顺万', '同意。', '丁富民2018-02-09 09:50:45', '王功勇2018-02-09 10:11:18', 'sctz2018020801', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('244', '{3640855C-C411-4029-A009-C212A26E052F}', '61', 'INHE-0381', '2018-02-08 12:36:14', '0000-00-00 00:00:00', '2018-03-23 14:49:44', 'unchecked', 'n', 'n', '', '1', 'sctz2018020804/CDN19-Y2/生产通知单', '', '客户要的急，希望放春节前寄出掌机，已OA申请提前备货。', '0', '2018-02-08 12:36:14', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'CDN', 'CDN19-Y2', 'INHESC2017121801', '2018-02-09', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '05', '生产通知单', '付款方式为合同全款40300USD需在合同签字后5天内通过信用证即期支付。当前信用证涉及CDN19-Y2的全款已到账，同意生产。			\r\r\n						\r\r\n', '同意', '朱君宜2018-03-22 18:32:23', '郭涛2018-03-20 11:07:52', '同意', '陶保荣2018-03-23 08:42:48', '', '', '', '', '同意。', '丁富民2018-03-23 13:41:52', '王功勇2018-03-23 14:17:23', 'sctz2018020804', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('245', '{929B9AF2-5867-4B1A-85AB-53F68946D4A1}', '60', 'INHE-0560', '2018-02-08 18:07:13', '0000-00-00 00:00:00', '2018-02-25 08:20:42', 'unchecked', 'n', 'n', '', '1', 'sctz2018020806/白雪801/生产通知单', '', '白雪单相表要求：\r\r\r\r\r\r\n1、采用新模具结构供货。     \r\r\r\r\r\r\n2、PCB板不需灌胶和喷三防漆！\r\r\r\r\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。      \r\r\r\r\r\r\n4、MAC地址为该表表号（表地址）的最后六位数字，该地址激光雕刻在表外壳背部。       \r\r\r\r\r\r\n5、PLC载波显示单元的铭牌标识为：CE208。         \r\r\r\r\r\r\n6、显示单元不需要贴易碎贴。        \r\r\r\r\r\r\n7、出厂设置：           \r\r\r\r\r\r\n1）表内时间为：GMT+4           \r\r\r\r\r\r\n2）冬夏令时转换功能关闭。           \r\r\r\r\r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\r\r\r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\r\r\r\r\n5）特殊节假日没有。           \r\r\r\r\r\r\n6）电表密码：000000.           \r\r\r\r\r\r\n7）负荷门限：0.           \r\r\r\r\r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\r\r\r\r\n9）取负荷点的平均时间：30分钟。          \r\r\r\r\r\r\n8、继电器：100A，但标识采用120A。      \r\r\r\r\r\r\n9、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）       \r\r\r\r\r\r\n10、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\r\r\r\r\n11、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU的内盒中。\r\r\r\n\r白雪三相表要求：\r\r\n\r\r\r\n1、采用双方验证过的程序版本TMF2-1B-16032201\r\r\r\n2、修改过脉冲输出的阻抗。						\r\r\r\n3. 铭牌、MAC地址等需要镭雕在电表外壳上； \r\r\r\n4. MAC地址铭牌的6位数字为该表表号的最后六位数字；\r\r\r\n5. 表内时间为GMT+3#FE54` \r\r\r\n6. 冬夏令时转换功能关闭； \r\r\r\n7. 需要把面板上的表号设到电表内 \r\r\r\n8. 计量单元不需要打铅封。\r\r\r\n9、计量单元、显示单元都不需要贴合格证 \r\r\r\n10、三相表默认密码为777777。 \r\r\r\n11：内盒不需要贴条形码\r\r\r\n12：计量单元和显示单元都取消易碎贴纸	\r  \r', '160320', '2018-02-08 18:07:13', 'Energomera CJSC', '白雪', '白雪801', 'PO#E18_3001', '2018-03-30', '国际一部 INTL.Business Dept.1', '李美娇', '', '04', '生产通知单', '付款方式：25%TT下单前，75%TT发货前。但王总特批同意收到10%预付款可生产，详见OA邮件：“白雪2018年订单事宜”，目前10%预付款已到招行，正在办理入账手续。同意生产。', '同意', '朱君宜2018-02-24 10:10:42', '王维2018-02-09 19:32:58', '同意', '陶保荣2018-02-24 10:26:47', '', '', '', '', '同意', '丁富民2018-02-24 13:53:09', '王功勇2018-02-24 21:57:46', 'sctz2018020806', '01', '', '', '', null, null, null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('246', '{8091C4E6-8E30-436D-A2B5-F3CAC4006B02}', '61', 'INHE-0381', '2018-02-24 13:38:41', '0000-00-00 00:00:00', '2018-02-25 10:02:11', 'unchecked', 'n', 'n', '', '1', 'sctz2018022401/ING06/生产通知单', '', '1. 出货一个大柜\r\r\r\r\r\n2. 外箱唛头需要修改：order number: 18000006 CA  ref: 17000371YS\r\r\r\n3. 模块类型：SRFD1-01，频率：424.8；modulation：FSK\r\r\r\n', '11376', '2018-02-24 13:38:41', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING06', '18000006 CA', '2018-04-05', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', 'ING06项目结算方式：100%LC，60天远期，当前已收到LC信用证通知单，同意生产。', '同意', '朱君宜2018-02-24 18:19:09', '郭涛2018-02-24 18:13:27', '同意', '陶保荣2018-02-24 21:11:03', '', '', '', '项目负责人：王顺万', '同意', '丁富民2018-02-25 09:11:52', '王功勇2018-02-25 09:59:21', 'sctz2018022401', '01', '', '', '', 'L/C已收到，可以下单。', '鲁慧珍2018-02-24 14:43:09', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('247', '{4DFAC3DB-0DE3-4611-93D8-9829561EFC36}', '61', 'INHE-0578', '2018-03-02 14:51:40', '0000-00-00 00:00:00', '2018-03-05 08:46:15', 'unchecked', 'n', 'n', '', '1', 'sctz2018030201/ESA13/生产通知单', '', '1.项目代号ESA13.散件需配备足量打包带（此前已OA申请）。\r\r\n\r\r\n\r\r\n2.预付款已到账37.4万美元，还差约4.2万美元客户在下周付出；已申请公司同意凭到账的37.4万美元下单生产。', '61000', '2018-03-02 14:51:40', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'ESA', 'ESA13', 'INHESC2018020901', '2018-03-26', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '', '02', '生产通知单', '结算方式为生产前通过TT支付416,940USD,发货前，通过TT支付1,667,760USD。	当前已收到374，000美元，部分预付款未到帐，但王总已特批，详见OA邮件“ESA13生产、发货、收款跟踪”										\r\r\n\r\r\r\n', '同意!', '朱君宜2018-03-02 17:55:10', '郭涛2018-03-02 16:08:19', '同意', '陶保荣2018-03-02 18:17:47', '', '', '', '翻单生产，请江西工厂安排处理。', '同意', '丁富民2018-03-02 18:56:01', '王功勇2018-03-02 23:10:16', 'sctz2018030201', '01', '', '', '', '尚差预付款未到账，但王总在标题“ESA13生产、发货、收款跟踪”的OA中已特批“同意下单”。', '鲁慧珍2018-03-02 15:07:08', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('248', '{2227BEDF-8A70-4201-8A3E-CB1C0579FF26}', '61', 'INHE-0500', '2018-03-02 16:53:39', '0000-00-00 00:00:00', '2018-03-05 11:47:48', 'unchecked', 'n', 'n', '', '1', 'sctz2018030202/ASL01/生产通知单', '', '', '33', '2018-03-02 16:53:39', 'GSA Ltd', 'ASL', 'ASL01', 'INHESC2018020801', '2018-04-10', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '05', '生产通知单', '结算方式：签订合同10天内T/T支付100%的合同款项。当前已收到全款，同意生产。', '同意。请注意BOX300是直通300A表，不是计量箱。', '朱君宜2018-03-05 10:03:45', '郭涛2018-03-03 11:17:05', '同意', '陶保荣2018-03-05 10:14:44', '', '', '', 'CT表、300A中电流箱为翻单产品，建议江西工厂处理； 200A\\300A计量装置建议利用客户服务部下的样品交货（二款表箱已经江西工厂）。', '同意', '丁富民2018-03-05 10:45:38', '王功勇2018-03-05 11:03:36', 'sctz2018030202', '01', '', '', '', '全款已收，同意下单。', '鲁慧珍2018-03-02 17:26:28', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('249', '{A6FEC3D5-8500-4C36-B6CA-DA728B4CA604}', '60', 'INHE-0560', '2018-03-05 09:33:50', '0000-00-00 00:00:00', '2018-03-07 15:44:36', 'unchecked', 'n', 'n', '', '1', 'sctz2018030501/白雪803/生产通知单', '', '\r\r\r\r\n白雪三相表要求：\r\r\r\r\n\r\r\r\n1、采用最新的软件硬件版本，即计量单元带开盖记录功能的版本2\r\r\r\r\n2、修改过脉冲输出的阻抗。						\r\r\r\r\n3. 铭牌、MAC地址等需要镭雕在电表外壳上； \r\r\r\r\n4. MAC地址铭牌的6位数字为该表表号的最后六位数字；\r\r\r\r\n5. 表内时间为GMT+3#FE54` \r\r\r\r\n6. 冬夏令时转换功能关闭； \r\r\r\r\n7. 需要把面板上的表号设到电表内 \r\r\r\r\n8. 计量单元不需要打铅封。\r\r\r\r\n9、计量单元、显示单元都不需要贴合格证 \r\r\r\r\n10、三相表默认密码为777777。 \r\r\r\r\n11：内盒不需要贴条形码\r\r\r\r\n12：计量单元和显示单元都取消易碎贴纸	  										\r\r\r\r\n', '100', '2018-03-05 09:33:50', 'Energomera CJSC', '白雪', '白雪803', 'PO#E18_1202', '2018-03-25', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式为发货前100%全额付款。当前暂未收到款，同意先生产，款到后再发货。		\r\n', '同意', '朱君宜2018-03-07 09:16:36', '王维2018-03-07 08:45:54', '同意', '陶保荣2018-03-07 10:19:35', '', '', '', '客户新增功后小批量订单----需要采用新的硬件软件版本，项目负责人王占颍。', '同意', '丁富民2018-03-07 13:26:36', '王功勇2018-03-07 14:13:02', 'sctz2018030501', '01', '', '', '', '付款方式为发货前全款T/T，可以下单', '鲁慧珍2018-03-05 10:15:40', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('250', '{4725021D-8CFB-4627-8667-E19C1FA3DB4D}', '61', 'INHE-0434', '2018-03-06 19:00:21', '0000-00-00 00:00:00', '2018-03-07 15:43:04', 'unchecked', 'n', 'n', '', '1', 'sctz2018030601/GZA01/生产通知单', '', '1. 该项目是清楚NR05库存\r\r\r\n2. 客户要求尽快发货(最好下周三前)，客户每日都在催发货，项目全款已收到', '75', '2018-03-06 19:00:21', 'ZAHYON SOLUTIONS LTD', 'GZA', 'GZA01', 'INHESC2018030101', '2018-03-12', '国际二部 INTL.Business Dept.2', '钟云林(Andy)', '', '06', '生产通知单', '结算方式：签订合同十天内并在准备生产原材料之前T/T支付100%的合同款项	，当前已收到全款，同意生产。\r\r\n', '同意。因收款拖延较久，希望本周能交付。', '朱君宜2018-03-07 10:00:52', '郭涛2018-03-07 09:52:56', '同意', '陶保荣2018-03-07 10:18:59', '', '', '', '', '同意', '丁富民2018-03-07 11:40:09', '王功勇2018-03-07 14:12:15', 'sctz2018030601', '01', '', '', '', '全款已收，可以下单', '鲁慧珍2018-03-07 08:40:16', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('251', '{7C15761C-4623-406D-801E-001BED3856DE}', '61', 'INHE-0381', '2018-03-11 18:52:40', '0000-00-00 00:00:00', '2018-03-29 14:57:17', 'unchecked', 'n', 'n', '', '1', 'sctz2018031101/ING05/生产通知单', '', '1. 出货2个大柜。\r\r\n2. 外箱唛头需要修改：order number：17001660. ref：17000370YS。\r\r\n3. 预付费转后付费模式，电表屏幕直接默认显示总有功电量。', '25344', '2018-03-11 18:52:40', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING05', '17001660 CA', '2018-05-11', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式：100%LC，60天远期。当前ING05 信用证已通过审核，详见OA邮件“ING03 信用证审核”，同意生产。', '同意', '朱君宜2018-03-27 14:14:48', '郭涛2018-03-27 11:38:29', '同意', '陶保荣2018-03-27 17:25:21', '', '', '', '', '同意。', '丁富民2018-03-28 08:22:44', '王功勇2018-03-29 09:22:43', 'sctz2018031101', '01', '', '', '', 'L/C已收到，审核有问题，但标题为“ING03信用证审核”的OA中王总已特批可以不修改。', '鲁慧珍2018-03-27 09:09:09', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('252', '{012FFAD7-81B1-48EC-93B8-BCFF72630FB8}', '60', 'INHE-0560', '2018-03-15 17:17:30', '0000-00-00 00:00:00', '2018-03-19 08:28:23', 'unchecked', 'n', 'n', '', '1', 'sctz2018031501/白雪804/生产通知单', '', '', '0', '2018-03-15 17:17:30', 'Energomera CJSC', '白雪', '白雪804', 'PO#E18_2702', '2018-03-23', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '白雪804结算方式：预付款13559.25USD-生产前TT,76985.75USD发货前TT。当前已收到预付款13559.25USD，同意生产。', '同意', '朱君宜2018-04-04 09:05:19', '王维2018-04-04 08:08:32', '同意', '陶保荣2018-04-04 14:23:58', '', '', '', '外购指定模块，请江西工厂安排处理。', '同意。', '丁富民2018-04-04 17:50:15', '王功勇2018-04-04 22:05:09', 'sctz2018031501', '01', '', '', '', '追加部分未支付预付款，但金额很小，建议先下单。', '鲁慧珍2018-04-03 18:01:20', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('253', '{09394996-0CED-4560-8460-33D2CD213F8F}', '66', 'INHE-0634', '2018-03-19 14:41:22', '0000-00-00 00:00:00', '2018-03-20 15:13:16', 'unchecked', 'n', 'n', '', '1', 'sctz2018031901/APE04/生产通知单', '', '', '1000', '2018-03-19 14:41:22', 'Alpha Power Engineering CO., ltd', 'APE', 'APE04', 'INHESC2018020501', '2018-04-19', '国际三部 INTL.Business Dept.3', '陈雁', '第三方检验', '02', '生产通知单', '\r结算方式：第一批货物的100% CIP金额70000\r美元，将在备料前通过T/T转账支付，当前已收到第一批货100%预付款，同意\r\r生产，请业务员尽快补齐第三方支付委托函和确认函原件并在发货前寄给财务，谢谢~\r\r\r\n', '同意下单。请陈雁尽快核实FAT试验内容及所需时间让客户确认。', '朱君宜2018-03-19 16:26:12', '王梅2018-03-19 16:12:53', '同意', '陶保荣2018-03-20 09:48:42', '', '', '', '产品研发负责人---高峰（王顺万项目组）。2018年04月19日交货是一个问题，此产品正在研发之中，目前还给不出BOM表，研发预计完成时间是：A 产品BOM表3月30日提供； B 表计程序预计在4月13日提供。', '同意', '丁富民2018-03-20 10:53:04', '王功勇2018-03-20 10:55:12', 'sctz2018031901', '01', '', '', '', '此批付款条件是全款T/T预付，款已到账，可以下单。', '鲁慧珍2018-03-19 16:04:36', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('254', '{E052C2C4-017C-4153-8B6A-3F9E83ACBA4C}', '61', 'INHE-0381', '2018-03-27 15:38:13', '0000-00-00 00:00:00', '2018-04-28 17:54:12', 'unchecked', 'n', 'n', '', '1', 'sctz2018032702/BFN05/生产通知单', '', '1. 电表屏幕需要蓝屏。\r\r\r\n2. VTC套件：CT表不上电时，可以提取CT表内的数据。\r\r\n3. 客户要求一定要符合技术规格。', '3500', '2018-03-27 15:38:13', 'TOGO ASSISTANCE SERVICES', 'BFN', 'BFN05', 'INHESC2017102601', '2018-05-11', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式：合同金额的20%在签订合同20天之内作为预付款通过信用证即期支付，余款80%通过不可撤销的保兑的远期60天信用证支付；当前L/C修改件已收到，已议付约11.6%预付款，建议下单。										\r\r\r\n\r\r\r\n\r\r\r\n					\r\r\r\n', '同意', '朱君宜2018-04-28 08:45:36', '郭涛2018-04-27 07:31:06', '同意', '陶保荣2018-04-28 09:03:09', '', '请按业务和技术支持丁总要求协调“去掉VTC接口”要求，因为公司CT表没有VTC接口，也无法增加VTC接口。', '', '公司CT表没有VTC接口；此问题给业务、客户服务部作过沟通。但生产通知单再次提出要符合此要求。', '不同意', '丁富民2018-04-28 14:15:30', '王功勇2018-04-28 14:42:48', 'sctz2018032702', '02', '', '', '', 'L/C收到，已议付约11.6%预付款，建议下单生产。', '鲁慧珍2018-04-26 17:04:51', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('255', '{22958330-23B8-4BDC-B1D7-943222483C28}', '61', 'INHE-0381', '2018-03-27 15:50:05', '0000-00-00 00:00:00', '2018-04-02 08:43:34', 'unchecked', 'n', 'n', '', '1', 'sctz2018032703/GS01/生产通知单', '', '1. 产品需要内置差动式可调节电流断路器。\r\r\r\r\r\r\n2. 模块频点信息待确认。\r\r\r\r\r\n3. 电力公司SGC600382.\r\r\n4. 出厂激活无电开端盖跳闸功能\r\n5. 大货生产前需要样机确认，先下生产通知单，准备物料。', '10000', '2018-03-27 15:50:05', 'TOGO ASSISTANCE SERVICES', 'GS01', 'GS01', 'INHESC2017110902', '2018-05-11', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式：20%生产前T/T+80%余款60天远期信用证。	当前L/C修改件未收到，20%预付款已议付到账，王总已特批，详见OA邮件“BFN05信用证审核”，同意下单。								\r\n	', '同意', '朱君宜2018-03-30 10:06:14', '郭涛2018-03-28 11:00:32', '同意', '陶保荣2018-03-30 11:25:20', '', '赶紧由技术支持牵头进行技术评估：是用现有产品供货？还是需要研发？成本与售价？', '', '公司没有符合技术要求的产品。如果按技术要求需要全新进行产品设计（开模、电子方案），研发时间预计三个月。成本完全高出销售价格。', '不同意。', '丁富民2018-03-30 15:18:10', '王功勇2018-03-30 18:07:36', 'sctz2018032703', '02', '', '', '', 'L/C修改件未收到，20%预付款已议付到账，请领导审批是否先下单生产，谢谢！', '鲁慧珍2018-03-27 20:44:50', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('256', '{4FAEB7F7-B59B-4A88-A41E-7D16BF885A52}', '61', 'INHE-0381', '2018-03-29 17:33:28', '0000-00-00 00:00:00', '2018-03-30 11:34:24', 'unchecked', 'n', 'n', '', '1', 'sctz2018032901/ING07/生产通知单', '', '1. 外箱唛头：REF：17000414YS，oder Number:18000251 CA\r\n2. 电表预付费模式屏幕显示剩余电量，切换为后付费模式时，自动切换为总有功电量。', '7200', '2018-03-29 17:33:28', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING07', '18000251 CA', '2018-05-15', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '同意。仅涉及技术事宜变更', '同意(技术事宜已经确认可行）。', '朱君宜2018-04-17 10:52:31', '郭涛2018-04-17 10:11:42', '同意', '陶保荣2018-04-19 16:36:07', '', '', '', '', '同意', '丁富民2018-04-19 17:07:53', '王功勇2018-04-19 17:34:35', 'sctz2018032901', '01', '', '', '', 'OK', '鲁慧珍2018-04-17 08:52:26', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('257', '{DE528982-0998-40B7-B98D-1205FBE4F2CE}', '61', 'INHE-0593', '2018-04-04 03:03:24', '0000-00-00 00:00:00', '2018-04-12 18:10:54', 'unchecked', 'n', 'n', '', '1', 'sctz2018040401/BFN10/生产通知单', '', 'SGE通过银河购买STS安全模块，银河收款后向STS购买模块，模块请直接发往BFN电力公司。\r\r\r\r\r\n电力公司联系人信息为：Akakpo Gabriel\r\r\r\r\r\n公司名称：Société Nationale D\'électricité du Burkina\r\r\r\r\n地址：55,Avenue de la Nation 01 B.P.54 OUAGADOUGOU 01 \r\r\r\r\r\r\n电话：226 70 23 25 44/50 30 61 00/02/03/04\r\r\r\r\r\r\nFax：226 50 31 03 40 \r\r\n订单总金额10695USD 付款方式为8070USD TT转账（已到公司帐户），尾款2625USD代理在CDN现场给了张柳芳，她回国时会带回。', '0', '2018-04-04 03:03:24', 'SOCIETE GENERALE D`ELECTRONIQUE', 'BFN10', 'BFN10', 'INHESC2018032801', '2018-04-10', '国际二部 INTL.Business Dept.2', '胡蝶', '', '06', '生产通知单', '', '同意', '朱君宜2018-04-12 18:10:44', '郭涛2018-04-04 11:55:07', '', '', '', '', '', '', '', '', '', 'sctz2018040401', '', '', '', '', 'T/T付款部分3/16已到账，现金付款部分张柳芳已确认收到，款已收齐，可以下单。', '鲁慧珍2018-04-04 11:39:30', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('258', '{8BFEF335-30A9-4716-ABC0-E54DBE7020E4}', '60', 'INHE-0560', '2018-04-04 15:49:55', '0000-00-00 00:00:00', '2018-04-08 17:08:43', 'unchecked', 'n', 'n', '', '1', 'sctz2018040402/白雪805/生产通知单', '', '', '0', '2018-04-04 15:49:55', 'Energomera CJSC', '白雪', '白雪805', 'PO#E18_2803', '2018-04-10', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式：100%预付款下单时支付，当前全款已到招行，待走流程入账，同意先下单。		\r\n', '同意', '朱君宜2018-04-04 16:51:00', '王维2018-04-04 16:30:34', '同意', '陶保荣2018-04-08 10:38:41', '', '', '', '', '同意', '丁富民2018-04-08 11:14:59', '王功勇2018-04-08 13:46:13', 'sctz2018040402', '01', '', '', '', '全款已到招行，待走流程入账，金额也较小，建议先下单。', '鲁慧珍2018-04-04 16:01:20', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('259', '{162F713B-240D-44D7-8650-9FE467005D58}', '66', 'INHE-0634', '2018-04-06 18:45:01', '0000-00-00 00:00:00', '2018-04-13 10:30:43', 'unchecked', 'n', 'n', '', '1', 'sctz2018040601/APE04/生产通知单', '', '', '9000', '2018-04-06 18:45:01', 'Alpha Power Engineering CO., ltd', 'APE', 'APE04', 'INHESC2018020501', '2018-05-25', '国际三部 INTL.Business Dept.3', '陈雁', '', '05', '生产通知单', '同意补流程，货已发。此合同重新签署客户变更为Tradelink Engineering &Trading Pte.Ltd.', '同意。', '朱君宜2018-09-06 09:52:41', '王梅2018-09-06 08:33:48', '同意', '陶保荣2018-09-06 10:12:26', '', '', '', '', '同意', '丁富民2018-09-06 11:06:45', '王功勇2018-09-06 13:44:47', 'sctz2018040601', '01', '', '', '', '补流程', '鲁慧珍2018-09-03 09:34:16', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('260', '{68C1CC6D-D57E-462C-9674-86133DFB9C14}', '61', 'INHE-0381', '2018-04-11 20:33:19', '0000-00-00 00:00:00', '2018-04-12 14:47:08', 'unchecked', 'n', 'n', '', '1', 'sctz2018041101/GS01/生产通知单', '', '1. 产品需要内置差动式，需要配合电表程序实现可调节差动断路器的保护功能，请见附件。\r\r\r\r\n2. 模块频点信息待确认。\r\r\r\r\n3. 电力公司SGC600382.。\r\r\r\n4. 出厂激活无电开端盖跳闸功能\r\r\r\r\n5. 大货生产前需要样机确认，先下生产通知单，准备物料。\r\r\n6. 电力公司人员会到江西工厂验货，预计在5月30号到。', '10000', '2018-04-11 20:33:19', 'TOGO ASSISTANCE SERVICES', 'GS01', 'GS01', 'INHESC2017110902', '2018-05-25', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '第三方检验', '02', '生产通知单', '同意。L/C修改件未收到，20%预付款已议付到账，王总已特批可以下单。详见OA：“BFN05信用证审核”										\r\r\n', '同意', '朱君宜2018-04-12 10:43:39', '郭涛2018-04-12 08:48:54', '同意', '陶保荣2018-04-12 10:59:50', '', '', '', '除PCB板、程序外，其他可以参考TN03项目单相三相表、以及RF无线通信显示单元进行物料备料安排。---研发也在等客户样机确认结果。', '同意。', '丁富民2018-04-12 11:14:57', '王功勇2018-04-12 14:38:41', 'sctz2018041101', '01', '', '', '', 'L/C修改件未收到，20%预付款已议付到账，王总已特批可以下单。', '鲁慧珍2018-04-12 08:41:24', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('261', '{6C254C57-9FC5-4E9F-A9CD-082054D15BF1}', '61', 'INHE-0381', '2018-04-16 03:32:08', '0000-00-00 00:00:00', '2018-04-25 11:12:33', 'unchecked', 'n', 'n', '', '1', 'sctz2018041601/NEW01/生产通知单', '', '1.DLMS协议电表，G3 PLC通信。电表需要满足技术规格。2.该项目金额已开立到GS01项目的信用证中。', '155', '2018-04-16 03:32:08', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'NEW', 'NEW01', 'INHESC2018040601', '2018-05-20', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '同意,此次变更电压改为230V.不涉及金额.', '同意', '朱君宜2019-02-20 18:18:34', '郭涛2019-02-20 17:23:42', '同意', '陶保荣2019-02-21 08:36:11', '', '', '', '', '同意', '丁富民2019-02-21 11:26:56', '王功勇2019-02-21 15:18:02', 'sctz2018041601', '01', '', '', '', '', '鲁慧珍2019-02-20 08:45:34', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('262', '{7265767C-8201-4844-81C4-2118FA64AB42}', '66', 'INHE-0579', '2018-04-23 15:06:13', '0000-00-00 00:00:00', '2018-04-24 14:17:00', 'unchecked', 'n', 'n', '', '1', 'sctz2018042301/YDD-A01/生产通知单', '', '1.铭牌要求电力公司确认后再反馈。\r\r\r\r\r\r\r\n2.包装要求： 700台单相表和300台三相表空运，其余4000台表（2800台单相和1200台三相）海运。\r\r\r\r\n①空运无需打托，包装贴易碎标志，纸箱内部包装稳固，适合空运。\r\r\r\r\r\r\n②海运需打托，从深圳发货（客户选择时效快的，且已多付运费）。\r\r\r\r\r\n3.产品需满足标书要求。\r\r\n4.产品需要BV检测认证。', '5000', '2018-04-23 15:06:13', 'Al-Jalmed Co.			', 'YDD-A', 'YDD-A01', 'INHESC2018022701', '2018-06-30', '国际三部 INTL.Business Dept.3', '孙娜', '第三方检验', '05', '生产通知单', '结算方式为预付款102,362欧元（约占合同金额33.7%）T/T支付，尾款201,378欧元T/T支付。当前已收到预付款TT，同意下单。\r\r\n\r\r\n						\r\r\n						\r\r\n', '同意下单.', '朱君宜2018-04-23 16:09:46', '王梅2018-04-23 15:48:24', '同意,', '陶保荣2018-04-23 16:17:12', '', '用二代单、三相模块表供货，请研发加班尽快完成设计定型。', '', '研发项目负责人：王顺万。   此款单相三相表没有作过小批量试生产，研发生产还有需要改进完善的方面；另外：三相表要求是对称接线方式，需要考虑模具和方案修改。6月份交货将是一个问题。', '同意', '丁富民2018-04-24 11:31:54', '王功勇2018-04-24 13:48:54', 'sctz2018042301', '01', '', '', '', '预付款已收到，可以下单。', '鲁慧珍2018-04-23 15:19:43', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('263', '{56A04FFF-9A9F-4FCB-9F4E-A31215BAC793}', '60', 'INHE-0088', '2018-04-25 14:34:39', '0000-00-00 00:00:00', '2018-04-27 13:56:26', 'unchecked', 'n', 'n', '', '1', 'sctz2018042501/BPD801/生产通知单', '', '紧急出差携带，已发货（补下生产通知单），现场收现金。', '0', '2018-04-25 14:34:39', 'Ideal Enterprise', 'BPD', 'BPD801', 'INHESC2018041101', null, '国际一部 INTL.Business Dept.1', '余冬纯', '', '06', '生产通知单', '结算方式：现金付款。同意。', '同意', '朱君宜2018-04-26 17:27:41', '王维2018-04-26 16:45:23', '同意', '陶保荣2018-04-26 17:37:30', '', '', '', '', '同意', '丁富民2018-04-27 08:55:13', '王功勇2018-04-27 13:52:02', 'sctz2018042501', '01', '', '', '', '补流程', '鲁慧珍2018-04-25 14:42:32', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('264', '{8D8B42FF-530D-41BA-8170-3F304C4D935D}', '61', 'INHE-0381', '2018-04-26 23:16:46', '0000-00-00 00:00:00', '2018-04-28 17:54:14', 'unchecked', 'n', 'n', '', '1', 'sctz2018042601/ING08/生产通知单', '', '1. 外箱Order num:18000113CA, Ref#FE54`17000414YS.', '12672', '2018-04-26 23:16:46', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING08', '18000113 CA', '2018-05-25', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式：100%LC，60天远期。 ING08LC\r通知书已收到，同意下单。	\r\r\r\r\r\r\r\r\r\n', '同意', '朱君宜2018-04-28 08:53:44', '郭涛2018-04-27 14:19:29', '同意', '陶保荣2018-04-28 09:03:29', '', '', '', '翻单生产，请江西工厂安排处理。技术方面二个修已经完成，请工程部品管部作核对。', '同意', '丁富民2018-04-28 13:51:18', '王功勇2018-04-28 14:39:10', 'sctz2018042601', '01', '', '', '', 'L/C 3/29已收到，ERP 4/9已下单。', '鲁慧珍2018-04-27 13:34:31', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('265', '{A5E31E04-01BE-47EB-9944-402732962EA7}', '60', 'INHE-0560', '2018-05-03 13:52:40', '0000-00-00 00:00:00', '2018-05-08 10:00:23', 'unchecked', 'n', 'n', '', '1', 'sctz2018050301/白雪806/生产通知单', '', '', '0', '2018-05-03 13:52:40', 'Energomera CJSC', '白雪', '白雪806', 'PO#E18_1204', '2018-05-10', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '该项目的信用政策为：下单时支付5650美金（25%），发货前支付16950美金（75%）。5650美金已收，同意下单', '同意', '朱君宜2018-05-07 14:42:27', '王维2018-05-04 08:39:47', '同意', '陶保荣2018-05-08 08:15:10', '', '', '', '', '同意', '丁富民2018-05-08 08:31:23', '王功勇2018-05-08 09:47:11', 'sctz2018050301', '01', '', '', '', '25%预付款已到账，可以下单。', '鲁慧珍2018-05-03 14:10:32', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('266', '{4C119937-913A-4D5F-AC81-85C584B4642C}', '61', 'INHE-0593', '2018-05-04 09:16:54', '0000-00-00 00:00:00', '2018-05-09 16:02:57', 'unchecked', 'n', 'n', '', '1', 'sctz2018050401/BFN05/生产通知单', '', '1. 产品1标书及报价单中的描述是：KIT de récupération des données en cas de panne du compteur 即电表故障时能够提取电表数据的工具。客户测样机时，会测试CT表不上电的情况下，如何提取数据。\r\n2.电表屏幕为蓝屏。\r\n3.务必遵守客户提出的修改要求。', '3500', '2018-05-04 09:16:54', 'TOGO ASSISTANCE SERVICES', 'BFN', 'BFN05', 'INHESC2017102601', '2018-06-10', '国际二部 INTL.Business Dept.2', '胡蝶', '第三方检验', '02', '生产通知单', '本合同中金额合计USD679 864，付款方式为合同金额的20%在签订合同20天之内作为预付款通过信用证即期支付，余款80%通过不可撤销的保兑的远期60天信用证支付。该项目已预收78941美元（为合同的11.61%），未达到约定的20%不符合信用政策，请领导决议审批。\r\r\n', '同意，请注意客户技术要求。', '朱君宜2018-05-08 09:52:11', '郭涛2018-05-04 10:13:41', '同意', '陶保荣2018-05-08 10:01:00', '', '', '', '项目研发负责人：王占颍。   生产前样机已经提供给业务，现等客户测试反馈。', '同意。', '丁富民2018-05-08 10:49:17', '王功勇2018-05-08 14:44:21', 'sctz2018050401', '01', '', '', '', 'L/C收到，已议付约11.6%预付款，建议下单生产。', '鲁慧珍2018-05-04 09:50:49', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('267', '{D2B6B6BE-F045-442F-B4A9-BB5B87D28E06}', '61', 'INHE-0690', '2018-05-14 08:50:06', '0000-00-00 00:00:00', '2018-05-15 14:48:09', 'unchecked', 'n', 'n', '', '1', 'sctz2018051401/IMF05/生产通知单', '', '1.KF02散件维修补料，交货比较紧急，希望能在5月23日采购完毕交货。\r\r\r\r\n2.IMF05的详细采购清单请见上述附件，由于合同产品与采购清单未能对应，请按照上述附件清单项目进行采购，出货。\r（清单1.V1-DKP2-3B17504,KF02项目单相二线DIN导轨安装分体式(PLC载波通信)预付费代码表-采购清单-20180502   清单2.V1-CIP显示单元(CIP-3B17504-KF02项目）采购清单-20180430）\r\r\r\n\r\r\r\r\n', '0', '2018-05-14 08:50:06', 'INHEMETER AFRICA CO., LTD.', 'IMF', 'IMF05', 'INHESC2018050902', '2018-05-25', '国际二部 INTL.Business Dept.2', '张正', '', '06', '生产通知单', 'IMF05的结算方式为提单后120天TT，同意。', '同意。因公司器件（类型和价格）保密需要，合同未按单个器件签，但生产需要按具体器件执行。', '朱君宜2018-05-15 09:07:59', '郭涛2018-05-14 17:35:48', '同意', '陶保荣2018-05-15 09:28:53', '', '', '', '', '同意', '丁富民2018-05-15 09:31:03', '王功勇2018-05-15 09:38:58', 'sctz2018051401', '01', '', '', '', '付款方式为提单后120天T/T全款，可以下单。', '鲁慧珍2018-05-14 13:55:11', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('268', '{CA6D0A2E-161A-450A-86E7-ADCE14AFD42E}', '61', 'INHE-0500', '2018-05-17 13:31:09', '0000-00-00 00:00:00', '2018-05-21 09:11:12', 'unchecked', 'n', 'n', '', '1', 'sctz2018051701/EOI02/生产通知单', '', 'EOI项目为直接采购项目，项目使用的三款电表和ZWS招标的三款电表一样，技术规格和ZWS技术规格一致。', '1450', '2018-05-17 13:31:09', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI02', 'INHESC2018050901', '2018-06-27', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '06', '生产通知单', '结算方式为：合同金额的30%在签订合同10天内作为预付款T/T支付，70%余款在发货前T/T支付。当前已收到预付款，同意生产。', '同意', '朱君宜2018-05-18 08:52:20', '郭涛2018-05-17 17:35:18', '同意', '陶保荣2018-05-18 14:05:47', '', '', '', '单相表（DIN导轨表、BS安装单相表）分体式（PLC)代码表章春鹏负责；三相分体式（PLC）代码表王顺万负责。', '同意。', '丁富民2018-05-18 15:37:22', '王功勇2018-05-18 16:57:10', 'sctz2018051701', '01', '', '', '', 'T/T预付款已收到，可以下单。', '鲁慧珍2018-05-17 14:15:11', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('269', '{A87BE9B8-5E43-4560-A657-D6167212FDBE}', '61', 'INHE-0381', '2018-05-18 08:42:27', '0000-00-00 00:00:00', '2018-05-21 09:08:36', 'unchecked', 'n', 'n', '', '1', 'sctz2018051801/ING09/生产通知单', '', '1. 外箱唛头：Order Num#FE54`18000114 CA  Ref: 17000414YS.', '12672', '2018-05-18 08:42:27', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING09', '18000114 CA', '2018-07-06', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '生产方式：100%LC，60天远期。ING09信用证通知单已收到，	同意生产。	\r\n', '同意', '朱君宜2018-05-18 15:49:50', '郭涛2018-05-18 15:41:28', '同意', '陶保荣2018-05-18 16:22:26', '', '', '', '', '同意', '丁富民2018-05-18 17:24:51', '王功勇2018-05-18 19:20:03', 'sctz2018051801', '01', '', '', '', '208/5/2收到L/C且审核通过，2018/4/26已ERP下单给工厂，要求交期2018/6/20', '鲁慧珍2018-05-18 08:54:55', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('270', '{28B37985-F5F1-4052-8AA2-3A78E03842D7}', '61', 'INHE-0381', '2018-05-18 14:55:13', '0000-00-00 00:00:00', '2018-05-24 17:52:12', 'unchecked', 'n', 'n', '', '1', 'sctz2018051802/MD02/生产通知单', '', '1.MD01翻单产品。\r\r\r\n2. 发货前需要SGS验货，麻烦提前通知。\r\r\n3. FOB九江，货发到九江码头。4.客户已付预付款。', '5078', '2018-05-18 14:55:13', 'BCCT.SAS', 'MD', 'MD02', '600000758', '2018-06-29', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '第三方检验', '06', '生产通知单', '结算方式：30%签订合同后T/T预付款+ 70%验货后发货前T/T付款。		\r\n当前已收预付款，同意生产。', '同意', '朱君宜2018-05-24 09:46:24', '郭涛2018-05-24 07:49:56', '同意', '陶保荣2018-05-24 10:19:11', '', '', '', 'MD01项目翻单生产，请江西工厂安排处理。', '同意。', '丁富民2018-05-24 14:53:55', '王功勇2018-05-24 16:08:32', 'sctz2018051802', '01', '', '', '', '30%预付款已到账，可以下单。', '鲁慧珍2018-05-23 15:41:28', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('271', '{F420EEAB-DCEB-4BCC-8F8E-19FB3870A227}', '80', 'INHE-0576', '2018-05-23 15:36:20', '0000-00-00 00:00:00', '2018-05-29 10:05:08', 'unchecked', 'n', 'n', '', '1', 'sctz2018052301/KF02/生产通知单', '', '', '120000', '2018-05-23 15:36:20', 'The Kenya Power * Lighting Company Limited', 'KF02', 'KF02', 'INHESC2017033101', '2018-05-25', 'Financial DPT.', '戴萍(Eileen)', '', '07', '生产通知单', '结算方式：交货后30天通过T/T付款。同意补KF02生产流程 ', '同意', '朱君宜2018-05-29 09:12:19', '郭涛2018-05-24 07:49:26', '', '', '', '注意：这个流程是“银河工业园”的生产通知单，不能代替IAC的生产通知单。', '', '', '同意。', '丁富民2018-05-29 09:31:59', '王功勇2018-05-29 09:38:06', 'sctz2018052301', '01', '01', '应公司流程需要，重补流程', '钟友谊2018-05-23 15:52:32', '', '', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('272', '{3E5A689A-9DB0-49A1-B750-14B7C4BEFDBC}', '61', 'INHE-0500', '2018-05-23 15:44:04', '0000-00-00 00:00:00', '2018-05-24 17:51:53', 'unchecked', 'n', 'n', '', '1', 'sctz2018052302/EOI03/生产通知单', '', 'EOI项目为直接采购项目，项目使用的三款电表和ZWS招标的三款电表一样，技术规格和ZWS技术规格一致。										\r\r\n', '1500', '2018-05-23 15:44:04', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI03', 'INHESC2018051001', '2018-07-05', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '06', '生产通知单', '结算方式：合同金额的30%在签订合同10天内作为预付款T/T支付，70%余款在发货前T/T支付，当前已收的预付款，同意生产。		\r\n', '同意', '朱君宜2018-05-24 08:50:39', '郭涛2018-05-24 07:48:50', '同意', '陶保荣2018-05-24 09:34:20', '', '', '', 'EOI翻单处理', '同意。', '丁富民2018-05-24 14:45:29', '王功勇2018-05-24 16:07:57', 'sctz2018052302', '01', '', '', '', '30%T/T预付款已到账，可以下单。', '鲁慧珍2018-05-23 15:54:40', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('273', '{F0D1F247-B690-4499-B75D-A089BCD983D1}', '61', 'INHE-0434', '2018-05-23 19:36:31', '0000-00-00 00:00:00', '2018-05-25 14:15:48', 'unchecked', 'n', 'n', '', '1', 'sctz2018052303/GA07/生产通知单', '', '1. DIN表需要具备【日用电门限】\r\n2. 技术要求中集中器备用20个PLC模块可暂不备货', '3600', '2018-05-23 19:36:31', 'GVE Projects Limited', 'GA', 'GA07', 'INHESC2018041802', '2018-06-30', '国际二部 INTL.Business Dept.2', '钟云林(Andy)', '', '06', '生产通知单', '结算方式：合同金额的50%在签订合同10天内作为预付款T/T支付，50%余款在发货前T/T支付。当前已收到预付款，同意生产。		\r\n', '同意', '朱君宜2018-05-25 10:10:23', '郭涛2018-05-25 09:06:49', '同意', '陶保荣2018-05-25 10:14:31', '', '', '', '同意。RF无线通信采用慧联通信方案（RF-II),实现RF无线集中抄表。---单相表使用CDN16#FE54`三相表使用CDN30#FE54`根据客户要求研发作面板、包装方面修改和物料核对。', '', '丁富民2018-05-25 13:49:46', '王功勇2018-05-25 13:51:53', 'sctz2018052303', '01', '', '', '', '50%T/T预付款已收齐，可以下单。', '鲁慧珍2018-05-25 08:32:20', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('274', '{D145C336-EA7D-4C7A-B99A-0401B0750970}', '61', 'INHE-0381', '2018-05-24 03:42:48', '0000-00-00 00:00:00', '2018-07-16 08:36:09', 'unchecked', 'n', 'n', '', '1', 'sctz2018052401/ING10/生产通知单', '', '1. 外箱唛头修改：Order ：18000115CA。Ref:17000414YS', '12672', '2018-05-24 03:42:48', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING10', '18000115 CA', '2018-08-01', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式：100%LC，60天远期。当前L/C正本收到且审核通过，同意生产。', '同意', '朱君宜2018-07-13 14:29:31', '郭涛2018-07-13 11:05:34', '同意', '陶保荣2018-07-13 14:34:03', '', '', '', '翻单订单，请江西工厂安排处理。', '同意。', '丁富民2018-07-13 16:37:33', '王功勇2018-07-13 16:51:07', 'sctz2018052401', '01', '', '', '', 'L/C正本收到且审核通过，可以下单。', '鲁慧珍2018-07-13 08:46:44', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('275', '{88E1A329-BA01-4525-BC57-B5ED31707C8C}', '60', 'INHE-0088', '2018-05-29 15:39:00', '0000-00-00 00:00:00', '2018-05-30 09:47:53', 'unchecked', 'n', 'n', '', '1', 'sctz2018052901/ST20710-2/生产通知单', '', '1. 参考ST20710-1 翻单资料无须修改\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n2. 库存已备料：\r（计划6月5日收款发货）\r\r\r\r\r\r\n26250套 单相2线DIN导轨安装PLC载波通信分体式预付费代码表散件（240V, 5(80)A） \r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n7100套 三相4线BS安装PLC载波通信分体式预付费代码表散件（3×240V, 5(100)A\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n3. 须生产：\r\r\r\r\r\r\r\r\r\r（计划6月底发货）\r\r\r\r\n26250套 单相2线DIN导轨安装PLC载波通信分体式预付费代码表散件（240V, 5(80)A） \r\r\r\r\r\r\r\r\r\r\r\r\r\r\n7100套 三相4线BS安装PLC载波通信分体式预付费代码表散件（3×240V, 5(100)A\r\r\r\r\r\r\r\r\r\r\r\r\r\n4. PCBA,LCD重要物料打托，金属件/电池物料打木箱，生产后提供该批次表号数据及密钥文件。\r\r\r\r\r', '66700', '2018-01-19 01:53:00', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20710', 'INHESC2017092801', '2018-06-25', '国际一部 INTL.Business Dept.1', '余冬纯', '', '02', '生产通知单', '结算方式：不可撤销非保兑即期信用证，信用证下10%预付，90%交发货单据扫描件议付。L/C已收到，修改件暂未收到，建议下单，请领导审批。										\r\n	\r\r\n', '同意', '朱君宜2018-05-29 17:28:47', '王维2018-05-29 16:42:16', '同意', '陶保荣2018-05-29 19:35:33', '', '', '', '', '同意', '丁富民2018-05-30 09:02:38', '王功勇2018-05-30 09:07:56', 'sctz2018052901', '01', '', '', '', 'L/C已收到，修改件暂未收到，建议下单，请领导审批。', '鲁慧珍2018-05-29 15:52:04', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('276', '{BC4D0EC4-8731-48AA-8540-3AC65AAE8839}', '61', 'INHE-0500', '2018-05-29 18:12:45', '0000-00-00 00:00:00', '2018-05-30 15:28:14', 'unchecked', 'n', 'n', '', '1', 'sctz2018052903/BAP05/生产通知单', '', '1.70台CT表其中50台按照按照BAP04翻单执行；\r\r\r\r\r\n2.另外20台请研发安排烧录BAP项目预付费实时需量扣款程序，将用作电力公司试点试挂。\r\n', '420', '2018-05-29 18:12:45', 'FactorFast (PTY) Ltd', 'BAP', 'BAP05', 'INHESC2018052301', '2018-07-07', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '05', '生产通知单', '结算方式：合同金额的30%生产前通过T/T支付，合同金额的70%发货前通过T/T支付。当前已收到30%预付款，同意生产。 		\r\n', '同意。请李忠鹏立即收尾款。后续10万美元以内的合同，一次性预付款收清。', '朱君宜2018-05-30 10:35:33', '郭涛2018-05-30 10:29:44', '同意', '陶保荣2018-05-30 11:05:52', '', '', '', '翻单生产，请江西工厂安排处理。', '同意。', '丁富民2018-05-30 11:53:49', '王功勇2018-05-30 14:37:34', 'sctz2018052903', '01', '', '', '', '30%T/T预付款已收齐，可以下单。', '鲁慧珍2018-05-29 18:39:19', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('277', '{C185DF39-8864-4215-8CFF-A6E3888B38E3}', '60', 'INHE-0066', '2018-05-31 15:40:29', '0000-00-00 00:00:00', '2018-06-07 08:06:27', 'unchecked', 'n', 'n', '', '1', 'sctz2018053101/白云801/生产通知单', '', '1、按2015年11月提供给客户的最近样机生产。（和602批次一样的出货，只是此次生产通知单没有按之前的整机下单，而是按散件下单。机芯和之前一样需要修调。）\r\r\r\r\r\r\n2、根据最新的报关要求，电表将分机芯（PCBA）、LCD显示板、铝面板、按键、五金件、磁卡、纸箱等几大部分出货。\r\r\r\r\r\r\n3、双回路计量。\r\r\r\r\r\r\n4、能支持复费率和阶梯电价两种结算方式。（默认设置见随后提供的出厂设置单）\r\r\r\r\r\r\n5、带远程通断电功能。\r\r\r\r\r\r\n6、负荷门限设置。\r\r\r\r\r\r\n7、能承受电压异常的瞬间波动，电压异常时，电表自动断电，电压恢复正常时，电表自动恢复供电。\r\r\r\r\r\r\n8、工厂出厂时直接编程设置为后付费模式，并激活继电器。 9、此次无需供塑胶底壳，其他配件保持不变。\r\r\r\r\r\r\n\r\r\r\r\r\r\n										\r\r\r\r\r\r\n										\r\r\r\r\r\r\n										\r\r\r\r\r\r\n										\r\r\r\r\r\r\n										\r\r\r\r\r\r\n										\r\r\r\r\r\r\n', '0', '2018-05-31 15:40:29', '\"Aspan-Energy \" LTD', '白云', '白云801', 'INHESC2018010902', '2018-06-15', '国际一部 INTL.Business Dept.1', '邱洁', '', '04', '生产通知单', '付款方式：预付款50%TT，50%发货前TT。当前已收到50%预付款，同意生产。', '同意', '朱君宜2018-06-05 16:51:12', '王维2018-06-05 15:01:09', '同意', '陶保荣2018-06-05 16:54:39', '', '', '', '翻单生产，请江西工厂安排处理。', '同意', '丁富民2018-06-05 19:49:59', '王功勇2018-06-05 22:41:43', 'sctz2018053101', '01', '', '', '', '50%T/T预付款已收齐，可以下单。', '鲁慧珍2018-06-05 14:53:56', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('278', '{BACD1563-962D-476A-9D11-E9AB76D7B4B5}', '60', 'INHE-0560', '2018-06-04 08:32:23', '0000-00-00 00:00:00', '2018-06-05 08:12:44', 'unchecked', 'n', 'n', '', '1', 'sctz2018060402/白雪807/生产通知单', '', '白雪单相表要求：\r\r\n1、采用新模具结构供货。     \r\r\n2、PCB板不需灌胶和喷三防漆！\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。      \r\r\n4、MAC地址为该表表号（表地址）的最后六位数字，该地址激光雕刻在表外壳背部。       \r\r\n5、PLC载波显示单元的铭牌标识为：CE208。         \r\r\n6、显示单元不需要贴易碎贴。        \r\r\n7、出厂设置：           \r\r\n1）表内时间为：GMT+4           \r\r\n2）冬夏令时转换功能关闭。           \r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\n5）特殊节假日没有。           \r\r\n6）电表密码：000000.           \r\r\n7）负荷门限：0.           \r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\n9）取负荷点的平均时间：30分钟。          \r\r\n8、继电器：100A，但标识采用120A。      \r\r\n9、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）       \r\r\n10、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\n11、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU的内盒中。\r\r\n12、计量单元删除年份信息（确保去掉年份信息后表号不发生左移或右移）\r\r\n	  										\r\r\n', '20040', '2018-06-04 08:32:23', 'Energomera CJSC', '白雪', '白雪807', 'PO#E18_1805', '2018-07-20', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '付款方式为15%-TT预付，75%-LC发货前付款。当前暂无收到预付款， 但王总已特批：详见OA邮件 ：“白雪807订单备料申请”同意生产。', '同意', '朱君宜2018-06-04 14:48:03', '王维2018-06-04 14:41:19', '同意', '陶保荣2018-06-04 14:59:05', '', '', '', '', '同意。', '丁富民2018-06-04 20:15:29', '王功勇2018-06-04 22:36:59', 'sctz2018060402', '01', '', '', '', '预付款未收到，但标题为“白雪807订单备料申请”的OA中王总已批示：同意先下单。', '鲁慧珍2018-06-04 09:30:37', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('279', '{EE95B2D7-DD09-45CC-8B63-33C1CD3105F5}', '60', 'INHE-0088', '2018-06-20 14:19:16', '0000-00-00 00:00:00', '2018-06-21 13:22:18', 'unchecked', 'n', 'n', '', '1', 'sctz2018062002/FU05/生产通知单', '', '翻单FU03,参考OA\"FU03项目翻单事宜\"，用于故障CIP更换库存，产品品号：0CIP01B13915，空运发货，不带电池，空白CIP表号流水号贴纸，不设表地址，客户自贴铭牌，铭牌年份2018，客户指定深圳货代，空运费客户自行承担。', '0', '2018-06-20 14:19:16', 'UTILA POWER COMPANY LTD.', 'FU', 'FU05', 'INHESC2018060801', '2018-07-31', '国际一部 INTL.Business Dept.1', '余冬纯', '', '06', '生产通知单', '结算方式：全款T/T预付		\r\n当前已收全款，同意生产。', '同意', '朱君宜2018-06-20 16:13:12', '王维2018-06-20 16:10:36', '同意', '陶保荣2018-06-20 16:58:38', '', '', '', '', '同意。---翻单产品，请江西工厂安排处理。', '丁富民2018-06-20 18:51:27', '王功勇2018-06-21 10:23:56', 'sctz2018062002', '01', '', '', '', '全款已收，可以下单。', '鲁慧珍2018-06-20 14:44:14', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('280', '{6A358BAB-F88C-4B27-AC94-255A794A13B1}', '61', 'INHE-0578', '2018-06-24 00:08:39', '0000-00-00 00:00:00', '2018-06-25 11:39:04', 'unchecked', 'n', 'n', '', '1', 'sctz2018062401/EXJ01/生产通知单', '', '1.DIN导轨表（除同EOI项目的2000台外）、BS单相、BS三相模块表，都需要支持TOU多费率、负荷曲线等功能；\r\n2.包装等需注意使用银河+NYC双logo。', '12000', '2018-06-24 00:08:39', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'EXJ', 'EXJ01', 'INHESC2018062001', '2018-07-24', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '', '02', '生产通知单', '结算方式：生产前TT支付263,750 USD，提单日后60天内TT支付 263,750 USD。当前已收到预收款，同意生产。		\r\n', '同意。请覃湘军注意EOI是供货不同市场，注意铭牌和规格。', '朱君宜2018-06-25 08:42:18', '郭涛2018-06-25 04:39:53', '同意', '陶保荣2018-06-25 10:28:42', '', '', '', '研发项目负责人：章春鹏   涉及到产品程序修改确认。', '同意。', '丁富民2018-06-25 10:43:08', '王功勇2018-06-25 11:35:16', 'sctz2018062401', '01', '', '', '', '', '', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('281', '{EBB52F50-55C5-4AF5-B90E-52513F676A51}', '61', 'INHE-0695', '2018-06-25 13:38:06', '0000-00-00 00:00:00', '2018-06-27 08:24:52', 'unchecked', 'n', 'n', '', '1', 'sctz2018062501/AN02/生产通知单', '', '上行GPRS,下行PLC。需配表箱，MCB，SPD和接线', '1000', '2018-06-25 13:38:06', 'Nayo Tropical Technology Limited', 'AN', 'AN02', 'INHESC2018052601', '2018-07-20', '国际二部 INTL.Business Dept.2', '卿于蓝', '', '05', '生产通知单', '结算方式：100%TT预付。当前已收到全款，同意生产。', '同意', '朱君宜2018-06-26 10:57:43', '郭涛2018-06-26 10:46:27', '同意', '陶保荣2018-06-26 14:09:18', '', '', '', '建议采用现有产品进行生产，具体请章春鹏处理。', '同意。', '丁富民2018-06-26 17:08:08', '王功勇2018-06-26 17:47:05', 'sctz2018062501', '01', '', '', '', '全款已收齐，可以下单。', '鲁慧珍2018-06-25 15:33:07', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('282', '{7C3233FF-27C7-4923-8CC0-A3E1DBB99682}', '61', 'INHE-0440', '2018-06-28 03:54:28', '0000-00-00 00:00:00', '2018-07-09 15:52:45', 'unchecked', 'n', 'n', '', '1', 'sctz2018062801/ITL02/生产通知单', '', '1.SKD的内盒包装, MCU和CIU的包装印上INHEMETER (T) LIMITED 和 www.inhemetertz.com， 外盒包装到货后，允许客户贴上MADE IN TANZANIA的标签。表箱上面的贴纸生产时根据客户要求定制。        2.SKD单相一体式GPRS模块表和SKD分体三相模块需要在我司工厂完成所有工序后，把机芯和表壳分开，客户在自己的工厂打下螺丝，铅封线，包装即可。                                                    					\r\r\n						\r\r\n', '10700', '2018-06-28 03:54:28', 'Africarriers Ltd', 'ITL', 'ITL02', 'INHESC2018032201', '2018-07-31', '国际二部 INTL.Business Dept.2', '汤伟(Will)', '第三方检验', '02', '生产通知单', '同意，此变更不影响合同金额，同意生产。', '同意', '朱君宜2018-08-06 17:40:34', '郭涛2018-08-06 16:13:22', '同意', '陶保荣2018-08-07 10:27:58', '', '', '另外：生产通知单包含订单合同（成交价格）是不妥当？', '10000台DIN导轨安装单相表研发已经给出BOM表，再正作程序测试验证。根据业务意见，200台BS安装单相一体式可更换通信模块表将按TTI方案翻单生产（SKD供货）；', '同意。', '丁富民2018-08-07 14:25:26', '王功勇2018-08-07 16:02:22', 'sctz2018062801', '01', '', '', '', '1.\"SKD分体式BS安装三相STS预付费可更换模块代码表（带CIF，GPRS模块和表箱）\"变更为  \"SKD分体式BS安装三相STS预付费可更换模块代码表（带CIF和表箱）\"只需要提供一个RF模块给到CIU,HHU和DCU通讯。 2.\"SKD一体式BS安装单相STS预付费可更换模块代码表（带GPRS模块）\" 变更为  \"SKD一体式BS安装单相STS预付费可更换模块代码表（带GPRS模块和键盘）\"电表MCU上面需要带键盘。3.ITL02 SKD总数量为 10700台。', '鲁慧珍2018-08-06 15:47:27', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('283', '{59A5CFCC-AB87-4042-B2C4-C1A5C88C5AD3}', '61', 'INHE-0500', '2018-07-03 12:39:40', '0000-00-00 00:00:00', '2018-07-04 17:52:39', 'unchecked', 'n', 'n', '', '1', 'sctz2018070301/EOI05/生产通知单', '', '', '1000', '2018-07-03 12:39:40', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI05', 'INHESC2018062801', null, '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '付款方式为合同金额的30%在签订合同10天内作为预付款T/T支付，70%余款在发货前T/T支付支付。当前30%预付款正在银行入账中，同意生产。		\r\r\n', '同意', '朱君宜2018-07-04 16:27:15', '郭涛2018-07-04 16:05:26', '同意', '陶保荣2018-07-04 17:01:50', '', '', '', 'EOI02项目的三相表正在研发设计阶段---王顺万负责', '同意。', '丁富民2018-07-04 17:26:58', '王功勇2018-07-04 17:28:59', 'sctz2018070301', '01', '', '', '', '30%预付款已到账，可以下单，要求交期2018/8/15', '鲁慧珍2018-07-04 14:30:35', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('285', '{CFA79357-0A3D-4D50-906C-7E5C11B88979}', '61', 'INHE-0690', '2018-07-11 10:13:38', '0000-00-00 00:00:00', '2018-07-11 14:35:03', 'unchecked', 'n', 'n', '', '1', 'sctz2018071102/IMF06/生产通知单', '', '1.KF02散件维修补料，交货比较紧急，希望能在7月18日采购完毕从工厂发货。\r\r\r\n2.IMF06的详细采购清单请见上述附件，请按照上述附件清单项目进行采购出货。                         3.上盖套件和底壳套件请安装在一起后发货。																						', '0', '2018-07-11 10:13:38', 'INHEMETER AFRICA CO., LTD.', 'IMF', 'IMF06', 'INHESC2018070901', '2018-07-18', '国际二部 INTL.Business Dept.2', '张正', '', '06', '生产通知单', '结算方式为提单日后120天T/T支付100%全款	，同意生产。', '同意', '朱君宜2018-07-11 11:44:39', '郭涛2018-07-11 11:33:53', '同意', '陶保荣2018-07-11 11:59:55', '', '', '', '', '同意', '丁富民2018-07-11 13:22:24', '王功勇2018-07-11 13:44:13', 'sctz2018071102', '01', '', '', '', '后付款订单，可以下单。', '鲁慧珍2018-07-11 10:31:35', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('286', '{082828E1-8D7D-4F42-B54A-E07F3707B181}', '60', 'INHE-0560', '2018-07-11 14:38:10', '0000-00-00 00:00:00', '2018-07-12 11:44:07', 'unchecked', 'n', 'n', '', '1', 'sctz2018071103/白雪808/生产通知单', '', '\r\r\r\n白雪三相表要求：\r\r\r\n\r\r\r\n1、采用双方验证过的程序版本TMF2-1B-16032201\r\r\r\n2、修改过脉冲输出的阻抗。						\r\r\r\n3. 铭牌、MAC地址等需要镭雕在电表外壳上； \r\r\r\n4. MAC地址铭牌的6位数字为该表表号的最后六位数字；\r\r\r\n5. 表内时间为GMT+3#FE54` \r\r\r\n6. 冬夏令时转换功能关闭； \r\r\r\n7. 需要把面板上的表号设到电表内 \r\r\r\n8. 计量单元不需要打铅封。\r\r\r\n9、计量单元、显示单元都不需要贴合格证 \r\r\r\n10、三相表默认密码为777777。 \r\r\r\n11：内盒不需要贴条形码\r\r\r\n12：计量单元和显示单元都取消易碎贴纸	  										\r\r\r\n', '3006', '2018-07-11 14:38:10', 'Energomera CJSC', '白雪', '白雪808', 'PO#E18_2506', '2018-10-01', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式为：15%T/T -下单时支付，85%每一批-LC 在每批货发货前7个工作日开出。当前已收到15%预付款，同意生产。		\r\n', '同意', '朱君宜2018-07-12 08:57:48', '王维2018-07-12 08:49:40', '同意', '陶保荣2018-07-12 09:34:48', '', '', '', '翻单生产，请江西工厂安排处理。', '同意。', '丁富民2018-07-12 10:13:18', '王功勇2018-07-12 10:25:36', 'sctz2018071103', '01', '', '', '', '15%预付款已收到，可以下单。', '鲁慧珍2018-07-12 08:43:02', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('287', '{6C8DEA8D-DEA0-4772-B16F-AA13BF5CC36A}', '61', 'INHE-0381', '2018-07-18 09:50:04', '0000-00-00 00:00:00', '2018-08-13 08:50:07', 'unchecked', 'n', 'n', '', '1', 'sctz2018071801/ING13/生产通知单', '', '1.从2018年7月16号起发往CDN的产品都要先进行第三方验货，本次订单开始会有泰纳到工厂检验。', '28272', '2018-07-18 09:50:04', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING13', '18000423 CA', '2018-08-20', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '第三方检验', '06', '生产通知单', '结算方式为100%LC，60天远期		\r\r\n当前ING13信用证正本已收到，同意生产。', '同意', '朱君宜2018-08-09 09:44:53', '郭涛2018-08-08 19:48:17', '同意', '陶保荣2018-08-09 10:26:17', '', '', '', '单相、三相直接接入式是翻单生产，请江西工厂安排处理；三相CT表BOM表已经确认，程序正在按客户要求修改之中，研发负责人王占颍。', '同意。', '丁富民2018-08-09 10:49:17', '王功勇2018-08-12 22:21:47', 'sctz2018071801', '01', '', '', '', 'L/C正本已收到，可以下单。（ERP 7/5已下单，要求交期8/1）', '鲁慧珍2018-08-08 14:24:40', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('288', '{E2581A83-E4AC-47F7-8EC8-7076FAEC05D0}', '60', 'INHE-0560', '2018-07-19 09:16:20', '0000-00-00 00:00:00', '2018-09-25 10:44:02', 'unchecked', 'n', 'n', '', '1', 'sctz2018071901/白雪809/生产通知单', '', '白雪单相表要求：\r\r\r\r\r\r\n1、采用新模具结构供货。     \r\r\r\r\r\r\n2、PCB板不需灌胶和喷三防漆！\r\r\r\r\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。      \r\r\r\r\r\r\n4、MAC地址为该表表号（表地址）的最后六位数字，该地址激光雕刻在表外壳背部。       \r\r\r\r\r\r\n5、PLC载波显示单元的铭牌标识为：CE208。         \r\r\r\r\r\r\n6、显示单元不需要贴易碎贴。        \r\r\r\r\r\r\n7、出厂设置：           \r\r\r\r\r\r\n1）表内时间为：GMT+4           \r\r\r\r\r\r\n2）冬夏令时转换功能关闭。           \r\r\r\r\r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\r\r\r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\r\r\r\r\n5）特殊节假日没有。           \r\r\r\r\r\r\n6）电表密码：000000.           \r\r\r\r\r\r\n7）负荷门限：0.           \r\r\r\r\r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\r\r\r\r\n9）取负荷点的平均时间：30分钟。          \r\r\r\r\r\r\n8、继电器：100A，但标识采用120A。      \r\r\r\r\r\r\n9、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）       \r\r\r\r\r\r\n10、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\r\r\r\r\n11、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU的内盒中。\r\r\r\r\r\r\n12、此订单的单相表不带显示单元	  										\r\r\r\r\r\r\n', '100', '2018-07-19 09:16:20', 'Energomera CJSC', '白雪', '白雪809', 'PO#E18_2206-T', '2018-07-25', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式：15%T/T -下单时支付，85%-发货前TT支付。当前预付款已收到，同意生产。', '同意', '朱君宜2018-07-20 09:22:03', '王维2018-07-20 09:13:45', '同意', '陶保荣2018-07-20 09:25:17', '', '', '', '', '同意，翻单生产，请江西工厂安排处理。', '丁富民2018-07-20 09:34:29', '王功勇2018-07-20 09:37:54', 'sctz2018071901', '01', '', '', '', '15%预付款已收到，可以下单。', '鲁慧珍2018-07-19 15:45:39', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('289', '{AE357F10-A4B8-47A4-909E-6B52EB1F0834}', '61', 'INHE-0500', '2018-07-20 13:35:13', '0000-00-00 00:00:00', '2018-07-23 15:20:02', 'unchecked', 'n', 'n', '', '1', 'sctz2018072001/EOI06/生产通知单', '', '技术规格同EOI05，翻单！\r\n', '200', '2018-07-20 13:35:13', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI06', 'INHESC2018071402', '2018-08-20', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式：合同金额的30%在签订合同10天内作为预付款T/T支付，70%余款在发货前T/T支付。当前出纳姚茜确认30%预付款已到建行，待提供合同后入账，交期比较紧，建议下单。										\r\n', '同意', '朱君宜2018-07-23 14:04:15', '郭涛2018-07-23 13:39:37', '同意', '陶保荣2018-07-23 14:14:55', '', '', '', 'EOI02/EOI05/EOI07翻单生产，请江西工厂安排处理。BOM表已发，程序本周完成。', '同意。', '丁富民2018-07-23 14:31:53', '王功勇2018-07-23 14:48:59', 'sctz2018072001', '01', '', '', '', '出纳姚茜确认30%预付款已到建行，待提供合同后入账，交期比较紧，建议下单。', '鲁慧珍2018-07-23 13:35:39', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('290', '{D9A9E0C6-BB2E-45BE-9D1B-14C4BA1431C9}', '61', 'INHE-0500', '2018-07-20 14:36:14', '0000-00-00 00:00:00', '2018-07-23 15:26:02', 'unchecked', 'n', 'n', '', '1', 'sctz2018072002/EOI07/生产通知单', '', '技术规格同EOI05一致，翻单！！！\r\n', '200', '2018-07-20 14:36:14', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI07', 'INHESC2018071801', '2018-08-20', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式：合同金额的30%在签订合同10天内作为预付款T/T支付，70%余款在发货前T/T支付。出纳姚茜确认30%预付款已到建行，待提供合同后入账，交期比较紧，建议下单。										\r\n		\r\r\r\n', '同意。注：立项客户名称同一个，买家多个。', '朱君宜2018-07-23 14:06:54', '郭涛2018-07-23 13:45:35', '同意', '陶保荣2018-07-23 14:14:33', '', '', '', 'EOI02\\EOI05项目二代三相代码表翻单，请江西工厂安排处理。BOM表已经确认，程序本周给出。', '同意。', '丁富民2018-07-23 14:29:37', '王功勇2018-07-23 14:49:34', 'sctz2018072002', '01', '', '', '', '出纳姚茜确认30%预付款已到建行，待提供合同后入账，交期比较紧，建议下单。', '鲁慧珍2018-07-23 13:37:40', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('291', '{4043F5FB-0486-4148-A279-037EDA306395}', '61', 'INHE-0636', '2018-07-20 15:12:35', '0000-00-00 00:00:00', '2018-07-23 10:29:22', 'unchecked', 'n', 'n', '', '1', 'sctz2018072003/KF03/生产通知单', '', '1.KF03项目115,230套电表全部按照成品供货给IAC，同KF02 9.6万套成品的出货状态，即成品：MCU(不打KEBS、打表号&条形码、不打产地)，CIU（打KEBS、不打表号&条形码、无需产地）；\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\n\r\r2.随货卡板需要先运至海外工厂，再发往电力公司，所以需要保障卡板质量，避免出现卡板质量差，货物倒塌的现象。', '115230', '2018-07-20 15:12:35', 'The Kenya Power * Lighting Company Limited', 'KF03', 'KF03', 'INHESC2018071301', '2018-09-17', '国际二部 INTL.Business Dept.2', '倪明杰', '第三方检验', '06', '生产通知单', '结算方式：每批发货的货值在提单日后120天采用T/T全款支付。赊销订单，同意生产。', '同意', '朱君宜2018-07-20 17:53:30', '郭涛2018-07-20 16:26:07', '同意', '陶保荣2018-07-23 08:28:56', '', '', '', '生产用BOM表近日提供（没有确认件为PCB板、继电器）；模具预计8月05日完成（曾年贵负责）；继电器8月31日具备批量供货条件（温燕负责）；PCB板及程序8月15日完成（章春鹏）；---研发项目负责人章春鹏。', '同意。', '丁富民2018-07-23 08:59:47', '王功勇2018-07-23 09:48:03', 'sctz2018072003', '01', '', '', '', '赊销订单，可以下单。', '鲁慧珍2018-07-20 16:08:56', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('292', '{86B0656C-5D22-42BA-A23A-82614D212E8B}', '61', 'INHE-0578', '2018-07-23 12:24:30', '0000-00-00 00:00:00', '2018-07-23 15:20:23', 'unchecked', 'n', 'n', '', '1', 'sctz2018072301/ESA14/生产通知单', '', '1. 负荷门限全部设置为4.6kW。2. 说明书装在CIU内盒内。3. 散件请配足量打包带。\r\n', '41000', '2018-07-23 12:24:30', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'ESA', 'ESA14', 'INHESC2018070301', '2018-08-01', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '', '02', '生产通知单', '结算方式：生产前通过TT支付281,300 USD,提单日后90天内TT支付1,125,200 USD.当前已收到预付款，同意生产。		\r\n', '同意', '朱君宜2018-07-23 13:59:41', '郭涛2018-07-23 13:38:14', '', '', '', '', '', '翻单生产，请江西工厂安排处理。', '同意。', '丁富民2018-07-23 14:26:32', '王功勇2018-07-23 14:29:20', 'sctz2018072301', '01', '', '', '', '预付款已收齐，可以下单。（7/5已ERP下单）', '鲁慧珍2018-07-23 13:29:50', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('293', '{7FC58390-20BF-4E2B-BDC2-6B5F97138B11}', '61', 'INHE-0500', '2018-07-24 21:12:47', '0000-00-00 00:00:00', '2018-07-26 08:55:50', 'unchecked', 'n', 'n', '', '1', 'sctz2018072401/EOI09/生产通知单', '', 'EOI项目翻单，请使用库存电表！', '600', '2018-07-24 21:12:47', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI09', 'INHESC2018072301', '2018-08-24', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式：合同30%预付款T/T支付，70%余款在发货前T/T支付。当前30%T/T预付款已收齐，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。				同意生产。						\r\r\n		\r\r\r\n', '同意使用EOI库存供货。', '朱君宜2018-07-25 18:20:56', '郭涛2018-07-25 15:08:44', '同意', '陶保荣2018-07-25 20:11:05', '', '', '', '业务说明使用EOI库存产品---请江西工厂安排处理。', '同意。', '丁富民2018-07-26 08:50:53', '王功勇2018-07-26 08:54:44', 'sctz2018072401', '01', '', '', '', '30%T/T预付款已收齐，可以下单。请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。', '鲁慧珍2018-07-25 13:33:27', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('294', '{11816629-C140-4779-BDA4-7F591498FA7A}', '61', 'INHE-0725', '2018-07-25 08:46:08', '0000-00-00 00:00:00', '2018-07-25 14:46:09', 'unchecked', 'n', 'n', '', '1', 'sctz2018072501/PAG01/生产通知单', '', '集中器建议翻单BAP05项目', '400', '', 'Process * Plant Automation Ltd', 'PAG', 'PAG01', 'INHESC2018062502', '2018-08-15', '国际二部 INTL.Business Dept.2', '赵政洁(Oscar)', '', '05', '生产通知单', '结算方式为：合同金额的30%在签订合同10天内作为预付款T/T支付，70%余款在发货前T/T支付。当前已收到预付款，同意生产。		\r\n', '同意', '朱君宜2018-07-25 11:36:09', '郭涛2018-07-25 11:25:44', '同意', '陶保荣2018-07-25 11:43:09', '', '', '', '业务已经明确每款产品的翻单说明。', '同意。翻单生产，请江西工厂安排处理。', '丁富民2018-07-25 13:56:31', '王功勇2018-07-25 14:44:04', 'sctz2018072501', '01', '', '', '', '30%T/T预付款已收到，可以下单。', '鲁慧珍2018-07-25 09:24:37', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('295', '{E1B319E3-34F0-4974-9AF6-8153979082F9}', '60', 'INHE-0560', '2018-07-27 13:49:50', '0000-00-00 00:00:00', '2018-07-30 14:42:31', 'unchecked', 'n', 'n', '', '1', 'sctz2018072701/白雪810/生产通知单', '', '\r\r\n白雪单相表要求：\r\r\n1、采用新模具结构供货。     \r\r\n2、PCB板不需灌胶和喷三防漆！\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。      \r\r\n4、MAC地址为该表表号（表地址）的最后六位数字，该地址激光雕刻在表外壳背部。       \r\r\n5、PLC载波显示单元的铭牌标识为：CE208。         \r\r\n6、显示单元不需要贴易碎贴。        \r\r\n7、出厂设置：           \r\r\n1）表内时间为：GMT+4           \r\r\n2）冬夏令时转换功能关闭。           \r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\n5）特殊节假日没有。           \r\r\n6）电表密码：000000.           \r\r\n7）负荷门限：0.           \r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\n9）取负荷点的平均时间：30分钟。          \r\r\n8、继电器：100A，但标识采用120A。      \r\r\n9、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）       \r\r\n10、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\n11、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU的内盒中。									\r\r\n12、单相表显示单元铭牌信息采用镭雕                                                             13、单相表不安装RF模块，不超声焊\r\r\n14、删除打标图上的版本号信息C2.OPR1.QD                                                         白雪三相表要求：\r\r\n1、采用双方验证过的程序版本TMF2-1B-16032201\r\r\n2、修改过脉冲输出的阻抗。						\r\r\n3. 铭牌、MAC地址等需要镭雕在电表外壳上； \r\r\n4. MAC地址铭牌的6位数字为该表表号的最后六位数字；\r\r\n5. 表内时间为GMT+3#FE54` \r\r\n6. 冬夏令时转换功能关闭； \r\r\n7. 需要把面板上的表号设到电表内 \r\r\n8. 计量单元不需要打铅封。\r\r\n9、计量单元、显示单元都不需要贴合格证 \r\r\n10、三相表默认密码为777777。 \r\r\n11：内盒不需要贴条形码\r\r\n12：计量单元和显示单元都取消易碎贴纸	  						   \r\r\n13、三相表不安装RF模块，不超声焊\r\r\n14、删除打标图上的版本号信息C36746OPR1.QYVFRP03			                                                         ', '150', '2018-07-27 13:49:50', 'Energomera CJSC', '白雪', '白雪810', 'PO#E18_1707-T', '2018-08-20', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式：15%T/T预付，85% T/T 发货前支付。当前已收到15%预付款，同意生产。', '同意', '朱君宜2018-07-30 08:54:18', '王维2018-07-29 10:15:35', '同意', '陶保荣2018-07-30 08:57:23', '', '', '', '', '同意。翻单生产请江西工厂安排处理。', '丁富民2018-07-30 12:01:49', '王功勇2018-07-30 14:13:37', 'sctz2018072701', '01', '', '', '', '15%T/T预付款已到账，可以下单。', '鲁慧珍2018-07-27 14:42:40', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('296', '{58975BD7-2034-4738-971F-D9AC9B97AA0E}', '61', 'INHE-0500', '2018-07-30 12:27:22', '0000-00-00 00:00:00', '2018-08-01 10:39:42', 'unchecked', 'n', 'n', '', '1', 'sctz2018073001/EOI08/生产通知单', '', '请使用EOI库存订单！！', '200', '2018-07-30 12:27:22', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI08', 'INHESC2018071401', '2018-08-30', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式：合同金额的100%在签订合同10天内作为预付款在发货前T/T支付。当前跟姚茜核实全款金额已到建行，已提交资料，等待入账，同意生产。		\r\n', '同意', '朱君宜2018-07-31 13:38:00', '郭涛2018-07-31 12:01:10', '同意', '陶保荣2018-07-31 14:11:08', '', '', '', '', '同意。翻单生产（业务提出库存产品）请江西工厂安排处理。', '丁富民2018-08-01 08:54:11', '王功勇2018-08-01 09:23:12', 'sctz2018073001', '01', '', '', '', '出纳姚茜确认此批全款已到建行，待提供合同等资料后即可入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2018-07-30 14:29:19', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('297', '{9AFA1CF5-D5BB-45DA-BD99-CD1692DA264B}', '61', 'INHE-0654', '2018-08-03 08:37:31', '0000-00-00 00:00:00', '2018-08-07 11:34:00', 'unchecked', 'n', 'n', '', '1', 'sctz2018080301/ADC02/生产通知单', '', '1，ADC02的2000台产品为ADC01的翻单，附件为客户确认的出厂设置单文件。                             2，显示单元要求不要带电池。\r\n3，交期要求为40至45天，美洲市场都需要当地认证，耗时耗力，该市场好不容易做完认证，订单数量较小，但也烦请公司给予美洲支持，抓紧时间安排生产，代理才能在当地更好更快的销售银河产品。                                                                                        4，注意前后端通信，余之前ADC01保持一致，支持前端集抄和后端显示单元显示，显示单元为用经过iram认证的H03VVH2-F插头，带保险管可更换电池版本。 见附件的CIP图片。                                                           5，预付费：密钥为：999937，电表的软件版本号17052603，短端子盖，继电器120A,内置PLC通讯模块。                                                                                                                             ', '2000', '2018-08-03 08:37:31', 'Cashpower Sudamericana S.A.', 'ADC', 'ADC02', 'INHES2018071002', '2018-09-10', '国际二部 INTL.Business Dept.2', '李明(Ming)', '', '05', '生产通知单', '结算方式：30%生产前TT预付款，70%发货前TT尾款。当前已收到30%预付款，同意生产。', '同意。但为了项目和市场健康发展，请李明整理合同项下技术规格，请技术支持评审签字，客户回签。银河不能靠自己的一张简单出厂设置单执行国际合同。因为并不是所有的市场和客户我们都可以随意，有些赔偿我们付不起。', '朱君宜2018-08-06 10:14:46', '郭涛2018-08-03 22:26:14', '同意', '陶保荣2018-08-06 12:31:40', '', '', '', '', '同意，业务说明是ADC01的翻单生产，请江西工厂安排处理。', '丁富民2018-08-07 09:15:48', '王功勇2018-08-07 10:54:31', 'sctz2018080301', '01', '', '', '', '30%预付款已到账，可以下单。', '鲁慧珍2018-08-03 14:09:09', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('298', '{BF6CD763-9536-4940-BB84-08015BB4A56D}', '61', 'INHE-0381', '2018-08-06 09:23:13', '0000-00-00 00:00:00', '2018-08-07 11:27:14', 'unchecked', 'n', 'n', '', '1', 'sctz2018080601/ING11/生产通知单', '', '1.外箱唛头信息：order num:18000116CA,ref:17000414ys. \r\n2.根据CDN现有新规定：发货前有第三方泰纳验货。需验货后才能发货。', '12672', '2018-08-06 09:23:13', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING11', '18000116 CA', '2018-09-03', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '第三方检验', '06', '生产通知单', '结算方式：100%LC，60天远期。当前信用证已收到且审核通过，同意下单。		\r\n', '同意', '朱君宜2018-08-06 13:46:47', '郭涛2018-08-06 11:42:39', '同意', '陶保荣2018-08-06 13:53:00', '', '', '', '', '同意，翻单生产，请江西工厂安排处理。', '丁富民2018-08-07 09:10:09', '王功勇2018-08-07 10:16:44', 'sctz2018080601', '01', '', '', '', '信用证收到且审核通过，可以下单。（7/13已ERP下单，要求交期8/15）', '鲁慧珍2018-08-06 09:51:47', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('299', '{C1E3FEC1-6930-4807-896D-211CB5C30771}', '61', 'INHE-0381', '2018-08-06 09:46:48', '0000-00-00 00:00:00', '2018-08-07 11:26:58', 'unchecked', 'n', 'n', '', '1', 'sctz2018080602/ING12/生产通知单', '', '1.外箱唛头信息：Ordre num:18000117CA,Ref#FE54`17000414YS.\r\n2.根据CDN新的进口规定，需要做第三方验货。货物需要验货后才能发。', '12672', '2018-08-06 09:46:48', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING12', '18000117 CA', '2018-09-28', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '第三方检验', '06', '生产通知单', '结算方式：100%LC，60天远期。当前信用证LC已收到且审核通过，同意下单。		\r\n', '同意', '朱君宜2018-08-06 13:50:01', '郭涛2018-08-06 11:45:17', '同意', '陶保荣2018-08-06 13:52:35', '', '', '', '', '同意，翻单生产，建议由江西工厂安排处理。', '丁富民2018-08-07 08:56:02', '王功勇2018-08-07 10:16:23', 'sctz2018080602', '01', '', '', '', 'L/C已收到且审核通过，可以下单。', '鲁慧珍2018-08-06 10:35:56', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('300', '{0D967AD8-764C-4DFE-A328-28BE436D4752}', '61', 'INHE-0381', '2018-08-06 13:39:32', '0000-00-00 00:00:00', '2018-08-06 15:43:45', 'unchecked', 'n', 'n', '', '1', 'sctz2018080603/ING12/生产通知单', '', '1.外箱唛头信息#FE54`order num:18000117CA,Ref:17000414YS.\r\n2.根据CDN新的进出口条款规定，进口的产品必须先做第三方验货。客户约的是泰纳检验。', '12672', '2018-08-06 13:39:32', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING12', '18000117 CA', '2018-09-28', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '第三方检验', '06', '生产通知单', '', '', '', '', '', '', '', '', '', '', '', '', '', 'sctz2018080603', '', '', '', '', '', '鲁慧珍2018-08-06 15:43:41', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('301', '{87FE908F-A835-41C8-B59A-A9D738CED3F4}', '61', 'INHE-0381', '2018-08-06 15:40:18', '0000-00-00 00:00:00', '2018-08-07 14:07:12', 'unchecked', 'n', 'n', '', '1', 'sctz2018080604/ING14/生产通知单', '', '1.外箱唛头信息：order num:18000439CA,Ref:18000045YS.\r\r\r\n2.根据CDN新的进出口条款规定，进口的产品必须先做第三方验货。客户约的是泰纳检验。', '25344', '2018-08-06 15:40:18', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING14', '18000439 CA', '2018-09-03', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '第三方检验', '06', '生产通知单', '结算方式为：100%LC，60天远期。当前LC已收到且审核通过，同意生产。', '同意', '朱君宜2018-08-06 17:31:06', '郭涛2018-08-06 16:40:12', '同意', '陶保荣2018-08-07 10:27:23', '', '', '', '', '同意。翻单产品，请江西工厂安排处理。', '丁富民2018-08-07 13:33:39', '王功勇2018-08-07 13:46:12', 'sctz2018080604', '01', '', '', '', 'L/C收到且审核通过，可以下单。（7/13已ERP下单，要求交期8/15）', '鲁慧珍2018-08-06 16:03:54', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('302', '{110A82E6-8012-439F-B61C-0ADC0CB36224}', '61', 'INHE-0381', '2018-08-06 16:01:44', '0000-00-00 00:00:00', '2018-08-07 14:06:46', 'unchecked', 'n', 'n', '', '1', 'sctz2018080605/ING15/生产通知单', '', '1.外箱唛头信息：order num:18000440CA,ref:18000045YS.\r\n2.出货前需要进行泰纳验货。', '25344', '2018-08-06 16:01:44', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING15', '18000440 CA', '2018-09-28', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '第三方检验', '06', '生产通知单', '结算方式：100%LC，60天远期。当前 LC已收到且审核通过，同意下单。		\r\n', '同意', '朱君宜2018-08-06 17:42:12', '郭涛2018-08-06 16:14:54', '同意', '陶保荣2018-08-07 10:26:54', '', '', '', '', '同意。翻单生产，请江西工厂安排处理。', '丁富民2018-08-07 13:32:14', '王功勇2018-08-07 13:45:45', 'sctz2018080605', '01', '', '', '', 'L/C收到且审核通过，可以下单。', '鲁慧珍2018-08-06 16:13:32', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('303', '{C61BFF3C-AED7-4424-86BA-3869B98FF213}', '60', 'INHE-0066', '2018-08-13 09:37:05', '0000-00-00 00:00:00', '2018-08-21 09:10:28', 'unchecked', 'n', 'n', '', '1', 'sctz2018081301/白云802/生产通知单', '', '1、按2015年11月提供给客户的最近样机生产。（和801批次一样的出货，此次生产通知单没有按之前的整机下单，而是按散件下单。机芯和之前一样需要修调。）\r\r\n2、根据最新的报关要求，电表将分机芯（PCBA）、LCD显示板、铝面板、按键、五金件、磁卡、纸箱等几大部分出货。\r\r\n3、双回路计量。\r\r\n4、能支持复费率和阶梯电价两种结算方式。（默认设置见随后提供的出厂设置单）\r\r\n5、带远程通断电功能。\r\r\n6、负荷门限设置。\r\r\n7、能承受电压异常的瞬间波动，电压异常时，电表自动断电，电压恢复正常时，电表自动恢复供电。\r\r\n8、工厂出厂时直接编程设置为后付费模式，并激活继电器。 9、此次无需供塑胶底壳，其他配件保持不变。（热熔铜螺母、挂钩片、孔镜等都需要配备）\r\r\n\r\r\n										\r\r\n										\r\r\n										\r\r\n										\r\r\n										\r\r\n										\r\r\n										\r\r\n', '0', '2018-08-13 09:37:05', '\"Aspan-Energy \" LTD', '白云', '白云802', 'INHESC2018060702', '2018-09-05', '国际一部 INTL.Business Dept.1', '邱洁', '', '04', '生产通知单', '同意。结算方式：50%TT-预付款下单时支付，50%TT-发货前支付。当前已收到50%预付款，同意生产。', '同意', '朱君宜2018-08-20 17:55:35', '王维2018-08-20 17:18:03', '同意', '陶保荣2018-08-20 18:58:33', '', '', '', '', '同意，翻单生产请江西工厂处理。', '丁富民2018-08-20 19:22:08', '王功勇2018-08-20 21:34:37', 'sctz2018081301', '01', '', '', '', '50%T/T预付款已收齐，可以下单。', '鲁慧珍2018-08-20 17:08:14', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('304', '{F04CE559-961E-468A-B212-9258ACAE0E2C}', '61', 'INHE-0713', '2018-08-20 09:08:42', '0000-00-00 00:00:00', '2018-08-21 09:20:20', 'unchecked', 'n', 'n', '', '1', 'sctz2018082001/MLC01/生产通知单', '', '', '9524', '2018-08-20 09:08:42', 'Energie du Mali –SA', 'MLC', 'MLC01', 'INHESC2018081301', '2018-09-10', '国际二部 INTL.Business Dept.2', '苏宏', '', '04', '生产通知单', '同意，结算方式为50%TT预付款生产前支付，50%TT尾款发货前支付。当前已收到50%预付款，同意生产。	\r\n', '同意', '朱君宜2018-08-20 15:40:09', '郭涛2018-08-20 15:21:47', '同意', '陶保荣2018-08-20 18:58:12', '', '请注意丁总的要求。', '', '在合同评审时提出，是否需要带配件（熔断器、断路器）以及集抄请说明。或者不要出现所谓的“单相智能电表带键盘及配件”的技术要求，避免大家混乱。', '不同意。', '丁富民2018-08-20 19:20:11', '王功勇2018-08-20 21:33:54', 'sctz2018082001', '02', '', '', '', '50%T/T预付款已到账，可以下单。', '鲁慧珍2018-08-20 10:17:07', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('305', '{C1322F7B-3624-4D11-9539-C38E93B6D65B}', '61', 'INHE-0713', '2018-08-20 09:31:19', '0000-00-00 00:00:00', '2018-08-23 08:39:52', 'unchecked', 'n', 'n', '', '1', 'sctz2018082003/MLCB/生产通知单', '', '1.此订单不涉及配件，客户购买的仅仅是电表\r\r\r\r\n\r\r\r\r\n2.已经更新技术规格，较前一份相比删除无关配件技术规格描述。\r\r\r\n\r\r\r\n\r\r\r\n3.MLC项目与MLB03项目为同一市场，MLC项目投标时使用的是MLB03项目的投标资料，MLC技术规格中要求的抄表技术，投标中银河提交的方案是：用i6300掌机，通过红外头抄电表。\r\r\r\n\r\r\r\n\r\r\r\n4.MLC订单尚未开始备料										\r\r\n', '476', '2018-08-20 09:31:19', 'Energie du Mali –SA', 'MLC', 'MLCB', 'INHESC2018081501', '2018-09-10', '国际二部 INTL.Business Dept.2', '苏宏', '', '04', '生产通知单', '同意。付款方式：合同金额的100%作为全款将通过银行转账在生产前支付。此订单用押金冲抵全款，同意生产。', '同意', '朱君宜2018-08-22 14:54:32', '郭涛2018-08-22 14:53:40', '同意', '陶保荣2018-08-22 15:00:43', '', '', '', 'MLB03项目产品翻单（业务建议），与MLB03项目技术要求一致；并确认使用光学通信接口实现抄表要求。MLB03项目产品翻单生产，请江西工厂安排处理。 ', '同意。', '丁富民2018-08-22 18:00:09', '王功勇2018-08-22 21:55:29', 'sctz2018082003', '01', '', '', '', '全款由押金充抵，可以下单。', '鲁慧珍2018-08-22 11:45:42', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('306', '{EFF7629A-7413-487F-890E-DBA8D9BB0FB5}', '61', 'INHE-0713', '2018-08-21 09:53:24', '0000-00-00 00:00:00', '2018-08-23 08:39:40', 'unchecked', 'n', 'n', '', '1', 'sctz2018082102/MLC01/生产通知单', '', '1.此订单不涉及配件，客户购买的仅仅是电表\r\r\r\r\n\r\r\r\r\n2.已经更新技术规格，较前一份相比删除无关配件技术规格描述。\r\r\r\n\r\r\r\n\r\r\r\n3.MLC项目与MLB03项目为同一市场，MLC项目投标时使用的是MLB03项目的投标资料，MLC技术规格中要求的抄表技术，投标中银河提交的方案是：用i6300掌机，通过红外头抄电表。\r\r\r\n\r\r\r\n\r\r\r\n4.MLC订单尚未开始备料', '9524', '', 'Energie du Mali –SA', 'MLC', 'MLC01', 'INHESC2018081301', '2018-09-10', '国际二部 INTL.Business Dept.2', '苏宏', '', '04', '生产通知单', '同意。结算方式为50%预付款生产前支付，50%尾款发货前支付	。当期已收到50%预付款，同意生产。	\r\n', '同意。其它事项说明：投标方案是，用掌机红外抄表。', '朱君宜2018-08-22 14:51:54', '郭涛2018-08-22 14:46:28', '同意', '陶保荣2018-08-22 15:00:09', '', '', '', 'MLB03项目产品翻单（业务意见），本次要求与MLB03要求一样，并说明光学通信接口实现抄表功能。请江西工厂安排处理。', '同意。', '丁富民2018-08-22 17:57:03', '王功勇2018-08-22 21:54:59', 'sctz2018082102', '01', '', '', '', '50%T/T预付款已到账，可以下单。', '鲁慧珍2018-08-22 11:46:36', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('307', '{D996B9B1-0750-4F3B-8266-3D017F2E82FA}', '60', 'INHE-0560', '2018-08-29 16:37:47', '0000-00-00 00:00:00', '2018-08-30 10:29:50', 'unchecked', 'n', 'n', '', '1', 'sctz2018082902/白雪811/生产通知单', '', '白雪单相表要求：\r\r\n1、采用新模具结构供货。     \r\r\n2、PCB板不需灌胶和喷三防漆！\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。      \r\r\n4、MAC地址为该表表号（表地址）的最后六位数字，该地址激光雕刻在表外壳背部。       \r\r\n5、PLC载波显示单元的铭牌标识为：CE208。         \r\r\n6、显示单元不需要贴易碎贴。        \r\r\n7、出厂设置：           \r\r\n1）表内时间为：GMT+4           \r\r\n2）冬夏令时转换功能关闭。           \r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\n5）特殊节假日没有。           \r\r\n6）电表密码：000000.           \r\r\n7）负荷门限：0.           \r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\n9）取负荷点的平均时间：30分钟。          \r\r\n8、继电器：100A，但标识采用120A。      \r\r\n9、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）       \r\r\n10、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\n11、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU的内盒中。\r\r\n12、此订单的单相表不带显示单元	  										\r\r\n										\r\r\n', '10', '2018-08-29 16:37:47', 'Energomera CJSC', '白雪', '白雪811', 'PO#E18_2408-T', '2018-09-04', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式为 发货前 100%付款。当前未收款，同意先下单。', '同意', '朱君宜2018-08-30 08:56:46', '王维2018-08-30 08:28:43', '同意', '陶保荣2018-08-30 09:12:35', '', '', '', '', '同意，翻单生产，请江西工厂安排处理', '丁富民2018-08-30 10:08:09', '王功勇2018-08-30 10:22:49', 'sctz2018082902', '01', '', '', '', '结算方式为发货前T/T全款，可以下单。', '鲁慧珍2018-08-29 17:50:13', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('308', '{A0C771A0-4421-40CD-A16C-B21C146FAA17}', '61', 'INHE-0654', '2018-08-29 16:52:03', '0000-00-00 00:00:00', '2018-08-30 10:29:11', 'unchecked', 'n', 'n', '', '1', 'sctz2018082903/CHL01/生产通知单', '借于客户已经支付预付款，先下发生产通知单，工厂可以准备采购物料。', '1，电表要支持停电上报的功能，BS安装单相可更换模块智能电表一体式，模块型号以及数量客户后期确认，先生产制作电表。2，规格要求要符合CHL的样机，与CHL的样机一致，具体可参考附件。3，请工厂可以较快交货，交期要求为40-45天。4，客户已经支付50%的预付款。', '1000', '2018-08-29 16:52:03', 'EDALTEC GRUPO', 'CHL', 'CHL01', 'INHESC2018081403', '2018-10-20', '国际二部 INTL.Business Dept.2', '李明(Ming)', '', '05', '生产通知单', '结算方式：50%生产前T/T预付款，50%发货前T/T尾款	。当前已收到预付款50%，同意生产。	\r\n', '同意', '朱君宜2018-08-30 09:00:11', '郭涛2018-08-30 02:04:20', '同意', '陶保荣2018-08-30 09:11:42', '', '', '', '根据技术要求，需要作产品硬件方面修改变动，也需要作嵌入式软件修改、测试验证。--可以先按MD01项目单相模块表备料（不代键盘，对称接线方式）', '同意。', '丁富民2018-08-30 10:07:06', '王功勇2018-08-30 10:22:27', 'sctz2018082903', '01', '', '', '', '50%T/T预付款已到账，可以下单。', '鲁慧珍2018-08-29 17:30:59', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('309', '{AB5A2C18-965F-4F60-85FC-5E42173AE203}', '61', 'INHE-0593', '2018-08-29 18:06:42', '0000-00-00 00:00:00', '2018-08-30 16:46:23', 'unchecked', 'n', 'n', '', '1', 'sctz2018082904/CM03/生产通知单', '', '1500台电表表号文件请见附件', '0', '2018-08-29 18:06:42', 'SOCIETE GENERALE D`ELECTRONIQUE#FE54`TOGO ASSISTANCE SERVICES', 'CM', 'CM03', 'INHESC2018080601', '2018-09-12', '国际二部 INTL.Business Dept.2', '胡蝶', '', '06', '生产通知单', '经核实，CM03合同未涉及电表背部贴纸收费且未收到经公司同意的OA邮件，请领导审批是否免费提供1500张铭牌对应的电表背部贴纸，谢谢~\r\n', '同意', '朱君宜2018-09-21 14:20:17', '郭涛2018-09-21 13:31:13', '同意', '陶保荣2018-09-21 14:24:01', '', '应该提交相关OA给财务作为审核依据。', '', '', '同意', '丁富民2018-09-23 11:58:15', '王功勇2018-09-25 08:38:56', 'sctz2018082904', '01', '', '', '', '', '鲁慧珍2018-09-21 08:36:22', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('310', '{9D1C9396-87FE-4368-B5A6-903F93D49752}', '60', 'INHE-0088', '2018-08-29 18:33:08', '0000-00-00 00:00:00', '2018-08-30 10:29:07', 'unchecked', 'n', 'n', '', '1', 'sctz2018082905/ST20710/生产通知单', '', '订单编号：ST20710-4\r\r\n1. 参考ST20710-3 翻单资料无须修改；\r\r\r\r\n2. PCBA,LCD重要物料打托，金属件/电池物料打木箱，生产后提供该批次表号数据及密钥文件。', '66700', '2018-08-29 18:37:00', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20710', 'INHESC2017092801', '2018-10-15', '国际一部 INTL.Business Dept.1', '余冬纯', '', '02', '生产通知单', '结算方式：不可撤销非保兑即期信用证，信用证下10%预付，90%交发货单据扫描件议付。王总特批先下单，请业务跟催客户尽快开来L/C。同意先下单。										\r\r\n	\r\r\r\r\n', '同意', '朱君宜2018-08-30 10:05:22', '王维2018-08-30 09:47:55', '同意', '陶保荣2018-08-30 10:06:34', '', '提前下单，请业务紧密跟催LC。', '', '', '同意。翻单生产，请江西工厂安排处理。', '丁富民2018-08-30 10:12:19', '王功勇2018-08-30 10:21:38', 'sctz2018082905', '01', '', '', '', '王总特批先下单，请业务跟催客户尽快开来L/C。', '鲁慧珍2018-08-30 08:39:53', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('311', '{ECC33F99-643E-4334-BB98-22FA5584AE4D}', '61', 'INHE-0500', '2018-08-30 00:07:43', '0000-00-00 00:00:00', '2018-08-30 16:46:05', 'unchecked', 'n', 'n', '', '1', 'sctz2018083001/EOI10/生产通知单', '', '1.出货时请按照表号顺序对应外箱及表号文件顺序包装；\r\n2.请使用EOI库存订单\r\n', '4100', '2018-08-30 00:07:43', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI10', 'INHESC2018080301', '2018-09-03', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式：合同金额的30%在签订合同10天内作为预付款T/T支付，70%余款在发货前T/T支付。当前出纳姚茜确认此批全款已到建行，待提供合同等资料后即可入账。同意下单。					\r\r\n		\r\r\r\n', '同意', '朱君宜2018-08-30 14:19:22', '郭涛2018-08-30 13:55:48', '同意。', '陶保荣2018-08-30 14:31:27', '', '', '', '', '同意。翻单生产，请江西工厂安排处理。', '丁富民2018-08-30 15:50:44', '王功勇2018-08-30 15:53:54', 'sctz2018083001', '01', '', '', '', '出纳姚茜确认此批全款已到建行，待提供合同等资料后即可入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2018-08-30 08:41:46', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('312', '{7BEDB2E7-BEF2-4057-AB8F-CF1D9F4A4C97}', '60', 'INHE-0066', '2018-08-31 16:03:42', '0000-00-00 00:00:00', '2018-09-03 13:21:20', 'unchecked', 'n', 'n', '', '1', 'sctz2018083101/白云804/生产通知单', '', '白云项目单、三相载波代码预付费电表上用到的配件，客户买来用于维修当地的坏表。', '0', '2018-08-31 16:03:42', '\"Aspan-Energy \" LTD', '白云', '白云804', 'INHESC2018081601', '2018-09-12', '国际一部 INTL.Business Dept.1', '邱洁', '', '05', '生产通知单', '结算方式：50%TT-预付款，50%TT-尾款发货前付清。当前已收到全款，同意生产。		\r\n', '同意', '朱君宜2018-09-03 09:03:19', '王维2018-09-03 08:39:19', '同意', '陶保荣2018-09-03 10:48:49', '', '', '', '', '同意。翻单表计配件，请江西工厂安排处理。', '丁富民2018-09-03 11:23:13', '王功勇2018-09-03 11:39:13', 'sctz2018083101', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2018-08-31 16:28:49', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('313', '{4B6FD151-D7EA-45A4-B096-1E59438CFEC9}', '61', 'INHE-0500', '2018-09-05 10:14:46', '0000-00-00 00:00:00', '2018-09-05 11:24:27', 'unchecked', 'n', 'n', '', '1', 'sctz2018090501/EOI10/生产通知单', '', '请按照和EOI库存订单执行和出货\r，发货时请跟单组和李忠鹏确认配传单和其他资料，有专门的OA进行安排，谢谢！\r\r\n', '4100', '2018-09-05 10:14:46', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI10', 'INHESC2018080301', '2018-09-09', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '', '', '', '', '', '', '', '', '', '', '', '', '', 'sctz2018090501', '', '', '', '', '', '鲁慧珍2018-09-05 11:24:22', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('314', '{23EE9479-8068-40EF-A779-ABA092041576}', '60', 'INHE-0560', '2018-09-05 16:46:32', '0000-00-00 00:00:00', '2018-09-06 13:46:12', 'unchecked', 'n', 'n', '', '1', 'sctz2018090503/白雪814/生产通知单', '', '', '0', '2018-09-05 16:46:32', 'Energomera CJSC', '白雪', '白雪814', 'PO#E18_0309', '2018-09-20', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式：发货前100%支付。当前暂未收到款，同意先生产。		\r\n', '同意', '朱君宜2018-09-06 08:55:31', '王维2018-09-06 08:31:50', '同意', '陶保荣2018-09-06 08:56:21', '', '', '', '', '同意。', '丁富民2018-09-06 11:07:15', '王功勇2018-09-06 13:44:07', 'sctz2018090503', '01', '', '', '', '结算方式为发货前100%T/T，可以下单。', '鲁慧珍2018-09-05 17:14:16', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('315', '{52A8A917-6849-48AF-BA6B-D0F1A8158B2A}', '60', 'INHE-0560', '2018-09-05 16:49:07', '0000-00-00 00:00:00', '2018-09-10 17:03:34', 'unchecked', 'n', 'n', '', '1', 'sctz2018090504/白雪812/生产通知单', '', '', '0', '2018-09-05 16:49:07', 'Energomera CJSC', '白雪', '白雪812', 'PO#E18_2308', '2018-09-20', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式：15%TT预付，85%发货前付款。当前已收到预付款，同意生产。', '同意', '朱君宜2018-09-10 13:30:21', '王维2018-09-10 13:23:01', '同意', '陶保荣2018-09-10 13:57:02', '', '', '', '', '同意', '丁富民2018-09-10 13:58:02', '王功勇2018-09-10 16:05:32', 'sctz2018090504', '01', '', '', '', '15%T/T预付款已到账，可以下单。', '鲁慧珍2018-09-07 17:50:12', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('316', '{DFC017D5-B74F-43C1-8A76-2426B9C54336}', '61', 'INHE-0500', '2018-09-06 07:06:59', '0000-00-00 00:00:00', '2018-09-07 13:53:53', 'unchecked', 'n', 'n', '', '1', 'sctz2018090601/EOI04/生产通知单', '', '请按照EOI库存订单出货\r\n', '1000', '2018-09-06 07:06:59', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI04', 'INHESC2018051002', '2018-09-09', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式：合同金额100%在签订合同30天内并在发货前作为预付款T/T支付。当前已收到全款，同意生产。', '同意', '朱君宜2018-09-07 09:02:16', '郭涛2018-09-06 18:17:06', '同意', '陶保荣2018-09-07 09:15:25', '', '', '', '', '同意，库存产品出货。', '丁富民2018-09-07 09:37:59', '王功勇2018-09-07 13:51:19', 'sctz2018090601', '01', '', '', '', '全款已到账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2018-09-06 18:11:43', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('317', '{09B562EF-C06B-49DD-86AF-A85E84BD83C9}', '60', 'INHE-0712', '2018-09-07 08:45:21', '0000-00-00 00:00:00', '2018-09-10 15:33:28', 'unchecked', 'n', 'n', '', '1', 'sctz2018090701/DPDC801/生产通知单', '', '1.参考DPDC601订单；\r\r\n\r\r\r\n2.客户要求DHL 空运，不能人工携带入境', '0', '2018-09-07 08:45:21', 'Ideal Enterprise', 'DPDC', 'DPDC801', 'INHESC2018080701', '2018-09-18', '国际一部 INTL.Business Dept.1', '杨晓婷', '', '06', '生产通知单', '付款方式：全款T/T预付。当前已收到全款，同意生产。		\r\n', '同意', '朱君宜2018-09-17 09:04:54', '王维2018-09-17 08:59:45', '同意', '陶保荣2018-09-17 10:06:42', '', '', '', '', '同意', '丁富民2018-09-17 14:28:19', '王功勇2018-09-17 22:14:42', 'sctz2018090701', '01', '', '', '', 'OK', '鲁慧珍2018-09-14 14:39:25', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('318', '{64915306-B5F5-42A7-8065-761B46775673}', '60', 'INHE-0088', '2018-09-10 15:30:40', '0000-00-00 00:00:00', '2018-10-19 12:55:33', 'unchecked', 'n', 'n', '', '1', 'sctz2018091001/ST20801/生产通知单', '', '1. 需配合尽快采购到位，海运发货以完成信用证议付，交期过长配件建议快递处理；\r\r\r\n2. 特殊产品物料需跟单组配合完成发货；\r\r\r\n3. 生产必须使用的耗材及工具，技术规格参考附件“ST20801需求明细”\r\r\r\n请协助配合采购。', '0', '2018-09-10 15:30:40', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20801', 'INHESC2017122402', '2018-09-30', '国际一部 INTL.Business Dept.1', '余冬纯', '', '06', '生产通知单', '结算方式：即期信用证，信用证下10%预付，90%交单议付。当前已收到10%预付款，同意生产。			\r\n', '同意', '朱君宜2018-10-18 08:52:49', '王维2018-10-18 08:46:21', '同意', '陶保荣2018-10-18 08:53:59', '', '“90%交代议付”还是“90%凭提单扫描件议付，到账后寄提单原件”？', '', '', '同意', '丁富民2018-10-18 22:40:51', '王功勇2018-10-19 12:17:14', 'sctz2018091001', '01', '', '', '', '10%L/C预付款已到账，可以下单。', '鲁慧珍2018-10-16 18:20:37', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('319', '{17C35654-A066-483F-95DF-FE27B89C7501}', '61', 'INHE-0440', '2018-09-13 16:20:37', '0000-00-00 00:00:00', '2018-09-14 13:22:21', 'unchecked', 'n', 'n', '', '1', 'sctz2018091301/ITL03/生产通知单', '', '1.SKD的内盒包装, MCU和CIU的包装印上INHEMETER (T) LIMITED 和 www.inhemetertz.com， 外盒包装到货后，允许客户贴上MADE IN TANZANIA的标签。表箱上面的贴纸生产时根据客户要求定制。        2.SKD分体三相模块需要在我司工厂完成所有工序后，客户在自己的工厂打下螺丝，铅封线，包装即可。                                                    					\r', '28200', '2018-09-13 16:20:37', 'Africarriers Ltd', 'ITL', 'ITL03', 'INHESC2018060401', '2018-10-17', '国际二部 INTL.Business Dept.2', '汤伟(Will)', '第三方检验', '02', '生产通知单', '\r\r\r\r\r\n付款方式为：5%预付款T/T支付，95%通过不可撤销的保兑的远期180天的L/C支付（承兑和贴现费用由客户承担）.当前T/T预付款已到帐，L/C未收到，但王总已特批，详见OA邮件：“\rTTA01项目订单生产、发货、议付跟踪”同意\r\r立刻下达ITL03订单28200台。			\r\r\r\r\r\n						\r\r\r\r\r\n', '同意', '朱君宜2018-09-14 09:04:27', '郭涛2018-09-13 23:05:31', '同意', '陶保荣2018-09-14 10:11:58', '', '', '', '翻单生产，请江西工厂安排处理。', '同意。', '丁富民2018-09-14 10:35:46', '王功勇2018-09-14 11:12:42', 'sctz2018091301', '01', '', '', '', 'T/T预付款已到账，L/C未收到，但王总在标题为“TTA01项目订单生产、发货、议付跟踪”的OA中已特批同意立即下达ITL03订单28200台。', '鲁慧珍2018-09-13 17:19:53', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('320', '{95E10700-D7CB-4728-B61E-EA9049D2682E}', '61', 'INHE-0578', '2018-09-14 14:22:40', '0000-00-00 00:00:00', '2018-09-18 08:23:44', 'unchecked', 'n', 'n', '', '1', 'sctz2018091401/N4-3/生产通知单', '', '货已由深圳采购购买、业务人员带走，工厂无需再安排采购。此流程为补充流程，请工厂补出入库手续。', '0', '2018-09-14 14:22:40', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'N', 'N4-3', 'INHESC2018091101', '2018-09-09', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '', '06', '生产通知单', '补流程，款未收，业务携带给客户，请业务及时追回款。', '同意。请覃湘君负责收回货款，也请财务和跟单督促覃湘君和我。', '朱君宜2018-09-17 09:08:15', '郭涛2018-09-16 00:02:20', '同意', '陶保荣2018-09-17 10:05:56', '', '', '', '', '同意。', '丁富民2018-09-17 14:25:46', '王功勇2018-09-17 22:15:12', 'sctz2018091401', '01', '', '', '', '补流程，款未收，但已发货。', '鲁慧珍2018-09-14 14:39:02', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('321', '{870D5B48-89B9-4045-B1C8-F6990BA2344D}', '60', 'INHE-0066', '2018-09-20 11:23:28', '0000-00-00 00:00:00', '2018-12-21 10:55:27', 'unchecked', 'n', 'n', '', '1', 'sctz2018092002/白云803/生产通知单', '', '三相表特殊要求或者补充说明：\r\r\r\r\r\r\n\r\r\r\r\r\r\n 1、有两种设计方案的面板，每种设计方案的面板各配一个。其中附件1面板： “INHE-0S01-TKP1-3D14416-01 铭牌---20140422 ”贴在表上，附件2面板“INHE-0S01-TKP1-3D14416-02 铭牌---20140422 单独包装出货”\r\r\r\r\r\r\n单独包装出货。\r\r\r\r\r\r\n2、能支持复费率和阶梯电价两种金额结算方式 \r\r\r\r\r\r\n3、带远程通断电功能 \r\r\r\r\r\r\n4、负荷门限设置 \r\r\r\r\r\r\n5、能承受电压异常的瞬间波动，电压异常时，电表自动断电，电压恢复正常时，电表恢复供电。 \r\r\r\r\r\r\n6、可编程后付费功能。\r\r\r\r\n7、内盒不需要任何图案和文字。\r\r\r\r\n\r\r\r\r\n\r集中器特殊要求或者补充说明：\r\n\r\n1、低压载波集中器，上行GPRS通信，下行载波通信。   \r\n2、必须具备三相表计量功能。   \r\n3、出货时包装上不要显示集中器等字样，客户那边把集中器当三相表来进口，以减少海关不必要的麻烦。  \r\n4、面板上需显示型号为：  DJZ22-INHE10  \r\n										\r\n\r\r\n\r\r\r\r\r\r\n', '500', '2018-09-20 11:23:28', '”Aspan-Energy“LTD', '白云', '白云803', 'INHESC2018081001', '2019-01-09', '国际一部 INTL.Business Dept.1', '邱洁', '', '05', '生产通知单', '结算方式:50%T/T-预付款，50%T/T-发货前支付。当前部分预付款尾款在银行,待入账,同意发货.		\r\n', '同意', '朱君宜2018-12-20 16:39:09', '王维2018-12-20 15:35:20', '同意', '陶保荣2018-12-20 17:14:52', '', '', '', '翻单生产，请江西工厂安排。', '同意。', '丁富民2018-12-21 09:47:46', '王功勇2018-12-21 10:41:27', 'sctz2018092002', '01', '', '', '', '50%预付款尾款出纳姚茜确认已到银行，待走流程入账，建议下单。', '鲁慧珍2018-12-20 11:21:12', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('322', '{8AE51E18-421A-4939-BBDB-BCA2AC80B107}', '61', 'INHE-0578', '2018-09-25 14:45:53', '0000-00-00 00:00:00', '2018-09-26 09:39:33', 'unchecked', 'n', 'n', '', '1', 'sctz2018092502/N4-4/生产通知单', '', '1. 此项目与EST项目紧密相关，交期需要全方面争取，对EST项目中标重要！\r\r\n\r\r\n\r\r\n2. 此项目部分设备与EST项目的新DIN产品结构紧密相关，需尽快确认DIN结构等等。\r\n\r\n\r\n3. 此项目设备需要工程师验货，需要公司内部协调安排好以便节省时间。', '0', '2018-09-25 14:45:53', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'N', 'N4-4', 'INHESC2018091401', '2018-11-30', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '', '06', '生产通知单', 'N4-4项目2个产品型号有变化，部分产品数量有变化，当前预付款已收，同意生产。', '同意', '朱君宜2018-11-05 11:00:16', '郭涛2018-11-02 18:32:58', '同意', '陶保荣2018-11-05 11:25:03', '', '', '', '', '同意', '丁富民2018-11-05 15:48:25', '王功勇2018-11-05 15:54:12', 'sctz2018092502', '01', '', '', '', '不涉及款项；请采购部门仔细核对变更内容，尽早交货，谢谢！', '鲁慧珍2018-11-02 17:53:28', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('323', '{53971B9B-D420-4A64-A66B-9CD935931D04}', '61', 'INHE-0725', '2018-09-26 16:41:00', '0000-00-00 00:00:00', '2018-09-28 09:39:14', 'unchecked', 'n', 'n', '', '1', 'sctz2018092601/PAG02/生产通知单', '', '该产品工厂已生产完毕，业务补发此生产通知单以完善公司流程', '0', '2018-09-26 16:41:00', 'Process * Plant Automation Ltd', 'PAG', 'PAG02', 'INHESC2018080302', '2018-09-26', '国际二部 INTL.Business Dept.2', '赵政洁(Oscar)', '', '05', '生产通知单', '同意。结算方式：合同金额的100%全款在签订合同10天内作为预付款T/T支付。当前已收到全款，同意生产。	\r\n', '同意', '朱君宜2018-09-27 09:25:40', '郭涛2018-09-27 08:56:24', '同意', '陶保荣2018-09-27 10:21:35', '', '', '', '', '同意', '丁富民2018-09-28 07:20:50', '王功勇2018-09-28 08:55:17', 'sctz2018092601', '01', '', '', '', '已收全款，可以下单。', '鲁慧珍2018-09-26 17:12:25', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('324', '{49D77892-244B-49AF-86D7-0355C1CD4556}', '61', 'INHE-0654', '2018-09-28 08:35:14', '0000-00-00 00:00:00', '2018-09-29 08:55:10', 'unchecked', 'n', 'n', '', '1', 'sctz2018092801/PSA10801/生产通知单', '', '1.已收到预付款30%，                                                                           2.此次直采的CIP是用于PSA10国电项目中标的电表，代理希望能借此机会加深电力公司对银河产品的印象，合同金额较小，同时交期较紧，希望能尽量在20-25天完成采购和生产', '0', '2018-09-28 08:35:14', 'MESSEN S.A.S', 'PSA10', 'PSA10801', 'INHESC2018092101', '2018-10-10', '国际二部 INTL.Business Dept.2', '李明(Ming)', '', '05', '生产通知单', '付款方式为30%生产前T/T付款，70%发货前T/T尾款	，当前已收到30%预付款，同意生产。	\r\r\n', '同意', '朱君宜2018-09-28 11:04:19', '郭涛2018-09-28 10:46:24', '同意', '陶保荣2018-09-28 11:05:57', '', '', '', '', '同意', '丁富民2018-09-28 22:51:08', '王功勇2018-09-29 08:49:29', 'sctz2018092801', '01', '', '', '', '预付款已到账，可以下单。', '鲁慧珍2018-09-28 09:51:58', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('325', '{B5F8A43A-032C-4027-8CBB-4A61462FCBDE}', '61', 'INHE-0725', '2018-09-28 17:24:28', '0000-00-00 00:00:00', '2018-09-29 11:10:06', 'unchecked', 'n', 'n', '', '1', 'sctz2018092802/GZA02/生产通知单', '', '该项目清理NR05项目库存', '70', '2018-09-28 17:24:28', 'ZAHYON SOLUTIONS LTD', 'GZA', 'GZA02', 'INHESC2018092102', null, '国际二部 INTL.Business Dept.2', '赵政洁(Oscar)', '', '05', '生产通知单', '同意。结算方式为全款TT预付，当前已收到全款，同意生产。', '同意', '朱君宜2018-09-29 10:27:41', '郭涛2018-09-29 10:18:33', '同意', '陶保荣2018-09-29 10:57:01', '', '', '', '', '同意', '丁富民2018-09-29 10:58:23', '王功勇2018-09-29 11:04:36', 'sctz2018092802', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2018-09-28 18:39:47', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('326', '{543A3430-40FC-44AA-9C51-44B27842F733}', '60', 'INHE-0088', '2018-09-29 10:08:52', '0000-00-00 00:00:00', '2018-09-30 16:27:47', 'unchecked', 'n', 'n', '', '1', 'sctz2018092902/WZT01/生产通知单', '', '1. 一批出货；\r\r\r\n2. 出货前客户到厂验货，须提供验货测试报告；\r\r\n3. 交期要求较紧，须协助配合。\r\r\n', '130000', '2018-09-29 10:08:52', 'West Zone Power Distributin Company Limited', 'WZT', 'WZT01', 'INHESC2018070401', '2018-11-30', '国际一部 INTL.Business Dept.1', '余冬纯', '', '02', '生产通知单', '结算方式：全款即期信用证。当前LC收到、须修改，但王总在标题为“WZT01订单生产、发货、议付跟踪”的OA中已特批“同意下单”。										\r\n	\r\r\n', '同意', '朱君宜2018-09-29 15:17:53', '王维2018-09-29 14:37:20', '同意', '陶保荣2018-09-29 15:24:09', '', '', '', '研发项目负责人何梓劲，由于继电器品牌要求其交货是一个问题。', '同意', '丁富民2018-09-30 11:17:51', '王功勇2018-09-30 14:39:53', 'sctz2018092902', '01', '', '', '', 'LC收到、须修改，但王总在标题为“WZT01订单生产、发货、议付跟踪”的OA中已特批“同意下单”。', '鲁慧珍2018-09-29 13:38:36', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('327', '{C48932EE-F702-45D5-841F-08AADAB7BCE4}', '61', 'INHE-0500', '2018-09-29 17:25:21', '0000-00-00 00:00:00', '2018-09-30 15:39:54', 'unchecked', 'n', 'n', '', '1', 'sctz2018092903/EOI15/生产通知单', '', '1.请使用EOI库存订单，请跟单组注意EOI15和EOI16实际为同一个客户，发货地址一致，发货请和李忠鹏核对发货地址和清关单据等文件。\r\r\n', '60', '2018-09-29 17:25:21', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI15', 'INHESC2018092701', '2018-09-30', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式：合同金额的100%在签订合同30天内作为预付款在发货前T/T支付。当前已收到全款，同意生产。 		\r\n', '同意', '朱君宜2018-09-30 10:50:11', '郭涛2018-09-30 09:56:05', '同意', '陶保荣2018-09-30 11:01:05', '', '', '', '', '同意', '丁富民2018-09-30 11:15:44', '王功勇2018-09-30 14:39:29', 'sctz2018092903', '01', '', '', '', '全款已到账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2018-09-29 17:58:47', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('328', '{BE988998-7B11-4962-A6EA-DFC6F4E8B4CD}', '61', 'INHE-0500', '2018-09-29 17:29:42', '0000-00-00 00:00:00', '2018-09-30 15:40:12', 'unchecked', 'n', 'n', '', '1', 'sctz2018092904/EOI16/生产通知单', '', '1.请使用EOI库存订单，请跟单注意EOI15和EOI16采购客户为同一个客户，发货地址相同。\r\n', '40', '2018-09-29 17:29:42', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI16', 'INHESC2018092702', '2018-09-30', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式：合同金额的100%在签订合同30天内作为预付款在发货前T/T支付。当前已收到款，同意生产。 		\r\r\n', '同意', '朱君宜2018-09-30 10:48:38', '郭涛2018-09-30 09:55:30', '同意', '陶保荣2018-09-30 11:00:09', '', '', '', '', '同意', '丁富民2018-09-30 11:14:51', '王功勇2018-09-30 14:39:11', 'sctz2018092904', '01', '', '', '', '全款已到账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2018-09-29 17:58:34', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('329', '{F15D779C-19D6-40B1-B838-D067E8390D16}', '60', 'INHE-0601', '2018-09-30 14:02:48', '0000-00-00 00:00:00', '2018-10-08 08:19:50', 'unchecked', 'n', 'n', '', '1', 'sctz2018093002/PIK01/生产通知单', '', '', '84', '2018-09-30 14:02:48', 'INTERLINK COMMUNICATION PUBLIC COMPANY LIMITED', 'PIK', 'PIK01', 'INHESC2018090301', '2018-10-17', '国际一部 INTL.Business Dept.1', '常一琳', '', '05', '生产通知单', '同意。结算方式,本合同金额的30%在签约后10天内以电汇方式预付，余额70%在装运前以电汇方式支付.当前已收到预付款，同意生产。请业务尽快填写收款登记表。		\r\n', '同意', '朱君宜2018-09-30 16:36:12', '王维2018-09-30 16:29:09', '同意', '陶保荣2018-09-30 16:45:19', '', '', '', '研发项目负责人:王顺万', '同意', '丁富民2018-10-03 07:59:48', '王功勇2018-10-03 11:53:09', 'sctz2018093002', '01', '', '', '', '30%T/T预付款已到账，可以下单。', '鲁慧珍2018-09-30 14:33:07', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('330', '{6FA3EFDF-FB65-4CFE-9FB4-232FC6E8FCFC}', '61', 'INHE-0500', '2018-10-15 11:47:13', '0000-00-00 00:00:00', '2018-10-16 16:49:48', 'unchecked', 'n', 'n', '', '1', 'sctz2018101501/EOI18/生产通知单', '', '1.请使用EOI库存订单；\r\n2.是按照表号文件顺序装箱。', '661', '2018-10-15 11:47:13', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI18', 'INHESC2018101201', '2018-10-16', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式：合同金额的100%在签订合同30天内作为预付款在发货前T/T支付。当前确认全款已到建行，待入账，同意下单。		\r\n', '同意。请李忠鹏签回合同。', '朱君宜2018-10-16 09:13:32', '郭涛2018-10-15 18:23:21', '同意', '陶保荣2018-10-16 11:08:52', '', '', '', '', '同意。', '丁富民2018-10-16 13:27:51', '王功勇2018-10-16 13:41:08', 'sctz2018101501', '01', '', '', '', '出纳姚茜确认此批全款已到建行，待提供合同等资料后即可入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2018-10-15 13:31:31', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('331', '{A4DFC57A-6223-474E-8FAD-D82B3C79D677}', '61', 'INHE-0440', '2018-10-15 16:37:17', '0000-00-00 00:00:00', '2018-10-26 15:36:14', 'unchecked', 'n', 'n', '', '1', 'sctz2018101502/ITL03/生产通知单', '', 'ITL03项目追加生产耗材 锡线 30卷。纯棉手套(礼仪手套)白色薄手套  300	双。打包带，13*1.0mm	100	卷。以上耗材收费，从ITL01剩余的运费抵扣过来。', '0', '2018-10-15 16:37:17', 'Africarriers Ltd', 'ITL', 'ITL03', 'INHESC2018060401', null, '国际二部 INTL.Business Dept.2', '汤伟(Will)', '第三方检验', '02', '生产通知单', '同意。请发OA明确这批货的费用以便抵扣，感谢~', '同意。请汤伟负责完成合同和收款。', '朱君宜2018-10-26 10:31:03', '郭涛2018-10-26 10:27:05', '同意', '陶保荣2018-10-26 11:21:20', '', '', '', '', '同意', '丁富民2018-10-26 13:26:43', '王功勇2018-10-26 14:08:13', 'sctz2018101502', '01', '', '', '', '已发货，领导OA特批，此流程是补给江西工厂的。请业务尽快确认以上耗材、运费金额，发OA明示给财务进行费用抵扣。', '鲁慧珍2018-10-25 17:53:17', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('332', '{37FC6537-D269-4BC2-9A8A-4DF30A5F29E7}', '61', 'INHE-0654', '2018-10-29 13:39:09', '0000-00-00 00:00:00', '2018-11-05 08:55:04', 'unchecked', 'n', 'n', '', '1', 'sctz2018102901/ADC03/生产通知单', '', '1,希望可以尽早交付，100个充电版的CIU-R是用来给ADD中标项目做试点用的，电力公司技术规格要求要充电版的CIU-R做试点，CIU-R序列号要与电力公司现有的产品表号做配对，由于无法上传过多附件，之后补在相应的OA中。2，请看CIU-R的技术要求这一部分，之前应答电力公司要求，要求显示单元要显示出电池的用电量，就像手机用电量显示一样，此次试点不需要满足，但是后期供货要满足，请研发丁总考虑一下对此点研发是否可以提前修改一下程序，以保证我们供货的时候可以满足。3，请工厂生产时或者实验室测试时要千万注意CIU-R能与此前出货的ADC01的产品保证通讯无问题。', '0', '2018-10-29 13:39:09', 'Cashpower Sudamericana S.A.', 'ADC', 'ADC03', 'INHESC2018102301', '2018-11-20', '国际二部 INTL.Business Dept.2', '李明(Ming)', '第三方检验', '05', '生产通知单', '结算方式：100%T/T预付。经核实， 全款已到建行， 待走流程入账，同意生产。', '同意。此批供货影响ADD订单执行，希望工厂支持，尽快交付。', '朱君宜2018-11-01 08:46:20', '郭涛2018-10-31 22:56:13', '同意', '陶保荣2018-11-01 14:23:55', '', '', '', 'ADD项目同王顺万负责，具体请王顺万作一下处理。', '同意', '丁富民2018-11-03 07:55:47', '王功勇2018-11-04 10:03:55', 'sctz2018102901', '01', '', '', '', '姚茜确认全款已到建行，待走流程入账，交期较急，建议下单。', '鲁慧珍2018-10-31 17:24:41', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('333', '{D18582CD-5137-4B1F-8AEB-0B10E13418CF}', '61', 'INHE-0500', '2018-10-31 18:24:48', '0000-00-00 00:00:00', '2018-11-02 08:30:04', 'unchecked', 'n', 'n', '', '1', 'sctz2018103101/EOI17/生产通知单', '', '1.按照表号顺序装箱；\r\n2.使用EOI库存订单\r\n', '300', '2018-10-31 18:24:48', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI17', 'INHESC2018103001', '2018-11-02', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式：合同金额的100%在签订合同30天内作为预付款在发货前T/T支付。当前已收到全款，同意生产。', '同意', '朱君宜2018-11-01 08:57:51', '郭涛2018-10-31 22:51:08', '同意', '陶保荣2018-11-01 14:23:30', '', '', '', '', '', '', '王功勇2018-11-01 18:22:23', 'sctz2018103101', '01', '', '', '', '全款已到账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2018-10-31 18:33:45', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('334', '{1CD3C207-94B0-41A9-9CBC-5D61BEE7F04E}', '61', 'INHE-0381', '2018-11-01 17:22:59', '0000-00-00 00:00:00', '2018-11-05 09:06:32', 'unchecked', 'n', 'n', '', '1', 'sctz2018110101/ING16/生产通知单', '', '', '32544', '2018-11-01 17:22:59', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING16', '18001039 CA', '2018-12-08', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '第三方检验', '06', '生产通知单', '结算方式：100%LC，60天远期。目前LC尚未收到，但王总在标题为“ING16项目提前备料申请”的OA中已特批同意提前备料。同意生产										\r\r\r\n', '同意。请张柳芳跟紧LC。', '朱君宜2018-11-02 08:52:58', '郭涛2018-11-02 08:34:30', '同意', '陶保荣2018-11-02 10:04:31', '', '请江西务必抓紧采购，交期很紧张。', '', '翻单生产， 请江西工厂安排处理。', '同意', '丁富民2018-11-03 07:53:37', '王功勇2018-11-04 10:03:27', 'sctz2018110101', '01', '', '', '', 'LC尚未收到，但王总在标题为“ING16项目提前备料申请”的OA中已特批同意提前备料。', '鲁慧珍2018-11-01 18:00:49', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('335', '{F3C16A1C-C642-45DB-ABFF-8E946B442B32}', '93', 'INHE-0789', '2018-11-05 18:02:43', '0000-00-00 00:00:00', '2018-11-07 14:51:01', 'unchecked', 'n', 'n', '', '1', 'sctz2018110501/MCT01/生产通知单', '', '1. 电表要求三相三线与三相四线可切换\r\r\r\n2. 分两批发货：\r\r\r\n1） 10台  交期：2018年11月15日   发货方式：通过DHL发货\r\r\r\n2）490台  交期：2018年11月30日   发货方式：通过空运发货\r\r\r\n', '500', '2018-11-05 18:02:43', 'IMSAQA ELECTRIC, Lda', 'MCT', 'MCT01', 'INHESC2018102903', '2018-11-30', '智能配电事业部业务', '林凤兰', '', '04', '生产通知单', '结算方式：全款TT预付。当前已收到全款，同意生产。', '同意。', '朱君宜2018-11-07 09:30:09', '杨爱军2018-11-07 09:22:19', '同意', '陶保荣2018-11-07 09:34:33', '', '', '', '研发项目负责人：王占颍。   建议按最近CDN项目生产出货的CT表方案安排，具体请王占颍核对安排处理。', '同意', '丁富民2018-11-07 12:54:46', '王功勇2018-11-07 14:26:33', 'sctz2018110501', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2018-11-06 09:57:15', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('336', '{045A767C-CFCF-44A1-AC55-443FAF54B1EF}', '61', 'INHE-0578', '2018-11-06 14:47:31', '0000-00-00 00:00:00', '2018-11-07 14:28:53', 'unchecked', 'n', 'n', '', '1', 'sctz2018110601/N4-5/生产通知单', '', '', '0', '2018-11-06 14:47:31', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'N', 'N4-5', ' INHESC2018102902', '2018-11-30', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '', '06', '生产通知单', '结算方式：合同金额的30%作为预付款TT支付，合同的70%在提单日后90天内TT支付。	当前已收到30%预付款，同意下单。	\r\n', '同意。请覃湘君落实收款进账和后续货款收款。', '朱君宜2018-11-07 08:46:17', '郭涛2018-11-06 19:57:25', '同意', '陶保荣2018-11-07 08:59:35', '', '', '', '', '同意', '丁富民2018-11-07 12:51:50', '王功勇2018-11-07 14:25:44', 'sctz2018110601', '01', '', '', '', '业务提供了客户11/5已支付30%预付款的水单，交期较紧，希望可以特批先下单。依据此客户的历史付款记录及信誉，建议先下单。', '鲁慧珍2018-11-06 15:03:20', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('337', '{E613C4A5-2994-438F-AB6B-788EA2CBC1E8}', '60', 'INHE-0560', '2018-11-08 13:56:33', '0000-00-00 00:00:00', '2018-12-21 13:48:49', 'unchecked', 'n', 'n', '', '1', 'sctz2018110801/白雪816/生产通知单', '', '', '0', '2018-11-08 13:56:33', 'Energomera CJSC', '白雪', '白雪816', 'PO#E18_1210', '2018-11-20', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式:15%-下单时TT支付 85%-发货前TT支付	.当前已收到15%预付款,请业务尽快填写收款登记表,同意下单.	\r\n', '同意', '朱君宜2018-12-06 09:05:10', '王维2018-12-06 08:08:54', '同意', '陶保荣2018-12-06 09:06:58', '', '', '', '', '同意', '丁富民2018-12-06 09:43:03', '王功勇2018-12-07 08:57:56', 'sctz2018110801', '01', '', '', '', '15%T/T预付款已到账，同意下单。', '鲁慧珍2018-12-05 10:55:29', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('338', '{C67E9B19-58B3-4CD6-908F-64CE30D03377}', '61', 'INHE-0500', '2018-11-08 18:00:42', '0000-00-00 00:00:00', '2018-11-09 16:27:39', 'unchecked', 'n', 'n', '', '1', 'sctz2018110802/EOI12/生产通知单', '', '', '2110', '2018-11-08 18:00:42', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI12', 'INHESC2018110701', '2018-11-12', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式：合同金额的100%在签订合同30天内并在发货前作为预付款T/T支付。当前款已到建行，待流程入账，同意下单。		\r\n', '同意', '朱君宜2018-11-09 08:50:27', '郭涛2018-11-08 19:25:22', '同意', '陶保荣2018-11-09 09:22:42', '', '', '', '', '同意', '丁富民2018-11-09 12:05:43', '王功勇2018-11-09 15:52:53', 'sctz2018110802', '01', '', '', '', '出纳姚茜确认此批全款已到建行，待走流程入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2018-11-08 18:21:05', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('339', '{345BBBD6-CBCA-49DF-BBF3-01DB231759C3}', '61', 'INHE-0725', '2018-11-11 18:21:18', '0000-00-00 00:00:00', '2018-11-13 12:31:34', 'unchecked', 'n', 'n', '', '1', 'sctz2018111101/PN05/生产通知单', '', '', '500', '2018-11-11 18:21:18', 'B.N.S.R. Sela', 'PN', 'PN05', 'INHESC2018083002', '2018-11-30', '国际二部 INTL.Business Dept.2', '赵政洁(Oscar)', '', '05', '生产通知单', '结算方式：签订合同10天内并在准备生产原材料之前T/T支付100%合同款项。当前已收到全款，同意生产。	\r\n', '同意', '朱君宜2018-11-12 14:26:53', '郭涛2018-11-12 13:19:20', '同意', '陶保荣2018-11-12 15:05:52', '', '', '', '', '同意', '丁富民2018-11-12 15:36:52', '王功勇2018-11-13 08:55:42', 'sctz2018111101', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2018-11-12 08:52:37', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('340', '{B9F018BD-06A1-4FE2-B221-4914FC992FD1}', '61', 'INHE-0593', '2018-11-13 17:23:00', '0000-00-00 00:00:00', '2018-11-20 17:17:59', 'unchecked', 'n', 'n', '', '1', 'sctz2018111301/BFN09/生产通知单', '', '1. 请重视反向电流处理\r方式\r\r\n2. 三相表希望能采用工厂库存TN11 三相表生产', '37000', '2018-11-13 17:23:00', 'SOCIETE GENERALE D`ELECTRONIQUE', 'BFN09', 'BFN09', 'INHESC2018080201', '2018-12-25', '国际二部 INTL.Business Dept.2', '胡蝶', '第三方检验', '02', '生产通知单', '结算方式：生产前-10%预付款，90%LC信用证尾款。当前新增的135台单相表和15台三相表10%预付款未收到，此外90%LC未收到，业务称新增产品的预付款跟LC一起开。同意下单。	\r\n', '同意。新增的订单货款客户一起开的LC里面。', '朱君宜2018-12-24 09:16:46', '郭涛2018-12-21 20:25:59', '同意', '陶保荣2018-12-24 09:41:21', '', '请业务紧密跟踪并及时收到LC。', '', '单相表章春鹏负责，涉及到嵌入式软件修改测试；三相表王顺万负责，涉及到硬件、软件设计确认；', '同意。', '丁富民2018-12-24 10:42:56', '王功勇2018-12-24 10:58:43', 'sctz2018111301', '01', '', '', '', '未收到追加的135台单相表及15台三相表的10%预付款，也未收到90%LC，请领导审批是否下单，谢谢！', '鲁慧珍2018-12-21 10:50:40', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('341', '{77A634E3-0B03-48C9-9A78-8AB84CF745EC}', '60', 'INHE-0560', '2018-11-19 10:40:05', '0000-00-00 00:00:00', '2018-11-20 13:53:26', 'unchecked', 'n', 'n', '', '1', 'sctz2018111901/白雪813/生产通知单', '', '此订单4台单相表翻单白雪809，2台三相表+显示单元翻单白雪808                                      白雪单相表要求：\r\r\r\r\r\n1、采用新模具结构供货。     \r\r\r\r\r\n2、PCB板不需灌胶和喷三防漆！\r\r\r\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。      \r\r\r\r\r\n4、MAC地址为该表表号（表地址）的最后六位数字，该地址激光雕刻在表外壳背部。       \r\r\r\r\r\n5、PLC载波显示单元的铭牌标识为：CE208。         \r\r\r\r\r\n6、显示单元不需要贴易碎贴。        \r\r\r\r\r\n7、出厂设置：           \r\r\r\r\r\n1）表内时间为：GMT+4           \r\r\r\r\r\n2）冬夏令时转换功能关闭。           \r\r\r\r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\r\r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\r\r\r\n5）特殊节假日没有。           \r\r\r\r\r\n6）电表密码：000000.           \r\r\r\r\r\n7）负荷门限：0.           \r\r\r\r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\r\r\r\n9）取负荷点的平均时间：30分钟。          \r\r\r\r\r\n8、继电器：100A，但标识采用120A。      \r\r\r\r\r\n9、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）       \r\r\r\r\r\n10、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\r\r\r\n11、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU的内盒中。\r\r\r\r\r\n12、此订单的单相表不带显示单元	  							\r\r\r\n                                                                                               白雪三相表要求：\r\r\r\n\r\r\r\n1、采用双方验证过的程序版本TMF2-1B-16032201\r\r\r\n2、修改过脉冲输出的阻抗。						\r\r\r\n3. 铭牌、MAC地址等需要镭雕在电表外壳上； \r\r\r\n4. MAC地址铭牌的6位数字为该表表号的最后六位数字；\r\r\r\n5. 表内时间为GMT+3#FE54` \r\r\r\n6. 冬夏令时转换功能关闭； \r\r\r\n7. 需要把面板上的表号设到电表内 \r\r\r\n8. 计量单元不需要打铅封。\r\r\r\n9、计量单元、显示单元都不需要贴合格证 \r\r\r\n10、三相表默认密码为777777。 \r\r\r\n11：内盒不需要贴条形码\r\r\r\n12：计量单元和显示单元都取消易碎贴纸	  										\r\r\r\n										\r\r\r\n\r\r\r\r\n										\r\r\r\r\r\n                                      ', '6', '2018-11-19 10:40:05', 'Energomera CJSC', '白雪', '白雪813', 'PO#E18_1708-T', '2018-11-29', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '已收款,已发货,补流程.', '同意', '朱君宜2018-11-20 08:41:41', '王维2018-11-20 08:36:30', '同意', '', '', '', '', '', '同意', '丁富民2018-11-20 09:00:48', '王功勇2018-11-20 13:47:13', 'sctz2018111901', '01', '', '', '', '已出货，补流程。', '鲁慧珍2018-11-19 10:57:04', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('342', '{968611B4-A7DA-4D84-91CA-FC94F0FF3ABF}', '61', 'INHE-0440', '2018-11-20 01:25:02', '0000-00-00 00:00:00', '2018-11-21 09:09:16', 'unchecked', 'n', 'n', '', '1', 'sctz2018112001/TTA01/生产通知单', '', '1.35000台为整机不打外壳螺钉，30000台为SKD。铅封套管需要打上INHEMETER的LOGO。防水接头需要能够接入18mm的电线，需提供表箱挂钩片，方便电力公司测试。新表需要提供上电工装给到ITL工厂。客户交期紧张，争取生产前收到L/C，需要提前备料和生产。', '65000', '2018-11-20 01:25:02', 'INHEMETER (T) LIMITED', 'TTA', 'TTA01', 'INHESC2018081503', '2018-12-10', '国际二部 INTL.Business Dept.2', '汤伟(Will)', '第三方检验', '02', '生产通知单', '结算方式：合同金额的100%通过不可撤销的保兑的远期180天的信用证支付。当前L/C未收到，但王总在标题为“TTA01项目订单生产、发货、议付跟踪”的OA中已特批“同意下单”。										\r\n', '请汤伟注意LC要尽量在未来10天收到，最迟不迟于开始生产前。', '朱君宜2018-11-20 15:13:22', '郭涛2018-11-20 15:02:56', '同意', '陶保荣2018-11-20 15:34:00', '', '注意：表箱和电表透明端盖的生产暂缓，等结构部通知。', '', '研发项目负责人：章春鹏    涉及到表箱有局部变动正在落实之中，电表部分BOM表已经确认，程序在最后测试之中。', '同意', '丁富民2018-11-20 19:15:46', '王功勇2018-11-20 21:32:53', 'sctz2018112001', '01', '', '', '', 'L/C未收到，但王总在标题为“TTA01项目订单生产、发货、议付跟踪”的OA中已特批“同意下单”。', '鲁慧珍2018-11-20 11:49:54', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('343', '{2F3F41CC-AAD9-4DE7-85DB-5CE955EBF80C}', '60', 'INHE-0560', '2018-11-20 09:43:58', '0000-00-00 00:00:00', '2018-11-21 15:20:14', 'unchecked', 'n', 'n', '', '1', 'sctz2018112002/白雪817/生产通知单', '', '1.须附送1套易损配件                                                                2.客户国电压为230V，设备需配备相应的电压转换装置                                       3.超声焊设备应采用日本进口换能器和变幅器                                            						\r\r\n', '0', '2018-11-20 09:43:58', 'Energomera CJSC', '白雪', '白雪817', 'PO#E18_2910', '2018-12-08', '国际一部 INTL.Business Dept.1', '李美娇', '', '06', '生产通知单', '结算方式:100%-TT预付.当前已收到款,同意下单.		\r\n', '同意', '朱君宜2018-11-21 09:22:00', '王维2018-11-21 09:12:19', '同意', '陶保荣2018-11-21 09:23:16', '', '', '', '', '同意', '丁富民2018-11-21 09:26:34', '王功勇2018-11-21 11:53:52', 'sctz2018112002', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2018-11-20 10:06:58', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('344', '{3ACEC356-3B8B-452D-9945-10A23A90B5E8}', '61', 'INHE-0500', '2018-11-20 15:19:07', '0000-00-00 00:00:00', '2019-01-15 08:58:11', 'unchecked', 'n', 'n', '', '1', 'sctz2018112003/EOI13/生产通知单', '', '1.请使用EOI库存订单；\r\n2.请按照表号顺讯装箱。', '657', '2018-11-20 15:19:07', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI13', 'INHESC2018111501', '2018-11-22', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式:合同金额的100%在签订合同30天内并在发货前作为预付款T/T支付。当前出纳已确认全款已到建行,待走流程入账,可以下单.	\r\r\n', '同意', '朱君宜2018-11-21 08:41:42', '郭涛2018-11-21 02:55:55', '同意', '陶保荣2018-11-21 08:56:59', '', '', '', '', '同意', '丁富民2018-11-21 09:26:59', '王功勇2018-11-21 11:49:35', 'sctz2018112003', '01', '', '', '', '出纳姚茜确认此批全款已到建行，待走流程入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2018-11-20 15:31:08', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('345', '{8BC029C8-D504-4ABD-BEE1-B3065789E110}', '61', 'INHE-0500', '2018-11-20 15:25:01', '0000-00-00 00:00:00', '2019-01-15 08:57:55', 'unchecked', 'n', 'n', '', '1', 'sctz2018112004/EOI19/生产通知单', '', '1.请使用EOI库存订单；\r\n2.请按照表号顺序装箱。', '200', '2018-11-20 15:25:01', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI19', 'INHESC2018111901', '2018-11-22', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式:合同金额的100%在签订合同30天内并在发货前作为预付款T/T支付.当前出纳姚茜确认此批全款已到建行，待走流程入账，可以下单。									\r\n	\r\r\n', '同意', '朱君宜2018-11-21 08:44:20', '郭涛2018-11-21 02:50:07', '同意', '陶保荣2018-11-21 08:56:31', '', '', '', '', '同意', '丁富民2018-11-21 09:27:22', '王功勇2018-11-21 11:49:10', 'sctz2018112004', '01', '', '', '', '出纳姚茜确认此批全款已到建行，待走流程入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2018-11-20 15:31:37', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('346', '{2ECEA874-8635-4A6B-B8F9-DFA405ED7ECC}', '61', 'INHE-0500', '2018-11-20 15:30:29', '0000-00-00 00:00:00', '2018-11-21 15:21:02', 'unchecked', 'n', 'n', '', '1', 'sctz2018112005/EOI20/生产通知单', '', '1.请使用EOI库存订单；\r\n2.请按照表号顺序装箱。', '100', '2018-11-20 15:30:29', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI20', 'INHESC2018111502', '2018-11-22', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式:合同金额的100%在签订合同30天内作为预付款在发货前T/T支付。当前已收到全款,同意下单.		\r\n', '同意', '朱君宜2018-11-21 08:46:18', '郭涛2018-11-20 18:16:25', '同意', '陶保荣2018-11-21 08:56:45', '', '', '', '', '同意', '丁富民2018-11-21 09:26:05', '王功勇2018-11-21 11:48:52', 'sctz2018112005', '01', '', '', '', '全款已到账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2018-11-20 15:35:01', null, null, null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('347', '{AF290548-C562-4E4D-933C-F86F8C4AA08A}', '60', 'INHE-0680', '2018-11-26 11:14:09', '0000-00-00 00:00:00', '2018-11-27 18:14:18', 'unchecked', 'n', 'n', '', '1', 'sctz2018112601/BY11/生产通知单', '', '', '100', '2018-11-26 11:14:09', 'OsOO ASMAN SERVIS', 'BY', 'BY11', ' INHESC2018111401 ', '2019-01-21', '国际一部 INTL.Business Dept.1', '陈嘉豪', '', '04', '生产通知单', '付款方式：30%生产前TT，70%发货前TT。当前BY06预付款支付BY11订单，已足够覆盖合同的30%，同意生产。		\r\r\r\n', '同意', '朱君宜2018-11-27 14:29:57', '王维2018-11-27 11:55:04', '同意', '陶保荣2018-11-27 14:37:56', '', '', '', '', '同意。BY08项目翻单生产，请江西工厂安排处理。', '丁富民2018-11-27 16:03:59', '王功勇2018-11-27 16:57:20', 'sctz2018112601', '01', '', '', '', '合同评审的付款方式为：BY06预付款余款作为BY11下单的预付款，尾款发货前TT付清。但PMC通知：1.80台直通表有库存，里面带的是RF模块，业务这批需要的是GPRS模块，需要将RF模块拆下来，做80个  GPRS模块换上去。2.20台CT表无库存，模块有库存。此批订单不能完全使用BY06库存表。BY06之前生产的135套三相表库存已积压将近两年，涉及新的采购、生产成本，是否继续生产请各位领导审批。谢谢！', '鲁慧珍2018-11-27 11:51:43', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('348', '{020FBDEE-BC62-452D-A3AE-9BC734CD2FF6}', '66', 'INHE-0634', '2018-11-30 15:47:36', '0000-00-00 00:00:00', '2018-12-04 11:07:03', 'unchecked', 'n', 'n', '', '1', 'sctz2018113001/PAR01/生产通知单', '', '', '1060', '2018-11-30 15:47:36', 'Parami Energy Service Co.,Ltd', 'PAR', 'PAR01', 'PES/SI/Power/PO-023/2018', '2019-01-21', '国际三部 INTL.Business Dept.3', '陈雁', '', '04', '生产通知单', '结算方式:100%即期保兑信用证支付.刚刚跟业务确认信用证还在修改中,因交货时间紧张,已申请特批,详见OA:\"PAR信用证咨询\"同意下单.		\r\n', '同意生产. 客户要求交货时间紧张,希望尽快安排生产, 信用证修改已获客户同意,下周改证应能收到.', '朱君宜2018-12-03 13:48:15', '王梅2018-12-03 12:32:34', '同意', '陶保荣2018-12-03 13:55:21', '', '按丁总意见，由江西研发处理，需要深圳研发支持的，及时明确提出。', '', '小范围太阳能电网使用。非电力公司主流市场需求，建议江西工厂研发、或者工程部根据库存产品作处理安排。深圳研发不参与此项目具体工作。', '同意。', '丁富民2018-12-03 15:48:23', '王功勇2018-12-03 17:53:01', 'sctz2018113001', '01', '', '', '', '已和跟单核实，此项目LC已收到但未加保，审核尚未通过，但王总在OA“PAR信用证咨询”中已特批。', '盛燕2018-11-30 18:00:42', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('349', '{1B58D760-539E-4732-95E0-43B6755912DC}', '61', 'INHE-0578', '2018-12-03 08:53:50', '0000-00-00 00:00:00', '2018-12-04 11:06:04', 'unchecked', 'n', 'n', '', '1', 'sctz2018120301/EAB01/生产通知单', '', '1.产品规格同AZA01项目产品；\r\r\r\r\n2.产品铭牌、内盒外箱设计仅包含银河Logo，在生产OA中单独确认（需与客户最终确认）；\r\r\r\r\n3.客户已支付预付款，12.3日可到账。此订单为试产订单，后续还有较多直采需求；若在春节前交货，则可推动项目执行，尽快争取第二个正式订单。希望公司能够帮忙协调生产、在春节前安排发货。', '704', '2018-12-03 08:53:50', 'Baltazar Fernandes and Moreira,lda', 'EAB', 'EAB01', 'INHESC2018081402', '2019-01-21', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '', '02', '生产通知单', '结算方式为合同金额的50%在签订合同10天内作为预付款T/T支付，50%尾款在生产完成前10天T/T支付。当前50%预付款已到建行，待入账，同意下单。 		\r\n', '同意', '朱君宜2018-12-03 16:12:19', '郭涛2018-12-03 16:02:06', '同意', '陶保荣2018-12-03 17:01:02', '', '', '', 'AZA01项目翻单生产，产品铭牌等包装资料需要与客户确认。建议由江西工厂工程部安排处理。', '同意。', '丁富民2018-12-03 17:33:31', '王功勇2018-12-03 17:50:58', 'sctz2018120301', '01', '', '', '', '预付款水单已提供给财务，待确认预付款到帐', '盛燕2018-12-03 10:45:38', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('350', '{4F6AA820-C5D8-4126-8944-77C7DA87C509}', '60', 'INHE-0560', '2018-12-04 18:08:00', '0000-00-00 00:00:00', '2018-12-13 15:54:30', 'unchecked', 'n', 'n', '', '1', 'sctz2018120401/白雪818/生产通知单', '', '', '0', '2018-12-04 18:08:00', 'Energomera CJSC', '白雪', '白雪818', 'PO#E18_1251', '2018-12-18', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式为15% -下单时支付  85%-发货前支付，当前已收	67.80%预付款，同意下单。	\r\n', '同意', '朱君宜2018-12-13 09:08:41', '王维2018-12-13 08:41:15', '同意', '陶保荣2018-12-13 10:08:43', '', '', '', '', '同意', '丁富民2018-12-13 10:32:13', '王功勇2018-12-13 10:44:55', 'sctz2018120401', '01', '', '', '', '已收67.836%的T/T预付款，可以下单。', '鲁慧珍2018-12-11 11:50:12', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('351', '{100B4D2E-47EA-4217-85B1-AD0BF6775232}', '66', 'INHE-0634', '2018-12-05 10:05:34', '0000-00-00 00:00:00', '2018-12-07 09:24:34', 'unchecked', 'n', 'n', '', '1', 'sctz2018120501/MOC02/生产通知单', '', '', '80', '2018-12-05 10:05:34', '达明（澳门）有限公司Dynamax (Macau) Limited', 'MOC', 'MOC02', 'INHESC2018120301', '2019-03-11', '国际三部 INTL.Business Dept.3', '陈雁', '', '04', '生产通知单', '结算方式：生产前100%预付款。当前全款已到银行，待走流程入账，同意下单。', '同意。', '朱君宜2018-12-05 17:55:39', '王梅2018-12-05 17:41:12', '同意', '陶保荣2018-12-06 08:51:55', '', '', '', '此项目订单数量很少（60台单相+20台三相CT表），单相表及表箱是翻单生产；三相CT表及表箱、电流互感器按公司正规产品生产（有附资料），建议由江西工厂根据库存表安排处理。----三相CT表可以使用TMG-1J为基表，配慧联通信RF-III三相表模块。【深圳研发作三相CT表程序修改，程序完成时间等定】', '同意。', '丁富民2018-12-06 10:05:04', '王功勇2018-12-07 09:01:00', 'sctz2018120501', '01', '', '', '', '出纳姚茜已确认全款已到银行，待走流程入账，可以下单。', '鲁慧珍2018-12-05 11:27:52', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('352', '{69B9B1A1-F6F8-4921-896E-48B537809A2E}', '61', 'INHE-0381', '2018-12-07 11:31:12', '0000-00-00 00:00:00', '2018-12-10 08:48:27', 'unchecked', 'n', 'n', '', '1', 'sctz2018120701/ING17/生产通知单', '', '翻单。', '25344', '2018-12-07 11:31:12', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING17', '18001040 CA', '2018-12-17', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式：100%LC，60天远期。当前已收到L/C信用证已审核，同意下单。		\r\n', '同意', '朱君宜2018-12-07 14:11:58', '郭涛2018-12-07 12:53:48', '同意', '陶保荣2018-12-07 15:05:10', '', '', '', '翻单生产，请江西工厂排。', '同意。', '丁富民2018-12-07 17:52:48', '王功勇2018-12-07 18:31:36', 'sctz2018120701', '01', '', '', '', 'L/C收到且审核通过，可以下单。（补流程，ERP 11/22已下单）', '鲁慧珍2018-12-07 11:47:05', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('353', '{5B9B397D-EEF0-40FD-93DB-C720F5E2818F}', '61', 'INHE-0381', '2018-12-07 11:37:46', '0000-00-00 00:00:00', '2018-12-10 08:24:28', 'unchecked', 'n', 'n', '', '1', 'sctz2018120702/ING18/生产通知单', '', '翻单产品', '25344', '2018-12-07 11:37:46', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING18', '18001041 CA', '2018-12-24', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '04', '生产通知单', '结算方式：100%LC，60天远期。当前已收到L/C信用证，同意下单。		\r\n		\r\r\n', '同意', '朱君宜2018-12-07 14:13:11', '郭涛2018-12-07 12:56:22', '同意', '陶保荣2018-12-07 15:04:47', '', '', '', '翻单生产，请江西工厂安排处理。', '同意', '丁富民2018-12-07 17:50:56', '王功勇2018-12-07 18:31:57', 'sctz2018120702', '01', '', '', '', 'L/C收到且审核通过，可以下单。（补流程，ERP 11/22已下单）', '鲁慧珍2018-12-07 11:48:18', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('354', '{BF6FDBA7-03B1-4B87-A2DE-37B77632EE65}', '61', 'INHE-0381', '2018-12-07 11:40:46', '0000-00-00 00:00:00', '2018-12-10 08:25:16', 'unchecked', 'n', 'n', '', '1', 'sctz2018120703/ING19/生产通知单', '', '1.翻单产品，客户要求春节前全部发货。2. ING19可能需要第三方验货后才能发货，需跟客户沟通确认。', '76032', '2018-12-07 11:40:46', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING19', '18001219 CA', '2019-01-21', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '第三方检验', '06', '生产通知单', '结算方式：100%LC，60天远期。当前L/C已收到，虽尚未评审通过，但王总2018/11/30在标题为“ING16项目提前备料申请”的OA中已同意下单。				\r\r\n		\r\r\r\n', '同意', '朱君宜2018-12-07 16:45:33', '郭涛2018-12-07 16:39:43', '同意', '陶保荣2018-12-07 17:48:03', '', '', '', '翻单生产，请江西工厂安排。', '同意', '丁富民2018-12-07 17:55:08', '王功勇2018-12-07 18:31:10', 'sctz2018120703', '01', '', '', '', 'L/C已收到，虽尚未评审通过，但王总2018/11/30在标题为“ING16项目提前备料申请”的OA中已同意下单。（ERP 11/30当天已下）', '鲁慧珍2018-12-07 13:36:18', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('355', '{770FACF6-4AF5-430C-9513-F1B140CA07FA}', '97', 'INHE-0690', '2018-12-19 17:06:53', '0000-00-00 00:00:00', '2018-12-25 08:31:25', 'unchecked', 'n', 'n', '', '1', 'sctz2018121901/M12-F1/生产通知单', '', '第一批5000台DIN-III电表，空运，承诺3-4周交付。\r\r\r\r\n计划调用EOI库存备用料，预计1月中生产结束，而后立即发货。\r\r\r\r\r\r\r\n第二批为15000台电表及表箱分海运发货。', '20000', '2018-12-19 17:06:53', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'M12-F1', 'M12-F1', ' ESC 469/ICB/RT/G/FY2016-17', '2019-01-12', '商务组', '张正', '', '06', '生产通知单', '结算方式：1.签订合同后五个工作日内T/T付款30%合同金额 2.第一批货物发货后的2周内 支付第一批货物的70%货款3.第二批货物发货前支付第二批货物的70%金额	。当前未收到预付款，但王总在标题为【M12-F1收款、生产、发货跟踪】的OA中已同意【在拿到合同条件下下单备料M12-F1】。同意下单 										\r\r\n	\r\r\r\r\n			\r\r\r\r\n', '同意', '朱君宜2018-12-24 16:20:04', '郭涛2018-12-24 15:30:28', '同意', '陶保荣2018-12-24 17:00:22', '', '', '', 'M12项目翻单生产，请江西工厂安排处理。', '同意', '丁富民2018-12-24 17:57:41', '王功勇2018-12-24 21:55:33', 'sctz2018121901', '01', '', '', '', '未收到预付款，但王总在标题为【M12-F1收款、生产、发货跟踪】的OA中已同意【在拿到合同条件下下单备料M12-F1】。', '鲁慧珍2018-12-24 11:54:37', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('356', '{771E200A-9A03-4DB7-A1B8-83FD56E08469}', '61', 'INHE-0654', '2018-12-20 10:49:51', '0000-00-00 00:00:00', '2018-12-21 09:10:48', 'unchecked', 'n', 'n', '', '1', 'sctz2018122001/PSA17-02/生产通知单', '', '1.因客户要求交期较紧，且中国春节放假时间从1月28号起，希望工厂配合，能在放假前即28号前发货。        2.此订单一共305台电表，305个模块，因客户需要测试，请安排先采购50个模块，提前发货，另205个模块与电表组装在一起，之后发货。                                                                         3.已收到客户预付款，请批准生产。', '305', '2018-12-20 10:49:51', 'MESSEN S.A.S', 'PSA17', 'PSA17-02', 'INHESC2018120701', '2019-01-25', '国际二部 INTL.Business Dept.2', '李明(Ming)', '第三方检验', '05', '生产通知单', '结算方式:30%生产T/T付款，70%发货前T/T尾款.当前30%预付款已到银行,待入账,同意下单.		\r\n', '同意', '朱君宜2018-12-20 15:21:04', '郭涛2018-12-20 12:53:08', '同意', '陶保荣2018-12-20 15:50:59', '', '请业务及时跟踪余款TT支付。很多时候“货等款”。', '', '项目负责人：王占颍', '同意', '丁富民2018-12-20 16:19:24', '王功勇2018-12-20 16:54:18', 'sctz2018122001', '01', '', '', '', '30%T/T预付款出纳姚茜确认已到银行，待走流程入账，建议下单。', '鲁慧珍2018-12-20 11:14:51', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('357', '{39CCF399-C7E6-49AE-9737-737FD46AFDCD}', '97', 'INHE-0549', '2018-12-21 08:10:53', '0000-00-00 00:00:00', '2018-12-24 14:13:09', 'unchecked', 'n', 'n', '', '1', 'sctz2018122101/KM01/生产通知单', '', 'sctz2018012301号生产通知单翻单，但是需要注意不要提供双绞线，且单三相电表要以后付费模式出厂。出厂时单三相表箱内部装好表和熔断器、熔芯和零线柱并接好线。单三相断路器，安装板和CIU可单独包装。如有任何问题请微信或电话联系王秀明：15705276012。					', '8140', '2018-12-21 08:10:53', 'KAMA.SA', 'KM', 'KM01', 'INHESC2017022202', '2019-01-21', '商务组', '王秀明', '', '05', '生产通知单', '结算方式：几内亚第二批30%将在下单时TT或90天不可撤销保兑LC支付，70%将在交货日期前15天由TT或90天不可撤销保兑LC支付。当前款已收齐，同意生产。', '同意', '朱君宜2018-12-24 10:50:43', '王维2018-12-24 08:08:48', '同意', '陶保荣2018-12-24 10:57:19', '', '', '', '翻单生产，请江西工厂安排处理。', '同意。', '丁富民2018-12-24 13:54:50', '王功勇2018-12-24 14:11:43', 'sctz2018122101', '01', '', '', '', '此部分产品全款已收齐，同意下单。', '鲁慧珍2018-12-21 09:36:45', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('358', '{AC97CE65-B6C0-42F2-8388-3C86956C7D0E}', '97', 'INHE-0769', '2018-12-27 16:46:55', '0000-00-00 00:00:00', '2018-12-29 10:29:39', 'unchecked', 'n', 'n', '', '1', 'sctz2018122702/STE01/生产通知单', '', '', '300', '2018-12-27 16:46:55', 'State Electric Company Limited', 'STE', 'STE01', 'INHESC2018122601', '2019-01-22', '商务组', '吴琼', '', '05', '生产通知单', '结算方式:100%不可撤销即期信用证.当前L/C正本已收到， 但港口显示有问题待更改， 交期待确认。请领导审批是否同意下单。', '同意', '朱君宜2018-12-28 09:46:09', '王维2018-12-28 09:30:46', '同意', '陶保荣2018-12-28 10:26:47', '', '请跟单组紧密跟踪LC修改和交期确认事宜。', '', '业务已经确认了程序版本，请刘欣核对一下对应BOM表。---数量不多，最好翻单处理。', '同意。', '丁富民2018-12-28 11:36:54', '王功勇2018-12-29 09:45:50', 'sctz2018122702', '01', '', '', '', 'L/C正本已收到，港口显示有问题待更改，交期待确认，其它OK。请领导审批是否同意先下单，谢谢！', '鲁慧珍2018-12-27 18:00:12', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('359', '{76CDB0F2-086A-4D87-897B-35E1D42AFDDF}', '60', 'INHE-0560', '2019-01-08 08:36:19', '0000-00-00 00:00:00', '2019-01-09 18:39:21', 'unchecked', 'n', 'n', '', '1', 'sctz2019010801/白雪901/生产通知单', '', '白雪单相表要求（不带RF模块）：\r\r\r\r\r\r\r\r\r\r\r\n1、采用新模具结构供货。     \r\r\r\r\r\r\r\r\r\r\r\n2、PCB板不需灌胶和喷三防漆！\r\r\r\r\r\r\r\r\r\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。             \r\r\r\r\r\r\r\r\r\r\r\n4、PLC载波显示单元的铭牌标识为：CE208。         \r\r\r\r\r\r\r\r\r\r\r\n5、显示单元不需要贴易碎贴。        \r\r\r\r\r\r\r\r\r\r\r\n6、出厂设置：           \r\r\r\r\r\r\r\r\r\r\r\n1）表内时间为：GMT+4           \r\r\r\r\r\r\r\r\r\r\r\n2）冬夏令时转换功能关闭。           \r\r\r\r\r\r\r\r\r\r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\r\r\r\r\r\r\r\r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\r\r\r\r\r\r\r\r\r\n5）特殊节假日没有。           \r\r\r\r\r\r\r\r\r\r\r\n6）电表密码：000000.           \r\r\r\r\r\r\r\r\r\r\r\n7）负荷门限：0.           \r\r\r\r\r\r\r\r\r\r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\r\r\r\r\r\r\r\r\r\n9）取负荷点的平均时间：30分钟。          \r\r\r\r\r\r\r\r\r\r\r\n7、继电器：100A，但标识采用120A。      \r\r\r\r\r\r\r\r\r\r\r\n8、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）     \r\r\r\r\n9、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\r\r\r\r\r\r\r\r\r\n10、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU内盒中                                                                          注意！！！！以下为此订单的单相表新增要求\r\r\r\r\r\r\r\r\r\r\n11、新增要求：\r\r\r\r\r\r\r\r\r\r\n1）不打印表计版本号C2.849.2.OPR1.QD\r\r\r\r\r\r\r\r\r\r\n2）不打印表计表号条形码及生产年份\r\r\r\r\r\r\r\r\r\r\n3）不粘贴表计背部MAC地址铭牌                                                \r\r\r\r\r\r\r\r\r\r\r\n白雪三相表要求（不带RF模块）：\r\r\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\r\r\n1、采用双方验证过的程序版本TMF2-1B-16032201\r\r\r\r\r\r\r\r\r\r\r\n2、修改过脉冲输出的阻抗。	 \r\r\r\r\r\r\r\r\r\r\r\n3. 表内时间为GMT+3#FE54` \r\r\r\r\r\r\r\r\r\r\r\n4. 冬夏令时转换功能关闭； \r\r\r\r\r\r\r\r\r\r\r\n5. 需要把面板上的表号设到电表内 \r\r\r\r\r\r\r\r\r\r\r\n6. 计量单元不需要打铅封。\r\r\r\r\r\r\r\r\r\r\r\n7、计量单元、显示单元都不需要贴合格证 \r\r\r\r\r\r\r\r\r\r\r\n8、三相表默认密码为777777。 \r\r\r\r\r\r\r\r\r\r\r\n9：内盒不需要贴条形码\r\r\r\r\r\r\r\r\r\r\r\n11：计量单元和显示单元都取消易碎贴纸                                         注意！！！！以下为此订单三相表新增要求\r\r\r\r\r\r\r\r\r\n\r\r\r\r\r\r\r\r\r\n12.新增要求\r\r\r\r\r\r\r\r\r\n1)不打印表计版本号 C36 746 OPR1.QYVF RP03\r\r\r\r\r\r\r\r\r\n2)不打印表计表号条形码及生产年份\r\r\r\r\r\r\r\r\r\n3)不打印表计正面的后6位表号	  										\r\r\r\r\r\r\r\r\r\r\r\n', '3006', '2019-01-08 08:36:19', 'Energomera CJSC', '白雪', '白雪901', 'PO#E18_2712-T', '2019-01-28', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式:30%预付TT下单（已经到账），剩余70% 发货前TT支付.当前已收到预付款,同意下单.', '同意', '朱君宜2019-01-09 10:30:04', '王维2019-01-09 09:33:44', '同意', '陶保荣2019-01-09 10:53:34', '', '', '', '在原设计产品基础上，根据客户要求减少一些物料处理。', '同意。', '丁富民2019-01-09 17:36:12', '王功勇2019-01-09 17:56:45', 'sctz2019010801', '01', '', '', '', '30%T/T预付款已到账，可以下单。', '鲁慧珍2019-01-08 09:40:00', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('360', '{98507D9D-5A49-4C90-93BC-C68F03BEFAF9}', '61', 'INHE-0500', '2019-01-08 19:12:34', '0000-00-00 00:00:00', '2019-01-09 18:38:54', 'unchecked', 'n', 'n', '', '1', 'sctz2019010802/EOI21/生产通知单', '', '出货请按照表号顺序装箱\r\n请使用EOI库存订单', '300', '2019-01-08 19:12:34', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI21', 'INHESC2019010301', '2019-01-14', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式:合同金额的100%在签订合同后作为预付款在发货前T/T支付。当前已收到全款,同意生产.		\r\n', '同意', '朱君宜2019-01-09 09:11:23', '郭涛2019-01-09 08:11:54', '同意', '陶保荣2019-01-09 09:25:53', '', '', '', '翻单处理，请江西工厂安排处理理。', '同意。', '丁富民2019-01-09 17:37:08', '王功勇2019-01-09 17:56:01', 'sctz2019010802', '01', '', '', '', '全款已到账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2019-01-08 19:25:28', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('361', '{7C271D44-2324-4AFA-AB00-F5572A7EE079}', '61', 'INHE-0500', '2019-01-08 19:17:43', '0000-00-00 00:00:00', '2019-01-25 16:56:29', 'unchecked', 'n', 'n', '', '1', 'sctz2019010803/EOI22/生产通知单', '', '出货请按照表号顺序装箱\r\n请使用EOI库存订单', '260', '2019-01-08 19:17:43', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI22', 'INHESC2019010302', '2019-01-26', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '合同金额的100%在签订合同30天内作为预付款在发货前T/T支付。当前款已到建行,待入账,同意下单.		\r\n', '同意', '朱君宜2019-01-25 11:01:59', '郭涛2019-01-25 10:42:22', '同意', '陶保荣2019-01-25 14:18:23', '', '', '', '', '同意', '丁富民2019-01-25 14:58:57', '王功勇2019-01-25 16:38:10', 'sctz2019010803', '01', '', '', '', '出纳姚茜确认此批全款已到建行，待走流程入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2019-01-25 10:26:52', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('362', '{A7FFA4BC-4BAC-4A9D-A24C-0D98BF71F908}', '97', 'INHE-0662', '2019-01-14 16:09:22', '0000-00-00 00:00:00', '2019-01-15 08:07:36', 'unchecked', 'n', 'n', '', '1', 'sctz2019011402/TTA01-2/生产通知单', '', '1.整机和散件的数量待业务确认后告知。\r\n2.客户交期紧张，业务会争取生产前收到L/C，现需要提前备料和生产。', '95000', '2019-01-14 16:09:22', 'INHEMETER (T) LIMITED', 'TTA', 'TTA01', 'INHESC2018081503', '2019-02-15', '商务组', '陈丽', '第三方检验', '02', '生产通知单', '付款方式为100%不可撤销保兑远期180天信用证。当前未收到L/C，请领导审批是否下单。', '同意', '朱君宜2019-01-14 18:13:13', '郭涛2019-01-14 17:27:27', '同意', '陶保荣2019-01-14 18:26:09', '', '注意：1、业务紧跟LC，控制风险；2、采购注意深圳研发调整、修改的部分。', '', '表箱底壳需要重新开模，已经作了安排；表计MCU单元BOM表、PCB板根据上次批量生产情况作局部调整优化，计划近期完成。', '同意', '丁富民2019-01-14 18:56:33', '王功勇2019-01-14 21:35:34', 'sctz2019011402', '01', '', '', '', '未收到L/C，请领导审批是否下单，谢谢。', '鲁慧珍2019-01-14 17:18:11', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('363', '{01C39628-37FE-4663-AA06-FE4939786256}', '66', 'INHE-0634', '2019-01-16 19:13:27', '0000-00-00 00:00:00', '2019-01-21 16:47:09', 'unchecked', 'n', 'n', '', '1', 'sctz2019011601/KNT01/生产通知单', '', '', '320', '2019-01-16 19:13:27', 'Kinetic Myanmar Technology Co., Ltd', 'KNT', 'KNT01', 'INHESC2018121401', '2019-03-17', '国际三部 INTL.Business Dept.3', '陈雁', '', '04', '生产通知单', '结算方式:100% T/T预付款,当前已收到全款,同意下单.		\r\n', '同意。', '朱君宜2019-01-18 09:27:02', '王梅2019-01-17 18:04:48', '同意', '陶保荣2019-01-18 10:04:19', '', '', '', '单相表按TTA项目单相代码表处理；三相表按ING项目三相代码表处理；RF采用慧联通信RF-III方案；集中器按现成产品生产；抄表系统收取年服务费用。---文控整理给出BOM表，研发不再安排处理。', '同意。', '丁富民2019-01-21 14:06:27', '王功勇2019-01-21 16:10:18', 'sctz2019011601', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2019-01-17 18:03:20', '00', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('364', '{9734FE28-A3C1-469B-B9D9-A85D370E283F}', '61', 'INHE-0654', '2019-01-17 15:16:46', '0000-00-00 00:00:00', '2019-01-21 16:44:27', 'unchecked', 'n', 'n', '', '1', 'sctz2019011702/ADD01/生产通知单', '下单数量不对', '1，客户的预付款将会在年前收到，由于工厂即将放假，业务先走生产通知单，望公司领导审批同意。2，ADD的订单共计为6万台，电力公司人员要求对前2万台产品进行产品检验。3，该市场要求极为严格，任何有变动修改的希望工厂要第一时间通知业务。', '20000', '2019-01-17 15:16:46', 'Cashpower Sudamericana S.A.', 'ADD', 'ADD01', 'INHESC2018092601', '2019-04-15', '国际二部 INTL.Business Dept.2', '李明(Ming)', '第三方检验', '02', '生产通知单', '结算方式:每批货物CIF货值10%预付款支付给银河表计,每批货物90%尾款在提单日后120天内通过T/T支付给银河表计.当前未收到预付款,请领导审核是否下单.', '同意备料。', '朱君宜2019-01-18 09:12:21', '郭涛2019-01-17 21:11:59', '同意', '陶保荣2019-01-18 10:03:52', '', '请业务紧密跟踪预付款到账，以及后续发货中信保的担保手续，订单不大，希望执行利索，马拉松式的执行，耗费太大。', '', '此项目研发负责人：王顺万    第一代可更换通信模块表，带分体式显示单元。', '同意。', '丁富民2019-01-21 11:52:46', '王功勇2019-01-21 16:09:23', 'sctz2019011702', '01', '', '', '', '未收到预付款，请领导审核能否下单，谢谢！', '鲁慧珍2019-01-17 18:15:37', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('365', '{52377889-6419-4DC9-8312-B06735140C55}', '60', 'INHE-0066', '2019-01-18 14:26:08', '0000-00-00 00:00:00', '2019-01-21 16:40:30', 'unchecked', 'n', 'n', '', '1', 'sctz2019011801/RTK01/生产通知单', '', '没有特殊的需求，按公司常规标准样机制作，基本性能参数如下：\r\r\n单相表：5（60）A，有功1.0，无功2.0,50Hz,230V,双回路计量，DLMS，带继电器，红外通信，复费率,GPRS/GSM，单进单出，温度：-40C-70C\r\r\n三相表：5(100)A，有功1.0，无功2.0，50Hz,3*230V,DLMS,带继电器，红外通信，复费率，GPRS/GSM，单进单出，温度：-40C-70C\r\r\n', '6', '2019-01-18 14:26:08', 'JSC NPK ROTEK', 'RTK', 'RTK01', ' INHESC2019011501', '2019-01-27', '国际一部 INTL.Business Dept.1', '邱洁', '', '05', '生产通知单', '结算方式为100%预付款TT.当前已收到全款，同意下单。', '同意', '朱君宜2019-01-18 18:31:08', '王维2019-01-18 18:24:00', '同意', '陶保荣2019-01-21 08:36:12', '', '', '', '业务提出没有特殊要求，按公司常规产品交货数量少（6台），建议江西工厂用库存产品处理交货。', '同意。', '丁富民2019-01-21 11:45:03', '王功勇2019-01-21 16:07:03', 'sctz2019011801', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2019-01-18 18:12:19', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('366', '{F6C63C55-9106-4787-AAAF-FEF82F303825}', '97', 'INHE-0771', '2019-01-21 18:02:40', '0000-00-00 00:00:00', '2019-01-24 16:03:05', 'unchecked', 'n', 'n', '', '1', 'sctz2019012104/MD03/生产通知单', '', '1. MD02翻单产品，有如下修改#FE54`电压为230V；电压门限值为0,7Un 至1,3Un；频率为50±2.5\rHZ.              2. 发货前需要SGS验货，麻烦提前通知。                                                           3. FOB九江，货发九江码头。                                                                   4. 客户已付预付款。\r\r\n\r\r\n\r\r\r\n\r\r\n', '10000', '2019-01-21 18:02:40', 'BCCT.SAS', 'MD', 'MD03', '600000862', '2019-03-08', '商务组', '吴艳', '第三方检验', '06', '生产通知单', '结算方式:30%签订合同后T/T预付款+ 70%验货后发货前T/T付款。当前已收到30%预付款,同意下单.		\r\n', '同意', '朱君宜2019-01-23 11:16:29', '郭涛2019-01-23 09:49:55', '同意', '陶保荣2019-01-23 18:45:25', '', '', '', '注意电能表额定工作电压由220V修改为230V.其他不作变动。', '同意。MD02项目翻单生产，请江西工厂安排处理；注意面板额电压由220V修改为230V.', '丁富民2019-01-24 10:14:16', '王功勇2019-01-24 15:59:18', 'sctz2019012104', '01', '', '', '', '30%预付款已到账，可以下单。', '鲁慧珍2019-01-22 17:35:28', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('367', '{EAFBB19A-7E8E-4634-A51B-35B232F237B1}', '60', 'INHE-0560', '2019-01-24 16:53:02', '0000-00-00 00:00:00', '2019-01-25 16:46:37', 'unchecked', 'n', 'n', '', '1', 'sctz2019012401/白雪902/生产通知单', '', '', '0', '2019-01-24 16:53:02', 'Energomera CJSC', '白雪', '白雪902', 'PO#E19_1901', '2019-02-19', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式:5173.5USD-预付  2196.5USD-尾款.当前已收到预付款, 同意下单.		\r\n', '同意', '朱君宜2019-01-25 09:27:47', '王维2019-01-25 08:59:34', '同意', '陶保荣2019-01-25 10:17:44', '', '', '', '', '同意', '丁富民2019-01-25 10:28:19', '王功勇2019-01-25 14:00:20', 'sctz2019012401', '01', '', '', '', '合同规定的预付款已到账，可以下单。', '鲁慧珍2019-01-24 17:13:00', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('368', '{43F23EC5-0FF2-4357-B125-2DF54769CC69}', '60', 'INHE-0560', '2019-01-24 16:55:44', '0000-00-00 00:00:00', '2019-01-25 16:35:28', 'unchecked', 'n', 'n', '', '1', 'sctz2019012402/白雪903/生产通知单', '', '\r\r\r\r\n白雪单相表要求：\r\r\r\r\n1、采用新模具结构供货。     \r\r\r\r\n2、PCB板不需灌胶和喷三防漆！\r\r\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。      \r\r\r\r\n4、MAC地址为该表表号（表地址）的最后六位数字，该地址激光雕刻在表外壳背部。       \r\r\r\r\n5、PLC载波显示单元的铭牌标识为：CE208。         \r\r\r\r\n6、显示单元不需要贴易碎贴。        \r\r\r\r\n7、出厂设置：           \r\r\r\r\n1）表内时间为：GMT+4           \r\r\r\r\n2）冬夏令时转换功能关闭。           \r\r\r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\r\r\n5）特殊节假日没有。           \r\r\r\r\n6）电表密码：000000.           \r\r\r\r\n7）负荷门限：0.           \r\r\r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\r\r\n9）取负荷点的平均时间：30分钟。          \r\r\r\r\n8、继电器：100A，但标识采用120A。      \r\r\r\r\n9、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）       \r\r\r\r\n10、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\r\r\n11、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU的内盒中。									\r\r\r\r\n12、单相表显示单元铭牌信息采用镭雕                                                             \r\r\n13、删除打标信息，改为可撕拉的贴纸标记表号和产品型号                                               白雪三相表要求：\r\r\r\r\n1、采用双方验证过的程序版本TMF2-1B-16032201\r\r\r\r\n2、修改过脉冲输出的阻抗。						\r\r\r\r\n3. 铭牌、MAC地址等需要镭雕在电表外壳上； \r\r\r\r\n4. MAC地址铭牌的6位数字为该表表号的最后六位数字；\r\r\r\r\n5. 表内时间为GMT+3#FE54` \r\r\r\r\n6. 冬夏令时转换功能关闭； \r\r\r\r\n7. 需要把面板上的表号设到电表内 \r\r\r\r\n8. 计量单元不需要打铅封。\r\r\r\r\n9、计量单元、显示单元都不需要贴合格证 \r\r\r\r\n10、三相表默认密码为777777。 \r\r\r\r\n11：内盒不需要贴条形码\r\r\r\r\n12：计量单元和显示单元都取消易碎贴纸	  						   \r\r\r\r\r\r\n13、删除打标信息，改为可撕拉的贴纸标记表号及产品型号			                                                         										\r\r\r\r\n', '10', '2019-01-24 16:55:44', 'Energomera CJSC', '白雪', '白雪903', 'PO#E19_1701-T', '2019-01-30', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式:100%TT-下单时支付.当前已收到全款,同意下单.', '同意', '朱君宜2019-01-25 09:50:14', '王维2019-01-25 09:00:08', '同意', '陶保荣2019-01-25 10:17:27', '', '', '', '', '同意', '丁富民2019-01-25 10:27:51', '王功勇2019-01-25 14:01:58', 'sctz2019012402', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2019-01-24 18:49:24', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('369', '{D9D48756-8A1B-4CA9-B504-1143AE75D4D4}', '61', 'INHE-0500', '2019-02-01 12:19:18', '0000-00-00 00:00:00', '2019-02-11 15:35:48', 'unchecked', 'n', 'n', '', '1', 'sctz2019020101/EOI24/生产通知单', '', '使用EOI库存订单；请按照表号顺序装箱发货\r\r\n\r\n', '400', '2019-02-01 12:19:18', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI24', 'INHESC2019012602', '2019-02-12', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式:合同金额100%发货前T/T支付.已跟出纳姚茜确认全款已到建行, 待走流程入账,建议下单.', '同意', '朱君宜2019-02-11 13:35:50', '郭涛2019-02-11 13:26:32', '同意', '陶保荣2019-02-11 14:27:57', '', '', '', '库存订单处理，请江西工厂安排。', '同意。', '丁富民2019-02-11 14:47:04', '王功勇2019-02-11 14:53:32', 'sctz2019020101', '01', '', '', '', '出纳姚茜确认此批全款已到建行，待走流程入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2019-02-11 09:09:02', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('370', '{6B0FE5D6-00E9-42B1-A4DD-F57EF3E669EE}', '61', 'INHE-0500', '2019-02-12 17:06:43', '0000-00-00 00:00:00', '2019-02-14 09:29:43', 'unchecked', 'n', 'n', '', '1', 'sctz2019021202/EOI25/生产通知单', '', '', '400', '2019-02-12 17:06:43', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI25', 'INHESC2019021101', null, '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式:合同金额的100%在签订合同30天内作为预付款在发货前T/T支付.已找出纳姚茜核实全款已到建行,待走流程入账,建议下单.', '同意', '朱君宜2019-02-13 16:39:53', '郭涛2019-02-13 13:47:05', '同意', '陶保荣2019-02-13 16:45:51', '', '', '', '库存订单，请江西工厂安排处理。', '同意。', '丁富民2019-02-14 09:08:04', '王功勇2019-02-14 09:11:18', 'sctz2019021202', '01', '', '', '', '出纳姚茜确认此批全款已到建行，待走流程入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2019-02-13 10:18:13', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('371', '{4CAF98A0-20CE-4B9E-A062-144B47969C2C}', '61', 'INHE-0381', '2019-02-22 14:08:56', '0000-00-00 00:00:00', '2019-02-25 17:43:59', 'unchecked', 'n', 'n', '', '1', 'sctz2019022201/GS02/生产通知单', '', '1.已收到客户全款。2.短信猫，需要客服负责验货后发货。', '0', '2019-02-22 14:08:56', 'TOGO ASSISTANCE SERVICES', 'GS01', 'GS02', 'INHESC2019022001', '2019-03-06', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '', '06', '生产通知单', '结算方式：100%采购前TT,当前已收到全款， 同意下单。', '同意', '朱君宜2019-02-25 15:47:40', '郭涛2019-02-25 15:07:45', '同意', '陶保荣2019-02-25 15:53:20', '', '', '', '', '同意。', '丁富民2019-02-25 17:05:10', '王功勇2019-02-25 17:42:06', 'sctz2019022201', '01', '', '', '', '全款已收齐，可以下单。', '鲁慧珍2019-02-22 14:16:21', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('372', '{3FEB8A15-1A8B-4011-81F4-9851AF6B5897}', '61', 'INHE-0500', '2019-02-24 18:56:39', '0000-00-00 00:00:00', '2019-02-27 18:15:22', 'unchecked', 'n', 'n', '', '1', 'sctz2019022401/EOI26/生产通知单', '', '请使用EOI库存订单；请按照表号顺序装箱\r\n', '400', '2019-02-24 18:56:39', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI26', 'INHESC2019022002', '2019-02-27', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '合同金额的100%在签订合同后作为预付款在发货前T/T支付。当前全款已到建行,待走流程入账,可以下单.		\r\n', '同意', '朱君宜2019-02-27 14:31:28', '郭涛2019-02-27 13:23:32', '同意', '陶保荣2019-02-27 14:37:08', '', '', '', '', '同意，EOI库存表生产，属翻单处理，请江西工厂安排。', '丁富民2019-02-27 17:11:38', '王功勇2019-02-27 17:51:01', 'sctz2019022401', '01', '', '', '', '出纳姚茜确认此批全款已到建行，待走流程入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2019-02-26 10:48:14', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('373', '{D921C92E-02FC-4400-AF4F-6456DADD7DD9}', '60', 'INHE-0088', '2019-02-25 11:16:31', '0000-00-00 00:00:00', '2019-02-26 08:05:52', 'unchecked', 'n', 'n', '', '1', 'sctz2019022501/ST20710-5&6/生产通知单', '', '生产要求如下：\r\r\r\r\r\n1. 外箱唛头更新银河公司名称；\r\r\r\r\r\r\n2. 产品图纸更新年份为2019；\r\r\r\r\r\r\n3. 散件PCBA,LCD重要物料打托，金属件/电池物料打木箱，生产后提供该批次表号数据及密钥文件；\r\n4. 300A计量箱木箱包装；\r\r\r\r\r\r\n5. 出货前客户将到厂验货；\r\r\r\r\n计划分两批出货：\r\r\r\r\r\r\n第一批：92733套单相表散件\r\r\r\r；\r\r\n第二批：500套BOX-T300中电流计量箱；', '93233', '2019-02-25 11:16:31', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20710', 'INHESC2017092801', '2019-03-25', '国际一部 INTL.Business Dept.1', '余冬纯', '', '02', '生产通知单', '结算方式：不可撤销非保兑即期信用证，信用证下10%预付，90%交发货单据扫描件议付	，当前10%预付款已到帐，L/C收到且审核通过。同意生产。	\r\n', '同意', '朱君宜2019-02-25 13:45:19', '王维2019-02-25 12:16:01', '同意', '陶保荣2019-02-25 14:29:29', '', '', '', '', '同意。翻单生产处理，有江西工厂安排。', '丁富民2019-02-25 17:03:39', '王功勇2019-02-25 17:41:13', 'sctz2019022501', '01', '', '', '', 'ST20710-5：92733套单相表散件；ST20710-6：500套BOX-T300中电流计量箱；L/C收到且审核通过，10%预付款已议付到账，可以下单。', '鲁慧珍2019-02-25 11:36:30', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('374', '{A6AFB37A-952E-4169-979C-666BB8E92480}', '61', 'INHE-0772', '2019-02-27 17:24:09', '0000-00-00 00:00:00', '2019-03-07 16:00:27', 'unchecked', 'n', 'n', '', '1', 'sctz2019022702/GBA01(旧)/生产通知单', '', '请先提供一台样机给客户验货', '5000', '2019-03-01', '冈比亚国家水电公司', 'GBA', 'GBA01(旧)', 'INHESC2019021102', '2019-03-15', '国际二部 INTL.Business Dept.2', '张子琦(Miranda)', '', '06', '生产通知单', '结算方式：50%TT-生产前，50%尾款， 当前50%预付款到建行，但因业务未提供合同和发票无法入帐，请领导审批是否同意下单。', '同意。请张子琦注意电流相关事宜。', '朱君宜2019-03-07 09:30:18', '郭涛2019-03-06 16:17:10', '同意', '陶保荣2019-03-07 10:31:18', '', '', '', '生产通知单上的电流规格与所附技术规格上的电流规格不一致，无法安排。', '不同意。', '丁富民2019-03-07 15:04:52', '王功勇2019-03-07 15:55:00', 'sctz2019022702', '02', '', '', '', '出纳姚茜确认50%预付款已到建行，因业务未提供合同和发票还无法入账，交期紧急，是否下单请各位领导审批，谢谢！', '鲁慧珍2019-03-06 15:00:42', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('375', '{19E9B331-FE38-4EB3-861E-9139493337BC}', '60', 'INHE-0560', '2019-02-28 08:51:04', '0000-00-00 00:00:00', '2019-02-28 18:48:55', 'unchecked', 'n', 'n', '', '1', 'sctz2019022802/白雪904/生产通知单', '', '', '0', '2019-02-28 08:51:04', 'Energomera CJSC', '白雪', '白雪904', 'PO#E19_1202', '2019-03-02', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式:30%-下单时预付，70%-发货前付款,当前已收到30%预付款,同意下单.		\r\n', '同意', '朱君宜2019-02-28 15:55:39', '王维2019-02-28 15:48:45', '同意', '陶保荣2019-02-28 16:19:05', '', '', '', '', '同意', '丁富民2019-02-28 17:08:15', '王功勇2019-02-28 17:11:01', 'sctz2019022802', '01', '', '', '', '30%预付款已到账，可以下单。', '鲁慧珍2019-02-28 10:29:46', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('376', '{3F2EC5AB-B16C-42EC-8118-3417C4E9DFCD}', '97', 'INHE-0549', '2019-03-01 14:14:04', '0000-00-00 00:00:00', '2019-03-05 11:46:36', 'unchecked', 'n', 'n', '', '1', 'sctz2019030102/CAM01/生产通知单', '', '出货产品与样机一致。如有任何问题请联系王秀明（15705276012）。谢谢！', '2000', '2019-03-01 14:14:04', 'Société IYA', 'CAM', 'CAM01', 'INHESC2019022601', '2019-03-26', '商务组', '王秀明', '', '05', '生产通知单', '结算方式：合同金额的50%在签订合同10天内作为预付款T/T支付，50%余款在发货前T/T支付，当前已收到50%预付款，同意下单。		\r\n', '同意', '朱君宜2019-03-04 09:18:37', '王维2019-03-04 07:22:41', '同意', '陶保荣2019-03-04 09:21:48', '', '', '', '第一代三相一体式代码预付费电能表，要求是 语提示。--GNC项目样机与CAM项目样机一致，程序需要作一个全面测试验证。章春鹏负责。', '同意。', '丁富民2019-03-04 10:17:16', '王功勇2019-03-04 10:29:42', 'sctz2019030102', '01', '', '', '', '出纳姚茜确认50%T/T预付款平安银行已查到并在入账中，可以下单。', '鲁慧珍2019-03-01 16:10:11', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('377', '{0326C89E-2C43-4E42-8C90-D03D0961202C}', '61', 'INHE-0500', '2019-03-01 16:51:51', '0000-00-00 00:00:00', '2019-03-04 13:45:01', 'unchecked', 'n', 'n', '', '1', 'sctz2019030105/EOI23/生产通知单', '', '请使用EOI库存订单出货；请按照表号顺序装箱\r\n', '808', '2019-03-01 16:51:51', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI23', 'INHESC2019012601', '2019-03-04', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '当前已收到全款，同意下单。', '同意', '朱君宜2019-03-01 17:40:26', '郭涛2019-03-01 17:08:34', '同意', '陶保荣2019-03-01 17:48:15', '', '', '', '', '同意', '丁富民2019-03-04 08:31:52', '王功勇2019-03-04 10:26:03', 'sctz2019030105', '01', '', '', '', '全款已收齐，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2019-03-01 17:00:27', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('378', '{42A99171-5B5F-49B6-9935-8F99AF266D72}', '61', 'INHE-0500', '2019-03-03 16:22:52', '0000-00-00 00:00:00', '2019-03-07 15:59:16', 'unchecked', 'n', 'n', '', '1', 'sctz2019030301/EAB02/生产通知单', '', '1.技术规格请和EAB01订单保持一致；\r\n2.电表和CIP铭牌、包材请提前和业务确认；\r\n3.请按照表号顺序装箱。', '2000', '2019-03-03 16:22:52', 'Baltazar Fernandes and Moreira,lda', 'EAB', 'EAB02', 'INHESC2019022701', '2019-04-01', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '付款条件：合同金额的玖万叁仟美元在签订合同20天内作为预付款T/T支付，合同尾款在发货前T/T支付。当前新增数量后尾款已到银行,待走流程入账,请业务提供合同给财务,可以下单.		\r\n', '同意', '朱君宜2019-05-27 09:01:13', '郭涛2019-05-25 22:55:29', '同意', '陶保荣2019-05-27 09:16:56', '', '', '', '订单增加订货数量,属翻单生产,请江西工厂安排处理.', '同意.', '丁富民2019-05-27 11:25:41', '王功勇2019-05-27 11:31:40', 'sctz2019030301', '01', '', '', '', '出纳姚茜确认新增数量后的尾款已到银行，待走流程入账，可以下单。', '鲁慧珍2019-05-24 16:37:46', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('379', '{ACE3F23D-8F6C-425F-9C70-F34AC0B23A43}', '97', 'INHE-0051', '2019-03-05 13:51:55', '0000-00-00 00:00:00', '2019-03-07 09:37:49', 'unchecked', 'n', 'n', '', '1', 'sctz2019030501/SNG01/生产通知单', '', '1.客户为珠海配电，已完成销售合同评审，近2天会签订合同。\r\r\r\n2.交期要求紧张，需尽快交货。\r\r\n', '10', '2019-03-05 13:51:55', 'Inhegrid', 'SNG', 'SNG01', 'INHESGC19022801', '2019-03-17', '商务组', '盛燕', '', '06', '生产通知单', '结算方式:合同签订后，卖方于 15 个工作日内完成生产,采用月结付款.赊销,同意下单.', '同意', '朱君宜2019-03-05 17:45:12', '盛燕2019-03-05 17:40:12', '同意', '陶保荣2019-03-05 20:05:33', '', '', '', '没有特别要求，建议由江西工厂按最新三相多功能表（CT表）BOM表、程序安排生产处理。', '同意。', '丁富民2019-03-06 09:25:49', '王功勇2019-03-06 10:17:59', 'sctz2019030501', '01', '', '', '', '赊销，可以下单。', '鲁慧珍2019-03-05 17:19:49', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('380', '{B0BE5F8C-BF6A-421F-AD84-3AB9700AEBA9}', '61', 'INHE-0500', '2019-03-06 11:05:25', '0000-00-00 00:00:00', '2019-03-07 15:57:53', 'unchecked', 'n', 'n', '', '1', 'sctz2019030601/EXJ03/生产通知单', '', '', '200', '2019-03-06 11:05:25', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'EXJ', 'EXJ03', 'INHESC2019022803', '2019-04-01', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式：签订合同20天内T/T支付100%的合同款项。当前未收到款，领导已同意备料生产，同意下单。	\r\n', '同意', '朱君宜2019-03-07 09:21:51', '郭涛2019-03-06 22:33:38', '同意', '陶保荣2019-03-07 10:06:52', '', '', '', 'EXJ01项目产品翻单处理，请江西工厂安排处理。', '同意。', '丁富民2019-03-07 14:50:41', '王功勇2019-03-07 15:52:54', 'sctz2019030601', '01', '', '', '', '未收到款，付款条件为100%发货前T/T，可以下单。', '鲁慧珍2019-03-06 11:26:18', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('381', '{5B572778-24B8-4209-AB84-3376C59ED750}', '61', 'INHE-0381', '2019-03-07 10:42:35', '0000-00-00 00:00:00', '2019-03-08 17:26:01', 'unchecked', 'n', 'n', '', '1', 'sctz2019030701/NEW02/生产通知单', '', '1.替换原来下发的NEW02试生产通知单。集中器要能跟电表通信。2.生产后会申请客服前往工厂验货。3.根据\r\r\r\r\r\r\r\r\r\r\r\r\n海关要求，客户要求发货前要BV或泰纳验货，发货需要带VOC证书一起。如果未获得客户验收成功的前提下，这些需要进行物理性验收的货物不能包装或发货。4。发货前，需要提前给客户发技术规格、VOC测试报告、厂家ISO证书副本。如果提供的文件或泰纳验收不允许签发\"VOC有效合格证书\"，那么本订单将被视为无效并且无法在目的国进口这些货物。5.包装需是加强的CI5纸板包装。若是用木箱包装，必须符合NIMP15标准，且带证书。6.在风险和环境方面，为了告知用户并采取一切可能的预防使用产品的风险，每份产品必须附上FDS产品表（安全数据文件），或者至少，每份产品附上环境和安全的特别说明。7.发货时必须提供以下文件：1）海关的出口申报表明重量（与装箱单上的相同）和该订单的总金额；2）所有电表的校准证书；3）测量测试报告；4）技术规格。8.请跟单组注意：开给客户的发票需要表明订单号、不含税，并请在发票上和原产地证书上注明：EXONERE DE TVA:VENTE SOUS DOUANE FCA，HORS CHAMP D\'APPLICATION TERRITOIRE DE LA TVA\"翻译为：免收增值税: 根据香港海关FCA销售,增值税的领土应用范围以外\"\r9.FCA香港。不按以上指示操作产生的所有费用，将由厂家承担。10.此项目特别重要，请务必按照以上要求执行。', '410', '2019-03-07 10:42:35', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'NEW', 'NEW02', '19000147 CA', '2019-03-29', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '第三方检验', '06', '生产通知单', '赊销，同意下单。', '同意。欧洲客户要求细致，请跟单注意货物出口和当地进口证书，文件的合规和准确。', '朱君宜2019-03-08 14:55:14', '郭涛2019-03-07 17:44:10', '同意', '陶保荣2019-03-08 15:00:19', '', '', '', '', '同意', '丁富民2019-03-08 15:09:43', '王功勇2019-03-08 16:32:01', 'sctz2019030701', '01', '', '', '', '赊销，可以下单。', '鲁慧珍2019-03-07 11:47:45', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('382', '{F4EEA9A5-FA9A-4392-910A-C4C6E265B002}', '61', 'INHE-0772', '2019-03-08 17:30:40', '0000-00-00 00:00:00', '2019-03-12 13:52:11', 'unchecked', 'n', 'n', '', '1', 'sctz2019022702/GBA01/生产通知单', '', '空运在3月20号前发货（1000支表），海运在4月4号前发货（4000支表）', '5000', '2019-03-01', '冈比亚国家水电公司', 'GBA', 'GBA01', 'INHESC2019021102', '2019-03-20', '国际二部 INTL.Business Dept.2', '张子琦(Miranda)', '', '06', '生产通知单', '结算方式：生产前50%T/T，50%尾款在发货前。当前50%预付款已到建行，待业务提供合同和发票后入账，交期紧急，是否下单请各位领导审批，谢谢！										\r\r\n', '同意。请注意交期，此订单是紧急直采，部分空运，需要按期交付。', '朱君宜2019-03-11 09:02:54', '郭涛2019-03-08 18:27:55', '同意', '陶保荣2019-03-11 09:13:12', '', '', '', '以TTA项目单相表为基础（已经批量供货），电流互感器需要作修改处理外【10（60）A---更换为5（80）A】，其他物料可以安排备料---项目由余祥林尹旭文负责', '同意', '丁富民2019-03-11 10:38:08', '王功勇2019-03-12 13:42:56', 'sctz2019022702', '01', '', '', '', '出纳姚茜确认50%预付款已到建行，待业务提供合同和发票后入账，交期紧急，是否下单请各位领导审批，谢谢！', '鲁慧珍2019-03-08 17:54:15', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('383', '{0E6C5344-5CC3-48AB-B315-12212010C102}', '97', 'INHE-0727', '2019-03-14 18:23:49', '0000-00-00 00:00:00', '2019-03-18 08:44:59', 'unchecked', 'n', 'n', '', '1', 'sctz2019031401/WZT02/生产通知单', '', '注：所需产品应从深圳发往客户', '0', '2019-03-14 18:23:49', 'West Zone Power Distributin Company Limited', 'WZT', 'WZT02', 'INHESC2019021901', '2019-03-19', '商务组', '何素贞', '', '06', '生产通知单', '客户追加15个关电头未付款,因外汇管制问题,采取现金收款,请领导审批。', '同意按照现金收款方式交易新增加的光电头，请王总考虑。', '朱君宜2019-03-22 09:32:47', '王维2019-03-22 09:10:53', '同意', '陶保荣2019-03-22 11:34:53', '', '', '', '', '同意', '丁富民2019-03-22 13:27:21', '王功勇2019-03-22 13:49:08', 'sctz2019031401', '01', '', '', '', '追加的15个光电头未付款，据业务反馈因客户外汇管制问题，此部分款将出差现场收取客户现金。交期紧急，请领导审批是否下单，谢谢！', '鲁慧珍2019-03-22 08:55:03', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('384', '{77D98CC3-C1F0-4855-BE99-811D0EB19CC8}', '61', 'INHE-0776', '2019-03-14 16:59:01', '0000-00-00 00:00:00', '2019-03-29 11:34:45', 'unchecked', 'n', 'n', '', '1', 'sctz2019031402/PLD01/生产通知单', '', '因公司现有RF模块433 MHz频段目前不满足市场强制要求，故申请延迟交货RF模块产品。 客户表示需要尽快交货此试点项目设备，电力公司也要求立即给具体的交货时间，同时合同有逾期交货罚款，请工厂方面务必尽快就除RF模块的电表产品立即排产，按时交货。', '91', '2019-03-14 16:59:01', 'TECH INDUSTRIAS GLOBALES S.R.L', 'PLD', 'PLD01', 'INHESC2019011601', '2019-04-10', '国际二部 INTL.Business Dept.2', '李玟', '', '05', '生产通知单', '结算方式：30%生产前TT预付，70%尾款发货前TT支付。当前已收到全款。同意下单。', '业务接受先交付除920MHZ模块外的其他产品，RF模块待公司研发测试完成再交付。', '朱君宜2019-03-29 10:58:17', '郭涛2019-03-29 04:47:11', '同意', '陶保荣2019-03-29 11:12:01', '', '', '', '技术规格非常简单，没有特别要求之处。建议使用ADD项目产品进行生产安排。---使用第一代可更换通信模块表，项目负责人王顺万。', '同意。', '丁富民2019-03-29 11:27:51', '王功勇2019-03-29 11:32:07', 'sctz2019031402', '01', '', '', '', '全款已到账，可以下单。交期紧张！', '鲁慧珍2019-03-28 16:29:10', '01', '★★', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('386', '{EDF5D523-8872-468B-A076-059EA8206E2C}', '61', 'INHE-0500', '2019-03-16 22:38:29', '0000-00-00 00:00:00', '2019-03-18 18:34:41', 'unchecked', 'n', 'n', '', '1', 'sctz2019031601/EOI14/生产通知单', '', '1.EOI14要求走海运，请跟单组提前尽快安排；\r\n2.请使用EOI库存订单和按照表号顺序装箱。', '2333', '2019-03-16 22:38:29', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI14', 'INHESC2018120501', '2019-03-19', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式：签订合同30天内并在准备生产原料之前100%TT支付。经确认EOI14全款金额已到平安银行，待入账，同意下单。', '同意', '朱君宜2019-03-18 17:38:07', '郭涛2019-03-18 16:55:39', '同意', '陶保荣2019-03-18 17:41:45', '', '', '', '翻单生产，请江西工厂安排处理。', '同意', '丁富民2019-03-18 17:49:15', '王功勇2019-03-18 18:00:45', 'sctz2019031601', '01', '', '', '', '出纳姚茜确认此批全款已到平安银行，待走流程入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2019-03-18 14:42:47', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('387', '{752058C1-7117-442A-B2C1-12D9F433F768}', '60', 'INHE-0560', '2019-03-21 09:41:50', '0000-00-00 00:00:00', '2019-03-22 17:12:28', 'unchecked', 'n', 'n', '', '1', 'sctz2019032101/白雪905/生产通知单', '', '', '0', '2019-03-21 09:41:50', 'Energomera CJSC', '白雪', '白雪905', 'PO#E19_0503', '2019-04-01', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式：30%-下单时支付 70%-发货前支付，当前已收到30%预付款，同意下单。', '同意', '朱君宜2019-03-21 18:07:41', '王维2019-03-21 17:57:22', '同意', '陶保荣2019-03-21 18:21:38', '', '', '', '', '同意', '丁富民2019-03-22 09:24:59', '王功勇2019-03-22 10:37:24', 'sctz2019032101', '01', '', '', '', '30%T/T预付款已到账，可以下单。', '鲁慧珍2019-03-21 09:49:00', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('388', '{4EF7CDA0-8731-43F1-830E-DCA1EF8C10CF}', '61', 'INHE-0500', '2019-03-21 14:55:20', '0000-00-00 00:00:00', '2019-03-22 17:12:02', 'unchecked', 'n', 'n', '', '1', 'sctz2019032102/EOI28/生产通知单', '', '', '500', '2019-03-21 14:55:20', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI28', 'INHESC2019031901', '2019-03-25', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式：发货前收到100%全款。经出纳核实，此批全款已到银行，预计今天入账，同意下单。', '同意', '朱君宜2019-03-22 09:38:31', '郭涛2019-03-21 19:29:36', '同意', '陶保荣2019-03-22 11:34:29', '', '', '', '库存产品，请江西工厂安排处理。', '同意', '丁富民2019-03-22 13:28:18', '王功勇2019-03-22 13:50:18', 'sctz2019032102', '01', '', '', '', '出纳姚茜确认此批全款已到银行，预计明天入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2019-03-21 17:54:15', '', '', null, null, null);
INSERT INTO `crs_tabledata719` VALUES ('389', '{C86F7755-7CBC-40A8-A2F5-024E6373194D}', '61', 'INHE-0500', '2019-03-22 20:40:04', '0000-00-00 00:00:00', '2019-03-27 16:25:23', 'unchecked', 'n', 'n', '', '1', 'sctz2019032201/EOI11/生产通知单', '', '1.DIN 导轨表总计3838台，其中3060台需要镭雕客户Logo，剩下778台直接按照EOI库存出货，2019年3月22日已和贾工OA确认镭雕方案；\r2.BS三相表100台，需要镭雕客户Logo，2019年3月22日已和贾工OA确认镭雕方案；\r3.EOI11空运发货需要分成两批两个地点，请跟单组和业务确认最终的箱单和发货资料；\r4.请按照表号顺序装箱和发货。\r\r\r\n\r\n', '3938', '2019-03-22 20:40:04', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI11', 'INHESC2019032101', '2019-04-01', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '结算方式：合同金额的100%在签订合同30天内并在发货前作为预付款T/T支付。当前已跟姚茜确认全款已到银行，待入账，同意下单。		\r\n', '同意', '朱君宜2019-03-26 16:11:09', '郭涛2019-03-26 16:02:45', '同意', '陶保荣2019-03-26 18:13:31', '', '', '', '库存表翻单生产，请江西工厂安排。', '同意', '丁富民2019-03-27 08:17:53', '王功勇2019-03-27 15:36:14', 'sctz2019032201', '01', '', '', '', '出纳姚茜确认此批全款已到银行，预计明后天入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2019-03-26 13:49:23', '', '', null, null, null);
