INSERT INTO `crs_tabledata719` VALUES ('398', '{13E34240-2BFE-4C19-8406-2BBA5AADE249}', '97', 'INHE-0662', '2019-04-16 16:17:39', '0000-00-00 00:00:00', '2019-04-17 18:54:47', 'unchecked', 'n', 'n', '', '1', 'sctz2019041602/ITL05/生产通知单', '', 'ITL市场几个LPO已经中标，包含15000台三相表，当地工厂急需三相生产和测试设备，需要尽快完成设备采购并发出。业务告知只有一个月的交期。', '0', '2019-04-16 16:17:39', 'Africarriers Ltd', 'ITL', 'ITL05', 'INHESC2019041001', '2019-04-29', '商务组(Commerce Division)', '陈丽', '', '05', '生产通知单', '结算方式:50%生产前支付,50%尾款发货前支付。当前已收到50%预付款, 同意下单. 		\r\n', '同意', '朱君宜2019-04-17 08:50:42', '郭涛2019-04-16 18:14:28', '同意', '陶保荣2019-04-17 09:49:34', '', '', '', '生产设备，请江西工厂安排处理。', '同意', '丁富民2019-04-17 10:09:26', '王功勇2019-04-17 11:27:55', 'sctz2019041602', '01', '', '', '', '出纳姚茜确认50%T/T预付款已在银行走入账流程，预计明天前到账，可以下单。', '鲁慧珍2019-04-16 17:52:18', '', '', 'Inhemeter (T) Limited', null, null);
INSERT INTO `crs_tabledata719` VALUES ('399', '{24720FA4-3275-4FB7-9023-4E535EB87E03}', '60', 'INHE-0560', '2019-04-18 08:41:41', '0000-00-00 00:00:00', '2019-04-19 16:59:06', 'unchecked', 'n', 'n', '', '1', 'sctz2019041801/白雪907/生产通知单', '', '白雪901订单单三相表原来使用的转接板不可用，此订单为客户重新采购的新转接板，新转接板交换了原转接板上rx信号和Tx信号的位置。（请参考附件采购生产）', '0', '2019-04-18 08:41:41', 'Energomera CJSC', '白雪', '白雪907', 'PO#E19_0304', '2019-04-25', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式：下单时-100% TT预付		\r\n当前已收到全款，同意下单。', '同意', '朱君宜2019-04-18 15:34:29', '王维2019-04-18 14:58:59', '同意', '陶保荣2019-04-18 16:41:30', '', '', '', '需要按排研发硬件项目组进行重新设计。---具体负责人张建刚。', '同意。', '丁富民2019-04-19 10:33:01', '王功勇2019-04-19 10:43:58', 'sctz2019041801', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2019-04-18 08:54:30', '', '', 'Energomera CJSC', null, null);
INSERT INTO `crs_tabledata719` VALUES ('400', '{2D70C57A-6F14-4919-A366-83259A80FEC6}', '60', 'INHE-0560', '2019-04-25 17:39:28', '0000-00-00 00:00:00', '2019-04-26 18:01:54', 'unchecked', 'n', 'n', '', '1', 'sctz2019042501/白雪908/生产通知单', '', '', '0', '2019-04-25 17:39:28', 'Energomera CJSC', '白雪', '白雪908', 'PO#E19_1904', '2019-05-13', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式:30%-TT下单预付；70%-TT发货前支付	.当前已收到30%预付款,同意下单	\r\n', '同意', '朱君宜2019-04-26 09:51:05', '王维2019-04-26 09:42:24', '同意', '陶保荣2019-04-26 10:09:33', '', '', '', '外购模块', '同意', '丁富民2019-04-26 10:38:12', '王功勇2019-04-26 14:17:17', 'sctz2019042501', '01', '', '', '', '30%T/T预付款已到账，可以下单。', '鲁慧珍2019-04-25 17:51:01', '', '', 'Energomera CJSC', null, null);
INSERT INTO `crs_tabledata719` VALUES ('401', '{1A21A577-A377-418A-8B21-00D0BCC784B4}', '97', 'INHE-0771', '2019-04-28 13:49:49', '0000-00-00 00:00:00', '2019-04-29 11:50:00', 'unchecked', 'n', 'n', '', '1', 'sctz2019042801/ING21/生产通知单', '', '1.Order Number：19000232 CA Réf:19000027YS#FE54` 2.翻单产品；3.需要在第三方验货后才能发货 4.需提供的文件：所有电表校准证书/出口申报单/技术规格\r\r\n', '87696', '2019-04-28 13:49:49', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING21', '19000232 CA', '2019-06-08', '商务组(Commerce Division)', '吴艳', '第三方检验', '06', '生产通知单', '结算方式：100%LC,60天远期。当前未收到LC，交期紧张，请领导评估是否同意先下单，谢谢！										\r\n\r\r\n', '同意。请张柳芳跟催LC。', '朱君宜2019-04-28 14:21:57', '郭涛2019-04-28 14:19:29', '同意', '陶保荣2019-04-28 14:26:34', '', '', '', '安新方案进行物料备料---新方案正在试生产中。', '同意。', '丁富民2019-04-29 09:14:32', '王功勇2019-04-29 11:38:11', 'sctz2019042801', '01', '', '', '', '未收到LC，交期紧张，请领导评估是否同意先下单，谢谢！', '鲁慧珍2019-04-28 14:12:39', '', '', 'Eranove', null, null);
INSERT INTO `crs_tabledata719` VALUES ('402', '{EA7070D8-7E87-45FD-B67E-C6C7BD4DBE5C}', '97', 'INHE-0771', '2019-04-28 14:04:00', '0000-00-00 00:00:00', '2019-04-29 11:44:52', 'unchecked', 'n', 'n', '', '1', 'sctz2019042802/ING22/生产通知单', '', '1.Order Number：19000233 CA Réf:19000027YS#FE54` 2.翻单产品；3.需要在第三方验货后才能发货\r 4.需提供文件：\r所有电表校准证书/出口申报单/技术规格\r\n\r\r\n', '50688', '2019-04-28 14:04:00', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING22', '19000233 CA', '2019-06-15', '商务组(Commerce Division)', '吴艳', '第三方检验', '06', '生产通知单', '结算方式：100%LC,60天远期，当前未收到LC，交期紧张，请领导评估是否同意先下单，谢谢！										\r\n		\r\r\n', '同意', '朱君宜2019-04-28 14:23:24', '郭涛2019-04-28 14:21:05', '同意', '陶保荣2019-04-28 14:24:33', '', '', '', '此订单按新方案进行备料生产---新方案正在试生产中。', '同意。', '丁富民2019-04-29 09:12:58', '王功勇2019-04-29 11:37:35', 'sctz2019042802', '01', '', '', '', '未收到LC，交期紧张，请领导评估是否同意先下单，谢谢！', '鲁慧珍2019-04-28 14:12:58', '', '', 'Eranove', null, null);
INSERT INTO `crs_tabledata719` VALUES ('403', '{9CA1CBB9-17AF-48C4-8836-CA33FD758F15}', '61', 'INHE-0578', '2019-04-30 18:08:49', '0000-00-00 00:00:00', '2019-05-06 14:05:30', 'unchecked', 'n', 'n', '', '1', 'sctz2019043001/EOI30/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。\r\r\n2. EOI30订单，全款已收到；使用EOI库存出货，往尽快安排发货。', '1313', '2019-04-30 18:08:49', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI30', 'INHESC2019042801', '2019-05-03', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '', '06', '生产通知单', '结算方式:签订合同30天内T/T支付合同全款。当前已收到全款,同意下单.		\r\n', '同意', '朱君宜2019-05-05 14:03:53', '郭涛2019-05-05 13:37:43', '同意', '陶保荣2019-05-05 15:34:11', '', '', '', '', '同意', '丁富民2019-05-06 10:44:01', '王功勇2019-05-06 13:46:55', 'sctz2019043001', '01', '', '', '', '全款已入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2019-05-05 08:51:31', '', '', 'PARAMOUNT CABLES PRIVATE LIMITED', null, null);
INSERT INTO `crs_tabledata719` VALUES ('404', '{AFF0A170-599B-43A0-95CC-D85C6B2553AA}', '61', 'INHE-0578', '2019-05-05 11:20:39', '0000-00-00 00:00:00', '2019-05-06 14:05:37', 'unchecked', 'n', 'n', '', '1', 'sctz2019050501/EOI32/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。\r\n2. EOI32订单，全款已到账；使用EOI库存出货，需尽快安排发货。', '420', '2019-05-05 11:20:39', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI32', 'INHESC2019043001', '2019-05-05', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '', '02', '生产通知单', '结算方式:发货前100% T/T结清。	当前已收到全款,同意下单.	\r\n', '同意', '朱君宜2019-05-05 13:42:04', '郭涛2019-05-05 13:36:45', '同意', '陶保荣2019-05-05 15:33:49', '', '', '', '', '同意', '丁富民2019-05-06 10:44:26', '王功勇2019-05-06 13:46:25', 'sctz2019050501', '01', '', '', '', '全款已入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2019-05-05 11:28:09', '', '', 'FRISERV INVESTMENTS (PRIVATE) LTD', null, null);
INSERT INTO `crs_tabledata719` VALUES ('405', '{C59B1D87-42C7-406D-A145-85B344D4A049}', '61', 'INHE-0772', '2019-05-09 10:44:47', '0000-00-00 00:00:00', '2019-05-09 16:59:20', 'unchecked', 'n', 'n', '', '1', 'sctz2019050906/GBA02/生产通知单', '', '1. 出厂设置单中的开上盖跳闸功能设置为关闭\r\r\n2. 出厂不激活, 安装后用技术token激活。\r\r\n3. 断电时不跳闸。\r\r\n4. 旁路不跳闸，记录事件，保持旁路计量。\r\r\n5. KRN为1，基准时间为1993。', '1000', '2019-05-09 10:44:47', '冈比亚国家水电公司', 'GBA', 'GBA02', 'NAWEC/OPO/COMM(9741)', '2019-05-12', '国际二部 INTL.Business Dept.2', '张子琦(Miranda)', '', '05', '生产通知单', '付款方式为100%发货前T/T，可以下单。当前未收到货款,同意先下单.										\r\r\n', '同意', '朱君宜2019-05-09 14:26:13', '郭涛2019-05-09 14:22:58', '同意', '陶保荣2019-05-09 14:56:25', '', '', '', 'GBA01项目翻单生产，除【电流规格修改为5（60）A，原供货产品是5（80）A；开上盖跳闸关闭；断电不跳闸】三点外，其他相同，请江西工厂安排处理。', '同意。', '丁富民2019-05-09 15:13:06', '王功勇2019-05-09 15:19:45', 'sctz2019050906', '01', '', '', '', '付款方式为100%发货前T/T，可以下单。', '鲁慧珍2019-05-09 11:15:10', '', '', 'NATIONAL WATER AND ELECTRICITY COMPANY LTD (NAWEC)', null, null);
INSERT INTO `crs_tabledata719` VALUES ('406', '{BF014017-B874-4DB8-A02E-7666DFA2BEA0}', '61', 'INHE-0654', '2019-05-17 09:18:40', '0000-00-00 00:00:00', '2019-05-20 13:29:20', 'unchecked', 'n', 'n', '', '1', 'sctz2019051701/ADD01/生产通知单', '', '1，客户要求再次验货，与工厂目前库存的1万台加本次下单的1万台+60台集中器一起验货。2，注意细节的把控。', '10000', '2019-05-17 09:18:40', 'Cashpower Sudamericana S.A.', 'ADD', 'ADD01', 'INHESC2018092601', '2019-06-10', '国际二部 INTL.Business Dept.2', '李明(Ming)', '第三方检验', '02', '生产通知单', '结算方式:这批货生产前电汇42,200.00美元；发货前电汇161,850.00美元#FE54`余款200,000.00美元，在提单日期后120天内电汇至INHEMETER。当前已收到预付款,同意生产.', '同意', '朱君宜2019-05-20 09:09:50', '郭涛2019-05-19 06:32:02', '同意', '陶保荣2019-05-20 09:30:08', '', '执行计划改变了，是否有相应合同变更？是否符合赊销条件（中信保的额度）？', '', '翻单生产，请江西工厂处理。', '同意', '丁富民2019-05-20 10:56:59', '王功勇2019-05-20 11:04:10', 'sctz2019051701', '01', '', '', '', '未收到预付款，请领导审批是否下单，谢谢！', '鲁慧珍2019-05-17 13:55:59', '', '', 'CASHPOWER SUDAMERICANA S.A', null, null);
INSERT INTO `crs_tabledata719` VALUES ('407', '{1ACCD160-3941-4577-8672-56D1CFE94284}', '60', 'INHE-0066', '2019-05-22 17:49:57', '0000-00-00 00:00:00', '2019-05-23 15:34:46', 'unchecked', 'n', 'n', '', '1', 'sctz2019052201/白云805/生产通知单', '', '1、按2015年11月提供给客户的最近样机生产。（和803批次一样的出货，此次生产通知单没有按之前的整机下单，而是按散件下单。机芯和之前一样需要修调。）\r\r\r\r\r\r\n2、根据最新的报关要求，电表将分机芯（PCBA）、LCD显示板、铝面板、按键、五金件、磁卡、纸箱等几大部分出货。\r\r\r\r\r\r\n3、双回路计量。\r\r\r\r\r\r\n4、能支持复费率和阶梯电价两种结算方式。（默认设置见随后提供的出厂设置单）\r\r\r\r\r\r\n5、带远程通断电功能。\r\r\r\r\r\r\n6、负荷门限设置。\r\r\r\r\r\r\n7、能承受电压异常的瞬间波动，电压异常时，电表自动断电，电压恢复正常时，电表自动恢复供电。\r\r\r\r\r\r\n8、工厂出厂时直接编程设置为后付费模式，并激活继电器。 9、此次无需供塑胶底壳，其他配件保持不变。热\r\r\r\n熔铜螺母、挂钩片、孔镜等都需要配备）\r\r\r\r\r\n\r\r10、采用规格为M4x8mm热塑铜螺母。\r\r\n\r\r\r\n\r\r\r\r\r\r\n										\r\r\r\r\r\r\n\r\r\r\r\r\r\n\r\r\r\r\r\r\n										\r\r\r\r\r\r\n										\r\r\r\r\r\r\n										\r\r\r\r\r\r\n										\r\r\r\r\r\r\n										\r\r\r\r\r\r\n										\r\r\r\r\r\r\n										\r\r\r\r\r\r\n										\r\r\r\r\r\r\n										\r\r\r\r\r\r\n										\r\r\r\r\r\r\n', '0', '2019-05-22 17:49:57', '\"Aspan-Energy \" LTD', '白云', '白云805', 'INHESC2019051501', '2019-06-20', '国际一部 INTL.Business Dept.1', '邱洁', '', '05', '生产通知单', '结算方式：50%TT-预付款下单时支付，50%TT-发货前支付。当前已收到50%预付款，同意下单。', '同意', '朱君宜2019-05-23 11:34:14', '王维2019-05-23 10:27:46', '同意', '陶保荣2019-05-23 11:55:52', '', '', '', '翻单生产，请江西工厂安排处理。', '同意', '丁富民2019-05-23 14:00:32', '王功勇2019-05-23 14:07:33', 'sctz2019052201', '01', '', '', '', '50%T/T预付款已到账，可以下单。', '鲁慧珍2019-05-22 18:05:33', '', '', '\"Aspan-Energy \" LTD', null, null);
INSERT INTO `crs_tabledata719` VALUES ('409', '{976DC831-CAB8-4877-9ECE-10C6483F0EA8}', '97', 'INHE-0662', '2019-05-24 18:49:27', '0000-00-00 00:00:00', '2019-05-28 08:05:06', 'unchecked', 'n', 'n', '', '1', 'sctz2019052405/TTL01/生产通知单', '', '1.单相表整机和散件数量各5万台。客户希望MCU能装进表箱，这样可以节省成本和运费，需研发和工程评估可行性，业务建议将散件装进表箱。\r\r\n2.单相表可按TTA01项目翻单生产，增加小贴纸MADA IN TANZANIA，大小与表号贴纸类似。\r\r\n3.三相表需配置GPRS和RF两个通讯模块，并实现与EDMI系统的兼容。\r\r\n4.如果出货中有不同规格的标准托盘，需提前告知业务，通知客户准备合适的工具卸货。\r\r\n5.如有任何关于出货，包装或者其他跟产品有关的变动，请提前告知业务。', '112000', '2019-05-24 18:49:27', 'INHEMETER (T) LIMITED', 'TTL', 'TTL01', 'INHESC2019051801', '2019-07-30', '商务组(Commerce Division)', '陈丽', '第三方检验', '02', '生产通知单', '结算方式:180天远期信用证.当前未收到LC,请领导审批下单!', '同意。请汤伟注意抓紧收款以及告知准确的“SKD”包装要求,便于工厂和跟单严格按要求发货，规避客户清关延迟和额外产生成本。', '朱君宜2019-05-27 14:19:36', '郭涛2019-05-27 13:24:04', '同意', '陶保荣2019-05-27 14:35:51', '', '', '', '单相表可以按TTA进行翻单生产，三相表兼容性已经作工作安排。', '同意。', '丁富民2019-05-27 19:07:51', '王功勇2019-05-27 22:04:19', 'sctz2019052405', '01', '', '', '', '未收到LC，请领导审批是否同意下单，谢谢！', '鲁慧珍2019-05-27 08:39:47', '', '', 'INHEMETER (T) LIMITED', null, null);
INSERT INTO `crs_tabledata719` VALUES ('410', '{1BEF0512-C22A-4661-A591-82F88B13E314}', '97', 'INHE-0773', '2019-05-28 15:31:00', '0000-00-00 00:00:00', '2019-05-30 07:58:25', 'unchecked', 'n', 'n', '', '1', 'sctz2019052804/EOI34/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。\r\r\r\n2. EOI34订单，全款已收到；使用EOI库存出货，往尽快安排发货。\r\r\n', '500', '2019-05-28 15:31:00', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI34', 'INHESC2019051601', '2019-05-28', '商务组(Commerce Division)', '林丹敏', '', '06', '生产通知单', '结算方式：发货前100%T/T支付全款。补流程，已发货。		\r\n', '', '朱君宜2019-05-29 13:50:40', '郭涛2019-05-29 10:58:30', '同意', '陶保荣2019-05-29 14:25:32', '', '', '', '', '同意', '丁富民2019-05-29 15:05:46', '王功勇2019-05-29 18:18:09', 'sctz2019052804', '01', '', '', '', '已审批发货，补流程。（库存表出货）', '鲁慧珍2019-05-28 15:55:35', '', '', 'Heliflex Investments(Pvt) Ltd', null, null);
