INSERT INTO `crs_tabledata719` VALUES ('412', '{8A36776B-7D60-420A-ABD5-0DAB72483A7F}', '97', 'INHE-0773', '2019-05-28 19:07:11', '0000-00-00 00:00:00', '2019-05-30 07:59:14', 'unchecked', 'n', 'n', '', '1', 'sctz2019052808/EOI36/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。\r\r\r\n2. EOI36订单，全款已收到；使用EOI库存出货，往尽快安排发货。\r\r\n', '311', '2019-05-28 19:07:11', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI36', 'INHESC2019052101', '2019-05-28', '商务组(Commerce Division)', '林丹敏', '', '06', '生产通知单', '结算方式：合同金额的100%在签订合同后作为预付款在发货前T/T支付。当前已收到全款，同意下单。	\r\n', '同意', '朱君宜2019-05-29 13:36:47', '郭涛2019-05-29 10:57:31', '同意', '陶保荣2019-05-29 14:24:25', '', '', '', '', '同意', '丁富民2019-05-29 15:04:55', '王功勇2019-05-29 18:16:29', 'sctz2019052808', '01', '', '', '', '全款已入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2019-05-29 08:44:10', '', '', '(JW) MR ITAI MANYANGA', null, null);
INSERT INTO `crs_tabledata719` VALUES ('413', '{D9E35757-B9E2-421B-9695-6CBF4CFD394E}', '60', 'INHE-0560', '2019-05-30 16:45:15', '0000-00-00 00:00:00', '2019-06-06 08:25:36', 'unchecked', 'n', 'n', '', '1', 'sctz2019053001/白雪909/生产通知单', '', '', '0', '2019-05-30 16:45:15', 'Energomera CJSC', '白雪', '白雪909', 'PO#E19_1405', '2019-07-15', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '结算方式:30%-下单时TT支付 ，70%-发货前TT支付.当前已收到预付款30%,同意下单.	\r\n', '同意', '朱君宜2019-06-05 11:48:07', '王维2019-06-05 11:39:41', '同意', '陶保荣2019-06-05 16:44:46', '', '', '', '', '同意。', '丁富民2019-06-05 17:32:50', '王功勇2019-06-05 18:47:29', 'sctz2019053001', '01', '', '', '', '30%T/T预付款已到账，可以下单。', '鲁慧珍2019-05-31 08:54:27', '', '', 'Energomera CJSC', null, null);
INSERT INTO `crs_tabledata719` VALUES ('414', '{E0986473-3CFF-4390-997E-C62C19368739}', '60', 'INHE-0066', '2019-05-31 14:01:41', '0000-00-00 00:00:00', '2019-06-03 11:07:45', 'unchecked', 'n', 'n', '', '1', 'sctz2019053102/白云806/生产通知单', '', '1、按2015年11月提供给客户的最近样机生产。（和803批次一样的出货，此次生产通知单没有按之前的整机下单，而是按散件下单。机芯和之前一样需要修调。）\r\n2、根据最新的报关要求，电表将分机芯（PCBA）、LCD显示板、铝面板、按键、五金件、磁卡、纸箱等几大部分出货。\r\n3、双回路计量。\r\n4、能支持复费率和阶梯电价两种结算方式。（默认设置见随后提供的出厂设置单）\r\n5、带远程通断电功能。\r\n6、负荷门限设置。\r\n7、能承受电压异常的瞬间波动，电压异常时，电表自动断电，电压恢复正常时，电表自动恢复供电。\r\n8、工厂出厂时直接编程设置为后付费模式，并激活继电器。 9、此次无需供塑胶底壳，其他配件保持不变。热\r\n熔铜螺母、挂钩片、孔镜等都需要配备）\r\n10、采用规格为M4x8mm热塑铜螺母。\r\n\r\n\r\n										\r\n\r\n\r\n										\r\n										\r\n										\r\n										\r\n										\r\n										\r\n										\r\n										\r\n										\r\n										\r\n										\r\n', '0', '2019-05-31 14:01:41', '\"Aspan-Energy \" LTD', '白云', '白云806', 'INHESC2019052201', '2019-07-05', '国际一部 INTL.Business Dept.1', '邱洁', '', '05', '生产通知单', '结算方式:50%TT-预付款下单时支付，50%TT-发货前支付.当前已收到50%预付款,同意下单.', '同意', '朱君宜2019-06-03 08:49:30', '王维2019-06-02 12:02:26', '同意', '陶保荣2019-06-03 08:52:04', '', '', '', '翻单生产，请江西工厂安排处理。', '同意', '丁富民2019-06-03 08:53:00', '王功勇2019-06-03 10:36:52', 'sctz2019053102', '01', '', '', '', '50%T/T预付款已到账，可以下单。', '鲁慧珍2019-05-31 14:48:13', '', '', '\"Aspan-Energy \" LTD', null, null);
INSERT INTO `crs_tabledata719` VALUES ('415', '{D8EAA4C2-D59B-423D-984F-D8747B7095F5}', '61', 'INHE-0772', '2019-06-05 10:08:29', '0000-00-00 00:00:00', '2019-07-12 16:40:22', 'unchecked', 'n', 'n', '', '1', 'sctz2019060501/GBB01/生产通知单', '', '本项目原计划6月上旬交货，由于我司内部流程问题有所耽搁。客户希望尽快实施。HHU为外部采购交货时间长烦请采购经理跟催，否则会影响出货和收款', '0', '2019-06-05 10:08:29', '冈比亚国家水电公司', 'GBB', 'GBB01', 'P163568', '2019-06-26', '国际二部 INTL.Business Dept.2', '张子琦(Miranda)', '', '06', '生产通知单', '当前已收到10%预付款,同意生产.', '张子琦反馈预付款已经收到。请财务核实。', '朱君宜2019-07-12 09:06:10', '郭涛2019-07-12 03:40:20', '同意', '陶保荣2019-07-12 11:08:52', '', '', '', '', '同意。', '丁富民2019-07-12 13:20:23', '王功勇2019-07-12 15:04:26', 'sctz2019060501', '01', '', '', '', '10%预付款未收到，是否同意下单请领导批示，谢谢！', '鲁慧珍2019-06-05 10:37:43', '02', '★★★', '冈比亚国家水电公司', null, null);
INSERT INTO `crs_tabledata719` VALUES ('416', '{41DD02C5-11CB-46B5-8678-E284CA1D8F52}', '60', 'INHE-0790', '2019-06-06 16:40:03', '0000-00-00 00:00:00', '2019-06-11 08:26:27', 'unchecked', 'n', 'n', '', '1', 'sctz2019060602/JES10/生产通知单', '', '参照订单JES09，FOB 深圳 海运，需提供测试报告给客户。', '580', '2019-06-06 16:40:03', 'JES Instrumentation * Controls', 'JES', 'JES10', 'INHESC2019042501', '2019-07-03', '国际一部 INTL.Business Dept.1', '莫亚检', '', '06', '生产通知单', '结算方式:合同金额的30%在签订合同前作为预付款T/T支付，70%余款在发货前T/T支付.当前已收到30%TT预付款,同意生产.', '同意', '朱君宜2019-06-10 08:42:25', '王维2019-06-10 08:29:02', '同意', '陶保荣2019-06-10 09:30:39', '', '', '', 'JES09订单翻单处理，请江西工厂安排。', '同意', '丁富民2019-06-10 11:26:56', '王功勇2019-06-11 00:06:17', 'sctz2019060602', '01', '', '', '', '30%T/T预付款已到账，可以下单。', '鲁慧珍2019-06-06 17:59:12', '', '', 'ALLURE TRADING DMCC', null, null);
INSERT INTO `crs_tabledata719` VALUES ('417', '{3EA4CAAD-51F2-44DE-8747-88656691FE85}', '61', 'INHE-0642', '2019-06-10 16:15:07', '0000-00-00 00:00:00', '2019-06-11 17:21:15', 'unchecked', 'n', 'n', '', '1', 'sctz2019061002/M15/生产通知单', '', '', '50000', '2019-06-10 16:15:07', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'M15', 'M15', 'INHESC2019060401', '2019-07-01', '国际二部 INTL.Business Dept.2', '潘正豪(James)', '', '07', '生产通知单', '已收到预付款水单,但款暂未入账.预付款金额包含20%产品总金额加FAT和培训金额,同意生产.', '同意。已经收到预付款水单。', '朱君宜2019-07-26 09:22:45', '郭涛2019-07-25 21:49:20', '同意', '陶保荣2019-07-26 09:27:11', '', '', '', '', '同意。此项目研发负责人章春鹏。', '丁富民2019-07-26 11:19:35', '王功勇2019-07-26 11:27:59', 'sctz2019061002', '01', '', '', '', '依然未收到预付款，新增加6500套两表位表箱，请领导批示，谢谢！', '鲁慧珍2019-07-15 08:59:00', '', '', 'ESCOM', null, null);
INSERT INTO `crs_tabledata719` VALUES ('418', '{FA930AA4-F0EC-44F6-A134-955D6C5B7F3B}', '60', 'INHE-0066', '2019-06-11 17:02:37', '0000-00-00 00:00:00', '2019-06-12 13:57:59', 'unchecked', 'n', 'n', '', '1', 'sctz2019061101/白云807/生产通知单', '', 'BS安装单相多费率智能电表-为2016年12月提供过白云项目所需要的：单相表低成本载波通信样机，详见OA：白云项目单相表低成本载波样机申请，客户接受样机的载波通信不是瑞斯康方案。但客户要求批量供货需采用瑞斯康的载波方案，确保电表可以和现有白云项目的集抄系统和集中器通信。						\r\r\r\r\r\n', '5100', '2019-06-11 17:02:37', '\"Aspan-Energy \" LTD', '白云', '白云807', 'INHESC2019052702', '2019-07-11', '国际一部 INTL.Business Dept.1', '邱洁', '', '05', '生产通知单', '结算方式:50%TT-预付款，50%TT-发货前支付.当前已收到50%预付款,同意下单.		\r\n			\r\n', '同意', '朱君宜2019-06-12 09:05:13', '王维2019-06-12 08:56:33', '同意', '陶保荣2019-06-12 09:18:04', '', '', '', '翻单生产，请江西工厂安排处理。', '同意', '丁富民2019-06-12 11:42:41', '王功勇2019-06-12 13:55:51', 'sctz2019061101', '01', '', '', '', '50%T/T预付款已到账，可以下单。', '鲁慧珍2019-06-12 08:44:37', '', '', '\"Aspan-Energy \" LTD', null, null);
INSERT INTO `crs_tabledata719` VALUES ('419', '{3D62AE20-6330-4270-93C1-2F4F29E80D5C}', '61', 'INHE-0500', '2019-06-21 14:06:17', '0000-00-00 00:00:00', '2019-06-27 07:59:11', 'unchecked', 'n', 'n', '', '1', 'sctz2019062101/CDE01/生产通知单', '', '1.涉及生产技术规格请研发和业务&客服再次确认，有部分我们无法满足需要探讨；', '2100', '2019-06-21 14:06:17', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'CDE', 'CDE01', 'INHESC2019060501', '2019-07-21', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '付款条件为100%发货前T/T，未收到款，可以下单。										\r\n', '同意', '朱君宜2019-06-21 15:47:47', '郭涛2019-06-21 15:39:08', '同意', '陶保荣2019-06-21 16:56:44', '', '', '', '业务、客服作了最终技术规格确认。除三相160A中电流表箱外，其他三款产品按公司现有产品安排生产。三相160A中电流表箱，根据技术要求，需要作硬件、嵌入软件作改进，时间上需要延后（等项目组完成现已经安排的工作后开始）。', '同意', '丁富民2019-06-26 17:54:42', '王功勇2019-06-26 18:35:14', 'sctz2019062101', '01', '', '', '', '付款条件为100%发货前T/T，未收到款，可以下单。', '鲁慧珍2019-06-21 14:26:41', '02', '★★★', 'Nyamezela Metering (Pty) Ltd', null, null);
INSERT INTO `crs_tabledata719` VALUES ('420', '{0324EFFF-F3F2-4420-8AEA-064EF3ED8E85}', '97', 'INHE-0773', '2019-06-26 14:39:04', '0000-00-00 00:00:00', '2019-06-28 17:47:45', 'unchecked', 'n', 'n', '', '1', 'sctz2019062602/EOI33/生产通知单', '', 'EOI33共4000套表，分6批次货物：\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n第一批次300套（使用现有库存）；第二批次500套，第三至六批次各800套（第二至六批次：待新库存生产完毕后，视付款进展安排；电表要求打上客户公司logo）', '4000', '2019-06-26 14:39:04', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI33', 'INHESC2019050801', '2019-06-26', '商务组(Commerce Division)', '林丹敏', '', '06', '生产通知单', '结算方式:20%TT预付款生产前,80%TT尾款发货前.当前已收到预付款,同意下单.', '同意', '朱君宜2019-06-28 11:13:57', '郭涛2019-06-27 19:33:37', '同意', '陶保荣2019-06-28 11:50:10', '', '', '', '翻单生产，请江西工厂处理', '同意。', '丁富民2019-06-28 15:49:58', '王功勇2019-06-28 16:47:53', 'sctz2019062602', '01', '', '', '', '20%T/T预付款已到账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2019-06-26 15:33:33', '', '', 'Helcraw Electrical (Pvt) Ltd', null, null);
INSERT INTO `crs_tabledata719` VALUES ('421', '{13089EC8-38F3-4FC1-A077-45E697E937C9}', '144', 'INHE-0771', '2019-07-02 10:19:37', '0000-00-00 00:00:00', '2019-10-28 17:59:05', 'unchecked', 'n', 'n', '', '1', 'sctz2019070201/ING23/生产通知单', '', '1.Order Number：19000487 CA Réf:19000101YS#FE54` 2.翻单产品；3.需提供文件：所有电表校准证书/出口申报单/技术规格\r\r\n', '50688', '2019-07-02 10:19:37', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING23', '19000487 CA', '2019-08-09', '商务组(Commerce Division)', '吴艳', '', '', '生产通知单', '未收到L/C，请领导批示是否同意下单，谢谢！										\r\n', '同意', '朱君宜2019-07-02 13:35:36', '郭涛2019-07-02 13:31:45', '同意', '陶保荣2019-07-02 14:45:49', '', '', '', '按ING21/22进行翻单生产，请江西工厂安排处理。', '同意。', '丁富民2019-07-02 17:48:17', '王功勇2019-07-02 17:54:19', 'sctz2019070201', '01', '', '', '', '未收到L/C，请领导批示是否同意下单，谢谢！', '鲁慧珍2019-07-02 10:48:27', '', '', 'Eranove', null, null);
INSERT INTO `crs_tabledata719` VALUES ('422', '{B5C854F1-DEB1-4602-81D7-F630EF90DA9E}', '97', 'INHE-0771', '2019-07-02 10:44:05', '0000-00-00 00:00:00', '2019-07-03 08:46:58', 'unchecked', 'n', 'n', '', '1', 'sctz2019070202/ING24/生产通知单', '', '1.Order Number：19000488 CA Réf:19000101YS#FE54` 2.翻单产品；3.需提供文件：所有电表校准证书/出口申报单/技术规格\r\r\n', '50688', '2019-07-02 10:44:05', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING24', '19000488 CA', '2019-08-15', '商务组(Commerce Division)', '吴艳', '', '', '生产通知单', '未收到L/C，请领导批示是否同意下单，谢谢！										\r\n', '同意', '朱君宜2019-07-02 13:36:49', '郭涛2019-07-02 13:35:17', '同意', '陶保荣2019-07-02 14:45:25', '', '', '', '按ING21/22进行翻单生产，请江西工厂安排处理。', '同意', '丁富民2019-07-02 17:50:25', '王功勇2019-07-02 17:54:00', 'sctz2019070202', '01', '', '', '', '未收到L/C，请领导批示是否同意下单，谢谢！', '鲁慧珍2019-07-02 10:50:18', '', '', 'Eranove', null, null);
INSERT INTO `crs_tabledata719` VALUES ('423', '{45395BFE-36FA-44A7-8838-C9F48489CD3C}', '60', 'INHE-0560', '2019-07-03 17:37:04', '0000-00-00 00:00:00', '2019-07-04 13:57:22', 'unchecked', 'n', 'n', '', '1', 'sctz2019070301/白雪910/生产通知单', '', '', '0', '2019-07-03 17:37:04', 'Energomera CJSC', '白雪', '白雪910', 'PO#E19_2106', '2019-07-10', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '当前已收到全款,同意下单.', '同意', '朱君宜2019-07-04 13:31:00', '王维2019-07-04 12:06:33', '同意', '陶保荣2019-07-04 13:42:56', '', '', '', '', '同意', '丁富民2019-07-04 13:48:43', '王功勇2019-07-04 13:49:45', 'sctz2019070301', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2019-07-03 18:00:05', '', '', 'Energomera CJSC', null, null);
INSERT INTO `crs_tabledata719` VALUES ('424', '{1B09B446-6DD9-4EE1-A40C-B48499E361A4}', '61', 'INHE-0654', '2019-07-09 14:51:43', '0000-00-00 00:00:00', '2019-07-10 16:47:34', 'unchecked', 'n', 'n', '', '1', 'sctz2019070901/ADD01/生产通知单', '', '1，工厂抓紧时间采购物料。2，注意铅封位置，电表里的电池需要打印上电池的生产月份/年份。3，其他与之前保持一致，如有不确定随时与业务确认。', '30000', '2019-07-09 14:51:43', 'Cashpower Sudamericana S.A.', 'ADD', 'ADD01', 'INHESC2018092601', '2019-08-10', '国际二部 INTL.Business Dept.2', '李明(Ming)', '第三方检验', '02', '生产通知单', '未收到预付款或者L/C，但王总在标题为“ADD01收款、生产、发货跟踪”的OA中已特批“同意下单3万台。”										\r\n', 'ADD第三批收到LC则等同本票收预付款102000美元。同意备料。', '朱君宜2019-07-10 10:03:01', '郭涛2019-07-09 18:09:40', '同意', '陶保荣2019-07-10 10:04:11', '', '', '', 'ADD项目翻单生产，请江西工厂安排处理。', '同意。', '丁富民2019-07-10 13:42:06', '王功勇2019-07-10 14:04:22', 'sctz2019070901', '01', '', '', '', '未收到预付款或者L/C，但王总在标题为“ADD01收款、生产、发货跟踪”的OA中已特批“同意下单3万台。”', '鲁慧珍2019-07-09 16:52:27', '', '', 'CASHPOWER SUDAMERICANA S.A', null, null);
INSERT INTO `crs_tabledata719` VALUES ('425', '{C539C3F1-5A2E-402C-8934-4A40914CB141}', '97', 'INHE-0727', '2019-07-18 09:18:10', '0000-00-00 00:00:00', '2019-07-22 16:55:36', 'unchecked', 'n', 'n', '', '1', 'sctz2019071802/WZT03/生产通知单', '', 'WZT03是WZT01的翻单，生产可参照WZT01，一批出货；\r\r\n出货前客户到厂验货，需提供验货测试报告；', '20000', '2019-07-18 09:18:10', 'West Zone Power Distributin Company Limited', 'WZT', 'WZT03', 'INHESC2019070501', '2019-08-19', '商务组(Commerce Division)', '何素贞', '第三方检验', '02', '生产通知单', 'L/C未收到，但王总在标题为“WZT翻单需求申请在拿到L/C之前先下生产订单”的OA中已同意下单。										\r\n', '同意', '朱君宜2019-07-22 09:18:03', '王维2019-07-22 08:51:35', '同意', '陶保荣2019-07-22 14:04:17', '', '特别注意交期，要快。同时注意继电器的处理方案。', '', 'WZT项目翻单生产，请江西工厂作安排处理。', '同意。', '丁富民2019-07-22 15:39:36', '王功勇2019-07-22 16:26:06', 'sctz2019071802', '01', '', '', '', 'L/C未收到，但王总在标题为“WZT翻单需求申请在拿到L/C之前先下生产订单”的OA中已同意下单。', '鲁慧珍2019-07-18 15:33:52', '', '', 'Ideal Electrical Enterprise Ltd.', null, null);
INSERT INTO `crs_tabledata719` VALUES ('426', '{39C66488-4DD2-41E7-96A0-2E6DEBDC35AC}', '97', 'INHE-0773', '2019-07-30 13:51:03', '0000-00-00 00:00:00', '2019-07-31 16:10:27', 'unchecked', 'n', 'n', '', '1', 'sctz2019073001/EOI38/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。\r\r\r\r\n2. EOI38订单，全款已到账；使用EOI库存出货，其中580套走空运，需尽快安排发货。100套走海运，将与配电EOI41订单一起发货，分开报关；									\r\r\r\n3. EOI38全款已入账\r\n', '680', '2019-07-30 13:51:03', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI38', 'INHESC2019061901', '2019-07-31', '商务组(Commerce Division)', '林丹敏', '', '02', '生产通知单', '全款已收到,可以下单.\r\n', '同意', '朱君宜2019-07-30 17:34:10', '郭涛2019-07-30 17:30:29', '同意', '陶保荣2019-07-31 08:32:44', '', '', '', '', '同意。', '丁富民2019-07-31 09:48:47', '王功勇2019-07-31 09:54:09', 'sctz2019073001', '01', '', '', '', '全款已到账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2019-07-30 14:05:28', '', '', 'PARAMOUNT CABLES PRIVATE LIMITED', null, null);
INSERT INTO `crs_tabledata719` VALUES ('427', '{F2038022-9771-47EA-9871-E19EB4BF2BA5}', '97', 'INHE-0727', '2019-08-01 09:12:03', '0000-00-00 00:00:00', '2019-08-02 19:14:18', 'unchecked', 'n', 'n', '', '1', 'sctz2019080101/WZT04/生产通知单', '', '该产品数量较少，需求较急，请尽快安排生产及出货，谢谢。', '0', '2019-08-01 09:12:03', 'West Zone Power Distributin Company Limited', 'WZT', 'WZT04', 'INHESC2019070502', '2019-08-12', '商务组(Commerce Division)', '何素贞', '', '06', '生产通知单', '已看到付款水单,款未收到,请领导批示是否同意下单.', '同意，付款水单应该已经发过来了', '朱君宜2019-08-01 17:01:22', '王维2019-08-01 16:35:17', '同意', '陶保荣2019-08-01 17:34:15', '', '', '', '现场测试工具，数量很少（16台）建议由研发实验室处理，项目组协助完成。', '同意。', '丁富民2019-08-02 10:25:50', '王功勇2019-08-02 14:36:01', 'sctz2019080101', '01', '', '', '', '款未收到，是否下单请领导批示，谢谢！', '鲁慧珍2019-08-01 09:38:50', '', '', 'Ideal Electrical Enterprise Ltd.', null, null);
INSERT INTO `crs_tabledata719` VALUES ('428', '{E1C373B7-1A43-49B5-A3BA-B4158DC0F385}', '60', 'INHE-0790', '2019-08-01 10:54:40', '0000-00-00 00:00:00', '2019-08-02 19:16:24', 'unchecked', 'n', 'n', '', '1', 'sctz2019080102/STE02/生产通知单', '交期要求2019/9/15', '此订单为STE01翻单，技术规格参考STE01三相表', '500', '2019-08-01 10:54:40', 'State Electric Company Limited', 'STE', 'STE02', 'INHESC2019070801', null, '国际一部 INTL.Business Dept.1', '莫亚检', '', '05', '生产通知单', 'L/C已收到且审核通过，可以下单。										\r\n', '同意', '朱君宜2019-08-01 17:05:50', '王维2019-08-01 16:36:41', '同意', '陶保荣2019-08-01 17:35:33', '', '', '', 'STE01项目翻单生产，请江西工厂安排处理', '同意。', '丁富民2019-08-02 10:23:14', '王功勇2019-08-02 14:26:01', 'sctz2019080102', '01', '', '', '', 'L/C已收到且审核通过，可以下单。', '鲁慧珍2019-08-01 11:39:46', '', '', 'State Electric Company Limited', null, null);
INSERT INTO `crs_tabledata719` VALUES ('429', '{35C4D6EC-F64A-4E04-970C-FE29B6A75FAA}', '66', 'INHE-0634', '2019-08-01 18:12:13', '0000-00-00 00:00:00', '2019-08-02 19:18:10', 'unchecked', 'n', 'n', '', '1', 'sctz2019080103/RMY01/生产通知单', '', '30%TT预付款已经到账，50%货款LC已经谈妥条款，正式开立中，暂未收到。20%货款在空运发货10天前TT支付。信用证上最迟装船期为：9月29日。按照合同约定，只有收到30%TT货款和符合要求的LC以后才下生产通知单，但考虑到物料较多，且信用证付款对交货期有绝对的限制性，请领导审核决定是否同意正式下单。（注：对外与客户仍然是坚持收到符合要求的信用证后才开始启动生产。）', '7200', '2019-08-01 18:12:13', 'Sipromad Group Company Limited', 'RMY', 'RMY01', 'INHESC2019053001', '2019-09-10', '国际三部 INTL.Business Dept.3', '陈雁', '', '02', '生产通知单', '结算方式：合同金额的30%在签订合同10天内作为预付款T/T支付；20%货款在发货前10天T/T支付；50%余款通过不可撤销的即期信用证支付。	当前30%预付款已到帐，50%LC正本已收到。	同意变更。 \r\n			\r\n', '同意变更.', '朱君宜2019-08-09 14:20:36', '王梅2019-08-09 14:12:08', '同意', '陶保荣2019-08-09 14:38:45', '', '', '', '增加特制铅封和铅封钳子（外购）。', '同意。', '丁富民2019-08-09 16:57:17', '王功勇2019-08-10 10:34:06', 'sctz2019080103', '01', '', '', '', '30%T/T预付款已到账，50%L/C正本已收到。', '鲁慧珍2019-08-09 13:41:53', '02', '★★★', 'Global Technologies', null, null);
INSERT INTO `crs_tabledata719` VALUES ('430', '{544AFBDD-17EF-4B58-9E4A-AA11A9CC1984}', '61', 'INHE-0721', '2019-08-05 14:36:17', '0000-00-00 00:00:00', '2019-08-08 17:37:47', 'unchecked', 'n', 'n', '', '1', 'sctz2019080502/CME01/生产通知单', '', '注：1.电表产品中单相两线、两相三线及三相直通表报价时包含CIP，请生产电表时配对生产CIP。2. 三相非直通式电表表0.5S配双绞线通讯的CIU。', '50', '2019-08-05 14:36:17', 'MESSEN S.A.S', 'CME', 'CME01', 'INHESC2019072301', '2019-09-06', '国际二部 INTL.Business Dept.2', '胡云义(Anita)', '', '05', '生产通知单', '同意.', '同意', '朱君宜2020-01-13 10:27:23', '郭涛2020-01-13 09:21:53', '同意', '陶保荣2020-01-13 10:28:57', '', '', '', 'CME01项目补货，请江西工厂安排处理。', '同意。', '丁富民2020-01-13 11:19:35', '王功勇2020-01-13 14:24:56', 'sctz2019080502', '01', '', '', '', 'CME01整批2019年10月份收齐款已发货，现因三种物料发货数量不对变更下单、补料。', '鲁慧珍2020-01-13 09:18:26', '02', '★★★', 'MESSEN S.A.S.', null, null);
INSERT INTO `crs_tabledata719` VALUES ('431', '{9F1069CD-1F7A-4B71-9392-A776B27273FE}', '61', 'INHE-0772', '2019-08-07 10:22:10', '0000-00-00 00:00:00', '2019-08-08 17:37:31', 'unchecked', 'n', 'n', '', '1', 'sctz2019080701/GBA03/生产通知单', '', '1. 生产激活，停电开盖为2小时或10度电才能激活；（此处需修改程序）    \r\r\r\r\r\r\r\n2. 断电继断电不跳闸；   \r\r\r\r\r\r\r\n3. 旁路不跳闸，记录事件，保持旁路计量；  \r\r\r\r\r\r\r\n4. 出厂设置开上上盖跳闸功能设置为关闭；     \r\r\r\r\r\r\n5. KRN为1，基准时间为1993.\r\r\r', '5000', '2019-08-07 10:22:10', '冈比亚国家水电公司', 'GBA', 'GBA03', 'NAWEC/OPO/COMM(1342)', '2019-08-30', '国际二部 INTL.Business Dept.2', '张子琦(Miranda)', '', '05', '生产通知单', '结算方式:T/T: 30%预付款，70%发货款,当前未收到30%预付款,据业务反馈客户在走付款流程,请领导审批是否同意下单.	\r\r\n', '同意备料，请张子琦抓紧收预付款，收到预付款启动生产。', '朱君宜2019-08-07 16:21:56', '郭涛2019-08-07 16:12:35', '同意', '陶保荣2019-08-07 16:26:23', '', '备料就产生风险了，与生不生产没关系，因此请确保及时收到预付款。', '', '可以按GAB01/GAB02进行翻单生产，但停电开端子盖断电功能需要激活（连续运行2小时、或者累计用电10度后才自动激活开端子盖断电功能）需要作程序修改---章春鹏负责。', '同意。', '丁富民2019-08-08 11:01:14', '王功勇2019-08-08 13:45:43', 'sctz2019080701', '01', '', '', '', '30%T/T预付款未收到，请领导审批是否同意下单，谢谢！', '鲁慧珍2019-08-07 10:59:44', '', '', 'NATIONAL WATER AND ELECTRICITY COMPANY LTD', null, null);
INSERT INTO `crs_tabledata719` VALUES ('432', '{16D91F35-7C55-4F60-9B1B-20ED3163FAD3}', '60', 'INHE-0560', '2019-08-08 09:46:41', '0000-00-00 00:00:00', '2019-08-09 09:32:13', 'unchecked', 'n', 'n', '', '1', 'sctz2019080801/白雪911/生产通知单', '', '', '0', '2019-08-08 09:46:41', 'Energomera CJSC', '白雪', '白雪911', 'PO#E19_2607', '2019-08-12', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '当前已收到全款,同意下单.', '同意', '朱君宜2019-08-08 14:18:31', '王维2019-08-08 14:14:52', '同意', '陶保荣2019-08-09 08:37:31', '', '', '', '', '同意', '丁富民2019-08-09 08:55:30', '王功勇2019-08-09 09:19:17', 'sctz2019080801', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2019-08-08 10:02:02', '', '', 'Energomera CJSC', null, null);
INSERT INTO `crs_tabledata719` VALUES ('433', '{41D77249-D6AF-4171-B37E-EADCBAB2CE7E}', '97', 'INHE-0051', '2019-08-12 11:24:37', '0000-00-00 00:00:00', '2019-08-12 18:00:07', 'unchecked', 'n', 'n', '', '1', 'sctz2019081201/SNG02/生产通知单', '', '1.电表请按表号顺序装箱，发货后请尽快提供准确的电表信息文件。\r\r\r\r\n2.SNG02订单，预付款已入账；库存表数量不足，望尽快安排采购和生产发货。									\r\r\r\r\n', '50', '2019-08-12 11:24:37', 'Inhegrid', 'SNG', 'SNG02', 'INHEGSC19062501 ', '2019-09-20', '商务组(Commerce Division)', '盛燕', '', '06', '生产通知单', '月结付款,同意下单.', '同意', '朱君宜2019-08-12 13:39:25', '盛燕2019-08-12 11:51:10', '同意', '陶保荣2019-08-12 16:25:04', '', '', '', '研发方面由王占颍负责-----建议使用现成方案生产。', '同意。', '丁富民2019-08-12 17:47:48', '王功勇2019-08-12 17:48:43', 'sctz2019081201', '01', '', '', '', '与配电月结，可以下单。', '鲁慧珍2019-08-12 11:50:13', '', '', '珠海配电智能电网有限公司', null, null);
INSERT INTO `crs_tabledata719` VALUES ('434', '{A3E399BB-888F-421E-8C33-D9D753C2C091}', '61', 'INHE-0772', '2019-08-13 08:48:24', '0000-00-00 00:00:00', '2019-08-26 13:37:48', 'unchecked', 'n', 'n', '', '1', 'sctz2019081301/GBC01/生产通知单', 'AMI系统请添加', '世行项目，交货期从合同签订时间8月9日开始计算，6周交货，客户到工厂验货FAT。', '2000', '2019-08-13 08:48:24', '冈比亚国家水电公司', 'GBC', 'GBC01', 'GM-NAWEC-72939-GO-RFB', '2019-09-09', '国际二部 INTL.Business Dept.2', '张子琦(Miranda)', '第三方检验', '07', '生产通知单', '结算方式：10%预付+80%见单付款+10%验收后支付。当前未收到预付款，是否同意生产请领导批示！', '同意', '朱君宜2019-08-30 15:45:50', '郭涛2019-08-30 15:39:17', '同意', '陶保荣2019-08-30 15:57:18', '', '', '', '', '同意', '丁富民2019-08-30 16:18:10', '王功勇2019-08-31 11:39:02', 'sctz2019081301', '01', '', '', '', '预付款仍未收到。', '鲁慧珍2019-08-30 11:35:46', '02', '★★★', 'NATIONAL WATER AND ELECTRICITY COMPANY LTD', null, null);
INSERT INTO `crs_tabledata719` VALUES ('435', '{863EF4B4-1846-4C13-A278-6A560A024350}', '144', 'INHE-0549', '2019-08-28 08:23:47', '0000-00-00 00:00:00', '2019-09-11 15:59:03', 'unchecked', 'n', 'n', '', '1', 'GLP01/sctz2019082801/生产通知单', '', '1. 样机验收后，经公司批准，原合同中的单相表由DIN II.I 改为DIN III,技术确认书客户签字版后续会在OA中发出；2.木箱需使用胶合板，不可用实木；3.发货前需通过第三方检测机构检测验收，具体机构待与客户确认；4. 提供CIU安装背板及附件；5. 三相表为墙上安装，非柱上安装，请去除背板上不必要的附件；6. 低压门限请设置为175V（原样机为180V）', '535', '2019-08-28 08:23:47', 'Inhegrid', 'GLP', 'GLP01', 'INHESC2019072504', '2019-10-10', '投标组', '王秀明', '第三方检验', '06', '生产通知单', '月结,同意下单.', '同意，珠海配电的生产通知单（电表和计量箱）已审批通过。', '朱君宜2019-09-11 09:07:43', '盛燕2019-09-11 09:00:28', '同意', '陶保荣2019-09-11 09:27:06', '', '', '', '建议几款电表按翻处理。', '同意----10月10日交货存在问题，几款计量箱（柜）需要外协加工。', '丁富民2019-09-11 10:13:59', '王功勇2019-09-11 15:50:09', 'sctz2019082801', '01', '', '', '', '月结，可以下单。（珠海配电已收到客户50%预付款，内部生产通知单流程已走完。）', '鲁慧珍2019-09-11 08:50:59', '', '', '珠海银河智能电网有限公司', null, null);
INSERT INTO `crs_tabledata719` VALUES ('436', '{FD4CE6D7-C88F-4ED7-A74B-4C16A571745F}', '97', 'INHE-0773', '2019-08-28 16:43:31', '0000-00-00 00:00:00', '2019-08-29 17:47:19', 'unchecked', 'n', 'n', '', '1', 'sctz2019082803/BAP06/生产通知单', '', '1. BAP06项目是BAP市场分体式电表延续，技术规格没有变化，按照BAP03、BAP04、BAP05对应产品的技术规格\r\r\r\r\r\r\r\r\r\n2. 发货条件：收到全款后60天内从工厂发出；业务希望越快发货越好。烦请公司尽快安排生产\r\r\r\r\r\r\r\r\r\n3. BAP06项目2019/08/28日银行收到13,100 USD，即将入账。合同剩余尾款预计在09/06日支付。', '200', '2019-08-28 16:43:31', 'FactorFast (PTY) Ltd', 'BAP', 'BAP06', 'INHESC2019082301', '2019-09-15', '商务部(Commerce Division)', '林丹敏', '', '04', '生产通知单', '出纳姚茜确认USD 13,100.00银行已查到，资料已提供,待走入账；此笔款不足合同约定的70%,相差543USD是否同意下单，请领导审批，谢谢！										\r\r\r\n', '同意下单，请李忠鹏抓紧催余款。', '朱君宜2019-08-29 10:35:21', '郭涛2019-08-29 10:06:01', '同意', '陶保荣2019-08-29 10:39:04', '', '', '', '', '同意。翻单订单，请江西工厂安排处理。', '丁富民2019-08-29 10:56:51', '王功勇2019-08-29 17:35:36', 'sctz2019082803', '01', '', '', '', '出纳姚茜确认USD 13,100.00银行已查到，待提供资料走入账流程；此笔款不足合同约定的70%，是否同意下单，请领导审批，谢谢！', '鲁慧珍2019-08-28 17:28:46', '', '', 'FactorFast (PTY) Ltd', null, null);
INSERT INTO `crs_tabledata719` VALUES ('437', '{1C19FC43-D5D1-4237-8AAB-EAD7425712DD}', '61', 'INHE-0721', '2019-08-28 23:03:18', '0000-00-00 00:00:00', '2019-08-29 17:46:31', 'unchecked', 'n', 'n', '', '1', 'sctz2019082804/PSA17-03/生产通知单', '', '1.与PSA17-02产品规格基本一致，相关更新技术规格请参考附件生产。                              2.已收到预付款，请领导批准生产。', '500', '2019-08-28 23:03:18', 'MESSEN S.A.S', 'PSA17', 'PSA17-03', 'INHESC2019072401', '2019-09-30', '国际二部 INTL.Business Dept.2', '胡云义(Anita)', '', '05', '生产通知单', '30%TT预付款已收齐，可以下单。										\r\r\n', '同意', '朱君宜2019-08-29 10:39:58', '郭涛2019-08-29 10:33:42', '同意', '陶保荣2019-08-29 10:44:59', '', '', '', '', '同意。翻单生产，请江西工厂安排处理。', '丁富民2019-08-29 10:55:44', '王功勇2019-08-29 17:35:11', 'sctz2019082804', '01', '', '', '', '预付款已收齐，可以下单。', '鲁慧珍2019-08-29 10:20:01', '', '', 'MESSEN S.A.S', null, null);
INSERT INTO `crs_tabledata719` VALUES ('438', '{8DA3B64B-AD0A-482D-A272-94AC34FA8B66}', '144', 'INHE-0549', '2019-09-04 11:07:00', '0000-00-00 00:00:00', '2019-09-16 08:59:30', 'unchecked', 'n', 'n', '', '1', 'sctz2019090401/SRA01/生产通知单', '', '出厂设置为后付费', '2000', '2019-09-04 11:07:00', 'Inhegrid', 'SRA', 'SRA01', 'INHEGSC2019062102', '2019-10-18', '投标组', '王秀明', '', '02', '生产通知单', '珠海配电订单,月结付款.', '同意', '朱君宜2019-09-04 13:32:59', '盛燕2019-09-04 13:26:35', '同意', '陶保荣2019-09-04 15:25:39', '', '', '', '按TTA项目单相表进行生产，相关工作请江西工厂作安排处理。', '同意。', '丁富民2019-09-04 17:15:27', '王功勇2019-09-04 17:20:33', 'sctz2019090401', '01', '', '', '', '珠海配电订单，月结；据王秀明反馈，珠海配电生产通知单已审批通过。', '鲁慧珍2019-09-04 11:48:40', '', '', '珠海银河智能电网有限公司', null, null);
INSERT INTO `crs_tabledata719` VALUES ('439', '{0C986E9F-0327-4811-9B82-08D75F5ABB97}', '61', 'INHE-0843', '2019-09-12 09:50:14', '0000-00-00 00:00:00', '2019-09-12 18:33:38', 'unchecked', 'n', 'n', '', '1', 'sctz2019091201/MXP01/生产通知单', '请刘畑杏随附客户和研发确认的技术规格', '', '0', '2019-09-12 09:50:14', 'Protecsa Ingeniería S.A. de C.V.', 'MXP', 'MXP', 'INHESC2019090401', '2019-10-31', '国际二部 INTL.Business Dept.2', '刘畑杏(Laura)', '', '02', '生产通知单', '合同要求收到20%TT预付款后50天内完成生产.当前已收到20%预付款,同意下单.', '同意。交期紧，涉及后续订单，希望研发和制造努力按期交付。', '朱君宜2019-09-12 16:13:56', '郭涛2019-09-12 15:59:08', '同意', '陶保荣2019-09-12 16:33:01', '', '此项目研发、生产总协调和督导：宋宁。同时，希望陶保荣深度参与进去。', '', '', '同意。', '丁富民2019-09-12 16:47:16', '王功勇2019-09-12 18:26:20', 'sctz2019091201', '01', '', '', '', '项目编号：MXP01，20%预付款已到账，可以下单。', '鲁慧珍2019-09-12 15:42:25', '03', '★★★★', 'Powermex Energy S.A de C.V.', null, null);
INSERT INTO `crs_tabledata719` VALUES ('440', '{C4758FCD-50F8-49BC-B19B-5E63FE011106}', '143', 'INHE-0773', '2019-09-20 09:32:02', '0000-00-00 00:00:00', '2019-09-24 08:10:58', 'unchecked', 'n', 'n', '', '1', 'sctz2019092001/EOI44/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。\r\n2. 全款已入账；使用EOI库存出货，请尽快安排发货。感谢', '250', '2019-09-20 09:32:02', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI44', 'INHESC2019091801', '2019-09-20', '竞标组', '林丹敏', '', '06', '生产通知单', '已收到全款,同意下单.', '同意', '朱君宜2019-09-23 11:22:09', '郭涛2019-09-23 10:37:33', '同意', '陶保荣2019-09-23 11:35:23', '', '', '', '', '同意。翻单处理， 请江西工厂安排。', '丁富民2019-09-23 21:21:39', '王功勇2019-09-23 21:47:46', 'sctz2019092001', '01', '', '', '', '全款已入账，可以下单。（请PMC注意，此批订单产品数量对应从标题为“EOI项目库存表生产安排”的OA中所下库存产品数量中扣减，不要重复采购生产。）', '鲁慧珍2019-09-20 09:55:16', '', '', 'HELIFLEX INVESTMENTS PRIVATE', null, null);
INSERT INTO `crs_tabledata719` VALUES ('441', '{1E27FF44-B88C-4B06-97EB-A3931F79E006}', '61', 'INHE-0853', '2019-09-24 09:53:54', '0000-00-00 00:00:00', '2019-09-27 09:14:05', 'unchecked', 'n', 'n', '', '1', 'sctz2019092401/FIX08/生产通知单', '', '客户要求的订单交期为6-8周', '0', '2019-09-24 09:53:54', 'FIX-IT Depot ', 'FIX', 'FIX08', 'INHESC2019082601', '2019-10-31', '国际二部 INTL.Business Dept.2', '胡亚婵(Zoe)', '', '', '生产通知单', '结算方式:签订合同后10天内100%生产前T/T.当前已收到全款,同意下单.		\r\n', '同意', '朱君宜2019-09-25 10:31:53', '郭涛2019-09-25 10:28:19', '同意', '陶保荣2019-09-25 13:38:30', '', '', '', '应该是二款不同电压规格的PLC载波通信的显示单元，此属于旧项目补显示单元。给出的CIU规格存在错误。', '同意。', '丁富民2019-09-26 05:37:06', '王功勇2019-09-26 08:56:20', 'sctz2019092401', '01', '', '', '', '全款已收齐，可以下单。', '鲁慧珍2019-09-24 11:42:04', '', '', 'GUYANA POWER&LIGHT,INC.', null, null);
INSERT INTO `crs_tabledata719` VALUES ('442', '{A0713DDE-C6D8-4A2F-95E7-61D70D802582}', '61', 'INHE-0500', '2019-09-25 15:10:53', '0000-00-00 00:00:00', '2019-09-29 09:19:00', 'unchecked', 'n', 'n', '', '1', 'sctz2019092501/EXJ02/生产通知单', '', '', '2000', '2019-09-25 15:10:53', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'EXJ', 'EXJ02', 'INHESC2019091901', '2019-10-25', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '新增的40套+5套表的全款已收齐，可以下单。										\r\n', '同意', '朱君宜2019-12-23 09:25:28', '郭涛2019-12-21 10:10:16', '同意', '陶保荣2019-12-23 10:33:07', '', '', '', '', '同意', '丁富民2019-12-23 10:41:29', '王功勇2019-12-23 12:00:07', 'sctz2019092501', '01', '', '', '', '新增的40套+5套表的全款已收齐，可以下单。', '鲁慧珍2019-12-20 17:25:46', '', '', 'Nyamezela Metering (Pty) Ltd', null, null);
INSERT INTO `crs_tabledata719` VALUES ('443', '{DD60A70B-F285-411D-968A-56935722EC3D}', '144', 'INHE-0727', '2019-09-26 15:54:05', '0000-00-00 00:00:00', '2019-09-27 16:20:02', 'unchecked', 'n', 'n', '', '1', 'sctz2019092604/TTL01/生产通知单', '', 'TTL01第二批技术规格与TTL01第一批相同，请安排生产。', '108000', '2019-09-26 15:54:05', 'INHEMETER (T) LIMITED', 'TTL', 'TTL01', 'INHESC2019051801', '2019-11-30', '投标组', '何素贞', '第三方检验', '02', '生产通知单', '预付款、L/C均未收到，请领导审批是否下单，谢谢！										\r\n', '同意', '朱君宜2019-09-27 10:05:37', '郭涛2019-09-27 09:51:34', '同意', '陶保荣2019-09-27 10:06:28', '', '', '', '', '同意', '丁富民2019-09-27 15:36:08', '王功勇2019-09-27 15:39:03', 'sctz2019092604', '01', '', '', '', '预付款、L/C均未收到，请领导审批是否下单，谢谢！', '鲁慧珍2019-09-26 16:29:25', '', '', 'INHEMETER (T) LIMITED', null, null);
INSERT INTO `crs_tabledata719` VALUES ('444', '{9A06492C-564A-4D5D-A60E-4078891B38C1}', '75', 'INHE-0432', '2019-09-29 10:13:54', '0000-00-00 00:00:00', '2019-09-30 08:29:12', 'unchecked', 'n', 'n', '', '1', 'sctz2019092901/KLA/生产通知单', '', '1.KLA项目10万套电表全部按照成品供货给IAC，同KF03成品的出货状态。\r\r\n\r\r\r\r\n2.随货卡板需要先运至海外工厂，再发往电力公司，所以需要保障卡板质量，避免出现卡板质量差，货物倒塌的现象。', '100000', '2019-09-29 10:13:54', 'The Kenya Power * Lighting Company Limited', 'KLA', 'KLA', 'INHESC2019092701', '2019-10-31', 'INHEMETER AFRICA', '谭东羊(Timon)', '第三方检验', '06', '生产通知单', '结算方式：每批发货的货值在提单日后120天采用T/T全款支付。同意生产。		\r\n', '', '朱君宜2019-09-29 14:11:34', '', '同意', '陶保荣2019-09-29 14:14:20', '', '注意：结构不能等新开模具，时间来不及。', '', '产品结构、电子方案需要优化。结构需要按最新UNW项目进行开模。', '同意。项目研发负责人章春鹏。', '丁富民2019-09-29 21:35:54', '王功勇2019-09-29 22:22:52', 'sctz2019092901', '01', '', '', '', '结算方式：每批发货的货值在提单日后120天采用T/T全款支付（全款赊销）', '鲁慧珍2019-09-29 10:29:31', '03', '★★★★', 'INHEMETER AFRICA COMPANY LIMITED', null, null);
INSERT INTO `crs_tabledata719` VALUES ('445', '{CED9D380-6A95-4EA8-ACDA-0164BD8C5C7C}', '61', 'INHE-0381', '2019-10-24 14:52:08', '0000-00-00 00:00:00', '2019-10-29 08:29:05', 'unchecked', 'n', 'n', '', '1', 'sctz2019102401/NEW03/生产通知单', '', '1.NEW订单的RF二代表，需要在不升级现在安装在现场的集中器的情况下，这些集中器能够对二代的RF模块表和一代的RF模块表进行混合集抄（能够实时抄读和集中器任务抄）。2.亮度等要求要跟最后一个NEW样机一样，支持短代码，用防拆螺丝，月冻结13个月。3.需要在上电恢复合闸前，电表经10s判断延时后才进行合闸.4.发货前需要做VOC验货。5.发货需要提供电表的校准证书，测量测试报告，可参考NEW02项目。', '27648', '2019-10-24 14:52:08', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'NEW', 'NEW03', '19000871 CA', '2019-12-02', '国际二部 INTL.Business Dept.2', '张柳芳(Alexie)', '第三方检验', '06', '生产通知单', '暂未收到L/C，但王总在标题为“NEW03订单生产、发货、议付跟踪”的OA中同意先下单。										\r\n', '同意', '朱君宜2019-10-25 08:37:10', '郭涛2019-10-24 19:10:17', '同意', '陶保荣2019-10-25 08:47:15', '', '', '', '产品还在研发之中，预计可以先提供BOM表，并安排一些特殊定制件开模加工。研发计划完成时间是2019年11月底。---项目负责人王顺万。', '同意。', '丁富民2019-10-25 18:09:57', '王功勇2019-10-25 23:12:50', 'sctz2019102401', '01', '', '', '', '暂未收到L/C，但王总在标题为“NEW03订单生产、发货、议付跟踪”的OA中同意先下单。', '鲁慧珍2019-10-24 15:37:12', '', '', 'ERANOVE SA', null, null);
INSERT INTO `crs_tabledata719` VALUES ('446', '{4273B554-E3AE-473C-A12D-30BF7D736052}', '143', 'INHE-0773', '2019-10-30 15:20:17', '0000-00-00 00:00:00', '2019-10-31 15:35:47', 'unchecked', 'n', 'n', '', '1', 'sctz2019103001/EOI46/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。\r\r\r\n2. EOI46全款已入账，已发货，补此流程', '100', '', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI46', 'INHESC2019101801', '2019-10-25', '竞标组', '林丹敏', '', '06', '生产通知单', '全款已收齐，已发货，补流程。										\r\r\n', '同意', '朱君宜2019-10-31 08:32:51', '郭涛2019-10-31 00:34:13', '同意', '陶保荣2019-10-31 08:46:28', '', '', '', '翻单订单，请江西工厂安排处理。', '同意。', '丁富民2019-10-31 09:06:28', '王功勇2019-10-31 15:05:05', 'sctz2019103001', '01', '', '', '', '全款收齐，已库存表发货，补流程。', '鲁慧珍2019-10-30 15:43:22', '', '', 'Sataf ( Pvt ) Ltd', null, null);
INSERT INTO `crs_tabledata719` VALUES ('447', '{17257F48-CF42-43FC-B9A9-BF9D64E33D29}', '143', 'INHE-0773', '2019-10-31 19:14:27', '0000-00-00 00:00:00', '2019-11-05 09:24:13', 'unchecked', 'n', 'n', '', '1', 'sctz2019103102/EOI47/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。\r\r\n2. EOI47全款水单已收到，待入账完毕，立即安排发货', '250', '', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI47', 'INHESC2019103001', '2019-11-06', '竞标组', '林丹敏', '', '06', '生产通知单', '出纳姚茜确认全款已在银行待入账，预计本周到账，可以下单。										\r\r\n', '同意', '朱君宜2019-11-04 10:43:39', '郭涛2019-11-04 10:42:25', '同意。', '陶保荣2019-11-04 16:42:30', '', '', '', '翻单生产，请江西工厂安排处理。', '同意。', '丁富民2019-11-04 22:18:34', '王功勇2019-11-05 08:57:41', 'sctz2019103102', '01', '', '', '', '出纳姚茜确认全款已在银行走入账流程，预计下周到账，可以下单。（库存表出货，不需要另行生产）', '鲁慧珍2019-11-01 11:43:21', '', '', 'HELIFLEX INVESTMENTS PRIVATE', null, null);
INSERT INTO `crs_tabledata719` VALUES ('448', '{43C85DD6-D7F6-4A86-B12A-9B8E2BB56E4E}', '144', 'INHE-0662', '2019-11-01 10:36:36', '0000-00-00 00:00:00', '2019-11-05 14:28:04', 'unchecked', 'n', 'n', '', '1', 'sctz2019110102/UNW01/生产通知单', '', '1.表计表型为DIN IV（第4代），需要配显示单元。\r\n2.表计需要超声焊。\r\n3.每个接电板需额外物料（安装木螺钉*4，规格2inch#FE54`软木板*1，规格540 x 360 x 25 mm；墙上插座*4 规格8mm；平行槽夹*2，规格50sq.mm；带夹铜接地棒*1，规格1200mm；铜接地线 3m,规格16sq.mm。）', '87500', '2019-11-01 10:36:36', 'Rural Electrification Agency', 'UNW', 'UNW01', 'INHESC2019102201', '2019-12-27', '投标组', '陈丽', '', '02', '生产通知单', '已收到20%预付款，同意下单。', '同意（RF订单暂缓采购物料）。', '朱君宜2020-06-08 08:45:01', '郭涛2020-06-06 15:49:12', '同意', '陶保荣2020-06-08 08:50:35', '', '', '', 'UNW项目研发负责人：章春鹏                         A: 根据前期公司代工作安排分工，研发负责表计（三款--双绞线、RF无线通信、PLC载波）、表箱（三款--单表位、二表位、四表位）、READY BOARD配电箱（接线板）、通信接线盒（表计1、2、3；配件1、2、3、11、13）八款江西工厂生产、配套的产品研发设计和BOM表；B: 其他配件由客服中心确定规格、型号（包括配件中4、5、6、7、8、9、10、12、14十项）#FE54` C:RF通信工作频率等等待客服中心确认后，研发才能确认相关无线通信模组和天线； D:表计（三类通信方式）与表箱配套方式需要等客服中心确认。', '同意。', '丁富民2020-06-08 11:42:30', '王功勇2020-06-08 14:31:10', 'sctz2019110102', '01', '', '', '', '20%预付款已到账，2019/11/5走完原生产通知单流程，此次为技术参数变更。', '鲁慧珍2020-06-05 20:49:52', '', '', 'Rural Electrification Agency', null, null);
INSERT INTO `crs_tabledata719` VALUES ('449', '{DD88572A-3DD1-4B41-9F80-985C3888B1E3}', '61', 'INHE-0721', '2019-11-01 17:10:35', '0000-00-00 00:00:00', '2019-11-05 09:03:32', 'unchecked', 'n', 'n', '', '1', 'sctz2019110105/ACN01/生产通知单', '', '电表为宽量程范围得三相直通表；接线端子盖要求透明；要求使用防退螺钉；LCD上要求有电流方向指示器；要求电表带RS 232 和 RS 485', '250', '2019-11-01 17:10:35', 'MESSEN S.A.S', 'ACN', 'ACN01', 'INHESC2019100801 ', '2019-12-01', '国际二部 INTL.Business Dept.2', '胡云义(Anita)', '第三方检验', '02', '生产通知单', '结算方式:50%TT下单,50%TT发货前.当前已收到50%预付款,同意下单.', '同意', '朱君宜2019-11-04 10:52:32', '郭涛2019-11-04 10:37:51', '同意。', '陶保荣2019-11-04 16:41:06', '', '', '', '技术规格存在问题  1：额定电压为【57.7/100V--270/480V】的直接接入式电能表是一个什么场景的使用？宽额定电压自动转换是适用于互感器接入的多功能表。2:5（120）A上限电流已经达到我们目前结构电子设计上限值，长期大电流运行存在问题。以上二点需要业务、客服澄清。', '不同意。', '丁富民2019-11-04 22:30:41', '王功勇2019-11-05 08:53:28', 'sctz2019110105', '02', '', '', '', '50%预付款已到账，可以下单。', '鲁慧珍2019-11-01 18:12:09', '01', '★★', 'MESSEN S.A.S', null, null);
INSERT INTO `crs_tabledata719` VALUES ('450', '{CCE37BCE-F12A-4838-91AF-17C2AF70A0BE}', '66', 'INHE-0634', '2019-11-04 10:20:39', '0000-00-00 00:00:00', '2019-11-06 08:45:08', 'unchecked', 'n', 'n', '', '1', 'sctz2019110401/RMY02/生产通知单', '', '技术要求与RMY01完全相同；由于12月临近圣诞节，运输仓位紧张，需尽快完成生产及早发出，避免后续延迟交货罚款等问题。', '1603', '2019-11-04 10:20:39', 'Sipromad Group Company Limited', 'RMY', 'RMY02', 'INHESC2019091601', '2019-12-08', '国际三部 INTL.Business Dept.3', '陈雁', '', '05', '生产通知单', '结算方式:100%不可撤销的保兑即期LC.当前L/C正本已收到，可以下单。										\r\r\n', '同意。', '朱君宜2019-11-04 14:01:06', '王梅2019-11-04 12:25:15', '同意。', '陶保荣2019-11-04 16:39:47', '', '', '', 'RMY项目翻单生产，请江西工厂安排处理。', '同意。', '丁富民2019-11-04 22:17:16', '王功勇2019-11-04 22:17:56', 'sctz2019110401', '01', '', '', '', 'L/C正本已收到，可以下单。', '鲁慧珍2019-11-04 10:59:42', '02', '★★★', 'Global Technologies', null, null);
