INSERT INTO `crs_tabledata719` VALUES ('452', '{5E3809C5-0430-4660-9749-50A1B596A397}', '60', 'INHE-0560', '2019-11-08 11:43:38', '0000-00-00 00:00:00', '2019-11-13 17:08:04', 'unchecked', 'n', 'n', '', '1', 'sctz2019110802/白雪913/生产通知单', '', '', '0', '2019-11-08 11:43:38', 'Energomera CJSC', '白雪', '白雪913', 'PO#E19_2510', '2019-11-28', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '全款已到账，可以下单。										\r\n', '同意', '朱君宜2019-11-12 11:42:45', '王维2019-11-12 11:41:50', '同意', '陶保荣2019-11-12 15:43:39', '', '', '', '', '同意', '丁富民2019-11-13 09:13:07', '王功勇2019-11-13 10:29:12', 'sctz2019110802', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2019-11-08 11:50:41', '', '', 'Energomera CJSC', null, null);
INSERT INTO `crs_tabledata719` VALUES ('453', '{6DD361B6-4586-40A0-BF25-6FCD438D947E}', '60', 'INHE-0560', '2019-11-08 11:46:47', '0000-00-00 00:00:00', '2019-11-13 17:07:19', 'unchecked', 'n', 'n', '', '1', 'sctz2019110803/白雪914/生产通知单', '', '翻单白雪907订单的三相表转接板', '0', '2019-11-08 11:46:47', 'Energomera CJSC', '白雪', '白雪914', 'PO#E19_2910', '2019-12-05', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '全款已到账，可以下单。										\r\n', '同意', '朱君宜2019-11-12 11:41:40', '王维2019-11-12 11:39:19', '同意', '陶保荣2019-11-12 15:43:16', '', '', '', '翻单生产，请江西工厂安排处理。', '同意。', '丁富民2019-11-13 09:12:38', '王功勇2019-11-13 10:28:39', 'sctz2019110803', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2019-11-08 11:51:15', '', '', 'Energomera CJSC', null, null);
INSERT INTO `crs_tabledata719` VALUES ('454', '{B30BD91F-BBF1-45D8-95EC-7CA026ED7235}', '60', 'INHE-0434', '2019-11-11 16:59:28', '0000-00-00 00:00:00', '2019-11-19 10:34:12', 'unchecked', 'n', 'n', '', '1', 'sctz2019111101/ST20710/生产通知单', '', '生产要求如下：\r\r\r\r\n1. 外箱唛头更新银河公司名称；\r\r\r\r\n2. 产品图纸更新年份为2019；\r\r\r\r\n3. 散件PCBA,LCD重要物料打托，金属件/电池物料打木箱，生产后提供该批次表号数据及密钥文件；\r\r\r\r\n4. 出货前客户将到厂验货；\r\r\r\r\n计划分两批出货：\r\r\r\r\n第一批：50000套单相表散件；\r\r\r\r\n第二批：50000套单相表散件\r\r\n									\r\r\r\r\n', '100000', '2019-11-11 16:59:28', 'SUDANESE ELECTRICITY DISTRIBUTION CO.LTD.', 'ST20', 'ST20710', 'INHESC2017092801', '2019-12-21', '国际一部 INTL.Business Dept.1', '钟云林(Andy)', '', '02', '生产通知单', 'L/C尚未收到，但王总在标题为“ST20710订单生产、发货、议付跟踪”的OA中已特批同意先下单。										\r\n', '同意', '朱君宜2019-11-12 08:52:57', '王维2019-11-12 08:36:12', '同意', '陶保荣2019-11-12 09:21:23', '', '', '', '按原设计进行翻单生产，请江西工厂安排处理', '同意。', '丁富民2019-11-12 14:01:40', '王功勇2019-11-12 20:54:04', 'sctz2019111101', '01', '', '', '', 'L/C尚未收到，但王总在标题为“ST20710订单生产、发货、议付跟踪”的OA中已特批同意先下单。', '鲁慧珍2019-11-11 17:44:22', '', '', 'Sudanese Chinese Meter Factory', null, null);
INSERT INTO `crs_tabledata719` VALUES ('455', '{E4720BB0-4193-40A6-947F-4138A6839D52}', '61', 'INHE-0721', '2019-11-13 11:41:01', '0000-00-00 00:00:00', '2019-11-18 08:09:36', 'unchecked', 'n', 'n', '', '1', 'sctz2019111302/ACN01/生产通知单', '', '1.此产品技术规格宽范围电压的三相直通表，立项时已说明，PSA市场代理2017年采购过此样机50台试用；2. 此产品电流接受5（100）A；3，接线端子盖要求透明；LCD要求有电流方向指示器，带RS232及RS485.4，客户有工厂验货要求，需安排尽快生产。', '250', '2019-11-13 11:41:01', 'MESSEN S.A.S', 'ACN', 'ACN01', 'INHESC2019100801 ', '2019-12-13', '国际二部 INTL.Business Dept.2', '胡云义(Anita)', '第三方检验', '02', '生产通知单', '50%预付款已到账，但该客PSA17-03订单（特批已发货）尾款还差USD13,127.37未付，请领导审批是否同意下单，谢谢！										\r\r\r\r\r\n', '同意', '朱君宜2019-11-15 09:05:02', '郭涛2019-11-15 06:31:26', '同意', '陶保荣2019-11-15 09:35:28', '', '', '', '2016年此市场PSA6项目曾经生产过60台三相四线直接接入式多功能表。此项目由王占颍负责，可能需要作部分硬件、软件调整修改。', '同意', '丁富民2019-11-15 11:43:56', '王功勇2019-11-15 14:09:47', 'sctz2019111302', '01', '', '', '', '50%预付款已到账，但该客户PSA17-03订单（特批已发货）尾款还差USD 13,127.37未付，请领导审批是否同意下单，谢谢！', '鲁慧珍2019-11-13 13:59:00', '01', '★★', 'MESSEN S.A.S', null, null);
INSERT INTO `crs_tabledata719` VALUES ('456', '{F83D1DD3-2097-4630-AB68-6BDCDE09F55F}', '61', 'INHE-0578', '2019-11-14 15:56:36', '0000-00-00 00:00:00', '2019-11-19 16:15:45', 'unchecked', 'n', 'n', '', '1', 'sctz2019111401/ZWS01/生产通知单', '', '1.ZWS01项目与EOI项目技术规格基本一致，技术支持在最终审核技术规格书中，OA“ZWS项目（中标项目）技术合同评审申请”。客服、研发部审核后将发到后续生产OA中。\r\r\n2.ZWS01订单丁总判定可由EOI项目翻单，但EOI项目单相BS表仅出\r\r\n货过950台、存在端盖需要修改的问题。ZWS项目要求【透明短端盖】，需公司评估、尽快安排确认生产方案。\r\r\n3.ZWS01订单结算方式为100%不可撤销、保兑的远期60天信用证，发货条件为收到LC后60天内从工厂发出。目前暂未收到开出的LC，交期也需公司评审、加快；尤其是【单相BS表端盖问题、继电器问题】、【三相表电压检测芯片问题】急需推进！', '9480', '2019-11-14 15:56:36', 'Finmark Industries (Pvt) Ltd.', 'ZWS', 'ZWS01', 'INHESC2019111101', '2019-12-27', '国际二部 INTL.Business Dept.2', '覃湘君(June)', '', '06', '生产通知单', '同意！										\r\n', '同意', '朱君宜2019-11-14 17:47:23', '郭涛2019-11-14 17:46:36', '同意', '陶保荣2019-11-15 09:02:20', '', '', '', '建议按翻单进行处理，研发近期忙于几个大订单研发工作，近期无法安排对此项目进行技术支持。', '同意。', '丁富民2019-11-15 09:06:11', '王功勇2019-11-19 16:00:47', 'sctz2019111401', '01', '', '', '', 'L/C正本已收到，可以下单。', '鲁慧珍2019-11-14 16:36:23', '', '', 'Zimbabwe Electricity Transmission & Distribution Company (Private) Limited.', null, null);
INSERT INTO `crs_tabledata719` VALUES ('457', '{C8B0DCA3-5CC7-4027-9D2C-F46A3228E02A}', '60', 'INHE-0066', '2019-11-18 09:23:42', '0000-00-00 00:00:00', '2019-11-20 11:37:50', 'unchecked', 'n', 'n', '', '1', 'sctz2019111801/白云808/生产通知单', '', '1、按2015年11月提供给客户的最近样机生产。（和803批次一样的出货，此次生产通知单没有按之前的整机下单，而是按散件下单。机芯和之前一样需要修调。）\r\n2、根据最新的报关要求，电表将分机芯（PCBA）、LCD显示板、铝面板、按键、五金件、磁卡、纸箱等几大部分出货。\r\n3、双回路计量。\r\n4、能支持复费率和阶梯电价两种结算方式。（默认设置见随后提供的出厂设置单）\r\n5、带远程通断电功能。\r\n6、负荷门限设置。\r\n7、能承受电压异常的瞬间波动，电压异常时，电表自动断电，电压恢复正常时，电表自动恢复供电。\r\n8、工厂出厂时直接编程设置为后付费模式，并激活继电器。 9、此次无需供塑胶底壳，其他配件保持不变。热\r\n熔铜螺母、挂钩片、孔镜等都需要配备）\r\n10、采用规格为M4x8mm热塑铜螺母。\r\n\r\n\r\n										\r\n\r\n\r\n										\r\n										\r\n										\r\n										\r\n										\r\n										\r\n										\r\n										\r\n										\r\n										\r\n										\r\n', '0', '2019-11-18 09:23:42', '\"Aspan-Energy \" LTD', '白云', '白云808', 'INHESC2019081501', '2019-12-18', '国际一部 INTL.Business Dept.1', '邱洁', '', '05', '生产通知单', '50%预付款已到账，可以下单。										\r\n', '同意', '朱君宜2019-11-19 15:03:51', '王维2019-11-19 14:23:10', '同意', '陶保荣2019-11-19 15:42:28', '', '', '', '翻单订单，请江西工厂安排处理。', '同意。', '丁富民2019-11-19 16:29:05', '王功勇2019-11-19 17:39:37', 'sctz2019111801', '01', '', '', '', '50%预付款已到账，可以下单。', '鲁慧珍2019-11-18 09:55:39', '', '', '', null, null);
INSERT INTO `crs_tabledata719` VALUES ('458', '{CFCFC916-A883-447D-A2F9-885C9CD522F9}', '80', 'INHE-0576', '2019-11-22 14:34:54', '0000-00-00 00:00:00', '2019-11-26 11:48:24', 'unchecked', 'n', 'n', '', '1', 'sctz2019112203/MNP01/生产通知单', '', '\r\r\n1. 需严格按照客户技术规格要求（附件1-MNP01技术规格）；\r\n2. 电表铭牌上的客户logo,请见附件2；\r\n3. 公司已同意使用EOI项目及ADD项目库存表销售，工厂返工注意事项，请见附件3.', '980', '2019-11-22 14:34:54', 'ACOB Lighting Technology Ltd', 'MNP', 'MNP01', 'INHESC2019081502', '2019-11-30', 'Financial DPT.', '戴萍(Eileen)', '', '06', '生产通知单', '当前约50%T/T预付款已到账，可以下单。										\r\n', '同意', '朱君宜2019-11-25 08:42:05', '郭涛2019-11-22 21:32:12', '同意', '陶保荣2019-11-25 08:48:17', '', '', '', '', '同意', '丁富民2019-11-26 09:56:40', '王功勇2019-11-26 11:36:12', 'sctz2019112203', '01', '', '', '', 'T/T预付款已到账，可以下单。', '鲁慧珍2019-11-22 15:31:31', '00', '', 'ACOB Lighting Technology Ltd', null, null);
INSERT INTO `crs_tabledata719` VALUES ('459', '{A2E22767-D942-4614-9886-8A19688AF1B2}', '66', 'INHE-0634', '2019-11-26 08:51:50', '0000-00-00 00:00:00', '2019-11-28 10:15:21', 'unchecked', 'n', 'n', '', '1', 'sctz2019112601/PAR03/生产通知单', '', 'PAR01翻单，技术要求与01完全一致。货款已经100%T/T预付。', '60', '2019-11-26 08:51:50', 'Parami Energy Service Co.,Ltd', 'PAR', 'PAR03', 'INHESC2019040101', '2020-01-18', '国际三部 INTL.Business Dept.3', '陈雁', '', '05', '生产通知单', '当前已收到全款,同意下单.', '同意。', '朱君宜2019-11-26 18:11:10', '王梅2019-11-26 18:09:03', '同意', '陶保荣2019-11-27 09:09:17', '', '', '', '数量不多，又是翻单生产，请江西工厂发排处理。', '同意。', '丁富民2019-11-27 19:29:05', '王功勇2019-11-27 22:09:07', 'sctz2019112601', '01', '', '', '', '全款已收齐，可以下单。', '鲁慧珍2019-11-26 18:03:12', '', '', 'Parami Energy Services Co.,Ltd', null, null);
INSERT INTO `crs_tabledata719` VALUES ('460', '{8C2D2CDF-B6F5-4BAB-9A0B-968C75B5145E}', '61', 'INHE-0500', '2019-11-29 05:19:30', '0000-00-00 00:00:00', '2019-12-04 18:05:46', 'unchecked', 'n', 'n', '', '1', 'sctz2019112901/EXJ04/生产通知单', '', '', '100', '2019-11-29 05:19:30', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'EXJ', 'EXJ04', 'INHESC2019112001', '2019-12-04', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', 'EXJ04项目付款方式为每批次在生产前100% T/T支付，但目前尚未收到款，请领导审批是否同意下单，谢谢！', '同意。                                         注：1. EXJ04订单8500美金，11月29日代理已安排付款，12月2日预计可以拿到水单；\r\r\n\r\r\n2.EXJ04订单采用EOI库存出货，仅需在电表铭牌上镭雕一个NYC的logo即可（雷经理评估100台新增logo镭雕3个小时可以完成），无需重新生产；                 3.市政公司要求在12月6日前交付不然取消订单，此市政公司好不容易建立内部客户关系，请协助。最晚需要定12月5日航班，即12月3日要工厂备好货发出。\r\r\n', '谭光婷2019-12-03 09:14:24', '郭涛2019-12-02 19:16:50', '同意', '陶保荣2019-12-03 09:18:24', '', '', '', '江西工厂库存表处理，建议由江西工厂安排。', '同意。', '丁富民2019-12-03 09:57:59', '王功勇2019-12-03 14:00:13', 'sctz2019112901', '01', '', '', '', '未收到款，不建议下单，请领导审批，谢谢！', '鲁慧珍2019-11-29 08:39:39', '', '', 'Nyamezela Metering (Pty) Ltd', null, null);
INSERT INTO `crs_tabledata719` VALUES ('461', '{E1FEBBDF-D8DE-4752-A0C8-566371BDF0C0}', '66', 'JXINHE-2559', '2019-11-29 16:59:25', '0000-00-00 00:00:00', '2019-12-04 13:30:58', 'unchecked', 'n', 'n', '', '1', 'sctz2019112905/PCN01/生产通知单', '', '客户已确认产品参数如附,无特殊要求,请按照要求生产.', '665', '2019-11-29 16:59:25', 'CNS ENGINEERING', 'PCN', 'PCN01', 'INHESC2019092501', '2020-02-08', '国际三部 INTL.Business Dept.3', '淦永妍', '', '06', '生产通知单', '', '', '', '', '', '', '', '', '', '', '', '', '', 'sctz2019112905', '', '', '', '', '', '鲁慧珍2019-12-04 13:30:53', '00', '', 'CNS ENGINEERING', null, null);
INSERT INTO `crs_tabledata719` VALUES ('462', '{0DFCF3D6-566D-46EB-B15C-18AF893B6CD8}', '143', 'INHE-0773', '2019-12-03 17:58:12', '0000-00-00 00:00:00', '2019-12-16 08:02:11', 'unchecked', 'n', 'n', '', '1', 'sctz2019120301/EOI48/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。\r\r\n2. EOI48订单请使用带ZETDC logo，但不带Helcraw logo的三相表出货.全款已入账，预计12月20日出货', '77', '', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI48', 'INHESC2019110103', '2019-12-04', '竞标组', '林丹敏', '', '06', '生产通知单', '尾款已在平安银行走入账流程，可以下单。\r\n', '同意。请仓库注意产品LOGO，不要混了，否则会损害业务持续。', '谭光婷2019-12-12 08:52:04', '郭涛2019-12-12 01:50:20', '同意', '陶保荣2019-12-12 13:37:52', '', '', '', '翻单处理，请江西工厂安排。', '同意', '丁富民2019-12-12 15:49:52', '王功勇2019-12-12 15:59:57', 'sctz2019120301', '01', '', '', '', '尾款已在平安银行走入账流程，可以下单。请PMC注意此批货从EOI库存中出，不要重复下单生产。', '鲁慧珍2019-12-11 08:44:50', '', '', 'PARAMOUNT CABLES PRIVATE LIMITED', null, null);
INSERT INTO `crs_tabledata719` VALUES ('463', '{6E715721-797B-490F-9582-0D22D39F9B51}', '61', 'INHE-0500', '2019-12-04 12:26:41', '0000-00-00 00:00:00', '2019-12-06 08:39:31', 'unchecked', 'n', 'n', '', '1', 'sctz2019120401/EAB03/生产通知单', '', '', '2350', '2019-12-04 12:26:41', 'Baltazar Fernandes and Moreira,lda', 'EAB', 'EAB03', 'INHESC2019112901', '2020-01-04', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '全款已到账，可以下单', '同意', '谭光婷2019-12-05 15:44:52', '郭涛2019-12-05 15:35:46', '同意', '陶保荣2019-12-05 16:06:34', '', '', '', '翻单生产，请江西工厂安排处理', '同意', '丁富民2019-12-05 17:48:07', '王功勇2019-12-05 22:07:21', 'sctz2019120401', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2019-12-05 15:20:16', '', '', 'DELEGATE IBERICA LDA', null, null);
INSERT INTO `crs_tabledata719` VALUES ('464', '{53E0ED70-C58E-479C-BF12-DDF192D6B51E}', '61', 'INHE-0500', '2019-12-04 12:32:06', '0000-00-00 00:00:00', '2019-12-06 17:20:06', 'unchecked', 'n', 'n', '', '1', 'sctz2019120402/EXJ05/生产通知单', '', '1 当前TTA的端子盖太短\r\r\n经过和Recharger等经销商实地安装测试，我们的端子盖太短（客户要求长度至少70mm），无法覆盖底部的接线容易导致用户轻易接触到底部接线进行窃电（客户安装在室内墙体上，没有表箱）。\r\r\n此项请公司结合在年均7万台基础上考虑新开端子盖的模具 4万 RMB。\r\r\n\r\n\r\r\n2.电表激活后，需要输入固定短代码才能激活开端盖断电功能，此功能和章工沟通后不影响硬件，简单更新程序即可；\r\n', '10000', '2019-12-04 12:32:06', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'EXJ', 'EXJ05', 'INHESC2019113001', '2020-01-15', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '已收到预付款， 同意下单。', '同意', '朱君宜2019-12-18 16:50:36', '郭涛2019-12-18 08:59:51', '同意', '陶保荣2019-12-18 17:45:21', '', '', '', '', '同意', '丁富民2019-12-18 19:42:11', '王功勇2019-12-19 08:54:32', 'sctz2019120402', '01', '', '', '', '原数量为10000套，增加1100套，增加部分20%预付款已收到，可以下单。', '鲁慧珍2019-12-17 18:16:53', '', '', 'Nyamezela Metering (Pty) Ltd', null, null);
INSERT INTO `crs_tabledata719` VALUES ('465', '{0691FD47-0285-4D38-9D62-312CD4D0D3F5}', '60', 'INHE-0560', '2019-12-09 10:03:07', '0000-00-00 00:00:00', '2019-12-10 09:29:45', 'unchecked', 'n', 'n', '', '1', 'sctz2019120903/白雪804/生产通知单', '', '白雪804订单补发336个模块', '0', '2019-12-09 10:03:07', 'Energomera CJSC', '白雪', '白雪804', 'PO#E18_2702', '2020-01-14', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '前期业务失误多发的336个模块，作为白雪804合同外新增加的产品处理，处理方案详见OA【存货盘点|无线通信模块（品号402APC220404）盘亏问题】。现补发白雪804订单336个模块，王总在OA中已同意重新下单采购。', '同意', '谭光婷2019-12-09 15:45:21', '王维2019-12-09 11:08:03', '同意', '陶保荣2019-12-09 16:05:36', '', '', '', '', '同意', '丁富民2019-12-09 16:22:25', '王功勇2019-12-09 17:46:59', 'sctz2019120903', '01', '', '', '', '白雪804订单补发336个模块给客户，王总在标题为“存货盘点|无线通信模块（品号402APC220404）盘亏问题”的OA中已同意，需重新下单采购。', '鲁慧珍2019-12-09 10:29:00', '', '', 'Energomera CJSC', null, null);
INSERT INTO `crs_tabledata719` VALUES ('466', '{F3054E7F-5EC5-41D0-AF37-55A9221943CE}', '143', 'INHE-0773', '2019-12-16 13:32:03', '0000-00-00 00:00:00', '2019-12-17 16:35:31', 'unchecked', 'n', 'n', '', '1', 'sctz2019121601/EOI50/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。\r\r\n2. EOI50待收到款后，请安排出货。使用EOI库存带ZETDC logo的DIN导轨表出货。', '150', '', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI50', 'INHESC2019121201', '2019-12-20', '竞标组', '林丹敏', '', '06', '生产通知单', '当前已收到全款，待入账，同意下单。', '同意', '朱君宜2019-12-17 14:20:50', '郭涛2019-12-17 11:42:37', '同意', '陶保荣2019-12-17 15:08:37', '', '', '', '翻单生产，请江西工厂安排处理。', '同意。', '丁富民2019-12-17 15:12:30', '王功勇2019-12-17 16:30:52', 'sctz2019121601', '01', '', '', '', '全款已到银行，待走流程入账，可以下单。请PMC注意此批货从EOI库存调用，不用重复下单生产。', '鲁慧珍2019-12-16 17:29:50', '', '', 'HELIFLEX INVESTMENTS PRIVATE', null, null);
INSERT INTO `crs_tabledata719` VALUES ('467', '{39A2AE7F-C55A-4877-BB1E-A6A1546C65E8}', '60', 'INHE-0781', '2019-12-17 08:53:55', '0000-00-00 00:00:00', '2019-12-17 14:02:52', 'unchecked', 'n', 'n', '', '1', 'sctz2019121701/BPP01/生产通知单', '', '附件是提交给电力公司审核的图纸，请先参考此份图纸。待电力公司审核后，再发出审批后的图纸。', '110000', '2019-12-17 08:53:55', 'Ideal Electrical Enterprise Ltd.', 'BPP', 'BPP01', 'INHESC2019120201', '2020-02-10', '国际一部 INTL.Business Dept.1', '李启坦', '第三方检验', '02', '生产通知单', 'BPP01订单备品，标题为“BPP项目申请生产备品”的OA中王总已同意。										\r\n', '同意', '朱君宜2020-01-08 08:41:43', '王维2020-01-08 08:32:33', '同意', '陶保荣2020-01-08 08:46:02', '', '', '', '', '同意', '丁富民2020-01-09 14:35:09', '王功勇2020-01-09 14:54:24', 'sctz2019121701', '01', '', '', '', 'BPP01订单备品，标题为“BPP项目申请生产备品”的OA中王总已同意。', '鲁慧珍2020-01-07 17:45:10', '02', '★★★', 'Ideal Electrical Enterprise Ltd.', null, null);
