INSERT INTO `crs_tabledata719` VALUES ('475', '{1B4D4F06-9817-46A4-9B20-9A26FB0BAA35}', '144', 'INHE-0771', '2020-01-06 17:31:27', '0000-00-00 00:00:00', '2020-01-08 11:35:12', 'unchecked', 'n', 'n', '', '1', 'sctz2020010602/GNF01/生产通知单', '', '表箱不包含断路器，熔芯，扎扣，钢带, 需要预接线', '38916', '2020-01-06 17:31:27', 'TOGO ASSISTANCE SERVICES', 'GNF', 'GNF01', 'INHESC2020010301', '2020-02-15', '投标组', '吴艳', '第三方检验', '02', '生产通知单', '注意此新增的验货样机为GNF项目合同数量之外的新增的样机,不收费,目前暂未发OA申请审批,请领导审批!', '同意。请张柳芳跟进尽快寄出产前样品，便于执行订单。', '朱君宜2020-02-19 13:34:52', '郭涛2020-02-19 13:17:38', '同意', '陶保荣2020-02-19 14:09:18', '', '请优先将样机生产好寄出，尽早获得验收，以免大货生产好不能及时发出。', '', '', '同意。增加产品出货数量。', '丁富民2020-02-19 16:03:17', '王功勇2020-02-19 16:16:14', 'sctz2020010602', '01', '', '', '', '增加验货样机一批，请领导批示，谢谢！', '鲁慧珍2020-02-19 10:25:39', '02', '★★★', 'TOGO ASSISTANCE SERVICES', null, null);
INSERT INTO `crs_tabledata719` VALUES ('477', '{C7139900-01FC-4DFE-B1C7-DE62EE127E19}', '66', 'INHE-0902', '2020-01-10 17:34:47', '0000-00-00 00:00:00', '2020-01-14 08:41:50', 'unchecked', 'n', 'n', '', '1', 'sctz2020011002/PCN01/生产通知单', '', '信用证上最迟发货期是3月8号', '665', '2020-01-10 17:34:47', 'CNS ENGINEERING', 'PCN', 'PCN01', 'INHESC2019092501', '2020-02-20', '国际三部 INTL.Business Dept.3', '黄元', '', '06', '生产通知单', 'PCN电表合同为100%即期保兑L/C,L/C收到但未加保，PCN软件合同款已到中行,待入账中,请领导审核是否同意下单，谢谢！										\r\n', 'PCN０１的软件合同全款２７４６美元已预收到账，可以作为一定形式的抵押担保，另外该客户还有后续项目PCN０２在谈，同意下单。', '朱君宜2020-01-13 09:23:39', '王梅2020-01-10 17:57:16', '同意', '陶保荣2020-01-13 10:18:18', '', '', '', '建议由江西工厂工程部负责处理（库存产品、或者现有批量产品处理），研发不参与此项目具体工作（小订单、私人项目）。', '同意（按现有产品翻单、或者库存产品处理）。', '丁富民2020-01-13 11:17:40', '王功勇2020-01-13 14:38:33', 'sctz2020011002', '01', '', '', '', 'L/C收到但未加保，请领导审核是否同意下单，谢谢！', '鲁慧珍2020-01-10 17:51:55', '00', '', 'CNS ENGINEERING', null, null);
INSERT INTO `crs_tabledata719` VALUES ('478', '{F692E0FA-32DD-403A-B53D-B6DB5C6025F8}', '144', 'INHE-0771', '2020-01-10 17:46:32', '0000-00-00 00:00:00', '2020-01-10 18:11:00', 'unchecked', 'n', 'n', '', '1', 'sctz2020011003/ING20/生产通知单', '', '用于客户现场更换。集中器配置GPRS模块+RF模块，出厂参数参照ING20集中器订单。审批见OA[CDN集中器客诉]\r\r\n\r\r\r\r\n\r\r\r\n\r\r\r\n', '0', '2020-01-10 17:46:32', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'ING', 'ING20', '19000285 CA', '2020-02-01', '投标组', '吴艳', '', '06', '生产通知单', '', '', '', '', '', '', '', '', '', '', '', '', '', 'sctz2020011003', '', '', '', '', '', '鲁慧珍2020-01-10 18:10:53', '', '', 'Eranove', null, null);
INSERT INTO `crs_tabledata719` VALUES ('479', '{7896F916-1BE9-4183-92FE-C8F7D6EF40E0}', '144', 'INHE-0549', '2020-01-10 17:29:28', '0000-00-00 00:00:00', '2020-01-10 18:14:30', 'unchecked', 'n', 'n', '', '1', 'sctz2020011004/NF7-01/生产通知单', '', '免费替换NF7现场CT表的审批OA请见《NF7出差报告》。由于财务没有收到生产通知单，工厂就没有生产的依据，现补充本生产通知单。', '154', '2020-01-10 17:29:28', 'Office National de l`électricité et de l`Eau Potable - Branche électricité', 'NF7', 'NF7-01', 'SM95507PU', '2020-02-01', '投标组', '王秀明', '', '06', '生产通知单', '', '', '', '', '', '', '', '', '', '', '', '', '', 'sctz2020011004', '', '', '', '', '', '鲁慧珍2020-01-10 18:14:26', '', '', 'Office National de l`électricité et de l`Eau Potable - Branche électricité', null, null);
INSERT INTO `crs_tabledata719` VALUES ('480', '{31C2C20C-8765-4CFB-8C01-FDC066B0C402}', '61', 'INHE-0916', '2020-01-18 15:15:05', '0000-00-00 00:00:00', '2020-02-02 08:49:20', 'unchecked', 'n', 'n', '', '1', 'sctz2020011801/EOI53/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。 2. EOI53订单全款已收到；使用EOI库存出货，往尽快安排发货。', '150', '2020/1/18 15:24:00', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI53', 'INHESC2020011601', '2020-01-16', '国际二部 INTL.Business Dept.2', '赖星威', '', '06', '生产通知单', '已跟出纳核实全款已到银行，在走流程入账					\r\r\r\n', '同意', '朱君宜2020-01-18 17:51:15', '郭涛2020-01-18 17:38:16', '同意', '陶保荣2020-01-31 10:02:30', '', '', '', '', '同意', '丁富民2020-01-31 17:18:03', '王功勇2020-01-31 21:02:47', 'sctz2020011801', '01', '', '', '', '全款已到银行，在走流程入账；库存表已发货，补流程。', '鲁慧珍2020-01-18 16:43:27', '', '', 'HELIFLEX INVESTMENTS PRIVATE', null, null);
INSERT INTO `crs_tabledata719` VALUES ('481', '{2980ECD0-43FD-4C20-8844-2872B3B29D41}', '61', 'INHE-0916', '2020-01-18 15:40:15', '0000-00-00 00:00:00', '2020-02-02 08:49:01', 'unchecked', 'n', 'n', '', '1', 'sctz2020011802/EOI52/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。\r\r\r\n2. EOI52订单未收到水单和款项。若20号到账则当天发货；否则年后发货。（详见OA“EOI52货物放行条申请”）', '563', '2020-01-18 15:40:15', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI52', 'INHESC2020011602', null, '国际二部 INTL.Business Dept.2', '赖星威', '', '06', '生产通知单', '尚未收到款，库存表出货，货已按二部要求提前发至深圳办公室。										\r\n', '同意。待货款收到深圳发货。', '朱君宜2020-01-18 17:43:36', '郭涛2020-01-18 17:37:50', '同意', '陶保荣2020-01-31 10:01:58', '', '', '', '', '同意。', '丁富民2020-01-31 17:17:36', '王功勇2020-01-31 21:02:19', 'sctz2020011802', '01', '', '', '', '尚未收到款，库存表出货，货已按二部要求提前发至深圳办公室。', '鲁慧珍2020-01-18 16:44:28', '', '', 'ALVESTONE ESTATES PRIVATE LI', null, null);
INSERT INTO `crs_tabledata719` VALUES ('482', '{1FB731FF-0E6C-4F61-B441-3A8D655ECB02}', '144', 'INHE-0662', '2020-02-06 15:35:50', '0000-00-00 00:00:00', '2020-06-22 10:22:59', 'unchecked', 'n', 'n', '', '1', 'sctz2020020601/TLU01/生产通知单', '已更换为最新的经客服整理业务确认的技术规格。', '\r\r\r\r\n1.【四表位表箱】1）标配5个M25格兰头，左1孔可扩展至M32。2）格兰头数量为5个；所有表箱都应有一个弹簧窗口，一旦打开能自动重新关闭。【显示单元】1)插头为与显示单元本身连在一起的类型 2）使用2节1.5V，AA的不可充电电池；【断路器】240V；【电表】1）改善超声焊2）PCB上没有线。3）火线与零线上使用一样的计量单元。4）EEPROM集成在微控制器上，且需更好的保护涂层。\r\r\n2.表计和MCB需安装在一表位和四表位表箱中完整出货。\r\r\r\r\n3.该订单仅为试订单，需要尽快出货以便争取后续的大订单。', '5000', '2020-02-06 15:35:50', 'Umeme Limited', 'TLU', 'TLU01', 'INHESC2019110801', '2020-07-06', '投标组', '陈丽', '', '06', '生产通知单', '同意.', '同意', '朱君宜2020-06-05 08:41:08', '郭涛2020-06-04 19:45:12', '同意', '陶保荣2020-06-05 09:59:12', '', '', '', '同UNW项目PLC载波通信的DIN-4.1单相分体式（PLC载波通信）代码预付费电能表。产品BOM表已经发江西工厂。研发方面项目负责人：章春鹏，程序正在受控测试之中。  建议表号出厂时按顺序包装，有利于客户安装使用。', '同意。', '丁富民2020-06-05 11:22:28', '王功勇2020-06-05 11:57:15', 'sctz2020020601', '01', '', '', '', '王总在标题为“TLU PO 审核”的OA中已同意100%赊销，喻经理已确认申请到中信保额度，可以下单。', '鲁慧珍2020-06-04 17:39:48', '', '', 'Umeme Limited', null, '02');
INSERT INTO `crs_tabledata719` VALUES ('483', '{90870684-296B-4618-810F-57EF70FFEDC3}', '61', 'INHE-0721', '2020-02-11 13:39:25', '0000-00-00 00:00:00', '2020-02-11 19:21:11', 'unchecked', 'n', 'n', '', '1', 'sctz2020021101/ADC01/生产通知单', '', '1，BS安装单相两线分体式可更换模块智能电表：非透明短端子盖，要求总无功和组合无功计量；当电表检测到掉电(电压)时，继电器不断开（为此前ADC出货程序小BUG，此批货物请规避此问题）2，针对DIN单相表、CT表、三相直通表，业务已同步向客服申请技术规格书提供给客户。3.请尽量于3.15前完成生产，以便保证客户交付时间。', '2245', '2020-02-11 13:39:25', 'Cashpower Sudamericana S.A.', 'ADC', 'ADC01', 'INHESC2017112702', '2020-03-15', '国际二部 INTL.Business Dept.2', '胡云义(Anita)', '', '06', '生产通知单', '', '', '', '', '', '', '', '', '', '', '', '', '', 'sctz2020021101', '', '', '', '', '', '鲁慧珍2020-02-11 19:21:02', '', '', 'CASHPOWER SUDAMERICANA S. A.', null, null);
INSERT INTO `crs_tabledata719` VALUES ('484', '{CAC6FA2A-AA1F-413C-A985-E8035760F45A}', '61', 'INHE-0721', '2020-02-12 12:27:33', '0000-00-00 00:00:00', '2020-02-13 08:53:53', 'unchecked', 'n', 'n', '', '1', 'sctz2020021201/ADC-04/生产通知单', '', '1，BS安装单相两线分体式可更换模块智能电表：非透明短端子盖，要求总无功和组合无功计量；当电表检测到掉电(电压)时，继电器不断开（为此前ADC出货程序小BUG，此批货物请规避此问题）2，针对DIN单相表、CT表、三相直通表，业务已同步向客服申请技术规格书提供给客户。3.请尽量于3.15前完成生产，以便满足给客户的交付时间。', '2245', '2020-02-12 12:27:33', 'Cashpower Sudamericana S.A.', 'ADC', 'ADC-04', 'INHESC2020020401', '2020-03-15', '国际二部 INTL.Business Dept.2', '胡云义(Anita)', '', '05', '生产通知单', '追加的170个PLC模块客户尚未付款，业务反馈客户急用，款近两天也会付出，要求先下单。是否同意请领导批示，谢谢！										\r\n', '同意。请特别注意：现场有225台i310二代模块表，有170个CIU-R（与i310通讯）。客户需要新增170个PLC模块。现场有10台i310(带模块）能与现场的CIU-R通讯，现场i310（带模块）的PLC型号为：FSK-PLC Module:TFF11-30#FE54`Frequency 1140KHZ,180KHZ。', '朱君宜2020-07-10 08:42:34', '郭涛2020-07-09 22:21:49', '同意', '陶保荣2020-07-10 08:47:12', '', '', '', '增补第二代三相模块表PLC(FSK模式）通信模块。', '同意。', '丁富民2020-07-10 09:12:02', '王功勇2020-07-10 09:29:59', 'sctz2020021201', '01', '', '', '', '追加的170个PLC模块客户尚未付款，业务反馈客户急用，款近两天也会付出，要求先下单。是否同意请领导批示，谢谢！', '鲁慧珍2020-07-09 09:10:47', '', '', 'Cashpower Sudamericana S.A.', null, null);
INSERT INTO `crs_tabledata719` VALUES ('485', '{1B07C167-D39B-45EC-9216-D75529F247FA}', '61', 'INHE-0916', '2020-02-17 12:34:19', '0000-00-00 00:00:00', '2020-02-17 18:09:15', 'unchecked', 'n', 'n', '', '1', 'sctz2020021701/EOI54/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。\r\r\r\n2. EOI54全款已收到，使用EOI库存发货。', '100', '2020-02-17 12:34:19', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI54', 'INHESC2020021201', null, '国际二部 INTL.Business Dept.2', '赖星威', '', '06', '生产通知单', '出纳姚茜确认款已到银行，待提供资料走入账流程；使用库存表。										\r\n', '同意', '朱君宜2020-02-17 16:10:49', '郭涛2020-02-17 15:22:38', '同意', '陶保荣2020-02-17 16:28:16', '', '', '', '', '同意', '丁富民2020-02-17 17:12:11', '王功勇2020-02-17 17:47:25', 'sctz2020021701', '01', '', '', '', '出纳姚茜确认款已到银行，待提供资料走入账流程；使用库存表。', '鲁慧珍2020-02-17 13:53:05', '', '', 'ZECHER INVESTMENTS', null, null);
INSERT INTO `crs_tabledata719` VALUES ('486', '{0CF93711-39DE-4002-B58D-A5D7D8CA507D}', '61', 'INHE-0916', '2020-02-18 08:16:00', '0000-00-00 00:00:00', '2020-02-18 11:48:57', 'unchecked', 'n', 'n', '', '1', 'sctz2020021801/EOI55/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。\r\n2. EOI54全款已收到，使用EOI库存发货。										\r\n', '420', '2020-02-18 08:16:00', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI55', 'INHESC2020021301', null, '国际二部 INTL.Business Dept.2', '赖星威', '', '06', '生产通知单', '出纳姚茜确认全款已收到，入账中,可以下单。使用库存表。										\r\n', '同意', '朱君宜2020-02-18 10:52:03', '郭涛2020-02-18 10:30:07', '同意', '陶保荣2020-02-18 11:10:57', '', '', '', '', '同意，翻单生产，请江西工厂安排处理。', '丁富民2020-02-18 11:33:16', '王功勇2020-02-18 11:34:42', 'sctz2020021801', '01', '', '', '', '出纳姚茜确认全款已收到，可以下单。使用库存表。', '鲁慧珍2020-02-18 08:33:46', '', '', 'HELIFLEX INVESTMENTS PRIVATE', null, null);
INSERT INTO `crs_tabledata719` VALUES ('487', '{6952F84E-DC68-45A5-B8C8-CA0F72DF3307}', '144', 'INHE-0771', '2020-02-21 08:23:09', '0000-00-00 00:00:00', '2020-02-21 17:20:23', 'unchecked', 'n', 'n', '', '1', 'sctz2020022101/NEW04/生产通知单', '', '与20000073CA电表订单一起发货', '0', '2020-02-21 08:23:09', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'NEW', 'NEW04', '20000086 CA', '2020-03-25', '投标组', '吴艳', '第三方检验', '06', '生产通知单', '客户尚未开立L/C，是否同意下单，请领导审批，谢谢！										\r\n', '老客户，信用良好，有明确交期。请张柳芳注意LC跟催。', '朱君宜2020-02-21 13:44:13', '郭涛2020-02-21 13:16:01', '同意', '陶保荣2020-02-21 15:00:18', '', '集中器的可靠性要求是最高的，道理上比表计要求高多了。请江西重视，注意工艺和老化、检测。', '', '集中器生产时，请注意质量控制，要作老化检测。', '同意', '丁富民2020-02-21 15:23:22', '王功勇2020-02-21 17:17:15', 'sctz2020022101', '01', '', '', '', '客户尚未开立L/C，是否同意下单，请领导审批，谢谢！', '鲁慧珍2020-02-21 08:45:45', '', '', 'ERANOVE SA', null, null);
INSERT INTO `crs_tabledata719` VALUES ('488', '{7212E157-BE81-48DE-B3BF-E93E057A94A5}', '61', 'INHE-0916', '2020-02-24 10:24:47', '0000-00-00 00:00:00', '2020-02-25 10:38:33', 'unchecked', 'n', 'n', '', '1', 'sctz2020022401/EOI56/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。\r\r\n2. 请使用带ZETDC logo，且不带Helcraw logo的三相表库存发货。									\r\r\n', '50', '2020-02-24 10:24:47', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI56', 'INHESC2020022001', null, '国际二部 INTL.Business Dept.2', '赖星威', '', '06', '生产通知单', '当前款已到银行,待入账中,库存表发货,请领导审批。										\r\r\n', '同意', '朱君宜2020-02-25 09:26:00', '郭涛2020-02-25 09:21:15', '同意', '陶保荣2020-02-25 09:32:33', '', '', '', '', '同意，翻单产品请江西工厂安排处理', '丁富民2020-02-25 09:55:08', '王功勇2020-02-25 10:19:27', 'sctz2020022401', '01', '', '', '', '暂未收到款，库存表发货。', '鲁慧珍2020-02-24 10:52:38', '', '', 'HELIFLEX INVESTMENTS PRIVATE', null, null);
INSERT INTO `crs_tabledata719` VALUES ('489', '{7F44BBCE-1C35-4E44-8C7A-A373E1B2A357}', '61', 'INHE-0916', '2020-02-25 14:54:21', '0000-00-00 00:00:00', '2020-02-27 11:00:19', 'unchecked', 'n', 'n', '', '1', 'sctz2020022501/EOI57/生产通知单', '', '1. 电表请按表号顺序装箱，发货后尽快提供准确电表信息文件。\r\r\r\r\n2. 请使用带ZETDC logo，且不带Helcraw logo的三相表库存发货。\r\r\n3. 请使用带ZETDC logo的单相表库存发货。', '145', '2020-02-25 14:54:21', 'Finmark Industries (Pvt) Ltd.', 'EOI', 'EOI57', 'INHESC2020022401', null, '国际二部 INTL.Business Dept.2', '赖星威', '', '06', '生产通知单', '出纳姚茜确认全款已在银行走入账流程，入账没有问题；使用EOI库存表发货。										\r\n', '同意', '朱君宜2020-02-26 20:36:00', '郭涛2020-02-26 18:48:57', '同意', '陶保荣2020-02-27 09:06:58', '', '', '', '', '同意。翻单生产请江西工厂处理。', '丁富民2020-02-27 09:39:41', '王功勇2020-02-27 09:49:05', 'sctz2020022501', '01', '', '', '', '出纳姚茜确认全款已在银行走入账流程，入账没有问题；使用EOI库存表发货。', '鲁慧珍2020-02-26 17:59:47', '', '', 'SMART METERING PVT LTD', null, null);
INSERT INTO `crs_tabledata719` VALUES ('490', '{F79DEE29-E266-4B2C-ADC9-345ED56CEAA0}', '144', 'INHE-0771', '2020-02-26 12:12:07', '0000-00-00 00:00:00', '2020-02-27 11:34:46', 'unchecked', 'n', 'n', '', '1', 'sctz2020022601/NEW05/生产通知单', '', '1.发货前需要做VOC验货。2.发货需要提供电表的校准证书，测量测试报告\r\r\n', '27648', '2020-02-26 12:12:07', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'NEW', 'NEW05', '20000072 CA', '2020-03-25', '投标组', '吴艳', '第三方检验', '06', '生产通知单', '尚未收到L/C，请领导审核是否同意下单，谢谢。										\r\n', '客户信誉较好，建议下单。', '朱君宜2020-02-26 15:03:34', '郭涛2020-02-26 14:48:22', '同意', '陶保荣2020-02-26 15:16:35', '', '首次大批量投产，请研发注意技术符合性和程序测试到位。请技术支持仔细核对要求，帮助把关。', '', '根据上批次生产反馈，研发作适量小的修改，以提高生产效率----具体由王顺万负责。', '同意。', '丁富民2020-02-26 16:23:06', '王功勇2020-02-27 11:25:48', 'sctz2020022601', '01', '', '', '', '尚未收到L/C，请领导审核是否同意下单，谢谢。', '鲁慧珍2020-02-26 12:29:29', '', '', 'ERANOVE SA', null, null);
INSERT INTO `crs_tabledata719` VALUES ('491', '{2C794887-F683-4B18-83EA-DB8A9F37060A}', '144', 'INHE-0771', '2020-02-27 11:45:51', '0000-00-00 00:00:00', '2020-02-27 14:26:02', 'unchecked', 'n', 'n', '', '1', 'sctz2020022701/NEW06/生产通知单', '', '1.发货前需要做VOC验货。2.发货需要提供电表的校准证书，测量测试报告 3.与NEW04一起发货\r\r\n', '26112', '2020-02-27 11:45:51', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'NEW', 'NEW06', '20000073 CA', '2020-04-05', '投标组', '吴艳', '第三方检验', '06', '生产通知单', '尚未收到L/C，但王总在订单跟踪OA中已同意先下单。										\r\n', '同意', '朱君宜2020-02-27 13:32:16', '郭涛2020-02-27 13:31:41', '同意', '陶保荣2020-02-27 13:34:06', '', '', '', '', '同意。', '丁富民2020-02-27 14:04:54', '王功勇2020-02-27 14:15:28', 'sctz2020022701', '01', '', '', '', '尚未收到L/C，但王总在订单跟踪OA中已同意先下单。', '鲁慧珍2020-02-27 12:03:26', '', '', 'ERANOVE SA', null, null);
