INSERT INTO `crs_tabledata719` VALUES ('493', '{398AFBEC-1AFA-449A-AE66-BA9729CEB4EF}', '144', 'INHE-0771', '2020-02-27 11:58:03', '0000-00-00 00:00:00', '2020-02-27 14:37:04', 'unchecked', 'n', 'n', '', '1', 'sctz2020022703/NEW08/生产通知单', '', '1.发货前需要做VOC验货。2.发货需要提供电表的校准证书，测量测试报告', '27648', '2020-02-27 11:58:03', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'NEW', 'NEW08', '20000076 CA', '2020-04-15', '投标组', '吴艳', '第三方检验', '06', '生产通知单', '尚未收到L/C，但王总在订单跟踪OA中已同意先下单。										\r\n', '同意', '朱君宜2020-02-27 13:34:53', '郭涛2020-02-27 13:34:05', '同意', '陶保荣2020-02-27 13:35:59', '', '', '', '', '同意', '丁富民2020-02-27 14:07:31', '王功勇2020-02-27 14:16:11', 'sctz2020022703', '01', '', '', '', '尚未收到L/C，但王总在订单跟踪OA中已同意先下单。', '鲁慧珍2020-02-27 12:04:52', '', '', 'ERANOVE SA', null, null);
INSERT INTO `crs_tabledata719` VALUES ('494', '{435E2CC0-5C77-4A53-94BC-9CEA244AF2AC}', '93', 'INHE-0811', '2020-02-28 09:47:15', '0000-00-00 00:00:00', '2020-05-11 15:33:25', 'unchecked', 'n', 'n', '', '1', 'sctz2020022802/BGC01/生产通知单', '', '电表出厂设置为后付费。', '570', '2020-02-28 09:47:15', 'REGIE DE PRODUCTION ET DE DISTRIBUTION D“EAU ET D“ELECTRICITE', 'BGC', 'BGC01', '13/I.B.13/INHEMETER CO.,LTD/PHJIMU/2019', '2020-05-10', '国际业务部(OBD)', '宁桃美(Viki Ning)', '第三方检验', '07', '生产通知单', '当前收到16.6%T/T预付款，未收到60%的L/C，是否下单请领导批示，谢谢！										\r\r\r\n！										\r\r\r\r\r\n', '同意下单。在“BGC项目申请下生产通知单”OA中已申请通过。', '朱君宜2020-04-14 17:29:10', '杨爱军(Andy Yang)2020-04-14 17:25:53', '同意', '陶保荣2020-04-14 19:12:10', '', '', '', '研发方面安排：三相CT表（2款）--王占颍负责；三相直通表（1款）---王顺万负责；表箱、外购电流互感由张俊鹏协助客服处理；软件由软件事业部黄庆安排。', '同意。--- ', '丁富民2020-04-15 10:08:59', '王功勇2020-04-15 10:16:12', 'sctz2020022802', '01', '', '', '', '20%T/T预付款未收齐（已收16.6%），未收到60%的L/C，是否下单请领导批示，谢谢！', '鲁慧珍2020-04-14 14:58:24', '02', '★★★', 'REGIE DE PRODUCTION ET DE DISTRIBUTION D“EAU ET D“ELECTRICITE', '银河电网', null);
INSERT INTO `crs_tabledata719` VALUES ('495', '{765B0BB3-CADE-4318-A083-2175009D23FD}', '60', 'INHE-0560', '2020-03-06 16:11:48', '0000-00-00 00:00:00', '2020-03-12 11:42:16', 'unchecked', 'n', 'n', '', '1', 'sctz2020030602/白雪201/生产通知单', '', '\r\r\r【注意】\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n						\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\r\n1、【此订单3650个模块从客户处进口，不需我司生产，我司仅需提供模块刷新服务】                        2、客户会在我司开始提供刷新服务前支付预付款（刷新服务费+补偿增值税）                               3、此下单流程主要为符合我司内部流程，配合采购资源部与客户签订进口采购合同并将其录入ERP系统。                         ', '0', '2020-03-06 16:11:48', 'Energomera CJSC', '白雪', '白雪201', 'E20_0403_D', '2020-04-10', '国际一部 INTL.Business Dept.1', '李美娇', '', '05', '生产通知单', '同意,调整模块数量,款已收齐.', '', '朱君宜2020-07-10 09:04:08', '杨松2020-07-10 09:02:57', '同意', '陶保荣2020-07-10 11:16:42', '', '', '', '', '同意', '丁富民2020-07-10 15:36:33', '王功勇2020-07-10 16:10:55', 'sctz2020030602', '01', '', '', '', '刷新服务款项已收齐。', '鲁慧珍2020-07-08 09:29:18', '', '', 'Energomera CJSC', '银河电力', null);
INSERT INTO `crs_tabledata719` VALUES ('496', '{376A23A8-BC88-428D-BF38-0E8510EA8BFD}', '60', 'INHE-0066', '2020-03-18 11:24:20', '0000-00-00 00:00:00', '2020-03-20 09:23:47', 'unchecked', 'n', 'n', '', '1', 'sctz2020031801/白云810/生产通知单', '', '\r\r\n1、按2015年11月提供给客户的最近样机生产。（和803批次一样的出货，此次生产通知单没有按之前的整机下单，而是按散件下单。机芯和之前一样需要修调。）\r\r\n2、根据最新的报关要求，电表将分机芯（PCBA）、LCD显示板、铝面板、按键、五金件、磁卡、纸箱等几大部分出货。\r\r\n3、双回路计量。\r\r\n4、能支持复费率和阶梯电价两种结算方式。（默认设置见随后提供的出厂设置单）\r\r\n5、带远程通断电功能。\r\r\n6、负荷门限设置。\r\r\n7、能承受电压异常的瞬间波动，电压异常时，电表自动断电，电压恢复正常时，电表自动恢复供电。\r\r\n8、工厂出厂时直接编程设置为后付费模式，并激活继电器。 9、此次无需供塑胶底壳，其他配件保持不变。热\r\r\n熔铜螺母、挂钩片、孔镜等都需要配备）\r\r\n10、采用规格为M4x8mm热塑铜螺母。\r\r\n11、铭牌上的生产年份为：2020年', '0', '2020-03-18 11:24:20', '\"Aspan-Energy \" LTD', '白云', '白云810', 'INHESC2019122002', '2020-04-18', '国际一部 INTL.Business Dept.1', '邱洁', '', '05', '生产通知单', '付款方式:50%TT-预付款下单时支付，50%TT-发货前支付,当前已收到预付款,同意下单.		\r\n', '同意', '朱君宜2020-03-19 09:08:56', '盛燕2020-03-19 08:42:01', '同意', '陶保荣2020-03-19 09:12:11', '', '', '', '翻单生产，请江西工厂安排处理。', '同意。', '丁富民2020-03-19 09:18:07', '王功勇2020-03-19 10:45:15', 'sctz2020031801', '01', '', '', '', '50%T/T预付款已收齐，可以下单。', '鲁慧珍2020-03-18 14:01:02', '', '', '\"Aspan-Energy \" LTD', '银河电力', null);
INSERT INTO `crs_tabledata719` VALUES ('497', '{7B72A8E8-2C58-4C23-9537-5A6A47AA9D90}', '61', 'INHE-0500', '2020-03-20 16:56:02', '0000-00-00 00:00:00', '2020-03-25 09:15:13', 'unchecked', 'n', 'n', '', '1', 'sctz2020032002/EXJ09/生产通知单', '', 'CDE库存直接出货\r\r\n无需任何修改', '30', '2020-03-20 16:56:02', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'EXJ', 'EXJ09', 'INHESC2020031901', null, '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '已收全款,同意下单.', '同意', '朱君宜2020-09-08 08:42:00', '郭涛(Captain)2020-09-07 22:40:02', '同意', '陶保荣2020-09-08 10:25:12', '', '', '', '业务已经说明使用库存产品处理出货，建议由江西工厂安排处理。', '同意。', '丁富民2020-09-08 10:32:49', '王功勇2020-09-08 10:39:16', 'sctz2020032002', '01', '', '', '', '新增三款产品的全款已收齐，可以下单。', '鲁慧珍2020-09-07 18:02:59', '', '', 'Nyamezela Metering PTY Ltd.', '银河电力', null);
INSERT INTO `crs_tabledata719` VALUES ('498', '{EA92A15C-E6B7-4738-B54C-8A194D75BE75}', '61', 'INHE-0772', '2020-04-03 09:12:13', '0000-00-00 00:00:00', '2020-04-09 09:55:41', 'unchecked', 'n', 'n', '', '1', 'sctz2020040301/MLD01/生产通知单', '', 'TTA表型，不需要RF模块，借用TTL物料', '10000', '2020-04-03 09:12:13', 'Amadou Baiba KOUMA', 'MLD', 'MLD01', 'INHESC2020021901', '2020-04-30', '国际二部 INTL.Business Dept.2', '张子琦(Miranda)', '第三方检验', '06', '生产通知单', '同意下单', '同意', '朱君宜2020-04-08 08:43:01', '郭涛2020-04-08 01:34:10', '同意', '陶保荣2020-04-08 08:58:29', '', '', '', '项目研发负责人：章春鹏   TTA表型不需要RF模块和显示单元。', '同意。', '丁富民2020-04-08 09:10:54', '王功勇2020-04-08 18:11:03', 'sctz2020040301', '01', '', '', '', '标题为“MLD01 订单生产和交付”的OA中领导已同意在收到28%预付款的情况下下单，当前已到款28.895%，可以下单。', '鲁慧珍2020-04-07 09:18:27', '01', '★★', 'Société IYA', '银河电力', null);
INSERT INTO `crs_tabledata719` VALUES ('499', '{F55F2CF5-E73B-482A-8358-ECDB6726ADE5}', '143', 'INHE-0773', '2020-04-10 15:24:52', '0000-00-00 00:00:00', '2020-05-06 09:52:39', 'unchecked', 'n', 'n', '', '1', 'sctz2020041001/ZWS02/生产通知单', '', '1. ZWS02项目与ZWS01项目的技术规格一致，按OA“ZWS项目（中标项目）技术合同评审申请”和附件终版技术规格书的要求为准。确认按ZWS01项目翻单。请工厂发出生产资料给业务确认。\r\r\r\n2. ZWS01订单结算方式是100%不可撤销、保兑的远期60天信用证。LC已开出，LC显示的最晚装船期是2020年6月26日\r\r\r\n3. ZWS02生产交期需公司评审推进\r\n4. 再次提醒注意：ZWS02电表须严格按连续的表号，进行装箱。', '20080', '2020-04-10 15:24:52', 'Finmark Industries (Pvt) Ltd.', 'ZWS', 'ZWS02', 'INHESC2020040702', '2020-06-05', '竞标组', '林丹敏', '', '06', '生产通知单', '全款L/C已收到，可以下单。										\r\n', '同意', '朱君宜2020-04-30 13:55:31', '郭涛2020-04-30 13:49:44', '同意', '陶保荣2020-04-30 14:13:50', '', '注意：【其他需要说明的事项】栏中的内容。', '', '与ZWS01项目技术要求一致，业务已经确认翻单生产，请江西工厂安排处理。', '同意。', '丁富民2020-04-30 15:01:07', '王功勇2020-04-30 15:05:46', 'sctz2020041001', '01', '', '', '', '全款L/C已收到，可以下单。', '鲁慧珍2020-04-30 11:36:53', '', '', 'Zimbabwe Electricity Transmission & Distribution Company (Private) Limited.', '银河电力', null);
INSERT INTO `crs_tabledata719` VALUES ('500', '{87B39BE8-7BE4-4001-9B81-C6D424AF0598}', '144', 'INHE-0771', '2020-04-10 17:36:28', '0000-00-00 00:00:00', '2020-04-15 09:53:55', 'unchecked', 'n', 'n', '', '1', 'sctz2020041003/NEW10/生产通知单', '', '通信模块用于一代模块表；与NEW07产品同运', '0', '2020-04-10 17:36:28', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'NEW', 'NEW10', '20000139 CA', '2020-04-22', '投标组', '吴艳', '第三方检验', '06', '生产通知单', '尚未收到L/C，但此批货同NEW07一起发货，建议下单，请领导审批，谢谢！										\r\n', '同意。请张柳芳落实LC。', '朱君宜2020-04-13 08:53:11', '郭涛2020-04-10 20:41:56', '同意', '陶保荣2020-04-13 10:21:13', '', '请业务跟进LC。', '', '原有产品配套的RF\\PLC模块、RF无线，建议江西工厂工程部安排处理。', '同意。', '丁富民2020-04-13 11:07:18', '王功勇2020-04-13 11:23:55', 'sctz2020041003', '01', '', '', '', '尚未收到L/C，但此批货同NEW07一起发货，建议下单，请领导审批，谢谢！', '鲁慧珍2020-04-10 17:44:45', '', '', 'ERANOVE SA', '银河电力', null);
INSERT INTO `crs_tabledata719` VALUES ('501', '{66D2D167-F32F-4C46-932A-1E6CDE97BD45}', '153', 'INHE-0535', '2020-04-23 11:24:48', '0000-00-00 00:00:00', '2020-04-24 10:39:33', 'unchecked', 'n', 'n', '', '1', 'sctz2020042301/JPM01/生产通知单', 'JPM01第一批和第二批', '1.第一批单相表50台和三相表10台整表货款已到账，可使用库存表，尽快备好发出，最迟下周内交付；\r\r\r\n2.第二批单相表540台和三相表30台整表货款已到账，可开始准备物料要求最迟2020年5月10号交付；\r\n3.表号由最终业主提供，正在确认中；\r\n4.铭牌内容正在与客户确认中；\r\r\n5.第一批第二批共630台整表将用于现场试点，全部需要在表红外口出加吸磁钢片；\r\n6.外箱唛头设计内容正在与客户确认中；\r\r\n', '630', '2020-04-23 11:24:48', 'JAY AUTOCOMPONENTS LIMITED', 'JPM', 'JPM01', 'INHESC2020040701', '2020-04-30', '重大项目部', '左亚楠', '', '06', '生产通知单', '此批次产品全款已收齐，同意下单。', '同意。', '朱君宜2020-04-23 16:39:58', '宋宁2020-04-23 16:34:01', '同意', '陶保荣2020-04-23 16:40:38', '', '', '', '此市场产品（单相、三相直通表）研发负责人：余卫东  1：第一批第二次整表需要在红外口加吸磁钢片，库存产品需要返工。2：第二批整表生产建议使用修改后的硬件软件设计，此BOM表还没有发放，采购还需要周期，所以2020年05月10日交货预计有问题，请业务方面知悉。', '同意', '丁富民2020-04-23 17:04:56', '王功勇2020-04-23 17:12:29', 'sctz2020042301', '01', '01', '', '王维2020-04-23 15:01:21', '全款已收齐，可以下单。（业务称此项目产品是在原有产品基础上稍做改动，所以未附单独的技术要求文件。）', '鲁慧珍2020-04-23 14:25:35', '', '', 'JPM Industries Limited', '银河电力', null);
INSERT INTO `crs_tabledata719` VALUES ('502', '{BDFD227C-680E-46ED-897B-33025BF79B69}', '18', 'INHE-0576', '2020-05-12 13:59:53', '0000-00-00 00:00:00', '2020-05-14 08:43:40', 'unchecked', 'n', 'n', '', '1', 'sctz2020051201/KLA/生产通知单', '', '1.此生产通知单中的CIU备品是针对 KLA-2项目，合同编号INHESC2020010901V2；\r\r\r\n2.根据项目需要，需要生产950台CIU备品, 发货到IAC,规格与KLA项目要求一样。\r\r\r\r\r\r\r\n备注：仅需要CIU备品', '950', '2020-05-12 13:59:53', 'The Kenya Power * Lighting Company Limited', 'KLA', 'KLA', 'INHESC2020010901', '2020-05-21', '会计部(FD)', '戴萍(Eileen)', '第三方检验', '06', '生产通知单', '同意.IAC订单，结算方式：每批发货的货值在提单日后120天采用T/T全款支付（全款赊销）										\r\n', '同意', '朱君宜2020-05-13 08:43:06', '郭涛2020-05-12 22:47:21', '同意', '陶保荣2020-05-13 10:02:16', '', '', '', 'KLA产品备品，请江西工厂安排处理。', '同意。', '丁富民2020-05-13 14:58:15', '王功勇2020-05-13 15:56:03', 'sctz2020051201', '01', '', '', '', 'IAC订单，结算方式：每批发货的货值在提单日后120天采用T/T全款支付（全款赊销）', '鲁慧珍2020-05-12 15:24:12', '03', '★★★★', 'INHEMETER AFRICA COMPANY LIMITED', '银河电力', null);
INSERT INTO `crs_tabledata719` VALUES ('503', '{8CF93A86-EDC2-4374-957A-CFDAB24BC184}', '144', 'INHE-0769', '2020-05-15 18:54:48', '0000-00-00 00:00:00', '2020-05-20 10:19:21', 'unchecked', 'n', 'n', '', '1', 'sctz2020051502/M15-F1/生产通知单', '', '', '100000', '2020-05-15 18:54:48', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', 'M15', 'M15-F1', 'ESC 05520/RFQ/FY2019-20', '2020-06-15', '投标英语组', '吴琼', '', '06', '生产通知单', '20%T/T预付款尚未收到，请领导批示是否下单！										\r\r\n', '同意！', '朱君宜2020-05-18 14:10:56', '郭涛2020-05-18 14:09:46', '同意', '陶保荣2020-05-18 15:01:41', '', '请业务紧密跟踪20%预付款。', '', 'M15项目--研发技术负责人章春鹏；M15-F1仍要求IP67,使用ordinary PLC(普通PLC--理解为M15项目的FSK-PLC），建议采用2019年07月M15的方案进行生产。', '同意。', '丁富民2020-05-18 16:43:04', '王功勇2020-05-18 17:09:44', 'sctz2020051502', '01', '', '', '', '20%T/T预付款尚未收到，请领导批示是否下单，谢谢！', '鲁慧珍2020-05-18 08:56:53', '', '', 'ELECTRICITY SUPPLY CORPORATION OF MALAWI LIMITED', '银河电力', '01');
INSERT INTO `crs_tabledata719` VALUES ('504', '{5AF00A85-4E37-409C-86D9-921CE3025879}', '66', 'INHE-0634', '2020-06-02 09:31:32', '0000-00-00 00:00:00', '2020-06-09 08:49:14', 'unchecked', 'n', 'n', '', '1', 'sctz2020060201/MOC03/生产通知单', '', '外购品，需软件部安装好抄表app，验收合格后方可发货。', '0', '2020-06-02 09:31:32', '达明（澳门）有限公司Dynamax (Macau) Limited', 'MOC', 'MOC03', 'PO-2005-1773', '2020-06-08', '国际三部 INTL.Business Dept.3', '陈雁', '', '06', '生产通知单', '全款已到账，同意下单。										\r\r\n', '同意。', '朱君宜2020-06-02 11:07:19', '王梅2020-06-02 11:03:32', '同意', '陶保荣2020-06-02 11:33:34', '', '', '', '', '同意', '丁富民2020-06-02 13:52:59', '王功勇2020-06-02 14:02:22', 'sctz2020060201', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2020-06-02 10:39:59', '', '', 'Dynamax (Macau) Limited', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('505', '{82506295-1E1C-4E1D-8FB4-C9A557C1FB6B}', '66', 'INHE-0634', '2020-06-08 15:58:24', '0000-00-00 00:00:00', '2020-06-10 08:42:32', 'unchecked', 'n', 'n', '', '1', 'sctz2020060801/URV01/生产通知单', '', '请软件部测试验收合格后方可出货。', '0', '2020-06-08 15:58:24', 'Sipromad Group Company Limited', 'URV', 'URV01', 'INHESC2019120901', '2020-06-16', '国际三部 INTL.Business Dept.3', '陈雁', '', '06', '生产通知单', '当前收到30%预付款水单，但款暂未到公司，70%L/C 已收到且审核通过，请领导审批！', '同意下单。', '朱君宜2020-06-08 16:57:52', '王梅2020-06-08 16:38:59', '同意', '陶保荣2020-06-08 16:59:34', '', '', '', '此掌机是外购产品，项目具体实施由软件事业部刘超负责。---此类不涉及到江西工厂加工、同时需要软件事业部验收的外购产品，能否直接安排到深圳采购、或者软件事业部、采购资源部处理？', '同意。', '丁富民2020-06-09 09:19:43', '王功勇2020-06-09 11:18:33', 'sctz2020060801', '01', '', '', '', '30%预付款水单已收到，预计明天到账；70%L/C已收到且审核通过。可以下单。', '鲁慧珍2020-06-08 16:21:53', '01', '★★', 'Global Technologies', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('506', '{9BABE79A-FA9E-4359-8E99-F8A2571C2150}', '61', 'INHE-0721', '2020-06-15 10:05:30', '0000-00-00 00:00:00', '2020-06-17 09:19:42', 'unchecked', 'n', 'n', '', '1', 'sctz2020061501/PSA17-06/生产通知单', '', '1.100台CT表，其中30台带GPRS模块，其余70台不带模块；2.GPRS模块上要求打印EMEI编码；3.电表支持三相三线及三相四线可切换,要求屏蔽逆相序，其他规格可参照PSA17-03项目CT表规格；4.收到预付款，请工厂按照客户要求交货时间（7.15）排单生产、交付。', '100', '2020-06-15 10:05:30', 'MESSEN S.A.S', 'PSA17', 'PSA17-06', 'INHESC2020061001', '2020-07-15', '国际二部 INTL.Business Dept.2', '胡云义(Anita)', '', '05', '生产通知单', '付款方式：预付30%，尾款70%。目前到账约23.6%预付款，不足30%，是否同意先下单，请领导批示，谢谢！										\r\r\r\n', '同意', '朱君宜2020-06-15 15:44:28', '郭涛2020-06-15 13:48:36', '同意', '陶保荣2020-06-15 15:59:33', '', '如此小单都不能利索付款执行，客户（代理）实力太小。', '', '建议按业务给出的--PSA17-03翻单处理；研发项目负责人：王占颍。', '同意。', '丁富民2020-06-15 17:43:49', '王功勇2020-06-15 17:54:26', 'sctz2020061501', '01', '', '', '', '目前到账约23.6%预付款，不足30%，是否同意先下单，请领导批示，谢谢！', '鲁慧珍2020-06-15 11:02:06', '', '', 'MESSEN S.A.S', '银河电力', '01');
INSERT INTO `crs_tabledata719` VALUES ('507', '{C8DB37A9-5EB8-41C1-BB8F-C05EC0BE11C6}', '61', 'INHE-0500', '2020-06-18 11:12:10', '0000-00-00 00:00:00', '2020-06-22 09:27:17', 'unchecked', 'n', 'n', '', '1', 'sctz2020061801/EAB04/生产通知单', '', 'EAB03翻单\r\n', '3000', '2020-06-18 11:12:10', 'Baltazar Fernandes and Moreira,lda', 'EAB', 'EAB04', 'INHESC2020061601', '2020-07-05', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '同意.', '同意', '朱君宜2020-06-18 13:57:35', '郭涛2020-06-18 13:45:29', '同意', '陶保荣2020-06-18 14:30:16', '', '', '', 'EAB03项目翻单处理，建议由江西工厂安排。', '同意', '丁富民2020-06-18 15:39:41', '王功勇2020-06-18 18:45:26', 'sctz2020061801', '01', '', '', '', '王总已在标题为“李忠鹏-EAB03项目产品&设备及工具报价申请单-20191010”的OA中同意预付款从2019年10月8日收到的保证金中扣除，可以下单。（尾款水单也已收到）', '鲁慧珍2020-06-18 13:42:24', '', '', 'DELEGATE IBERICA LDA', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('508', '{AF8B4238-AAAF-468D-90A0-044C3678F92D}', '61', 'INHE-0913', '2020-06-22 10:28:01', '0000-00-00 00:00:00', '2020-06-24 08:21:05', 'unchecked', 'n', 'n', '', '1', 'sctz2020062202/MEC01/生产通知单', '', '', '1436', '2020-06-22 10:28:01', 'SETH', 'MEC', 'MEC01', 'SC NO.1907/007/20-REV1 and NO.1907/008/20-REV1', '2020-08-06', '国际二部 INTL.Business Dept.2', '魏紫薇(Valentine)', '第三方检验', '02', '生产通知单', '30%预付款已到银行，待走流程入账，是否同意先下单，请领导审批，谢谢！										\r\n', '同意', '朱君宜2020-06-23 08:38:47', '郭涛2020-06-22 19:36:05', '同意', '陶保荣2020-06-23 08:48:41', '', '请落实清楚丁总提出的技术要求和电流规格问题。', '', '1: 生产通知单上三相表电流规格15(100)A与提供的《MEC技术规格整理15（40）A \\ 5(60)A》给出的不一致；2: 生产通知单与技术规格精度要求不一致；3: 【5.12.2.3.2 分体式单三相规格  第18条存在问题---要求是漏电保护断路器】，电表无法实现。', '不同意。', '丁富民2020-06-23 09:54:04', '王功勇2020-06-23 10:03:11', 'sctz2020062202', '02', '', '', '', '30%预付款已到银行，待走流程入账，是否同意先下单，请领导审批，谢谢！', '鲁慧珍2020-06-22 16:34:38', '01', '★★', 'Sociedade de Empreitadas e Trabalhos Hidráulicos, S.A', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('509', '{0E511BAB-E4B9-4522-9A48-53D6F06C58F3}', '61', 'INHE-0913', '2020-06-23 14:13:12', '0000-00-00 00:00:00', '2020-06-28 13:32:29', 'unchecked', 'n', 'n', '', '1', 'sctz2020062301/MEC01/生产通知单', '', '', '1436', '2020-06-23 14:13:12', 'SETH', 'MEC', 'MEC01', 'SC NO.1907/007/20-REV1 and NO.1907/008/20-REV1', '2020-08-06', '国际二部 INTL.Business Dept.2', '魏紫薇(Valentine)', '第三方检验', '02', '生产通知单', '已跟出纳姚茜确认30%预付款已到银行，待走流程入账，是否同意先下单，请领导审批，谢谢！					\r\r\r\n		', '同意', '朱君宜2020-06-24 15:25:37', '郭涛2020-06-24 14:20:05', '同意', '陶保荣2020-06-24 15:29:50', '', '', '', '此项目研发负责人：章春鹏   项目表计数量不多，没有特别的功能要求，建议按现有产品进行翻单处理。', '同意。', '丁富民2020-06-24 17:21:52', '王功勇2020-06-24 18:32:50', 'sctz2020062301', '01', '', '', '', '30%预付款已到银行，待走流程入账，是否同意先下单，请领导审批，谢谢！（出纳姚茜确认入账没问题）', '鲁慧珍2020-06-23 16:01:36', '01', '★★', 'Sociedade de Empreitadas e Trabalhos Hidráulicos, S.A', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('510', '{A02A02D3-A870-4698-AFDB-FED6EE465CEE}', '61', 'INHE-0725', '2020-07-02 09:40:40', '0000-00-00 00:00:00', '2020-07-03 17:18:46', 'unchecked', 'n', 'n', '', '1', 'sctz2020070201/MNP02/生产通知单', '', '电表SGC需我方提供', '300', '2020-07-02 09:40:40', 'ACOB Lighting Technology Ltd', 'MNP', 'MNP02', 'INHESC2020022501', '2020-07-21', '国际二部 INTL.Business Dept.2', '赵政洁(Oscar)', '', '05', '生产通知单', '全款已收齐，可以下单。										\r\n', '同意。', '朱君宜2020-07-02 13:49:33', '郭涛2020-07-02 12:53:12', '同意', '陶保荣2020-07-02 14:24:25', '', '', '', '订单数量很少，同意业务意见，使用EOI项目库存电能表处理，建议江西工厂安排处理。', '同意。', '丁富民2020-07-02 17:30:20', '王功勇2020-07-02 17:41:04', 'sctz2020070201', '01', '', '', '', '全款已收齐，可以下单。', '鲁慧珍2020-07-02 10:11:06', '00', '', 'New Moon Nigeria Limited', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('511', '{D405C464-26DC-4457-B316-E0E4621C4985}', '61', 'INHE-0500', '2020-07-06 08:50:44', '0000-00-00 00:00:00', '2020-07-07 14:29:07', 'unchecked', 'n', 'n', '', '1', 'sctz2020070601/EXJ06/生产通知单', '', 'CDE库存直接出货，无需任何修改\r，无需另外补库存给CDE订单\r\r\n', '5', '2020-07-06 08:50:44', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'EXJ', 'EXJ06', 'INHESC2020070201', '2020-07-06', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '同意，增加采购50台BS三相电表，款已收齐。', '同意', '朱君宜2020-07-20 11:08:45', '郭涛2020-07-19 14:39:10', '同意', '陶保荣2020-07-20 11:10:12', '', '', '', '使用库存产品处理，请江西工厂安排。', '同意。', '丁富民2020-07-20 11:36:20', '王功勇2020-07-20 11:37:50', 'sctz2020070601', '01', '', '', '', '三相表增加50套，款已到齐，可以下单。', '鲁慧珍2020-07-17 11:13:27', '', '', 'Nyamezela Metering (Pty) Ltd', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('512', '{843293A6-4B6B-4E58-BD81-FEB4E9A58396}', '61', 'INHE-0500', '2020-07-17 10:42:54', '0000-00-00 00:00:00', '2020-07-21 11:52:31', 'unchecked', 'n', 'n', '', '1', 'sctz2020071701/EAB05/生产通知单', '7/17已收到尾款。', 'BS安装三相四线直接接入式分体式（PLC通讯）预付费代码表请研发根据业务技术要求，推荐直接翻单项目，无其他特殊要求\r\r\r\n', '3060', '2020-07-17 10:42:54', 'Baltazar Fernandes and Moreira,lda', 'EAB', 'EAB05', 'INHESC2020071501', '2020-08-21', '国际二部 INTL.Business Dept.2', '李忠鹏(Evans)', '', '04', '生产通知单', '同意，货款已收齐。', '同意。请李忠鹏收清欠款。', '朱君宜2020-07-20 15:23:32', '郭涛2020-07-19 14:34:26', '同意', '陶保荣2020-07-20 15:35:14', '', '', '', '单相表按EAB04翻单处理；三相表翻单由章春鹏作确认。', '同意。', '丁富民2020-07-20 17:08:22', '王功勇2020-07-20 18:04:13', 'sctz2020071701', '01', '', '', '', '客户原付保证金中扣除一小部分后的尾款客户已付（业务有提供水单），暂未到账，请领导审批是否同意先下单，谢谢！', '鲁慧珍2020-07-17 11:46:52', '', '', 'DELEGATE IBERICA LDA', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('513', '{2139B03F-C69B-4C0B-92DE-D964DC909A2A}', '66', 'INHE-0634', '2020-07-24 10:15:38', '0000-00-00 00:00:00', '2020-07-27 11:04:48', 'unchecked', 'n', 'n', '', '1', 'sctz2020072401/KNT11/生产通知单', '', '（1）电表安装在表箱内出货（2）KNT11和KNT12可合并生产，但是打包出货的时候注意区分开，不要合并。', '424', '2020-07-24 10:15:38', 'Kinetic Myanmar Technology Co., Ltd', 'KNT', 'KNT11', 'INHESC2020071301', '2020-09-01', '国际三部 INTL.Business Dept.3', '陈雁', '', '05', '生产通知单', '同意.', '同意。', '朱君宜2020-07-28 16:36:54', '王梅2020-07-28 16:27:04', '同意', '陶保荣2020-07-29 10:02:55', '', '', '', '翻单生产，请江西工厂安排处理', '同意。', '丁富民2020-07-29 10:15:27', '王功勇2020-07-29 10:21:32', 'sctz2020072401', '01', '', '', '', '三相表箱变更型号，价格不变。', '鲁慧珍2020-07-28 16:21:19', '00', '', 'KYOCERA Communication Systems Kinetic Myanmar Co., Ltd', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('514', '{4A9E4A40-EB53-45C2-B0EF-6BD070C20071}', '66', 'INHE-0634', '2020-07-24 10:58:09', '0000-00-00 00:00:00', '2020-07-27 11:05:18', 'unchecked', 'n', 'n', '', '1', 'sctz2020072402/KNT12/生产通知单', '', '（1）电表安装在表箱内出货（2）KNT11和KNT12可合并生产，但是打包出货的时候注意区分开，不要合并。										\r\n', '707', '2020-07-24 10:58:09', 'Kinetic Myanmar Technology Co., Ltd', 'KNT', 'KNT12', 'INHESC2020071303', '2020-09-01', '国际三部 INTL.Business Dept.3', '陈雁', '', '05', '生产通知单', '同意', '同意。', '朱君宜2020-07-28 16:37:25', '王梅2020-07-28 16:27:39', '同意', '陶保荣2020-07-29 10:02:24', '', '', '', '翻单生产，请江西工厂安排处理。', '同意。', '丁富民2020-07-29 10:14:31', '王功勇2020-07-29 10:15:55', 'sctz2020072402', '01', '', '', '', '三相表箱型号变更，价格不变。', '鲁慧珍2020-07-28 16:22:12', '00', '', 'KYOCERA Communication Systems Kinetic Myanmar Co., Ltd', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('515', '{818B2FC5-5BE6-4B33-A4C0-60DFF63C9AAF}', '167', 'INHE-0549', '2020-07-24 10:55:50', '0000-00-00 00:00:00', '2020-07-30 09:06:35', 'unchecked', 'n', 'n', '', '1', 'sctz2020072403/NGC01/生产通知单', '', 'SGC:123456', '100', '2020-07-24 10:55:50', '尼日尔国家电力公司', 'NGC', 'NGC01', 'DDM20201256', '2020-08-07', '投标法语组', '王秀明', '', '06', '生产通知单', '已收款,同意下单.', '同意', '朱君宜2020-07-27 08:44:48', '郭涛2020-07-25 21:49:05', '同意', '陶保荣2020-07-27 08:54:58', '', '', '', '数量不多，按公司已经批量生产的产品进行翻单或者库存产品进行处理，建议由江西工厂负责安排。', '同意。', '丁富民2020-07-27 10:37:37', '王功勇2020-07-27 10:41:59', 'sctz2020072403', '01', '', '', '', '据张柳芳反馈，郑超波在标题为“NGC试点PO”的OA中确认2020/7/21收到客户付的现金全款，已跟会计部确认手续齐全，可以下单。', '鲁慧珍2020-07-24 13:56:31', '01', '★★', '尼日尔国家电力公司', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('516', '{48DEBC0C-7EB3-42C3-A6AA-7BFAE5D95D17}', '66', 'INHE-0774', '2020-07-24 16:21:33', '0000-00-00 00:00:00', '2020-07-27 14:05:01', 'unchecked', 'n', 'n', '', '1', 'sctz2020072404/BAL/生产通知单', '', '以上交货时间从合同签订日期6月29日起算90天，合同规定90天内要运到客户目的地仓库#FE54`预付费CT表的下行通信方式待客户最终确认。', '16200', '2020-07-24 16:21:33', 'MOSECO C Modern Scientific & Electronics Co.', 'BAL', 'BAL', 'PEA WB-RPP 01/2019', '2020-09-27', '国际三部 INTL.Business Dept.3', '何森华', '第三方检验', '02', '生产通知单', '10预付款未收到,王总已特批,详见OA如上,同意下单.', '预付款保函已经在工行申请开立审核中，为尽可能减少交货期的延迟，同意提前下单。', '朱君宜2020-07-27 09:23:46', '王梅2020-07-27 09:04:23', '同意', '陶保荣2020-07-27 09:27:46', '', '', '', 'BAL项目表计方面研发负责人：王顺万。 由于要采用3G+PLC/RF模块和相应的通信显示单元，涉及到研发工作。研发方案确定后，先给出生产用BOM表进行备料。  ', '同意。', '丁富民2020-07-27 10:23:44', '王功勇2020-07-27 10:33:19', 'sctz2020072404', '01', '', '', '', '付款方式：10%收到预付款保函后T/T支付，70%在发货前通过不可撤销保兑L/C支付，20%验收后T/T支付。10%预付款未收到，但王总在标题为“BAL项目申请提前备料和提前下生产通知单”的OA中已同意下单。', '鲁慧珍2020-07-27 08:58:13', '02', '★★★', 'Palestinian energy and Natural Resources Authority', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('517', '{56E707EF-E562-4EB5-96BB-E3D4E48339F9}', '144', 'INHE-0859', '2020-07-31 14:20:56', '0000-00-00 00:00:00', '2020-08-04 10:50:09', 'unchecked', 'n', 'n', '', '1', 'sctz2020073101/TTL02/生产通知单', '', '50000台为整机SKD不打外壳螺钉。铅封套管需要打上INHEMETER的LOGO。铭牌镭雕TBS LOGO,并提供MADE IN TANZANIA贴纸。外箱贴纸和其他生产细节可以参考TTL01项目。电力公司要求总供货量5%的CIU作为备品，暂时按千分之二提供备品，100个，后期和客户再想办法处理备品CIU不足的事情。由于目前供货数量较多，现场表计和生产维护需要，单相表，客户要求提供万分之四的备品，20台。\r\n', '50000', '2020-07-31 14:20:56', 'INHEMETER (T) LIMITED', 'TTL', 'TTL02', 'INHESC2020060601', '2020-09-15', '投标英语组', '陈金珠', '第三方检验', '02', '生产通知单', '未收到预付款或者L/C，是否同意下单，请领导批示，谢谢！										\r\n', '同意下单，业务负责8月中收到预付款。', '朱君宜2020-08-03 08:34:38', '郭涛2020-08-01 02:13:47', '同意', '陶保荣2020-08-03 08:38:39', '', '请业务补齐合同等手续，紧密跟踪预付款。', '', '研发已经完成BOM表修改和资料发放（主要是处理表计开上盖检测和表箱出气孔），生产程序再作一些优化。----研发项目负责人章春鹏。', '同意。', '丁富民2020-08-03 13:16:51', '王功勇2020-08-03 13:51:57', 'sctz2020073101', '01', '', '', '', '未收到预付款或者L/C，是否同意下单，请领导批示，谢谢！', '鲁慧珍2020-07-31 16:14:55', '', '', 'INHEMETER (T) LIMITED', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('518', '{C8D30A31-CFC4-4816-A78D-76B66F53BD68}', '61', 'INHE-0654', '2020-08-04 13:58:17', '0000-00-00 00:00:00', '2020-08-06 09:28:44', 'unchecked', 'n', 'n', '', '1', 'sctz2020080403/MCM01/生产通知单', '', '1.为避免重新走合同流程，已将两相三相的命名已经在合同中更改为公司的标准命名i312，故生产通知单的型号未能更改，合同中均已使用公司最新的产品命名；2.希望能保证良好的交期；3.生产时候要注意显示单元和对应的电表能匹配使用以及通讯模块的匹配使用\r\r\n', '13400', '2020-08-04 13:58:17', 'MEDIDAS ELECTRONICAS CENTRALIZADAS', 'MCM', 'MCM01', 'INHESC2020072801', '2020-09-15', '国际二部 INTL.Business Dept.2', '李明(Ming)', '第三方检验', '05', '生产通知单', '当前30%预付款已到账，可以下单。										\r\r\n', '同意', '朱君宜2020-08-04 15:03:47', '郭涛2020-08-04 14:52:15', '同意', '陶保荣2020-08-04 19:56:42', '', '请按丁总的要求，明确产品技术（RF通信）要求。', '', '技术规格中没有对RF通信给出具体参数要求，研发无法确定产品BOM表。请业务、客服与客户沟通确认RF通信的频率等参数。【此问题点在销售合同评审时也提出过】', '不同意。', '丁富民2020-08-05 08:50:43', '王功勇2020-08-05 09:56:03', 'sctz2020080403', '02', '', '', '', '30%预付款已到账，可以下单。', '鲁慧珍2020-08-04 14:24:41', '01', '★★', 'Medidas electronicas centralizadas sas', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('519', '{FA48A990-D5F6-4AA0-9788-8FB134A9E7F3}', '61', 'INHE-0654', '2020-08-05 11:40:11', '0000-00-00 00:00:00', '2020-08-11 09:19:06', 'unchecked', 'n', 'n', '', '1', 'sctz2020080501/MCM01/生产通知单', '由于增加RF通讯参数, 因而需要重新走流程', '1.为避免重新走合同流程，已将两相三相的命名已经在合同中更改为公司的标准命名i312，故生产通知单的型号未能更改，合同中均已使用公司最新的产品命名；2.希望能保证良好的交期；3.生产时候要注意显示单元和对应的电表能匹配使用以及通讯模块的匹配使用；4.补充RF具体参数如附件图示，红圈处均可用（426.025-426.1375，426.0375-426.1125，429.8125-429.925，449.7125-449.825，449.8375-449.8875）\r\r\n', '13400', '2020-08-04 13:58:17', 'MEDIDAS ELECTRONICAS CENTRALIZADAS', 'MCM', 'MCM01', 'INHESC2020072801', '2020-09-15', '国际二部 INTL.Business Dept.2', '李明(Ming)', '第三方检验', '05', '生产通知单', '当前30%预付款已到账，可以下单。										\r\n', '同意', '朱君宜2020-08-06 08:39:46', '郭涛2020-08-05 23:02:21', '同意', '陶保荣2020-08-06 08:44:50', '', '', '', '由于RF无线通信的信道不是慧联通信RF-IV所列，存在慧联通信针对性此项目进行RF无线模组研发、测试时间，有可能会影响交期。研发方面此项目负责人：王顺万', '同意。', '丁富民2020-08-06 09:37:38', '王功勇2020-08-06 10:19:37', 'sctz2020080501', '01', '', '', '', '30%预付款已到账，可以下单。', '鲁慧珍2020-08-05 14:01:05', '01', '★★', '', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('520', '{66001DC0-8FD1-4E50-8B23-E5E37F7D87EA}', '60', 'INHE-0781', '2020-08-06 14:47:21', '0000-00-00 00:00:00', '2020-08-11 09:18:03', 'unchecked', 'n', 'n', '', '1', 'sctz2020080601/WZC01/生产通知单', '', '1、因样机及投标资料上的脉冲常数是5000，需改到10000，此外电力公司审核的图纸上还有几处小错误需要修改，因此图纸还在沟通中；\r\n2、因CT表客户不具备维修条件，因此在生产时需多做5个作为备品，一旦出现故障表可以及时替换，坏表返厂修理。', '1000', '2020-08-06 14:47:21', 'West Zone Power Distributin Company Limited', 'WZC', 'WZC01', 'INHESC2020062901', '2020-09-07', '国际一部 INTL.Business Dept.1', '李启坦', '第三方检验', '02', '生产通知单', '同意变更', '同意。', '朱君宜2020-09-24 16:59:41', '杨松2020-09-24 16:58:53', '同意', '陶保荣2020-09-24 17:07:20', '', '', '', '研发、采购资源部已经给出料号，可以直接安排采购。原采购的棒状天线需要采购部、PMC安排处理。', '同意变更。', '丁富民2020-09-24 18:43:45', '王功勇2020-09-24 22:17:51', 'sctz2020080601', '01', '', '', '', '', '鲁慧珍2020-09-24 16:46:21', '', '', 'Ideal Electrical Enterprise Ltd.', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('521', '{9B78626B-AF77-4D6A-ACD0-4A120B3F73F6}', '167', 'INHE-0838', '2020-08-07 15:01:03', '0000-00-00 00:00:00', '2020-08-27 17:18:49', 'unchecked', 'n', 'n', '', '1', 'sctz2020080702/BFN11/生产通知单', '', '', '11400', '2020-08-07 15:01:03', 'SOCIETE GENERALE D`ELECTRONIQUE', 'BFN10', 'BFN11', 'N004/SGE/2020', '2020-10-02', '投标法语组', '廖云巧', '', '07', '生产通知单', '已跟出纳核实20%预付款已在建行入帐中，可以下单。', '同意', '朱君宜2020-08-27 14:23:09', '郭涛(Captain)2020-08-27 14:11:03', '同意', '陶保荣2020-08-27 14:27:14', '', '', '', 'BFN11项目需要作硬件、嵌入式软件修改；项目负责人：章春鹏', '同意。', '丁富民2020-08-27 15:06:43', '王功勇2020-08-27 15:41:20', 'sctz2020080702', '01', '', '', '', '20%预付款已在建行入账，可以下单。', '鲁慧珍2020-08-27 10:53:19', '', '', 'SOCIETE GENERALE D`ELECTRONIQUE', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('522', '{261C8719-1377-4492-9AEE-58C51E2D6866}', '18', 'INHE-0576', '2020-08-08 23:03:58', '0000-00-00 00:00:00', '2020-08-11 09:17:12', 'unchecked', 'n', 'n', '', '1', 'sctz2020080802/KFD/生产通知单', '', '1.严格按照客户提供的英文版技术规格生产，附件为中英对照参考。\r\r\r\r\r\r\r\r\n2.1250 台 CIU作为备品，免费提供给客户。\r\r\r\r\r\r\r\r\n3.如果公司要求IAC在今年12月底前完成电力公司交付12.5万台，则需要江西工厂在9月初完成国内发货，预计大货在10月中旬抵达肯尼亚IAC工厂，立即启动本地生产，才能完成12月底前交付。', '125000', '2020-08-08 23:03:58', 'The Kenya Power * Lighting Company Limited', 'KFD', 'KFD', 'INHESC2020080602', '2020-09-08', '会计部(FD)', '戴萍(Eileen)', '第三方检验', '06', '生产通知单', '付款方式:付款方式为每批发货的货值在提单日后120天采用T/T支付.建议变更合同评审,把新增20备品分摊到合同单价里.', '同意', '朱君宜2020-08-12 08:37:11', '郭涛2020-08-11 19:41:25', '同意', '陶保荣2020-08-12 08:40:08', '', '增加备品', '', '研发此项目负责人：章春鹏', '同意', '丁富民2020-08-12 09:04:02', '王功勇2020-08-12 09:11:33', 'sctz2020080802', '01', '', '', '', '增加20套备品表，请领导批示，谢谢。', '鲁慧珍2020-08-11 14:50:17', '03', '★★★★', 'INHEMETER AFRICA CO.,LTD.', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('523', '{7453B97A-1D07-4D2B-BA4B-5EF2F9928218}', '167', 'INHE-0771', '2020-08-10 14:38:59', '0000-00-00 00:00:00', '2020-08-12 07:57:43', 'unchecked', 'n', 'n', '', '1', 'sctz2020081001/NEW11/生产通知单', '', '1.发货前需要做VOC验货。2.发货需要提供电表的校准证书，技术规格 3.订单号20000473 CA， Ref：20000128YS / 20000175YS\r\r\n', '34616', '2020-08-10 14:38:59', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'NEW', 'NEW11', '20000473 CA', '2020-09-14', '投标法语组', '吴艳', '第三方检验', '06', '生产通知单', '尚未收到L/C，是否同意下单请领导批示，谢谢！										\r\n', '同意。 ', '朱君宜2020-08-10 16:03:14', '郭涛2020-08-10 15:59:00', '同意', '陶保荣2020-08-10 16:22:51', '', '', '', '此项目研发负责人：王顺万。', '同意。', '丁富民2020-08-10 18:02:28', '王功勇2020-08-10 18:06:45', 'sctz2020081001', '01', '', '', '', '尚未收到L/C，是否同意下单请领导批示，谢谢！', '鲁慧珍2020-08-10 15:29:31', '', '', 'ERANOVE SA', '银河电力', '02');
