INSERT INTO `crs_tabledata719` VALUES ('525', '{6FE94334-562B-4FAE-89B3-1C6B42D509D3}', '60', 'INHE-0066', '2020-08-21 11:26:57', '0000-00-00 00:00:00', '2020-08-25 08:00:07', 'unchecked', 'n', 'n', '', '1', 'sctz2020082102/白雪203/生产通知单', '需结构部重新对胶水进行选型，防止再次出现粘贴不牢固很容易揭开的问题。', '', '0', '2020-08-21 11:26:57', 'Energomera CJSC', '白雪', '白雪203', 'NO 20_0010769', null, '国际一部 INTL.Business Dept.1', '邱洁', '', '05', '生产通知单', '全款已到账，可以下单。										\r\n', '同意', '朱君宜2020-08-24 09:04:32', '杨松2020-08-21 15:56:10', '同意', '陶保荣2020-08-24 09:30:11', '', '', '', '', '同意', '丁富民2020-08-24 10:44:19', '王功勇2020-08-24 11:32:03', 'sctz2020082102', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2020-08-21 11:35:16', '', '', 'Energomera CJSC', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('526', '{D40E94C0-B861-4E66-B63F-C8123D12542A}', '173', 'INHE-0937', '2020-08-31 15:43:33', '0000-00-00 00:00:00', '2020-09-03 18:25:09', 'unchecked', 'n', 'n', '', '1', 'sctz2020083101/BAP08/生产通知单', '', '', '0', '2020-08-31 15:43:33', 'FactorFast (PTY) Ltd', 'BAP', 'BAP08', 'INHESC2020082401', '2020-09-02', '南非区SADC', '杨政(Echo)', '', '06', '生产通知单', '当期已收到全款,同意下单.', '同意', '朱君宜2020-09-02 13:31:31', '郭涛(Captain)2020-09-02 12:45:51', '同意', '陶保荣2020-09-02 14:37:30', '', '', '', '水表产品---慧联通信负责', '同意。', '丁富民2020-09-02 16:18:24', '王功勇2020-09-02 21:17:08', 'sctz2020083101', '01', '', '', '', '全款已到账，可以下单。', '鲁慧珍2020-09-01 17:38:42', '', '', 'FACTORFAST METERING(PTY) LTD', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('527', '{C1B9616E-2061-4F58-A8B4-B79B41C9973C}', '144', 'INHE-0931', '2020-09-10 15:14:56', '0000-00-00 00:00:00', '2020-09-14 09:38:56', 'unchecked', 'n', 'n', '', '1', 'sctz2020091002/KFE01/生产通知单', '', '1.需严格按照标书技术规格制作，另附上标书规格原文及中英对照，供研发参考；                            2.公司要求2020年12月31日前完成向电力公司的交付，请工厂价加紧生产。                       ', '70000', '2020-09-10 15:14:56', 'The Kenya Power * Lighting Company Limited', 'KFE', 'KFE01', 'KP1/9A.3/OT/34/19-20', '2020-10-25', '投标英语组', '杨睛睛', '第三方检验', '02', '生产通知单', '在完成满意交付，提交发票及要求文件的30天内开始支付货款。（全款赊销）										\r\n', '同意。需要国内尽快提供产前图纸给客户签字确认。', '朱君宜2020-09-11 14:50:37', '郭涛(Captain)2020-09-11 13:38:26', '同意', '陶保荣2020-09-11 15:33:50', '', '', '', '此项目产品属新开发产品；--研发项目负责人肖国成（电子张建刚  结构王亦毅）', '同意。', '丁富民2020-09-11 17:42:44', '王功勇2020-09-12 13:38:30', 'sctz2020091002', '01', '', '', '', '在完成满意交付，提交发票及要求文件的30天内开始支付货款。（全款赊销）', '鲁慧珍2020-09-11 11:22:01', '01', '★★', 'The Kenya Power * Lighting Company Limited', '银河电力', '01');
INSERT INTO `crs_tabledata719` VALUES ('528', '{8D56A3A9-D36C-48DF-8B41-0003FC909F0A}', '144', 'INHE-0927', '2020-09-11 09:56:43', '0000-00-00 00:00:00', '2020-09-16 07:59:07', 'unchecked', 'n', 'n', '', '1', 'sctz2020091105/IMF07/生产通知单', '', '该销售合同为IAC向银河电力采购工厂辅料，和KFD大货一起发出，不需要单独清关.其中1至6项物品为此次需要随KFD发出货物,需要生产；7至9项物品为早已发出货物这次随本合同补合同评审流程（应江西工厂要求），无需生产。						\r\r\n', '0', '2020-09-11 09:56:43', 'INHEMETER AFRICA CO., LTD.', 'IMF', 'IMF07', 'INHESC2020090402', '2020-10-28', '投标英语组', '张倩', '', '06', '生产通知单', '付款方式：每批发货的货值在提单日后120天采用T/T支付，赊销，可以下单。										\r\n', '同意', '朱君宜2020-09-11 14:48:43', '郭涛(Captain)2020-09-11 14:41:48', '同意', '陶保荣2020-09-11 15:32:27', '', '', '', '生产辅料，请客服与江西工厂安排处理。', '同意。', '丁富民2020-09-11 16:35:38', '王功勇2020-09-12 13:45:30', 'sctz2020091105', '01', '', '', '', '付款方式：每批发货的货值在提单日后120天采用T/T支付，赊销，可以下单。', '鲁慧珍2020-09-11 10:17:51', '', '', 'INHEMETER AFRICA CO., LTD.', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('532', '{D9EB204C-6DDD-405A-BF09-F8DD98C5FDF7}', '144', 'INHE-0931', '2020-09-14 09:03:37', '0000-00-00 00:00:00', '2020-09-16 08:48:05', 'unchecked', 'n', 'n', '', '1', 'sctz2020091403/LME01/生产通知单', '', '1.LME项目电表产品的技术规格同KF03项目；但是注意电表铭牌上不打KEBS标志；同时需要研发按照标书要求尽快提供生产图纸及技术参数，让客户审批。                                                           2.此项目的断路器属于外购产品，需要客服联系当时投标授权的厂家，按照标书要求提供图纸（参数，铭牌，包装信息等）技术文件。                                                                              3.一般情况下一个电表配两个断路器，则需要198310个断路器。但是标书交期表要求提供198312个，所以按照标书要求提供。', '99155', '2020-09-14 09:03:37', 'The Kenya Power * Lighting Company Limited', 'LME', 'LME01', 'KP1/6E.3/PT/3/18/A66', '2020-10-15', '投标英语组', '杨睛睛', '第三方检验', '02', '生产通知单', '同意。10%：签订合同后60天T/T，需提交同等金额的银行保证金以及付款申请（尚未收到款）；80%：发货后通过不可撤销的保兑信用证在60天内支付；10%：客户签发验收证明并提交付款申请后60天内T/T。										\r\r\n', '同意', '朱君宜2020-09-14 14:03:08', '郭涛(Captain)2020-09-14 11:21:57', '同意', '陶保荣2020-09-14 15:57:06', '', '', '', 'LME(A81)项目：表计部分研发负责人：章春鹏 断路器请温燕、张俊鹏负责，由客服给出当初投标时提供的品牌型号等。', '同意。', '丁富民2020-09-14 17:44:24', '王功勇2020-09-14 17:46:11', 'sctz2020091403', '01', '', '', '', '10%：签订合同后60天T/T，需提交同等金额的银行保证金以及付款申请（尚未收到款）；80%：发货后通过不可撤销的保兑信用证在60天内支付；10%：客户签发验收证明并提交付款申请后60天内T/T。', '鲁慧珍2020-09-14 09:44:15', '', '', 'The Kenya Power & Lighting Company Limited', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('533', '{5413F97F-3A1E-4B8F-B106-6BAC2944C69A}', '175', 'INHE-0721', '2020-09-15 04:45:01', '0000-00-00 00:00:00', '2020-09-17 11:52:10', 'unchecked', 'n', 'n', '', '1', 'sctz2020091501/CME03/生产通知单', '', '1.50+10台CT表给CME01项目电力公司客户EHU供货，需带带EHU的logo#FE54`后10台CT表需带以太网接口；2.其中350台CT表为PSA17-06项目翻单产品，带GPRS模块，带电力公司EEP的logo，为方便生产，合并下单；3.中标供货项目，有交期要求，客户要求10月19日交货；已收到预付款；', '410', '2020-09-15 04:45:01', 'MESSEN S.A.S', 'CME', 'CME03', 'INHESC2020090701', '2020-10-19', '南美区S. America', '胡云义(Anita)', '', '05', '生产通知单', '当前已收到30%预付款,可以下单.', '根据现场统计，仅仅PSA市场有几千台故障CT表。强烈建议公司严苛完整测试新订单产品。CT表安装分散，美洲又地广人稀，装表成本数倍于电表本身价格。同时，CT表是电费大头，任何电力公司都没有理由和自己的主要收入打哈哈，绝对不敢差不多就行。CT表出问题会导致严重社会和经济后果乃至厂家被巨额索赔。希望公司重视CT表产品品质，避免灾难。', '朱君宜2020-09-15 10:41:05', '郭涛(Captain)2020-09-15 10:37:57', '同意', '陶保荣2020-09-15 14:23:32', '', '', '', '410台三相多功能表（CT表），研发负责人王颍。  2019年前供货的三相多功能表（CT表）问题已经作了说明并给出处理意见、以及程序升级说明，现场问题请业务、客服按当初公司意见进行处理。', '同意。', '丁富民2020-09-16 08:45:26', '王功勇2020-09-16 10:17:36', 'sctz2020091501', '01', '', '', '', '30%预付款已收齐，可以下单。', '鲁慧珍2020-09-15 10:25:37', '', '', 'MESSEN S.A.S', '', '02');
INSERT INTO `crs_tabledata719` VALUES ('534', '{F88A2B7A-05A2-4A47-94EE-E7D8C3E26223}', '60', 'INHE-0066', '2020-09-15 10:51:52', '0000-00-00 00:00:00', '2020-09-17 07:59:52', 'unchecked', 'n', 'n', '', '1', 'sctz2020091502/白雪204/生产通知单', '', '按翻单生产。', '0', '2020-09-15 10:51:52', 'Energomera CJSC', '白雪', '白雪204', '20_0011432', '2020-09-26', '国际一部 INTL.Business Dept.1', '邱洁', '', '05', '生产通知单', '30%预付款应付USD7425.9,实付USD7128.55,少付部分跟尾款一起支付,请领导审批!', '同意', '朱君宜2020-09-15 11:16:25', '杨松2020-09-15 11:06:43', '同意', '陶保荣2020-09-15 14:23:01', '', '', '', '外购安美通RF无线模块（翻单），请江西工厂安排处理。', '同意。', '丁富民2020-09-16 08:27:57', '王功勇2020-09-16 10:16:36', 'sctz2020091502', '01', '', '', '', '30%预付款USD 7,425.9，实际到账USD 7,128.55，客户算错少付了USD 297.35，业务建议先下单，所差部分跟70%尾款一起收回，请领导审批，谢谢！', '鲁慧珍2020-09-15 11:05:42', '', '', 'Energomera CJSC', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('535', '{9FFA884F-9F65-473B-ADB4-68E1488672EC}', '60', 'INHE-0066', '2020-09-15 10:59:35', '0000-00-00 00:00:00', '2020-09-17 07:59:28', 'unchecked', 'n', 'n', '', '1', 'sctz2020091503/白雪205/生产通知单', '', '按白雪技术要求生产。', '0', '2020-09-15 10:59:35', 'Energomera CJSC', '白雪', '白雪205', 'No.20_0012649', '2020-09-26', '国际一部 INTL.Business Dept.1', '邱洁', '', '05', '生产通知单', '全款已收齐，可以下单。										\r\n', '同意', '朱君宜2020-09-15 11:20:24', '杨松2020-09-15 11:12:11', '同意', '陶保荣2020-09-15 14:13:14', '', '需要IT部将银河电力销售，生产订单下给珠海电网的“生产通知单”做合理修改。', '', '这些是属于珠海银河电网负责的产品，请由珠海银河电网负责安排生产处理，而不是江西工厂。', '同意。', '丁富民2020-09-16 08:24:18', '王功勇2020-09-16 10:13:20', 'sctz2020091503', '01', '', '', '', '全款已收齐，可以下单。', '鲁慧珍2020-09-15 11:07:48', '', '', 'Energomera CJSC', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('536', '{55AD41F4-AE47-4BE2-9E0B-3D65E0F77E38}', '153', 'INHE-0535', '2020-09-16 16:22:29', '0000-00-00 00:00:00', '2020-09-21 08:55:22', 'unchecked', 'n', 'n', '', '1', 'sctz2020091601/JPM01/生产通知单', 'JPM01-4', '1.本批次订单数量和供货明细如下：\r\r\r\n1）单相表SKD（不带塑胶件和五金件的SKD）- 即贴片后的电表主板PCBA套件+贴片后的模块板PCBA套件+插件，10050套，散货包装；\r\r\r\n2）三相表SKD（带塑胶件和五金件的整表SKD）- 即贴片后的电表主板PCBA套件+电表电源板PCBA套件+贴片后的模块PCBA套件+塑胶件+五金件，2010套，散货包装；\r\r\r\n3）单相表CKD（不带塑胶件和五金件的全散）- 即全散，不包含塑胶件和五金件部分，503套，全散包装；\r\r\r\n\r\r\r\n2. 上述订单数量包含0.5%备品；\r\r\r\n\r\r\r\n3. PCB板及元器件上不能含有中国制造或厂家标识或任何与中国有关的标识，需要客服部和采购部与供应商沟通。\r\n\r\n4.该笔订单L/C银行已收到，但需要客户修改3处内容，修改后的L/C最迟下周一可开出。', '12563', '2020-09-16 16:22:29', 'JAY AUTOCOMPONENTS LIMITED', 'JPM', 'JPM01', 'INHESC2020040701', '2020-10-30', '重大项目部', '左亚楠', '', '06', '生产通知单', '此批全款L/C已收到，可以下单。（0.5%备品为免费备品）										\r\n', '同意。确保此单能按期、按质交付，以便业务加快接下来的订单的谈判。近日客户要银河的产能，以便与终端客户谈,或有更大批量的订单。', '朱君宜2020-09-17 09:00:25', '宋宁2020-09-17 08:58:21', '同意', '陶保荣2020-09-17 11:21:45', '', '', '', 'JPM项目---项目研发负责人余卫东', '同意。', '丁富民2020-09-17 17:27:56', '王功勇2020-09-17 17:49:16', 'sctz2020091601', '01', '', '', '', '此批全款L/C已收到，可以下单。（0.5%备品为免费备品）', '鲁慧珍2020-09-16 18:00:40', '', '', 'JPM Industries Limited', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('537', '{A093D670-A430-4D83-B262-45D024237452}', '174', 'INHE-0434', '2020-09-17 16:53:27', '0000-00-00 00:00:00', '2020-09-21 08:55:43', 'unchecked', 'n', 'n', '', '1', 'sctz2020091701/EXJ10/生产通知单', '', 'OA：EXJ项目申请备库存，王总审批同意按以上库存下单申请。\r\r\r\r\n\r\r', '24000', '2020-09-17 16:53:27', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'EXJ', 'EXJ10', 'INHESC2020091001', '2020-10-30', '东北非NEAC', '钟云林(Andy)', '', '06', '生产通知单', '当前已收合同的70%预付款，业务按标题为EXJ项目申请备库存“王总批准的库存数量下单', '同意。EXJ库存单。ONTEC已下订单已经收取70%预付款。', '朱君宜2020-09-18 08:50:16', '郭涛(Captain)2020-09-18 08:46:10', '同意', '陶保荣2020-09-18 08:57:35', '', '', '', '', '同意', '丁富民2020-09-18 11:19:38', '王功勇2020-09-18 11:37:18', 'sctz2020091701', '01', '', '', '', 'EXJ10已走合同评审订单数量（4000+100+20+1）70%预付款已收到，业务按标题为“EXJ项目申请备库存”王总批准的库存数量下单。', '鲁慧珍2020-09-17 17:20:30', '', '', 'Ontec Systems (Pty) Ltd', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('538', '{98A39FCF-08F5-4EA5-A534-C557A8822A8E}', '170', 'INHE-0793', '2020-09-21 14:30:46', '0000-00-00 00:00:00', '2020-09-27 17:45:20', 'unchecked', 'n', 'n', '', '1', 'sctz2020092102/TTP01/生产通知单', 'TTP项目下单', '1.铅封产品共分13种颜色，各自数量不同，详情请见OA“TTP项目技术解析申请 ”。                         2.产品的外包装事宜有特殊要求，详情请见OA“TTP项目外箱包装印刷图纸”。                              3.每种颜色产品批量生产前需要先给到我司样品确认，并提供相关色号等具体信息。                          4.鉴于是下游厂家供应，请采购即刻下单。', '0', '2020-09-21 14:30:46', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TTP', 'TTP01', 'PA/001/2019-20/HQ/G/246', '2020-11-04', '东非区EAC', '辛方腾(Daniel)', 'COC认证，保险', '04', '生产通知单', '付款方式“10%在发货后向电力公司提交提单等文件，而后以不可撤销信用证结算；90%在电力公司收货后向电力公司提供验收证明，后60天内TT”，全款赊销。										\r\n', '同意。', '朱君宜2020-09-22 09:07:30', '郭涛(Captain)2020-09-21 20:12:48', '同意', '陶保荣2020-09-22 09:26:14', '', '', '', '客户订制的铅封供货，属外购器件---研发方面由曾年贵负责，采购资源部温燕协助处理。', '同意。', '丁富民2020-09-22 10:02:23', '王功勇2020-09-22 10:57:32', 'sctz2020092102', '01', '', '', '', '付款方式“10%在发货后向电力公司提交提单等文件，而后以不可撤销信用证结算；90%在电力公司收货后向电力公司提供验收证明，后60天内TT”，全款赊销。', '鲁慧珍2020-09-21 16:04:17', '01', '★★', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('539', '{7BBE9394-0016-4D74-8363-592084556E78}', '173', 'INHE-0500', '2020-09-22 08:36:33', '0000-00-00 00:00:00', '2020-09-23 09:08:36', 'unchecked', 'n', 'n', '', '1', 'sctz2020092201/EXJ11/生产通知单', '', '使用CDE库存直接出货，无需任何修改\r\n', '50', '2020-09-22 08:36:33', 'Nyamezela Consulting Engineers (Pty) Ltd.', 'EXJ', 'EXJ11', 'INHESC2020092101', '2020-09-23', '南非区SADC', '李忠鹏(Evans)', '无', '04', '生产通知单', '全款已到账，可以生产出货。										\r\n', '同意。使用CDE库存。', '朱君宜2020-09-22 11:10:56', '郭涛(Captain)2020-09-22 11:02:09', '同意', '陶保荣2020-09-22 11:15:53', '', '', '', '库存产品处理---请江西工厂工程安排。', '同意', '丁富民2020-09-22 11:39:17', '王功勇2020-09-22 11:39:58', 'sctz2020092201', '01', '', '', '', '全款已到账，可以生产出货。', '鲁慧珍2020-09-22 08:43:54', '', '', 'Nyamezela Metering (Pty) Ltd', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('540', '{2C0856FB-F048-40B0-955E-C3CEFF8B422F}', '167', 'INHE-0771', '2020-09-22 08:43:22', '0000-00-00 00:00:00', '2020-09-23 09:07:49', 'unchecked', 'n', 'n', '', '1', 'sctz2020092202/NEW12/生产通知单', '', '1.发货需要提供电表的校准证书，技术规格 2.订单号20000603 CA，Ref：20000128YS / 20000217YS\r\r\r\n', '52584', '2020-09-22 08:43:22', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'NEW', 'NEW12', '20000603CA', '2020-10-30', '投标法语组', '吴艳', '无', '06', '生产通知单', 'L/C尚未收到，是否同意下单，请领导批示，谢谢。										\r\n', '同意。请考虑新旧方案电表DCU的集抄兼容。', '朱君宜2020-09-22 11:07:30', '郭涛(Captain)2020-09-22 11:01:21', '同意', '陶保荣2020-09-22 11:15:33', '', '', '', '表计部分由王顺万负责；G3-PLC方面由何梓劲负责；', '同意。', '丁富民2020-09-22 13:48:33', '王功勇2020-09-22 14:16:39', 'sctz2020092202', '01', '', '', '', 'L/C尚未收到，是否同意下单，请领导批示，谢谢。', '鲁慧珍2020-09-22 09:34:47', '', '', 'ERANOVE SA', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('541', '{DD7740DC-8745-495E-B793-6997285A098D}', '167', 'INHE-0771', '2020-09-22 09:20:42', '0000-00-00 00:00:00', '2020-09-23 09:10:22', 'unchecked', 'n', 'n', '', '1', 'sctz2020092203/NEW13/生产通知单', '', '1.发货需要提供电表的校准证书，技术规格 3.订单号20000604 CA， Ref：20000217YS\r\r\n', '71680', '2020-09-22 09:20:42', 'COMPAGNIE IVOIRIENNE D`ELECTRICITE', 'NEW', 'NEW13', '20000604CA', '2020-11-10', '投标法语组', '吴艳', '无', '06', '生产通知单', 'L/C尚未收到，是否同意下单请领导批示，谢谢。										\r\n', '同意。请考虑新旧DCU集抄事宜（二代RF表和一代RF表现场抄读已经出现状况）。', '朱君宜2020-09-22 11:01:51', '郭涛(Captain)2020-09-22 10:59:40', '同意', '陶保荣2020-09-22 11:14:42', '', '', '', '表计部门研发负责人：王顺万； G3-PLC技术负责人何梓劲。', '同意', '丁富民2020-09-22 13:50:32', '王功勇2020-09-22 14:16:18', 'sctz2020092203', '01', '', '', '', 'L/C尚未收到，是否同意下单请领导批示，谢谢。', '鲁慧珍2020-09-22 09:35:29', '', '', 'ERANOVE SA', '银河电力', '03');
INSERT INTO `crs_tabledata719` VALUES ('542', '{B8A8AA0C-6797-418F-B423-B066F0FCDC2B}', '60', 'INHE-0066', '2020-09-23 08:35:09', '0000-00-00 00:00:00', '2020-09-24 09:35:29', 'unchecked', 'n', 'n', '', '1', 'sctz2020092301/白雪206/生产通知单', '', '白雪单相表要求：\r\r\n1、采用新模具结构供货。     \r\r\n2、PCB板不需灌胶和喷三防漆！\r\r\n3、注意：表号范围（表地址）已给出。同时取消配备两个条形码。      \r\r\n4、MAC地址为该表表号（表地址）的最后六位数字，该地址激光雕刻在表外壳背部。       \r\r\n5、PLC载波显示单元的铭牌标识为：CE208。         \r\r\n6、显示单元不需要贴易碎贴。        \r\r\n7、出厂设置：           \r\r\n1）表内时间为：GMT+4           \r\r\n2）冬夏令时转换功能关闭。           \r\r\n3）1月1日至12月31日默认为第一套年时区表。           \r\r\n4）第一套年时区表为：7:00-费率1,23:00-费率2.           \r\r\n5）特殊节假日没有。           \r\r\n6）电表密码：000000.           \r\r\n7）负荷门限：0.           \r\r\n8）继电器的闭合默认通过通信接口来实现。           \r\r\n9）取负荷点的平均时间：30分钟。          \r\r\n8、继电器：100A，但标识采用120A。      \r\r\n9、按新修改的计量单元结构供货，即（强化电表结构解决防水防尘问题，接线柱光孔8.2mm（无螺纹），适用于M8螺钉，背部加内凹的壁脚板区域用于贴表号标签。）       \r\r\n10、正确的接线方式为架空线安装。因接线方式处无此选项，为了流程往下走，选了双进双出。   \r\r\n11、注:每台MCU需配备4个法兰螺栓和4个法兰螺母。4个法兰螺栓和4个法兰螺母用小袋装好，放到每台MCU的内盒中。  										\r\r\n', '17535', '2020-09-23 08:35:09', 'Energomera CJSC', '白雪', '白雪206', 'PO 20_0013652', '2020-10-25', '国际一部 INTL.Business Dept.1', '邱洁', '无', '05', '生产通知单', '30%预付款已到账，可以下单。										\r\n', '同意', '朱君宜2020-09-23 15:49:30', '杨松2020-09-23 13:54:11', '同意', '陶保荣2020-09-23 15:57:06', '', '', '', '按2018年批量生产方案翻单生产，请江西工厂安排处理。', '同意。', '丁富民2020-09-23 18:01:04', '王功勇2020-09-23 18:45:40', 'sctz2020092301', '01', '', '', '', '30%预付款已到账，可以下单。', '鲁慧珍2020-09-23 10:35:45', '', '', 'Energomera CJSC', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('543', '{A71C2B6E-7495-415E-A813-FBF1B83FE7D2}', '167', 'INHE-0549', '2020-09-27 09:21:29', '0000-00-00 00:00:00', '2020-09-30 16:17:54', 'unchecked', 'n', 'n', '', '1', 'sctz2020092701/KM01/生产通知单', '', 'sctz2018122101号生产通知单翻单，不要提供双绞线，且单三相电表要以后付费模式出厂。出厂时单三相表箱内部装好表和熔断器、熔芯和零线柱并接好线。断路器、安装板、CIU、钢带和扎扣以及多出的475只电表和熔芯可单独包装。如有任何问题请微信或电话联系王秀明：15705276012。					', '9775', '2020-09-27 09:21:29', 'KAMA.SA', 'KM', 'KM01', 'INHESC2017022202', '2020-10-28', '投标法语组', '王秀明', 'ECTN', '05', '生产通知单', '此批货款已收齐，可以下单。										\r\n', '同意。业务对客户仍然只确认收到预付款，不说收到部分订单全款。', '朱君宜2020-09-27 15:59:18', '郭涛(Captain)2020-09-27 13:57:39', '同意', '陶保荣2020-09-27 18:07:07', '', '', '', '技术规格、要求与2018年二个生产通知单相同，业务也明确是SCTZ2018122101号生产通知单翻单，请江西工厂安提成处理。---研发此项目负责人：章春鹏', '同意。', '丁富民2020-09-27 18:36:06', '王功勇2020-09-27 18:39:16', 'sctz2020092701', '01', '', '', '', '此批货款已收齐，可以下单。', '鲁慧珍2020-09-27 11:11:34', '', '', 'KAMA-SA', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('544', '{C44383AD-FD7F-4DB6-9C9B-B2C785B033CD}', '60', 'INHE-0066', '2020-09-27 14:06:34', '0000-00-00 00:00:00', '2020-09-29 08:13:48', 'unchecked', 'n', 'n', '', '1', 'sctz2020092702/白云811/生产通知单', '集中器下行通信为瑞斯康PLC方案，和白云历史供货集中器一致。', '\r\r\n\r\r\n集中器特殊要求或者补充说明：\r\r\n\r\r\n1、低压载波集中器，上行GPRS通信，下行载波通信。   \r\r\n2、必须具备三相表计量功能。   \r\r\n3、出货时包装上不要显示集中器等字样，客户那边把集中器当三相表来进口，以减少海关不必要的麻烦。  \r\r\n4、面板上需显示型号为：  DJZ22-INHE10  \r\r\n										\r\r\n\r\r\n\r\r\n										\r\r\n', '0', '2020-09-27 14:06:34', '\"Aspan-Energy \" LTD', '白云', '白云811', 'INHESC2020033001', '2020-10-30', '国际一部 INTL.Business Dept.1', '邱洁', '无', '05', '生产通知单', '50%预付款已到账，可以下单。										\r\n', '同意。', '朱君宜2020-09-27 15:41:10', '杨松2020-09-27 14:26:23', '同意', '陶保荣2020-09-27 18:05:43', '', '', '', '项目研发负责人：何梓劲', '同意。', '丁富民2020-09-27 18:12:49', '王功勇2020-09-27 18:29:17', 'sctz2020092702', '01', '', '', '', '50%预付款已到账，可以下单。', '鲁慧珍2020-09-27 14:25:33', '', '', '\"Aspan-Energy \" LTD', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('545', '{F56CD1D8-6777-4E7B-AB1A-C6C26E510A92}', '144', 'INHE-0859', '2020-09-28 15:59:02', '0000-00-00 00:00:00', '2020-09-28 16:29:10', 'unchecked', 'n', 'n', '', '1', 'sctz2020092801/TTP01/生产通知单', '', '（1）外购产品，客服到外购厂家进行验货。（2）公司已批准提前生产；', '0', '2020-09-28 15:59:02', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', 'TTP', 'TTP01', 'PA/001/2019-20/HQ/G/246', '2021-01-01', '投标英语组', '陈金珠', '第三方检验', '06', '生产通知单', '', '', '', '', '', '', '', '', '', '', '', '', '', 'sctz2020092801', '', '', '', '', '重复下单？', '鲁慧珍2020-09-28 16:29:03', '01', '★★', 'TANZANIA ELECTRIC SUPPLY COMPANY LIMITED', '银河电力', '02');
INSERT INTO `crs_tabledata719` VALUES ('546', '{6A80246A-3413-4029-AE9F-F97DF4D25A52}', '66', 'INHE-0902', '2020-09-30 16:29:36', '0000-00-00 00:00:00', '2020-09-30 17:49:30', 'unchecked', 'n', 'n', '', '1', 'sctz2020093001/KNT14/生产通知单', '', '电表均安装在表箱内出货', '442', '2020-09-30 16:29:36', 'Kinetic Myanmar Technology Co., Ltd', 'KNT', 'KNT14', 'INHESC2020092501', '2020-10-31', '国际三部 INTL.Business Dept.3', '黄元', '无', '05', '生产通知单', '', '', '', '', '', '', '', '', '', '', '', '', '', 'sctz2020093001', '', '', '', '', '业务有提供全款付款水单，节后才能入账，是否同意先下单请领导批示，谢谢！', '鲁慧珍2020-09-30 17:49:22', '00', '', 'KYOCERA Communication Systems Kinetic Myanmar Co., Ltd', '银河电力', '02');
